const _SOS_TEMPO = [
  { name: 'langsam', jps: 0.25 },   // Erdjahre je Sekunde
  { name: 'schnell', jps: 3 },
  { name: 'sehr schnell', jps: 30 },
];

function _sosInit() {
  // Startet bewusst auf der langsamsten Stufe: bei 3 Erdjahren je Sekunde
  // (bisherige Vorgabe) dreht Merkur zwoelf Runden je Sekunde und springt bei
  // 60 Bildern/s um 74 Grad je Bild weiter - er wirkt dann wie zufaellig
  // verstreut statt schnell. Bei 0,25 Jahren/s sieht man genau das, worum es
  // geht: innen flink, aussen traege. Wer es eilig hat, schaltet hoch.
  _sos = { ansicht: 'bahnen', tempo: 0, jahre: 0, gewaehlt: 2, tAnim: 0 };
}

/* Bahnradius auf dem Schirm. Die echten Abstaende reichen von 0,39 bis 30 AE -
   linear waeren Merkur bis Mars ein einziger Punkt. Deshalb gestaucht; die
   ungestauchte Wahrheit zeigt die Ansicht "Abstände". */
function _sosR(a) { return 26 + 26.8 * Math.pow(a, 0.45); }

function _sosSetzen(was, wert) {
  if (was === 'ansicht') _sos.ansicht = wert;
  if (was === 'tempo') _sos.tempo = wert;
  if (was === 'planet') _sos.gewaehlt = wert;
  _sosStatus();
  document.querySelectorAll('[data-sos]').forEach(b => {
    const [k, v] = b.dataset.sos.split(':');
    const an = (k === 'ansicht' && _sos.ansicht === v) ||
               (k === 'tempo' && String(_sos.tempo) === v);
    b.classList.toggle('primary', an);
  });
}

function _sosHTML() {
  const opt = _SOS_P.map((p, i) => `<option value="${i}">${p.n}</option>`).join('');
  return `<div class="sim-box sim-box-wide fpm-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🪐 Acht Planeten, zwei Sorten</h3>
    <div class="fpm-note" style="margin-top:2px">Vier kleine Gesteinsplaneten innen, außen zwei Gasriesen und zwei Eisriesen. Größen und Abstände passen nie gleichzeitig auf einen Bildschirm – schalte um und sieh selbst.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="sosAnim" width="480" height="330" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" data-sos="ansicht:bahnen"    onclick="_sosSetzen('ansicht','bahnen')">Umlauf</button>
          <button class="sim-btn"         data-sos="ansicht:steckbrief" onclick="_sosSetzen('ansicht','steckbrief')">Steckbrief</button>
          <button class="sim-btn"         data-sos="ansicht:groessen"  onclick="_sosSetzen('ansicht','groessen')">Größen</button>
          <button class="sim-btn"         data-sos="ansicht:abstaende" onclick="_sosSetzen('ansicht','abstaende')">Abstände</button>
        </div>
        <div class="sim-btn-row" style="margin-top:4px">
          <span class="fpm-label" style="margin-right:4px">Tempo</span>
          <button class="sim-btn primary" data-sos="tempo:0" onclick="_sosSetzen('tempo',0)">langsam</button>
          <button class="sim-btn"         data-sos="tempo:1" onclick="_sosSetzen('tempo',1)">schnell</button>
          <button class="sim-btn"         data-sos="tempo:2" onclick="_sosSetzen('tempo',2)">sehr schnell</button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Planet wählen</div>
        <select class="sim-select" style="margin-top:4px;width:100%"
                onchange="_sosSetzen('planet', +this.value)">${opt}</select>
        <div class="lmp-status on" id="sosStatus" style="margin-top:8px"></div>
        <div class="fpm-note" style="margin-top:10px">Zwischen Mars und Jupiter liegt der <b>Asteroidengürtel</b>. <b>Pluto</b> ist seit 2006 kein Planet mehr, sondern ein Zwergplanet. Im Weltraum herrschen etwa <b>−270 °C</b>.</div>
      </div>
    </div>
  </div>`;
}

function _sosStatus() {
  const el = document.getElementById('sosStatus'); if (!el || !_sos) return;
  const p = _SOS_P[_sos.gewaehlt], erde = _SOS_P[2];
  const mal = (p.d / erde.d).toFixed(p.d > erde.d ? 1 : 2).replace('.', ',');
  // Die Drehung gehoert in die Kurzinfo: nur so faellt ohne Umweg ueber den
  // Steckbrief auf, dass Venus und Uranus rueckwaerts laufen. Und Venus
  // braucht fuer eine Drehung laenger als fuer einen ganzen Umlauf - das wird
  // aus den beiden Zahlen berechnet, nicht als Merksatz hingeschrieben.
  const tagLaenger = Math.abs(p.rot) / 24 > p.u * 365.25;
  el.innerHTML =
    `<b>${p.n}</b> – ${p.typ}${p.gas ? ', keine feste Oberfläche' : ', feste Oberfläche'}<br>` +
    `Durchmesser ${p.d.toLocaleString('de-DE')} km (${mal}-mal Erde)<br>` +
    `Abstand ${String(p.a).replace('.', ',')} AE · Umlauf ${_sosUmlauf(p)}<br>` +
    `Eine Drehung ${_sosTag(p)}<br>` +
    `Temperatur ${_sosTemp(p)}<br>` +
    `Dichte ${String(p.rho).replace('.', ',')} g/cm³` + (p.rho < 1 ? ' – <b>leichter als Wasser</b>' : '') + '<br>' +
    `${p.mond === 0 ? 'kein Mond' : p.mond === 1 ? '1 Mond' : p.mond + ' Monde'} · ${p.atmo}` +
    (tagLaenger ? '<br><b>Ein Tag dauert hier länger als ein Jahr!</b>' : '');
}

/* Umlaufzeit so schreiben, wie ein Kind sie liest: kurze Zeiten in Tagen,
   lange in Jahren und Tagen. 11,86 Jahre sagt niemandem etwas. */
function _sosUmlauf(p) {
  if (p.u < 1) return Math.round(p.u * 365.25) + ' Tage';
  const j = Math.floor(p.u), tage = Math.round((p.u - j) * 365.25);
  return j + (j === 1 ? ' Jahr' : ' Jahre') + (tage ? ' ' + tage + ' Tage' : '');
}
function _sosTemp(p) {
  return p.tmin === p.tmax ? p.tmin + ' °C'
       : p.tmin + ' °C bis ' + p.tmax + ' °C';
}
/* Rotationsdauer: negativ heisst rueckwaerts. Venus dreht sich so langsam,
   dass ein Tag dort laenger dauert als ihr Jahr - das gehoert in den Steckbrief. */
function _sosTag(p) {
  const h = Math.abs(p.rot);
  const s = h < 48 ? h.toFixed(1).replace('.', ',') + ' Stunden'
                   : (h / 24).toFixed(0) + ' Tage';
  return s + (p.rot < 0 ? ' (rückwärts)' : '');
}





function _sosUpdate(dt) {
  if (!_sos) return;
  _sos.tAnim += dt;
  _sos.jahre += _SOS_TEMPO[_sos.tempo].jps * dt;
}

/* Steckbrief: der Planet aufgeschnitten, daneben seine Daten.
   Das Schulbuch zeigt so einen Schnitt als starres Bild. Hier dreht sich der
   Planet, der Keil oeffnet und schliesst sich langsam, und die Schichten sind
   beschriftet - man sieht also, dass der Schnitt durch eine Kugel geht. */
/* Steckbrief: der Planet aufgeschnitten, daneben seine Daten.
   Das Schulbuch zeigt so einen Schnitt als starres Bild. Hier dreht sich der
   Planet, der Keil oeffnet und schliesst sich langsam, und die Schichten sind
   beschriftet - man sieht also, dass der Schnitt durch eine Kugel geht. */
function _sosSteckbrief(ctx, W, H, p, t) {
  const cx = 118, cy = 121, R = 80;

  /* Drehtempo aus der echten Rotationsdauer. Die reicht von 9,9 Stunden
     (Jupiter) bis 5832 Stunden (Venus) - das Verhaeltnis 1:589 waere linear
     nicht darstellbar, Venus stuende still. Die Wurzelkennlinie staucht das
     Verhaeltnis auf etwa 1:7, haelt aber die Reihenfolge ein: Jupiter wirbelt,
     Venus kriecht. Vorher drehten sich ALLE Planeten gleich schnell - direkt
     neben der Zeile "Eine Drehung: 243 Tage". Vorzeichen = Drehrichtung. */
  const tempoD = 0.55 * Math.pow(9.9 / Math.abs(p.rot), 0.3);
  const drehung = t * tempoD * (p.rot < 0 ? -1 : 1);

  // Keil atmet zwischen 26 und 52 Grad
  const halb = (26 + 13 * (1 + Math.sin(t * 0.55))) * Math.PI / 180;
  const a1 = -Math.PI / 2 - halb, a2 = -Math.PI / 2 + halb;

  /* Uranus liegt auf der Seite - sein Ring steht deshalb fast senkrecht.
     Flach gezeichnet waere er ein zweiter Saturn und wuerde dem Satz
     "Liegt auf der Seite" widersprechen. */
  const steil = p.n === 'Uranus';
  const ringA = R * 1.42;
  const ringHalb = vorne => {
    const a0 = steil ? -Math.PI / 2 : 0;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(steil ? 0.26 : 1, steil ? 1 : 0.26);
    ctx.strokeStyle = vorne ? 'rgba(238,222,180,0.8)' : 'rgba(238,222,180,0.38)';
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.arc(0, 0, ringA, vorne ? a0 : a0 + Math.PI, vorne ? a0 + Math.PI : a0 + 6.283);
    ctx.stroke();
    ctx.restore();
  };
  // Hintere Ringhaelfte VOR den Planeten - sie verschwindet dann hinter ihm.
  if (p.ring) ringHalb(false);

  // ── Aussenansicht mit Oberflaeche ──────────────────────────────────
  ctx.save();
  ctx.beginPath(); ctx.arc(cx, cy, R, 0, 6.283); ctx.clip();
  _wrKoerper(ctx, cx, cy, R, p.f, { lx: -0.45, ly: -0.45, rand: false });
  if (p.gas) {
    // Waagerechte Wolkenbaender. Sie liegen fest - Baender wandern nicht mit
    // der Drehung, die Wirbel darin schon (siehe unten).
    ctx.globalAlpha = 0.5;
    for (let i = -8; i <= 8; i++) {
      const yb = cy + i * R / 9;
      const b = R / 11 * (0.5 + 0.5 * Math.abs(Math.sin(i * 1.7)));
      ctx.fillStyle = i % 2 ? p.f[1] : p.f[0];
      ctx.beginPath();
      ctx.ellipse(cx, yb, R, b, 0, 0, 6.283);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  /* Krater (Gesteinsplanet) bzw. Wirbel (Gasplanet). Sie sitzen auf festen
     Laengen- und Breitengraden und werden auf die Kugel projiziert.
     Wichtig ist die Tiefe z: nur was z > 0 hat, liegt auf der uns zugewandten
     Seite. Ohne diese Pruefung wandert ein Fleck bis zum Rand und dann wieder
     zurueck - das sieht aus wie Schaukeln, nicht wie Drehen.
     Alle Zufallszahlen werden VOR dem Ueberspringen gezogen, sonst bekaeme
     jeder Fleck in jedem Bild eine andere Groesse und das Bild flimmert. */
  const rnd = _wrRnd(p.n.length * 37 + 5);
  const anz = p.gas ? 7 : 22;
  for (let i = 0; i < anz; i++) {
    const lam = rnd() * 6.283;
    const phi = (rnd() - 0.5) * (p.gas ? 1.8 : 2.4);
    const gr = 0.4 + rnd();
    const w = lam + drehung;
    const z = Math.cos(w) * Math.cos(phi);
    if (z <= 0.06) continue;                       // Rueckseite
    const px = cx + Math.sin(w) * Math.cos(phi) * R * 0.92;
    const py = cy + Math.sin(phi) * R * 0.92;
    ctx.fillStyle = p.gas ? 'rgba(255,255,255,0.14)' : 'rgba(0,0,0,0.16)';
    ctx.beginPath();
    // am Rand gestaucht (mal z), damit die Kugel raeumlich bleibt
    ctx.ellipse(px, py, R * 0.09 * gr * z, R * 0.07 * gr, 0, 0, 6.283);
    ctx.fill();
  }
  if (p.n === 'Jupiter') {
    // Der Grosse Rote Fleck auf der Suedhalbkugel - an ihm sieht man die
    // Drehrichtung am deutlichsten.
    const w = 1.1 + drehung, phi = 0.36;
    const z = Math.cos(w) * Math.cos(phi);
    if (z > 0.06) {
      ctx.fillStyle = 'rgba(188,84,52,0.75)';
      ctx.beginPath();
      ctx.ellipse(cx + Math.sin(w) * Math.cos(phi) * R * 0.9, cy + Math.sin(phi) * R * 0.9,
                  R * 0.17 * z, R * 0.085, 0, 0, 6.283);
      ctx.fill();
    }
  }
  ctx.restore();

  // ── Der aufgeschnittene Keil ───────────────────────────────────────
  ctx.save();
  ctx.beginPath(); ctx.moveTo(cx, cy); ctx.arc(cx, cy, R, a1, a2); ctx.closePath();
  ctx.clip();
  let r = R;
  p.schicht.forEach(([name, farbe, anteil]) => {
    ctx.fillStyle = farbe;
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, 6.283); ctx.fill();
    r -= R * anteil;
  });
  // Schnittflaechen leicht abdunkeln, damit der Keil Tiefe bekommt
  const sg = ctx.createLinearGradient(cx, cy - R, cx, cy);
  sg.addColorStop(0, 'rgba(0,0,0,0)'); sg.addColorStop(1, 'rgba(0,0,0,0.3)');
  ctx.fillStyle = sg;
  ctx.beginPath(); ctx.moveTo(cx, cy); ctx.arc(cx, cy, R, a1, a2); ctx.closePath(); ctx.fill();
  ctx.restore();

  // Kanten des Keils
  ctx.strokeStyle = 'rgba(255,255,255,0.5)'; ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(cx, cy); ctx.lineTo(cx + Math.cos(a1) * R, cy + Math.sin(a1) * R);
  ctx.moveTo(cx, cy); ctx.lineTo(cx + Math.cos(a2) * R, cy + Math.sin(a2) * R);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,0.22)';
  ctx.beginPath(); ctx.arc(cx, cy, R, 0, 6.283); ctx.stroke();

  if (p.saum) _wrGlanz(ctx, cx, cy, R * 1.3, p.saum, 0.3);
  // Vordere Ringhaelfte zuletzt - sie laeuft vor dem Planeten vorbei.
  if (p.ring) ringHalb(true);

  // ── Schichten benennen ─────────────────────────────────────────────
  // feste Hoehe, damit der senkrechte Uranus-Ring nicht in die Namen ragt
  let ly = 250;
  p.schicht.forEach(([name, farbe]) => {
    ctx.fillStyle = farbe;
    ctx.beginPath(); ctx.arc(16, ly - 3.5, 4.5, 0, 6.283); ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.35)'; ctx.lineWidth = 0.8; ctx.stroke();
    _wrText(ctx, 27, ly, name, { align: 'left', font: '9.5px system-ui, sans-serif' });
    ly += 15;
  });

  // ── Datenblock ─────────────────────────────────────────────────────
  const dx = 246;
  _wrText(ctx, dx, 40, p.n, { align: 'left', font: '700 21px system-ui, sans-serif', farbe: '#fff7e6' });
  _wrText(ctx, dx, 58, p.typ + (p.gas ? ' – keine feste Oberfläche' : ' – feste Oberfläche'),
          { align: 'left', font: '10px system-ui, sans-serif',
            farbe: p.typ === 'Eisriese' ? '#a9dced' : p.typ === 'Gasriese' ? '#e8cfa4' : '#f0c69a' });
  const zeilen = [
    ['Durchmesser', p.d.toLocaleString('de-DE') + ' km'],
    ['Abstand zur Sonne', String(p.a).replace('.', ',') + ' AE'],
    ['Ein Umlauf', _sosUmlauf(p)],
    ['Eine Drehung', _sosTag(p)],
    ['Temperatur', _sosTemp(p)],
    ['Dichte', String(p.rho).replace('.', ',') + ' g/cm³' + (p.rho < 1 ? '  ⟵ schwimmt' : '')],
    ['Monde', p.mond === 0 ? 'keiner' : String(p.mond)],
    ['Lufthülle', p.atmo],
  ];
  let y = 80;
  zeilen.forEach(([k, v], i) => {
    if (i % 2 === 0) { ctx.fillStyle = 'rgba(255,255,255,0.045)'; ctx.fillRect(dx - 6, y - 11, W - dx - 10, 19); }
    _wrText(ctx, dx, y, k, { align: 'left', font: '9.5px system-ui, sans-serif', farbe: '#93a4c8' });
    /* Der Wert wird notfalls kleiner gesetzt. "sehr dicht, fast nur
       Kohlenstoffdioxid" ist rechtsbuendig sonst 205 px breit und schiebt
       sich quer durch das Wort "Lufthülle". */
    ctx.font = '9.5px system-ui, sans-serif';
    const platz = W - 14 - dx - ctx.measureText(k).width - 10;
    let vf = 10.5;
    ctx.font = '600 ' + vf + 'px system-ui, sans-serif';
    while (vf > 8 && ctx.measureText(v).width > platz) {
      vf -= 0.5;
      ctx.font = '600 ' + vf + 'px system-ui, sans-serif';
    }
    _wrText(ctx, W - 14, y, v, { align: 'right', font: '600 ' + vf + 'px system-ui, sans-serif' });
    y += 19;
  });

  // ── Temperaturband: von -270 (Weltraum) bis +500 ────────────────────
  const bx = dx, bw = W - dx - 14, byy = y + 12;
  const skala = c => bx + (Math.max(-270, Math.min(500, c)) + 270) / 770 * bw;
  const tg = ctx.createLinearGradient(bx, 0, bx + bw, 0);
  tg.addColorStop(0, '#2b4a8f'); tg.addColorStop(0.35, '#57a3c9');
  tg.addColorStop(0.55, '#e8d48a'); tg.addColorStop(1, '#c94a2a');
  ctx.fillStyle = tg; ctx.fillRect(bx, byy, bw, 7);
  ctx.fillStyle = 'rgba(255,255,255,0.85)';
  const x1 = skala(p.tmin), x2 = skala(p.tmax);
  ctx.fillRect(x1 - 1, byy - 3, Math.max(2.5, x2 - x1), 13);
  _wrText(ctx, bx, byy + 22, '−270 °C', { align: 'left', font: '8.5px system-ui, sans-serif', farbe: '#7f8ca8' });
  _wrText(ctx, bx + bw, byy + 22, '+500 °C', { align: 'right', font: '8.5px system-ui, sans-serif', farbe: '#7f8ca8' });

  /* Die eine Besonderheit, die man sich merken soll - berechnet, nicht
     eingetippt: Venus dreht sich langsamer, als sie die Sonne umrundet,
     Uranus dreht rueckwaerts, Saturn ist leichter als Wasser. */
  const bes = Math.abs(p.rot) / 24 > p.u * 365.25 ? 'Ein Tag dauert länger als ein Jahr!'
            : p.rot < 0 ? 'Dreht sich rückwärts – als einziger Riese.'
            : p.rho < 1 ? 'Leichter als Wasser – würde schwimmen.'
            : '';
  if (bes) _wrText(ctx, bx + bw / 2, byy + 48, bes,
                   { font: '600 10px system-ui, sans-serif', farbe: '#ffd98a' });

  _wrText(ctx, W / 2, H - 10, p.kurz, { font: '10.5px system-ui, sans-serif', farbe: '#cfd8ee' });
}

function _sosDraw(ctx, cv) {
  if (!_sos) return;
  const W = cv.width, H = cv.height, t = _sos.tAnim;
  _wrHimmel(ctx, cv, t, { oben: '#050a1c', unten: '#01030c', dichte: 0.9, seed: 12 });

  if (_sos.ansicht === 'steckbrief') {
    _sosSteckbrief(ctx, W, H, _SOS_P[_sos.gewaehlt], t);
    return;
  }

  /* Ring in zwei Haelften: die hintere kommt VOR den Planeten und verschwindet
     hinter ihm, die vordere danach. Als ganze Ellipse gezeichnet lief das Band
     quer ueber die Kugel - der Ring sass also vor UND hinter dem Planeten.
     steil = Uranus: er liegt auf der Seite, sein Ring steht fast senkrecht. */
  const ringHalb = (x, y, rr, steil, vorne, breite) => {
    const a0 = steil ? -Math.PI / 2 : 0;
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(steil ? 0.28 : 1, steil ? 1 : 0.3);
    ctx.strokeStyle = vorne ? 'rgba(238,222,180,0.8)' : 'rgba(238,222,180,0.4)';
    ctx.lineWidth = breite;
    ctx.beginPath();
    ctx.arc(0, 0, rr * 2, vorne ? a0 : a0 + Math.PI, vorne ? a0 + Math.PI : a0 + 6.283);
    ctx.stroke();
    ctx.restore();
  };

  if (_sos.ansicht === 'bahnen') {
    const cx = W / 2, cy = H / 2;
    // Bahnen
    _SOS_P.forEach((p, i) => {
      const r = _sosR(p.a);
      ctx.strokeStyle = i === _sos.gewaehlt ? 'rgba(255,225,150,0.55)' : 'rgba(150,170,210,0.16)';
      ctx.lineWidth = i === _sos.gewaehlt ? 1.4 : 1;
      ctx.beginPath(); ctx.arc(cx, cy, r, 0, 6.283); ctx.stroke();
    });
    // Asteroidenguertel zwischen Mars und Jupiter (2,1 bis 3,3 AE)
    const rA = (_sosR(2.1) + _sosR(3.3)) / 2, dA = (_sosR(3.3) - _sosR(2.1)) / 2;
    const ra = _wrRnd(5);
    ctx.fillStyle = 'rgba(190,180,160,0.5)';
    for (let i = 0; i < 130; i++) {
      const w = ra() * 6.283 + t * 0.04, r = rA + (ra() - 0.5) * 2 * dA;
      ctx.beginPath(); ctx.arc(cx + Math.cos(w) * r, cy + Math.sin(w) * r, 0.7, 0, 6.283); ctx.fill();
    }
    // Sonne
    _wrGlanz(ctx, cx, cy, 44, '255,214,120', 0.55);
    _wrKoerper(ctx, cx, cy, 13, ['#fffdf0', '#ffd257', '#f0902a'], { rand: false });
    // Planeten mit ihren echten relativen Bahngeschwindigkeiten
    _SOS_P.forEach((p, i) => {
      const r = _sosR(p.a);
      const w = (_sos.jahre / p.u) * 6.283 + i * 1.1;
      const x = cx + Math.cos(w) * r, yy = cy + Math.sin(w) * r;
      // Groesse hier nur nach Sorte, damit die Kleinen sichtbar bleiben
      const rr = p.gas ? (p.d > 100000 ? 6.5 : 5.4) : 3.4;
      const steil = p.n === 'Uranus';
      if (i === _sos.gewaehlt) _wrGlanz(ctx, x, yy, rr * 4.5, '255,235,170', 0.5);
      if (p.ring) ringHalb(x, yy, rr, steil, false, 1.6);
      _wrKoerper(ctx, x, yy, rr, p.f, { lx: (cx - x) / r, ly: (cy - yy) / r, saum: p.saum });
      if (p.ring) ringHalb(x, yy, rr, steil, true, 1.6);
    });
    // Hinweis auf BEIDE Verzerrungen: sonst haelt ein Kind Merkur und Erde
    // fuer gleich gross, weil sie hier gleich gross gezeichnet sind.
    _wrText(ctx, 10, 16, 'Abstände gestaucht, Größen nicht maßstäblich',
            { align: 'left', font: '9.5px system-ui, sans-serif', farbe: '#93a4c8' });
    const j = _sos.jahre;
    _wrText(ctx, W - 10, 16, 'seit dem Start: ' + (j < 10 ? j.toFixed(1).replace('.', ',') : Math.round(j)) + ' Erdjahre',
            { align: 'right', font: '10px system-ui, sans-serif' });

  } else if (_sos.ansicht === 'groessen') {
    /* Alle acht im gleichen Massstab. Der Massstab wird aus dem verfuegbaren
       Platz berechnet, damit KEIN Mindestradius noetig ist: sobald man Merkur
       auf 1,6 px hochzieht, ist er so gross wie Mars und fast so gross wie die
       Erde - genau die Fehlvorstellung, die diese Ansicht widerlegen soll. */
    const y = H / 2, luecke = 10, xStart = 78, xEnde = W - 10;
    const summe = _SOS_P.reduce((s, p) => s + p.d, 0);
    // Saturn braucht links und rechts je einen Planetenradius fuer den Ring
    const sk = (xEnde - xStart - 7 * luecke) / (summe + _SOS_P[5].d);

    // Sonnenrand im GLEICHEN Massstab: 1 392 700 km Durchmesser, also fast das
    // Zehnfache von Jupiter. Vorher war der Bogen 34 % zu gross gezeichnet.
    const sR = 1392700 / 2 * sk, sx = 30 - sR;
    const sg = ctx.createRadialGradient(sx, y, sR * 0.15, sx, y, sR);
    sg.addColorStop(0, '#fff8d8'); sg.addColorStop(0.82, '#ffd257'); sg.addColorStop(1, '#f0902a');
    ctx.fillStyle = sg;
    ctx.beginPath(); ctx.arc(sx, y, sR, 0, 6.283); ctx.fill();
    _wrGlanz(ctx, 30, y, 45, '255,214,120', 0.4);
    // Beschriftung neben den Rand statt darauf: dunkler Text auf dem gelben
    // Bogen waere am Uebergang zum schwarzen Himmel nicht mehr zu lesen.
    ctx.strokeStyle = 'rgba(255,214,120,0.5)'; ctx.lineWidth = 0.8;
    ctx.beginPath(); ctx.moveTo(50, y - 38); ctx.lineTo(33, y - 16); ctx.stroke();
    _wrText(ctx, 54, y - 42, 'Sonne', { font: '600 10.5px system-ui, sans-serif', farbe: '#ffd98a' });

    let x = xStart;
    _SOS_P.forEach((p, i) => {
      const rr = p.d * sk / 2;
      const steil = p.n === 'Uranus';
      if (p.ring && !steil) x += rr;          // Platz fuer die linke Ringhaelfte
      const cxp = x + rr;
      if (i === _sos.gewaehlt) _wrGlanz(ctx, cxp, y, rr * 2.4 + 16, '255,235,170', 0.45);
      const rb = Math.max(1.4, rr * 0.16);
      if (p.ring) ringHalb(cxp, y, rr, steil, false, rb);
      _wrKoerper(ctx, cxp, y, rr, p.f, { saum: p.saum });
      if (p.ring) ringHalb(cxp, y, rr, steil, true, rb);
      /* Die vier Gesteinsplaneten sind hier nur 3 bis 8 px breit - ihre Namen
         wuerden sich nebeneinander ueberlappen. Deshalb stehen sie gestaffelt
         untereinander, jeder an einer duennen Fuehrungslinie. */
      const lb = i < 4 ? y + 26 + i * 14 : y + (steil ? rr * 2 : rr) + 14;
      if (i < 4) {
        ctx.strokeStyle = 'rgba(150,170,210,0.4)'; ctx.lineWidth = 0.8;
        ctx.beginPath(); ctx.moveTo(cxp, y + rr + 2); ctx.lineTo(cxp, lb - 9); ctx.stroke();
      }
      _wrText(ctx, cxp, lb, p.n, { font: '9.5px system-ui, sans-serif' });
      x += rr * 2 + luecke + (p.ring && !steil ? rr : 0);
    });
    _wrText(ctx, W / 2, H - 12, 'Größen im gleichen Maßstab – die Abstände stimmen hier NICHT',
            { font: '10px system-ui, sans-serif', farbe: '#93a4c8' });

  } else {
    // Abstaende im gleichen Massstab: eine Linie von der Sonne bis Neptun.
    const y = H / 2, x0 = 30, x1 = W - 24;
    const sk = (x1 - x0) / _SOS_P[7].a;
    ctx.strokeStyle = 'rgba(150,170,210,0.3)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(x0, y); ctx.lineTo(x1, y); ctx.stroke();

    /* Ein Lichtblitz laeuft von der Sonne los und startet alle 25 s neu.
       Er ist nach 8 Minuten bei der Erde und braucht danach noch gut vier
       Stunden bis Neptun - dieses Verhaeltnis macht die Strecke begreifbar,
       und die Ansicht steht nicht mehr voellig still. */
    const lauf = Math.min(1, (t % 25) / 22);
    const xl = x0 + lauf * (x1 - x0);
    _wrSpur(ctx, [[x0, y], [xl, y]], '255,240,190', 1.2);
    _wrGlanz(ctx, xl, y, 13, '255,245,200', 0.8);
    const sek = lauf * _SOS_P[7].a * 499;       // 499 s = Licht bis zur Erde
    const zeit = sek < 90 ? Math.round(sek) + ' Sekunden'
               : sek < 5400 ? Math.round(sek / 60) + ' Minuten'
               : Math.floor(sek / 3600) + ' Stunden ' + Math.round(sek % 3600 / 60) + ' Minuten';
    _wrText(ctx, W / 2, 20, 'Das Licht der Sonne ist unterwegs: ' + zeit,
            { font: '10.5px system-ui, sans-serif', farbe: '#ffe9b0' });

    _wrGlanz(ctx, x0, y, 26, '255,214,120', 0.6);
    _wrKoerper(ctx, x0, y, 4.5, ['#fffdf0', '#ffd257', '#f0902a'], { rand: false });

    /* Beschriftung gestaffelt. In diesem Massstab liegen Merkur, Venus, Erde
       und Mars innerhalb von 16 Pixeln - nebeneinander waeren ihre Namen ein
       einziger Brei. Jeder Name sucht sich die erste Etage, in der links von
       ihm noch nichts steht, und wird mit einer duennen Linie angebunden. */
    const etagen = [-26, 26, -44, 44, -62, 62];
    const belegt = etagen.map(() => -999);
    const marke = (mx, name) => {
      ctx.font = '9.5px system-ui, sans-serif';
      const b = ctx.measureText(name).width;
      let e = 0;
      while (e < etagen.length - 1 && belegt[e] + 7 > mx - b / 2) e++;
      belegt[e] = mx + b / 2;
      const off = etagen[e], s = off < 0 ? -1 : 1;
      ctx.strokeStyle = 'rgba(150,170,210,0.4)'; ctx.lineWidth = 0.8;
      ctx.beginPath(); ctx.moveTo(mx, y + s * 7); ctx.lineTo(mx, y + off - s * 8); ctx.stroke();
      _wrText(ctx, mx, y + off + (s < 0 ? 0 : 3), name, { font: '9.5px system-ui, sans-serif' });
    };
    marke(x0, 'Sonne');
    _SOS_P.forEach((p, i) => {
      const x = x0 + p.a * sk;
      const rr = i === _sos.gewaehlt ? 4 : 2.6;
      if (i === _sos.gewaehlt) _wrGlanz(ctx, x, y, 18, '255,235,170', 0.6);
      _wrKoerper(ctx, x, y, rr, p.f, { rand: false });
      marke(x, p.n);
    });
    _wrText(ctx, W / 2, H - 12, 'Abstände im gleichen Maßstab – die Planeten wären hier unsichtbar klein',
            { font: '10px system-ui, sans-serif', farbe: '#93a4c8' });
  }
}


// ═══ PLANETENBAHN ════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════════════
// PLANETENBAHN – "Warum fallen die Planeten nicht in die Sonne?"
// Die Bahn wird wirklich gerechnet: a = GM/r² zur Sonne hin, integriert mit
// Velocity-Verlet. Verlet ist hier Pflicht und nicht Geschmackssache - mit
// einfachem Euler waechst die Bahnenergie von Runde zu Runde, der "Kreis"
// spiralte nach aussen und genau die Beobachtung, um die es auf der Heftseite
// geht ("bei welcher Einstellung ist die Bahn fast ein Kreis?"), waere kaputt.
//
// Einheiten: Laenge in AE, Zeit in Jahr/2π, GM = 1. Dann ist die Kreisbahn bei
// r = 1 genau v = 1, und v = 1 entspricht 29,785 km/s - der echten Bahn-
// geschwindigkeit der Erde. So stehen auf dem Regler richtige km/s und nicht
// erfundene Einheiten, und die Bereiche des Hefts liegen an echten Zahlen:
//   stuerzt hinein  bis etwa 15 km/s
//   fast ein Kreis  bei 29,8 km/s  (= Mitte des Reglers 6…54)
//   Ellipse         darueber
//   entkommt        ab 42,1 km/s   (= √2 · 29,785)
// ═══════════════════════════════════════════════════════════════════════════

const _PBN_VK    = 29.785;   // km/s – Kreisbahngeschwindigkeit bei 1 AE
const _PBN_VENT  = 42.122;   // km/s – Entkommen, = √2 · _PBN_VK
const _PBN_R0    = 1;        // AE   – Startabstand, immer gleich
const _PBN_RS    = 0.16;     // AE   – Sonnenradius im Bild UND Trefferradius.
                             //        Beides derselbe Wert, damit "trifft die
                             //        Sonne" genau dann gemeldet wird, wenn man
                             //        den Treffer auch sieht.
const _PBN_TEMPO = 0.9;      // Zeiteinheiten je echter Sekunde -> Kreis ≈ 7 s

let _pbn = null;
/* Die ganze Bahnform steht schon vor dem ersten Rechenschritt fest - der Start
   quer zur Verbindungslinie ist immer ein Apsidenpunkt. Deshalb wird sie hier
   geschlossen ausgerechnet: nur so kann die Statusspalte "kommt zurueck" oder
   "kommt nicht zurueck" sicher sagen, ohne stundenlang mitrechnen zu muessen. */
function _pbnBahn(vkms) {
  const f  = vkms / _PBN_VK;          // v in Einheiten der Kreisbahn
  const f2 = f * f;
  const entkommt = f2 >= 2;           // v ≥ √(2GM/r)
  // vis-viva: 1/a = (2 - f²)/r0 ; senkrechter Start -> e = |1 - f²|
  const a     = entkommt ? Infinity : _PBN_R0 / (2 - f2);
  const e     = entkommt ? f2 - 1 : Math.abs(1 - f2);
  const rPeri = entkommt ? _PBN_R0 : a * (1 - e);
  const rApo  = entkommt ? Infinity : a * (1 + e);
  const T     = entkommt ? Infinity : Math.pow(a, 1.5);   // Jahre (3. Kepler)
  const sturz = !entkommt && rPeri <= _PBN_RS;
  let form;
  if (sturz)          form = 'stürzt in die Sonne';
  else if (entkommt)  form = 'entkommt';
  else if (e <= 0.15) form = 'fast ein Kreis';
  else if (e < 0.35)  form = 'Ellipse';
  else                form = 'lang gezogene Ellipse';
  return { f, e, a, rPeri, rApo, T, entkommt, sturz, form };
}
/* Massstab: die vier Zeilen der Hefttabelle passen alle bei 66 px je AE ins
   Bild. Nur die schmale Zone dicht unter der Entkommgrenze wird groesser als
   das Bild - dort wird herausgezoomt statt den Planeten minutenlang unsichtbar
   draussen laufen zu lassen. Der Massstabsbalken unten links macht den Wechsel
   sichtbar, sonst haelte man eine kleiner gezeichnete Ellipse fuer eine engere. */
function _pbnSkala(b) {
  if (b.entkommt || !isFinite(b.rApo)) return 66;
  return Math.max(26, Math.min(66, 180 / b.rApo));
}
function _pbnInit() {
  _pbn = {
    v: 6,                 // Regler startet ganz klein - genau Schritt 1 im Heft
    x: _PBN_R0, y: 0, vx: 0, vy: 0,
    t: 0, tLauf: 0, tAnim: 0,
    spur: [], spurV: 6, geist: [], zeigeGeist: true,
    raffer: 1, skala: 66, phase: 'lauf', pause: 0, draussen: 0, blitz: 0,
    ergebnis: null,
    W: 460, H: 300, cx: 251, cy: 152
  };
  _pbnStart();
}
/* Neuer Lauf. Wird auch automatisch aufgerufen, wenn der Planet die Sonne
   getroffen hat oder aus dem Bild gelaufen ist - das Bild bleibt dadurch immer
   in Bewegung, ohne dass jemand einen Knopf druecken muss. */
function _pbnStart() {
  if (!_pbn) return;
  // Die Spur des vorigen Laufs bleibt blass stehen, aber nur wenn sie zu einer
  // ANDEREN Einstellung gehoert. Sonst laege sie deckungsgleich unter der neuen
  // und man saehe ausgerechnet den Unterschied nicht, um den es geht.
  if (_pbn.zeigeGeist && _pbn.spur.length > 8 && _pbn.spurV !== _pbn.v) {
    const q = [], schritt = Math.max(1, Math.floor(_pbn.spur.length / 120));
    for (let i = 0; i < _pbn.spur.length; i += schritt) q.push(_pbn.spur[i]);
    _pbn.geist = q;
  }
  const b = _pbnBahn(_pbn.v);
  _pbn.ergebnis = b;
  _pbn.skala = _pbnSkala(b);
  _pbn.x = _PBN_R0; _pbn.y = 0;
  _pbn.vx = 0; _pbn.vy = -b.f;      // senkrecht zur Verbindungslinie, im Bild nach oben
  _pbn.t = 0; _pbn.tLauf = 0; _pbn.draussen = 0; _pbn.blitz = 0;
  _pbn.phase = 'lauf'; _pbn.pause = 0;
  _pbn.spur = [[_PBN_R0, 0]];
  _pbn.spurV = _pbn.v;
  _pbnStatus();
}
function _pbnSetV(v) {
  if (!_pbn) return;
  _pbn.v = Math.round(+v);
  const l = document.getElementById('pbnVLbl');
  if (l) l.textContent = _fpmNum(_pbn.v, 0) + ' km/s';
  document.querySelectorAll('[data-pbn]').forEach(btn =>
    btn.classList.toggle('primary', +btn.dataset.pbn === _pbn.v));
  _pbnStart();                       // Heft: "jedes Mal neu starten"
}
/* Die vier Knoepfe sind genau die vier Zeilen der Hefttabelle. */
function _pbnWahl(v) {
  const s = document.getElementById('pbnV');
  if (s) s.value = v;
  _pbnSetV(v);
}
function _pbnRaffer() {
  if (!_pbn) return;
  _pbn.raffer = _pbn.raffer === 1 ? 4 : 1;
  const b = document.getElementById('pbnRafBtn');
  if (b) { b.textContent = '🕐 Zeitraffer ×' + _pbn.raffer; b.classList.toggle('primary', _pbn.raffer > 1); }
}
function _pbnGeist() {
  if (!_pbn) return;
  _pbn.zeigeGeist = !_pbn.zeigeGeist;
  if (!_pbn.zeigeGeist) _pbn.geist = [];
  const b = document.getElementById('pbnGeistBtn');
  if (b) { b.textContent = '👁 Vergleichsspur ' + (_pbn.zeigeGeist ? 'an' : 'aus'); b.classList.toggle('primary', _pbn.zeigeGeist); }
}
function _pbnHTML() {
  const knopf = (v, txt) =>
    `<button class="sim-btn${_pbn.v === v ? ' primary' : ''}" data-pbn="${v}" onclick="_pbnWahl(${v})">${txt}</button>`;
  return `<div class="sim-box sim-box-wide fpm-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🪐 Warum fallen die Planeten nicht in die Sonne?</h3>
    <div class="fpm-note" style="margin-top:2px">Der Planet startet immer <b>neben</b> der Sonne, im gleichen Abstand wie die Erde (1 AE). Sein Anschub geht <b>quer</b> zur Sonne – der grüne Pfeil zeigt ihn. Vergrößere die Startgeschwindigkeit Schritt für Schritt und sieh zu, was aus der Bahn wird.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="pbnAnim" width="460" height="300" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          ${knopf(6, '➊ ganz klein')}
          ${knopf(30, '➋ mittlerer Wert')}
          ${knopf(36, '➌ etwas darüber')}
          ${knopf(50, '➍ Gegenprobe groß')}
        </div>
        <div class="sim-btn-row" style="margin-top:4px">
          <button class="sim-btn primary" onclick="_pbnStart()">↺ neu starten</button>
          <button class="sim-btn" id="pbnRafBtn" onclick="_pbnRaffer()">🕐 Zeitraffer ×1</button>
          <button class="sim-btn primary" id="pbnGeistBtn" onclick="_pbnGeist()">👁 Vergleichsspur an</button>
        </div>
        <div class="phys-ctrl" style="margin-top:8px">
          <span class="phys-ctrl-label">Startgeschwindigkeit quer zur Sonne: <b id="pbnVLbl">${_fpmNum(_pbn.v, 0)} km/s</b></span>
          <input type="range" id="pbnV" min="6" max="54" step="1" value="${_pbn.v}"
            oninput="_pbnSetV(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
      </div>
      <div>
        <div class="fpm-label">Was wird aus der Bahn?</div>
        <div class="lmp-status" id="pbnStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Die Sonne zieht den Planeten die <b>ganze Zeit</b> zu sich – sie hört keinen Moment damit auf. Weil er zugleich <b>seitwärts</b> unterwegs ist, fällt er immerzu <b>an ihr vorbei</b> statt auf sie. Dieses ewige Vorbeifallen ist die Umlaufbahn.</div>
        <div class="fpm-note" style="margin-top:8px">Ist der Anschub zu klein, reicht das Vorbeifallen nicht – der Planet trifft die Sonne. Ist er sehr groß, zieht die Sonne zwar weiter an ihm, holt ihn aber nicht mehr zurück. Die Anziehung wird mit dem Abstand rasch schwächer: bei <b>doppeltem</b> Abstand nur noch <b>ein Viertel</b> so stark.</div>
        <div class="fpm-note" style="margin-top:8px">Sonne und Planet sind viel <b>größer gezeichnet</b>, als sie im Maßstab wären – sonst wären beide nur Pünktchen. Der Balken unten links zeigt, wie lang 1 AE gerade im Bild ist.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      ganz klein → stürzt hinein &nbsp;|&nbsp; <b>29,8 km/s</b> → fast ein Kreis &nbsp;|&nbsp; etwas mehr → lang gezogene Ellipse &nbsp;|&nbsp; ab <b>42,1 km/s</b> → weg für immer
    </p>
  </div>`;
}
function _pbnStatus() {
  const el = document.getElementById('pbnStatus');
  if (!el || !_pbn || !_pbn.ergebnis) return;
  const b = _pbn.ergebnis;
  const z = [];
  z.push('Bahnform: <b>' + b.form + '</b>');
  z.push('Anschub quer zur Sonne: <b>' + _fpmNum(_pbn.v, 0) + ' km/s</b>');
  if (b.sturz) {
    z.push('Der Anschub ist zu klein. Der Planet fällt an der Sonne nicht mehr vorbei – er trifft sie.');
    z.push('<b>Er kommt nicht wieder heraus.</b>');
  } else if (b.entkommt) {
    z.push('kleinster Abstand: <b>1,00 AE</b> (das ist der Start)');
    z.push('größter Abstand: <b>keiner</b> – er wird immer weiter');
    z.push('<b>Er kommt nicht zurück.</b>');
  } else {
    z.push('kleinster Abstand: <b>' + _fpmNum(b.rPeri, 2) + ' AE</b> · größter: <b>' +
           _fpmNum(b.rApo, b.rApo >= 20 ? 0 : 2) + ' AE</b>');
    z.push('ein Umlauf dauert <b>' + _fpmNum(b.T, b.T >= 20 ? 0 : 2) + ' Jahre</b>');
    z.push('<b>Er kommt zurück.</b>');
  }
  // Die beiden Grenzwerte kommen aus den Konstanten, nicht aus dem Text -
  // sonst driften Anzeige und Rechnung auseinander, sobald jemand GM aendert.
  z.push('<span style="opacity:.75">Für einen Kreis braucht er ' + _fpmNum(_PBN_VK, 1) +
         ' km/s · ab ' + _fpmNum(_PBN_VENT, 1) + ' km/s entkommt er.</span>');
  el.innerHTML = z.join('<br>');
  el.className = b.sturz ? 'lmp-status' : 'lmp-status on';
}
function _pbnUpdate(dt) {
  if (!_pbn) return;
  const rdt = Math.min(dt, 0.05);
  _pbn.tAnim += rdt;
  if (_pbn.blitz > 0) _pbn.blitz = Math.max(0, _pbn.blitz - rdt);

  if (_pbn.phase === 'ende') {
    // Kurz stehen lassen, damit man das Ergebnis liest - dann von selbst neu.
    _pbn.pause -= rdt;
    if (_pbn.pause <= 0) _pbnStart();
    return;
  }
  _pbn.tLauf += rdt;

  let rest = _PBN_TEMPO * _pbn.raffer * rdt;
  const minD = 3 / _pbn.skala;        // Spurpunkt erst nach etwa 3 Pixeln
  let n = 0;
  while (rest > 1e-7 && n++ < 600) {
    const r = Math.hypot(_pbn.x, _pbn.y);
    /* Schrittweite nach dem Abstand: dicht an der Sonne dreht sich die Bahn
       rasend (Winkelrate ~ r^-1,5). Mit einem festen Schritt schnitte die enge
       Kurve am Perihel ab und die Bahn spraenge auf eine falsche Ellipse. */
    const h = Math.min(0.0045, 0.0028 * Math.pow(Math.max(r, 0.06), 1.5), rest);

    // ── Velocity-Verlet: a = GM/r² zur Sonne, GM = 1 ──────────────────
    const k = -1 / (r * r * r);       // -GM/r³, mal Ortsvektor = Beschleunigung
    const ax = _pbn.x * k, ay = _pbn.y * k;
    _pbn.x += _pbn.vx * h + 0.5 * ax * h * h;
    _pbn.y += _pbn.vy * h + 0.5 * ay * h * h;
    const rn = Math.hypot(_pbn.x, _pbn.y);
    const kn = -1 / (rn * rn * rn);
    _pbn.vx += 0.5 * (ax + _pbn.x * kn) * h;
    _pbn.vy += 0.5 * (ay + _pbn.y * kn) * h;
    _pbn.t += h;
    rest -= h;

    const letzt = _pbn.spur[_pbn.spur.length - 1];
    if (!letzt || Math.hypot(_pbn.x - letzt[0], _pbn.y - letzt[1]) > minD) {
      _pbn.spur.push([_pbn.x, _pbn.y]);
      if (_pbn.spur.length > 260) _pbn.spur.shift();   // Spur bleibt kurz genug
    }
    if (rn <= _PBN_RS) {              // Treffer: der Planet stuerzt hinein
      _pbn.phase = 'ende'; _pbn.pause = 2.0; _pbn.blitz = 0.6;
      break;
    }
  }

  if (_pbn.phase === 'lauf') {
    const px = _pbn.cx + _pbn.x * _pbn.skala, py = _pbn.cy + _pbn.y * _pbn.skala;
    const drin = px > -10 && px < _pbn.W + 10 && py > -10 && py < _pbn.H + 10;
    _pbn.draussen = drin ? 0 : _pbn.draussen + rdt;
    /* Wer entkommt, ist nach gut zwei Sekunden weit weg - laenger auf ein leeres
       Bild zu schauen bringt nichts. Eine sehr lang gezogene Ellipse bekommt
       mehr Zeit, weil sie draussen umkehrt und zurueckkommen koennte. */
    if (_pbn.draussen > (_pbn.ergebnis.entkommt ? 2.2 : 5.0)) {
      _pbn.phase = 'ende'; _pbn.pause = 1.2;
    }
  }
}
function _pbnDraw(ctx, cv) {
  if (!_pbn || !_pbn.ergebnis) return;
  const W = cv.width, H = cv.height;
  const cx = Math.round(W * 0.545), cy = Math.round(H * 0.505);
  _pbn.W = W; _pbn.H = H; _pbn.cx = cx; _pbn.cy = cy;
  const s = _pbn.skala, b = _pbn.ergebnis;

  _wrHimmel(ctx, cv, _pbn.tAnim, { oben: '#070d22', unten: '#01020a', dichte: 1.0, seed: 19 });

  // ── Vergleichsspur des vorigen Laufs ────────────────────────────────
  // Sie ist in AE gespeichert, nicht in Pixeln - dadurch stimmt der Vergleich
  // auch dann noch, wenn fuer die neue Bahn herausgezoomt wurde.
  if (_pbn.zeigeGeist && _pbn.geist.length > 2) {
    ctx.save();
    ctx.setLineDash([4, 4]);
    ctx.strokeStyle = 'rgba(203,213,225,0.32)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    _pbn.geist.forEach((p, i) => {
      const x = cx + p[0] * s, y = cy + p[1] * s;
      i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
    });
    ctx.stroke();
    ctx.restore();
  }

  // ── die wirklich gelaufene Bahn ─────────────────────────────────────
  if (_pbn.spur.length > 1) {
    _wrSpur(ctx, _pbn.spur.map(p => [cx + p[0] * s, cy + p[1] * s]), '125,211,252', 1.9);
  }

  // ── Sonne ───────────────────────────────────────────────────────────
  const rs = Math.max(4, _PBN_RS * s);
  _wrGlanz(ctx, cx, cy, rs * 4.6, '255,206,110', 0.62);
  _wrKoerper(ctx, cx, cy, rs, ['#fffdf0', '#ffd257', '#f0902a'], { rand: false });
  if (_pbn.blitz > 0) _wrGlanz(ctx, cx, cy, rs * (5 + 8 * _pbn.blitz), '255,240,190', 0.25 + 0.5 * _pbn.blitz);

  // ── Startpunkt: immer derselbe Abstand, das gehoert zum Versuch ──────
  ctx.strokeStyle = 'rgba(148,163,184,0.55)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.arc(cx + _PBN_R0 * s, cy, 3.6, 0, 6.283); ctx.stroke();

  // ── Anschubpfeil: quer zur Sonne, Laenge zeigt die eingestellte Groesse ──
  if (_pbn.phase === 'lauf' && _pbn.tLauf < 1.6) {
    const al = Math.min(1, (1.6 - _pbn.tLauf) / 0.7);
    const x0 = cx + _PBN_R0 * s, y0 = cy - 7, L = 12 + 46 * (_pbn.v / 54);
    ctx.save();
    ctx.strokeStyle = 'rgba(134,239,172,' + (0.9 * al).toFixed(2) + ')';
    ctx.fillStyle = 'rgba(134,239,172,' + (0.9 * al).toFixed(2) + ')';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0, y0 - L); ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x0, y0 - L - 7); ctx.lineTo(x0 - 4.5, y0 - L + 1); ctx.lineTo(x0 + 4.5, y0 - L + 1);
    ctx.closePath(); ctx.fill();
    ctx.restore();
  }

  // ── Planet, oder ein Zeiger an den Bildrand, wenn er draussen ist ────
  const px = cx + _pbn.x * s, py = cy + _pbn.y * s;
  const drin = px > -10 && px < W + 10 && py > -10 && py < H + 10;
  const d = Math.hypot(px - cx, py - cy) || 1;
  if (_pbn.phase === 'lauf' && drin) {
    _wrGlanz(ctx, px, py, 17, '125,211,252', 0.55);
    _wrKoerper(ctx, px, py, 4.6, ['#dbeafe', '#60a5fa', '#1d4ed8'],
               { lx: (cx - px) / d, ly: (cy - py) / d, saum: '120,180,255' });
  } else if (_pbn.phase === 'lauf') {
    // Der Zeiger wandert am Rand mit und die Abstandszahl unten laeuft weiter -
    // so bleibt sichtbar, dass der Planet noch unterwegs ist.
    const ux = (px - cx) / d, uy = (py - cy) / d;
    const tX = ux !== 0 ? ((ux > 0 ? W - 16 : 16) - cx) / ux : 1e9;
    const tY = uy !== 0 ? ((uy > 0 ? H - 16 : 16) - cy) / uy : 1e9;
    const tt = Math.min(Math.abs(tX), Math.abs(tY));
    const mx = cx + ux * tt, my = cy + uy * tt;
    _wrGlanz(ctx, mx, my, 14, '125,211,252', 0.5);
    ctx.save();
    ctx.translate(mx, my); ctx.rotate(Math.atan2(uy, ux));
    ctx.fillStyle = 'rgba(147,197,253,0.95)';
    ctx.beginPath(); ctx.moveTo(7, 0); ctx.lineTo(-4, -5); ctx.lineTo(-4, 5);
    ctx.closePath(); ctx.fill();
    ctx.restore();
  }

  // ── Massstabsbalken: macht das Herauszoomen ehrlich sichtbar ─────────
  const bx = 14, by = H - 16;
  ctx.strokeStyle = 'rgba(203,213,225,0.75)'; ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(bx, by - 4); ctx.lineTo(bx, by + 4);
  ctx.moveTo(bx, by); ctx.lineTo(bx + s, by);
  ctx.moveTo(bx + s, by - 4); ctx.lineTo(bx + s, by + 4);
  ctx.stroke();

  // ── Beschriftung: nie mehr als vier Texte gleichzeitig ───────────────
  _wrText(ctx, bx + s / 2, by - 7, '1 AE', { font: '9.5px system-ui, sans-serif', farbe: '#cbd5e1' });
  _wrText(ctx, 10, 16, 'Anschub quer zur Sonne: ' + _fpmNum(_pbn.v, 0) + ' km/s',
          { align: 'left', font: '10px system-ui, sans-serif', farbe: '#cbd5e1' });
  _wrText(ctx, W - 10, 16, 'Bahn: ' + b.form,
          { align: 'right', font: '600 11px system-ui, sans-serif',
            farbe: b.sturz ? '#fca5a5' : b.entkommt ? '#fcd34d' : '#bbf7d0' });
  const rAU = Math.hypot(_pbn.x, _pbn.y);
  const unten = (_pbn.blitz > 0 || (_pbn.phase === 'ende' && b.sturz))
    ? 'Treffer – der Planet stürzt in die Sonne'
    : drin ? 'Abstand zur Sonne ' + _fpmNum(rAU, 2) + ' AE'
           : 'schon ' + _fpmNum(rAU, rAU >= 20 ? 0 : 2) + ' AE weit draußen';
  _wrText(ctx, W - 10, H - 14, unten,
          { align: 'right', font: '10px system-ui, sans-serif', farbe: '#cbd5e1' });
}

// ═══ STERNLEBEN ══════════════════════════════════════════════
/* ══════════════════════════════════════════════════════════════════════════
   STERNLEBEN – Warum leuchtet ein Stern, und warum nicht ewig?
   ──────────────────────────────────────────────────────────────────────────
   Kernidee der Heftseite: Die Masse ist der EINE Regler, an dem alles haengt -
   Lebensdauer, Farbe und Ende. Alle drei Groessen werden hier aus der Masse
   GERECHNET, nichts steht als fertige Tabelle fest verdrahtet da.

   Lebensdauer  T = 10 Mrd. Jahre * M^(-2,5)
   Sie folgt aus zwei Saetzen: Der Vorrat an Wasserstoff waechst mit der Masse
   (~M), der Verbrauch ist die Leuchtkraft (~M^3,5). Vorrat geteilt durch
   Verbrauch ergibt M / M^3,5 = M^(-2,5). Genau das ist der Grund, warum die
   Gegenprobe mit 25 Sonnenmassen NICHT wieder nach oben geht: mehr Brennstoff
   nuetzt nichts, wenn er noch viel schneller verheizt wird.
   ══════════════════════════════════════════════════════════════════════════ */

// Regler-Rasterung. Bewusst eine feste Liste statt eines stufenlosen Reglers:
// nur so trifft man die vier Zeilen des Hefts (0,5 · 1 · 10 · 25) exakt und
// nicht "0,49" oder "24,7" - sonst stimmen die notierten Werte nicht.
const _STB_M = [0.1, 0.2, 0.3, 0.5, 0.8, 1, 1.5, 2, 3, 5, 8, 10, 15, 20, 25, 30, 40];

// Die vier Zeilen der Tabelle im Heft.
const _STB_HEFT = [0.5, 1, 10, 25];

// Oberflaechentemperatur der Hauptreihe als Stuetzstellen, dazwischen wird
// logarithmisch interpoliert. Stuetzstellen statt einer einzigen Potenzformel,
// weil die drei Werte des Hefts (3800 K / 5800 K / 22000 K) dann GENAU
// herauskommen; jede Potenzfunktion trifft sie nur ungefaehr.
const _STB_TEFF = [[0.1, 2800], [0.2, 3200], [0.5, 3800], [1, 5800], [2, 9000],
                   [5, 16000], [10, 22000], [20, 33000], [25, 35000], [40, 42000]];

// Sichtbare Sternfarbe zur Temperatur - von tiefrot bis blau-weiss.
const _STB_FARBEN = [[2500, '255,146,72'], [3800, '255,178,104'], [5800, '255,224,138'],
                     [7500, '255,246,226'], [10000, '222,232,255'], [22000, '176,206,255'],
                     [45000, '156,190,255']];

const _STB_WELTALTER = 13.8e9;   // Alter des Weltalls in Jahren
const _STB_RIESE = '255,150,88'; // Farbe eines Roten Riesen bzw. Ueberriesen

let _stb = null;
function _stbInit() {
  // laeuft:true -> der Lebenslauf startet sofort von selbst, ohne Knopfdruck.
  // tab sammelt die vollstaendig durchlaufenen Sterne fuer die Heft-Tabelle.
  _stb = { M: 1, prog: 0, laeuft: true, pause: 0, tAnim: 0, phi: -1, tab: {} };
}
/* Lebensdauer in Jahren. T = 10 Mrd. Jahre * M^(-2,5).
   Probe: 0,5 -> 56,6 Mrd; 1 -> 10 Mrd; 10 -> 31,6 Mio; 25 -> 3,2 Mio. */
function _stbT(M) { return 1e10 * Math.pow(M, -2.5); }
/* Leuchtkraft in Sonnenleuchtkraeften. L ~ M^3,5 - das ist der VERBRAUCH, der
   die Lebensdauer bestimmt. Beide Formeln passen zusammen: T = Vorrat/Verbrauch
   = M / M^3,5. Deshalb darf hier keine andere Potenz stehen. */
function _stbL(M) { return Math.pow(M, 3.5); }
/* Radius auf der Hauptreihe in Sonnenradien. Unterhalb einer Sonnenmasse
   waechst der Radius steiler mit der Masse als darueber - deshalb zwei
   Exponenten. Probe auf Widerspruchsfreiheit: M=10 gibt 4,0 Sonnenradien;
   zusammen mit 22000 K liefert das Strahlungsgesetz daraus 3300-mal die
   Sonnenleuchtkraft - fast genau die 3160, die M^3,5 verlangt. */
function _stbRadius(M) { return M < 1 ? Math.pow(M, 0.8) : Math.pow(M, 0.6); }
/* Oberflaechentemperatur: logarithmische Interpolation der Stuetzstellen.
   Logarithmisch, weil die Masse ueber zwei Zehnerpotenzen laeuft - linear
   waere zwischen 0,1 und 0,5 Sonnenmassen praktisch nichts aufgeloest. */
function _stbTeff(M) {
  const S = _STB_TEFF;
  let i = 0;
  while (i < S.length - 2 && M > S[i + 1][0]) i++;
  const a = S[i], b = S[i + 1];
  const u = Math.max(0, Math.min(1, Math.log(M / a[0]) / Math.log(b[0] / a[0])));
  return Math.exp(Math.log(a[1]) + u * Math.log(b[1] / a[1]));
}
/* Farbe zur Temperatur, ebenfalls logarithmisch interpoliert. Rueckgabe ohne
   rgba() drumherum, weil der Weltraum-Baukasten Farben genau so erwartet. */
function _stbFarbe(teff) {
  const S = _STB_FARBEN;
  let i = 0;
  while (i < S.length - 2 && teff > S[i + 1][0]) i++;
  const a = S[i], b = S[i + 1];
  const u = Math.max(0, Math.min(1, Math.log(teff / a[0]) / Math.log(b[0] / a[0])));
  const pa = a[1].split(',').map(Number), pb = b[1].split(',').map(Number);
  return pa.map((c, k) => Math.round(c + (pb[k] - c) * u)).join(',');
}
/* Farbwort fuer die Spalte "Farbe" im Heft. Die Grenzen sind so gelegt, dass
   die drei Faelle des Hefts genau die erwarteten Woerter ergeben:
   3800 K -> roetlich, 5800 K -> gelb, 22000 K -> blau-weiss. */
function _stbFarbwort(teff) {
  if (teff < 3300)  return 'rot';
  if (teff < 4800)  return 'rötlich';
  if (teff < 6300)  return 'gelb';
  if (teff < 7800)  return 'gelblich-weiß';
  if (teff < 11000) return 'weiß';
  if (teff < 20000) return 'weiß-blau';
  return 'blau-weiß';
}
/* Das Ende haengt allein an der Masse. Die Grenzen 0,8 / 8 / 20 Sonnenmassen
   sind die ueblichen Schulbuchwerte.
   Unter 0,8 wird bewusst KEIN Ende behauptet: so ein Stern lebt laenger, als
   das Weltall bisher alt ist, sein Ende hat noch nie jemand gesehen. Das steht
   im Text so drin, damit aus einer Modellrechnung keine Beobachtung wird. */
function _stbEnde(M) {
  if (M < 0.8) return {
    typ: 'zwerg', modell: true, kurz: 'Weißer Zwerg (Modell)',
    phase: 'Der Stern leuchtet immer noch',
    lang: 'Modelle sagen einen <b>Weißen Zwerg</b> voraus – <b>beobachtet hat das noch nie jemand</b>, denn so ein Stern lebt länger, als das Weltall bisher alt ist (13,8 Mrd. Jahre).'
  };
  if (M < 8) return {
    typ: 'zwerg', kurz: 'Weißer Zwerg',
    phase: 'Hülle wird abgestoßen → Weißer Zwerg',
    lang: 'Erst <b>Roter Riese</b>, dann stößt er seine Hülle ab. Übrig bleibt ein <b>Weißer Zwerg</b>.'
  };
  if (M <= 20) return {
    typ: 'neutron', kurz: 'Neutronenstern',
    phase: 'Supernova → Neutronenstern',
    lang: 'Erst <b>Roter Überriese</b>, dann eine <b>Supernova</b>. Übrig bleibt ein <b>Neutronenstern</b>.'
  };
  return {
    typ: 'loch', kurz: 'Schwarzes Loch',
    phase: 'Supernova → Schwarzes Loch',
    lang: 'Erst <b>Roter Überriese</b>, dann eine <b>Supernova</b>. Übrig bleibt ein <b>Schwarzes Loch</b>.'
  };
}
/* Massenzahl deutsch: 0.5 wird zu "0,5". */
function _stbMText(M) { return String(M).replace('.', ','); }
/* Jahre in Mrd./Mio./Jahre. Bewusst mit Nachkommastelle: 0,5 Sonnenmassen
   ergeben 56,6 Mrd. Jahre - "rund hundert Milliarden" waere fast das Doppelte
   und damit schlicht falsch. Das Kind soll den gerechneten Wert eintragen. */
function _stbZeit(j) {
  if (j >= 1e9) return _stbGross(j / 1e9) + ' Mrd. Jahre';
  if (j >= 1e6) return _stbGross(j / 1e6) + ' Mio. Jahre';
  return Math.round(j).toLocaleString('de-DE') + ' Jahre';
}
/* Unter 100 mit einer Nachkommastelle, darueber ganzzahlig mit Punkt als
   Tausendertrennung - "56,6" und "3.162" liest sich beides sofort. */
function _stbGross(v) {
  return v < 100 ? _fpmNum(v, 1) : Math.round(v).toLocaleString('de-DE');
}
/* Auf n geltende Ziffern runden - 3162 wird zu 3200, nicht zu "3162,4".
   Eine Naeherungsformel darf keine Genauigkeit vortaeuschen, die sie nicht hat. */
function _stbSig(v, n) {
  const e = Math.pow(10, Math.floor(Math.log10(v)) - n + 1);
  return Math.round(v / e) * e;
}
function _stbLText(M) {
  const L = _stbL(M);
  if (L >= 1000) return _stbSig(L, 2).toLocaleString('de-DE');
  if (L >= 10)   return String(Math.round(L));
  if (L >= 1)    return _fpmNum(L, 1);
  // Unter 1 immer zwei geltende Ziffern: bei 0,1 Sonnenmassen ist L = 0,00032 -
  // mit fester Stellenzahl staende dort nur "0,000", also gar nichts.
  return _fpmNum(_stbSig(L, 2), Math.min(6, 1 - Math.floor(Math.log10(L))));
}
/* Temperatur auf hundert Kelvin gerundet - genauer ist die Naeherung nicht. */
function _stbTeffText(M) {
  return (Math.round(_stbTeff(M) / 100) * 100).toLocaleString('de-DE') + ' K';
}
/* Dauer eines ganzen Durchlaufs in Sekunden. Sie richtet sich nach dem
   Logarithmus der Lebensdauer: ein schwerer Stern rast in knapp sechs Sekunden
   durch sein Leben, ein leichter braucht ueber zwoelf - man SIEHT also, dass
   schwere Sterne es eilig haben. Linear ginge das nicht: zwischen 3,2 Mio. und
   56,6 Mrd. Jahren liegt der Faktor 18000. */
function _stbDauer(M) {
  const u = Math.max(0, Math.min(1, (Math.log10(_stbT(M)) - 6) / 5.2));
  return 5 + 8 * u;
}
/* Welche Lebensphase gehoert zum Fortschritt p (0..1)?
   Sterne unter 0,8 Sonnenmassen bekommen KEINE Riesenphase: kein einziger von
   ihnen ist bisher alt genug geworden, um die Hauptreihe zu verlassen. Statt
   ein Ende zu erfinden, zeigt die Simulation dort ehrlich einen Ausblick (i=4). */
function _stbPhase(M, p) {
  const e = _stbEnde(M);
  if (p < 0.07) return { i: 0, u: p / 0.07, name: 'Gaswolke zieht sich zusammen' };
  if (M < 0.8) {
    if (p < 0.86) return { i: 1, u: (p - 0.07) / 0.79, name: 'Hauptreihe – im Kern: Wasserstoff → Helium' };
    return { i: 4, u: (p - 0.86) / 0.14, name: e.phase };
  }
  if (p < 0.76) return { i: 1, u: (p - 0.07) / 0.69, name: 'Hauptreihe – im Kern: Wasserstoff → Helium' };
  if (p < 0.90) return { i: 2, u: (p - 0.76) / 0.14, name: M < 8 ? 'Roter Riese' : 'Roter Überriese' };
  return { i: 3, u: (p - 0.90) / 0.10, name: e.phase };
}
/* Alter des Sterns in Jahren zum aktuellen Bild. Die Hauptreihe reicht genau
   von 0 bis T - das ist die Zahl, die ins Heft kommt. Riesen- und Endphase
   dauern zusammen rund ein Zehntel davon; so lang sind sie auch wirklich. */
function _stbAlter(M, ph, T) {
  if (ph.i === 0) return 0;
  if (ph.i === 1) return T * ph.u;
  if (ph.i === 2) return T * (1 + 0.05 * ph.u);
  if (ph.i === 3) return T * (1.05 + 0.05 * ph.u);
  return T;                    // massearmer Stern: er steht noch auf der Hauptreihe
}
/* Regler: der Wert ist ein Index in _STB_M, keine Masse. Nur so liegen die
   vier Heftwerte exakt auf Raststellen. */
function _stbSetIdx(i) {
  const k = Math.max(0, Math.min(_STB_M.length - 1, Math.round(+i)));
  _stbSetM(_STB_M[k]);
}
/* Masse aendern heisst immer: der Lebenslauf faengt von vorn an. Genau das
   verlangt die Heftseite ("jedes Mal den ganzen Lauf ablaufen lassen"). */
function _stbSetM(m) {
  if (!_stb) return;
  _stb.M = m;
  const sl = document.getElementById('stbM'), i = _STB_M.indexOf(m);
  if (sl && i >= 0) sl.value = i;      // die Knoepfe schieben den Regler mit
  _stbNeu();
}
function _stbNeu() {
  if (!_stb) return;
  _stb.prog = 0; _stb.laeuft = true; _stb.pause = 0; _stb.phi = -1;
  _stbStatus();
}
/* Ein vollstaendig durchlaufener Stern wandert in die Tabelle. Nur die vier
   Massen des Hefts werden gemerkt - die Tabelle soll die Heftseite abbilden
   und nicht zu einer Liste aus siebzehn Zeilen wachsen. */
function _stbMerken() {
  if (!_stb || _STB_HEFT.indexOf(_stb.M) < 0) return;
  const M = _stb.M;
  _stb.tab[M] = { zeit: _stbZeit(_stbT(M)), farbe: _stbFarbwort(_stbTeff(M)), ende: _stbEnde(M).kurz };
}
function _stbHTML() {
  const knoepfe = _STB_HEFT.map(m =>
    `<button class="sim-btn${_stb.M === m ? ' primary' : ''}" data-stb="${m}" onclick="_stbSetM(${m})">${m === 25 ? 'Gegenprobe 25' : _stbMText(m)}</button>`).join('');
  return `<div class="sim-box sim-box-wide fpm-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">⭐ Warum leuchtet ein Stern – und warum nicht ewig?</h3>
    <div class="fpm-note" style="margin-top:2px">Stelle die Masse ein und lass den ganzen Lebenslauf im Zeitraffer durchlaufen: <b>Gaswolke → Stern → Riese → Ende</b>. Notiere jedes Mal Lebensdauer, Farbe und Ende.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="stbAnim" width="460" height="300" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          ${knoepfe}
          <button class="sim-btn" onclick="_stbNeu()">↺ Lauf neu starten</button>
        </div>
        <div class="phys-ctrl" style="margin-top:4px">
          <span class="phys-ctrl-label">Masse des Sterns: <b id="stbMLbl">1 Sonnenmasse</b></span>
          <input type="range" id="stbM" min="0" max="${_STB_M.length - 1}" step="1" value="${_STB_M.indexOf(_stb.M)}"
            oninput="_stbSetIdx(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="fpm-note" style="margin-top:4px">Der Stern ist <b>nicht maßstäblich</b> gezeichnet: ein Roter Überriese wäre in Wirklichkeit viele hundertmal so groß wie der Stern davor.</div>
      </div>
      <div>
        <div class="fpm-label">Messwerte</div>
        <div class="lmp-status on" id="stbStatus" style="margin-top:4px"></div>
        <div class="fpm-label" style="margin-top:10px">Deine Tabelle</div>
        <div id="stbTab" style="margin-top:4px"></div>
        <div class="fpm-note" style="margin-top:10px">Im Kern verschmelzen <b>Wasserstoffkerne zu Helium</b>. Das ist <b>Kernfusion</b> – kein Verbrennen: Es gibt dort keinen Sauerstoff, und aus einem Kilogramm Wasserstoff wird millionenfach mehr Energie frei als beim Verbrennen.</div>
        <div class="fpm-note" style="margin-top:6px">Ein schwerer Stern hat <b>mehr</b> Brennstoff, verbraucht ihn aber <b>viel</b> schneller: doppelte Masse heißt rund <b>11-mal</b> so hohe Leuchtkraft und deshalb nur noch etwa <b>ein Sechstel</b> der Lebensdauer.</div>
      </div>
    </div>
  </div>`;
}
/* Die vier Zeilen des Hefts. Eine Zeile fuellt sich erst, wenn dieser Stern
   einmal GANZ durchgelaufen ist - so wird aus dem Zusehen ein Versuch, und die
   Gegenprobe mit 25 Sonnenmassen muss wirklich gemacht werden. */
function _stbTabelleHTML() {
  if (!_stb) return '';
  const zelle = (v, hell) => '<td style="padding:3px 4px;border-bottom:1px solid #f1f5f9;color:' + (hell ? '#334155' : '#94a3b8') + '">' + v + '</td>';
  let s = '<table style="width:100%;border-collapse:collapse;font-size:.68rem;line-height:1.3">' +
          '<tr style="color:#64748b;font-weight:800;text-align:left">' +
          ['Masse', 'Lebensdauer', 'Farbe', 'Ende'].map(k =>
            '<th style="padding:2px 4px;border-bottom:1px solid #e2e8f0">' + k + '</th>').join('') +
          '</tr>';
  _STB_HEFT.forEach(m => {
    const e = _stb.tab[m];
    s += '<tr style="' + (_stb.M === m ? 'background:#f5f3ff' : '') + '">' +
         '<td style="padding:3px 4px;border-bottom:1px solid #f1f5f9;font-weight:800;color:#334155">' + _stbMText(m) + '</td>' +
         zelle(e ? e.zeit : '—', !!e) + zelle(e ? e.farbe : '—', !!e) + zelle(e ? e.ende : '—', !!e) +
         '</tr>';
  });
  return s + '</table><div class="fpm-note" style="margin-top:4px">Eine Zeile füllt sich, sobald dieser Stern <b>einmal ganz</b> durchgelaufen ist.</div>';
}
function _stbStatus() {
  if (!_stb) return;
  const M = _stb.M, T = _stbT(M), teff = _stbTeff(M), e = _stbEnde(M);

  const el = document.getElementById('stbStatus');
  if (el) {
    let s = '<b>' + _stbMText(M) + (M === 1 ? ' Sonnenmasse' : ' Sonnenmassen') + '</b><br>' +
            'Lebensdauer <b>' + _stbZeit(T) + '</b><br>' +
            'Farbe <b>' + _stbFarbwort(teff) + '</b> · Oberfläche etwa ' + _stbTeffText(M) + '<br>' +
            'Leuchtkraft etwa <b>' + _stbLText(M) + '-mal</b> die Sonne<br>' +
            'Ende: ' + e.lang;
    // Der Vergleich mit dem Weltalter wird gerechnet, nicht behauptet.
    if (M >= 0.8 && T > _STB_WELTALTER) {
      s += '<br>Das ist <b>länger, als das Weltall bisher alt ist</b> (13,8 Mrd. Jahre).';
    }
    // Antwort auf die Gegenprobe der Heftseite - genau dort, wo sie gemacht wird.
    if (M >= 20) {
      s += '<br><b>Gegenprobe:</b> Die Lebensdauer fällt <b>weiter</b>. Sie steigt nie wieder – mehr Masse heißt immer kürzeres Leben.';
    }
    s += '<br>gerade im Bild: ' + _stbPhase(M, _stb.prog).name;
    el.innerHTML = s;
  }

  const tb = document.getElementById('stbTab');
  if (tb) tb.innerHTML = _stbTabelleHTML();

  const lbl = document.getElementById('stbMLbl');
  if (lbl) lbl.textContent = _stbMText(M) + (M === 1 ? ' Sonnenmasse' : ' Sonnenmassen');

  document.querySelectorAll('[data-stb]').forEach(b =>
    b.classList.toggle('primary', +b.dataset.stb === M));
}
function _stbUpdate(dt) {
  if (!_stb) return;
  const d = Math.min(dt, 0.05);
  _stb.tAnim += d;                       // laeuft immer weiter: Funkeln, Puls, Strahlen

  if (_stb.pause > 0) {                  // Endzustand kurz stehen lassen, dann von vorn.
    _stb.pause -= d;                     // Ohne das stuende das Bild nach dem ersten
    if (_stb.pause <= 0) { _stb.prog = 0; _stb.laeuft = true; _stb.phi = -1; }
    return;                              // Durchlauf fuer immer still.
  }
  if (!_stb.laeuft) return;

  _stb.prog += d / _stbDauer(_stb.M);
  if (_stb.prog >= 1) {
    _stb.prog = 1; _stb.laeuft = false; _stb.pause = 2.8;
    _stbMerken();                        // erst der vollstaendige Lauf zaehlt
    _stbStatus();
  }
  // Die Textanzeige nur beim Phasenwechsel neu schreiben, nicht in jedem Bild -
  // sonst wuerde bei 60 Bildern je Sekunde 60-mal die halbe Seite neu gebaut.
  const i = _stbPhase(_stb.M, _stb.prog).i;
  if (i !== _stb.phi) { _stb.phi = i; _stbStatus(); }
}
/* Farbstring 'r,g,b' aufhellen (f>1) oder abdunkeln (f<1) - fuer den
   Kugelverlauf, damit der Stern rund wirkt und nicht als flacher Kreis. */
function _stbMisch(rgb, f) {
  const p = rgb.split(',').map(Number);
  const m = c => Math.max(0, Math.min(255, Math.round(f >= 1 ? c + (255 - c) * (f - 1) : c * f)));
  return 'rgb(' + m(p[0]) + ',' + m(p[1]) + ',' + m(p[2]) + ')';
}
function _stbDraw(ctx, cv) {
  if (!_stb) return;
  const W = cv.width, H = cv.height, t = _stb.tAnim, M = _stb.M;
  _wrHimmel(ctx, cv, t, { oben: '#070b1c', unten: '#02030a', dichte: 1.0, seed: 7 });

  const T = _stbT(M), teff = _stbTeff(M), ende = _stbEnde(M);
  const ph = _stbPhase(M, _stb.prog), u = Math.max(0, Math.min(1, ph.u));
  const cx = W / 2, cy = 132;
  // Gezeichneter Hauptreihenradius. Die Wurzelkennlinie staucht das echte
  // Verhaeltnis 1:58 auf etwa 1:6 - sonst waere ein Stern mit 0,1 Sonnenmassen
  // ein unsichtbarer Punkt oder einer mit 40 groesser als das Bild.
  const rHR = 9 * Math.pow(_stbRadius(M), 0.45);
  let farbe = _stbFarbe(teff);     // faerbt Stern UND Zeitbalken
  let unten = '';                  // Bildunterschrift direkt unter dem Stern

  if (ph.i === 0) {
    // ── Gaswolke: Staub und Gas fallen zusammen, in der Mitte zuendet der Kern
    _wrGlanz(ctx, cx, cy, 122 - 44 * u, '86,116,196', 0.20 * (1 - u) + 0.05);
    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    const rnd = _wrRnd(9);           // fester Seed: die Wolke flackert nicht neu
    for (let i = 0; i < 46; i++) {
      const a0 = rnd() * 6.283, r0 = 34 + rnd() * 96, gr = 0.9 + rnd() * 1.5;
      const a = a0 + u * 2.6 + t * 0.12;         // die Wolke dreht sich beim Fallen
      const r = r0 * (1 - u * 0.94) + 3;
      ctx.fillStyle = 'rgba(163,186,236,' + (0.14 + 0.42 * u).toFixed(2) + ')';
      ctx.beginPath();
      ctx.arc(cx + Math.cos(a) * r * 1.3, cy + Math.sin(a) * r * 0.8, gr, 0, 6.283);
      ctx.fill();
    }
    ctx.restore();
    const rp = rHR * u * u;                      // der Protostern waechst und wird heisser
    if (rp > 0.6) {
      const fp = _stbFarbe(1800 + (teff - 1800) * u * u);
      _wrGlanz(ctx, cx, cy, rp * 3 + 8, fp, 0.32 * u);
      _wrKoerper(ctx, cx, cy, rp, [_stbMisch(fp, 1.5), 'rgb(' + fp + ')', _stbMisch(fp, 0.62)],
                 { lx: 0, ly: 0, rand: false });
    }
    farbe = '150,176,232';
    unten = 'kalte Wolke aus Wasserstoff und Staub';

  } else if (ph.i === 1 || ph.i === 4) {
    // ── Hauptreihe: der Stern steht ruhig da und fusioniert Wasserstoff.
    // Phase 4 ist derselbe Zustand - ein massearmer Stern hat ihn nach dem
    // ganzen bisherigen Weltalter noch immer nicht verlassen.
    const r = rHR * (1 + 0.10 * (ph.i === 1 ? u : 1));
    _wrGlanz(ctx, cx, cy, r * 3.2 + 20, farbe, 0.34 + 0.05 * Math.sin(t * 1.7));

    // Abgestrahltes Licht als pulsierende Strahlen - das ist es, was wir sehen.
    ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.lineCap = 'round';
    ctx.strokeStyle = 'rgba(' + farbe + ',0.26)'; ctx.lineWidth = 1.1;
    for (let i = 0; i < 12; i++) {
      const a = i * 0.5236 + t * 0.16;
      const l = r * 1.12, l2 = l + 7 + 5 * Math.sin(t * 2.1 + i * 1.4);
      ctx.beginPath();
      ctx.moveTo(cx + Math.cos(a) * l, cy + Math.sin(a) * l);
      ctx.lineTo(cx + Math.cos(a) * l2, cy + Math.sin(a) * l2);
      ctx.stroke();
    }
    ctx.restore();

    _wrKoerper(ctx, cx, cy, r, [_stbMisch(farbe, 1.55), 'rgb(' + farbe + ')', _stbMisch(farbe, 0.6)],
               { lx: 0, ly: 0, rand: false });

    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    const rn = _wrRnd(4);
    for (let i = 0; i < 9; i++) {          // brodelnde Oberflaeche
      const a = rn() * 6.283 + t * 0.3 * (i % 2 ? 1 : -1), d = (0.2 + rn() * 0.55) * r;
      ctx.fillStyle = 'rgba(255,255,255,0.045)';
      ctx.beginPath(); ctx.arc(cx + Math.cos(a) * d, cy + Math.sin(a) * d, r * 0.22, 0, 6.283); ctx.fill();
    }
    // Kernfusion sichtbar machen: vier Wasserstoffkerne laufen nach innen,
    // treffen sich - und der Kern blitzt auf. Das ist der Motor des Sterns,
    // und es ist kein Feuer: die Kerne verschmelzen, sie verbrennen nicht.
    const p = (t * 1.25) % 1;
    for (let i = 0; i < 4; i++) {
      const a = i * 1.5708 + t * 0.9, d = r * 0.45 * (1 - p);
      ctx.fillStyle = 'rgba(255,255,255,' + (0.8 * (1 - p)).toFixed(2) + ')';
      ctx.beginPath(); ctx.arc(cx + Math.cos(a) * d, cy + Math.sin(a) * d, Math.max(1.2, r * 0.06), 0, 6.283); ctx.fill();
    }
    ctx.restore();
    _wrGlanz(ctx, cx, cy, r * 0.9, '255,255,255', 0.12 + 0.34 * p * p);

    if (ph.i === 4) {
      // Ab hier gibt es keine Beobachtung mehr, nur noch Modellrechnung. Der
      // gestrichelte Ring markiert genau diese Grenze - und rechts steht blass
      // der Weisse Zwerg, den die Modelle vorhersagen.
      ctx.setLineDash([4, 5]);
      ctx.strokeStyle = 'rgba(196,181,253,' + (0.35 + 0.35 * Math.abs(Math.sin(t * 1.2))).toFixed(2) + ')';
      ctx.lineWidth = 1.2;
      ctx.beginPath(); ctx.arc(cx, cy, r + 22 + 6 * u, 0, 6.283); ctx.stroke();
      const zx = cx + 104;
      ctx.setLineDash([2, 3]); ctx.strokeStyle = 'rgba(147,197,253,0.45)'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(zx, cy, 13, 0, 6.283); ctx.stroke();
      ctx.setLineDash([]);
      _wrGlanz(ctx, zx, cy, 17, '198,222,255', 0.16 + 0.16 * u);
      ctx.fillStyle = 'rgba(219,234,254,' + (0.35 + 0.4 * u).toFixed(2) + ')';
      ctx.beginPath(); ctx.arc(zx, cy, 3.2, 0, 6.283); ctx.fill();
      unten = 'Ende noch nie beobachtet · Modell: Weißer Zwerg';
    } else {
      unten = _stbFarbwort(teff) + ' · Oberfläche etwa ' + _stbTeffText(M);
    }

  } else if (ph.i === 2) {
    // ── Riese: der Wasserstoff im Kern ist alle, die Huelle blaeht sich auf
    // und kuehlt dabei ab - deshalb wird der Stern gross UND rot.
    const rZiel = Math.min(76, rHR * 2.6 + 26);
    const rg = (rHR + (rZiel - rHR) * u) * (1 + 0.035 * Math.sin(t * 1.4));  // Riesen pulsieren wirklich
    const pa = farbe.split(',').map(Number), pb = _STB_RIESE.split(',').map(Number);
    farbe = pa.map((c, k) => Math.round(c + (pb[k] - c) * Math.min(1, u * 1.8))).join(',');

    _wrGlanz(ctx, cx, cy, rg * 1.9, farbe, 0.30);
    _wrKoerper(ctx, cx, cy, rg, [_stbMisch(farbe, 1.32), 'rgb(' + farbe + ')', _stbMisch(farbe, 0.55)],
               { lx: 0, ly: 0, rand: false });
    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    const rn = _wrRnd(6);
    for (let i = 0; i < 10; i++) {         // riesige aufsteigende Gasblasen
      const a = rn() * 6.283 + t * 0.22, d = (0.25 + rn() * 0.6) * rg;
      ctx.fillStyle = 'rgba(255,214,170,0.05)';
      ctx.beginPath(); ctx.arc(cx + Math.cos(a) * d, cy + Math.sin(a) * d, rg * 0.2, 0, 6.283); ctx.fill();
    }
    ctx.restore();
    // Gestrichelt: so gross war derselbe Stern vorher. Ohne diesen Vergleich
    // sieht man das Aufblaehen nicht, weil sonst kein Massstab im Bild ist.
    ctx.setLineDash([3, 4]);
    ctx.strokeStyle = 'rgba(226,232,240,0.5)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(cx, cy, rHR, 0, 6.283); ctx.stroke();
    ctx.setLineDash([]);
    unten = 'rot · nur noch etwa 3.500 K · ' + (M < 8 ? 'rund 100-mal so groß' : 'viele 100-mal so groß');

  } else {
    // ── Ende
    if (ende.typ === 'zwerg') {
      // Planetarischer Nebel: die Huelle treibt weg, der nackte heisse Kern bleibt.
      ctx.save(); ctx.globalCompositeOperation = 'lighter';
      for (let k = 0; k < 3; k++) {
        const rr = rHR * 2.2 + u * (105 + k * 26);
        ctx.strokeStyle = 'rgba(150,210,255,' + Math.max(0, (0.42 - k * 0.1) * (1 - u)).toFixed(3) + ')';
        ctx.lineWidth = 7 - k * 1.6;
        ctx.beginPath(); ctx.ellipse(cx, cy, rr, rr * 0.78, 0, 0, 6.283); ctx.stroke();
      }
      ctx.restore();
      _wrGlanz(ctx, cx, cy, 26, '198,222,255', 0.55);
      _wrKoerper(ctx, cx, cy, 3.4, ['#ffffff', '#dbeafe', '#93c5fd'], { lx: 0, ly: 0, rand: false });
      farbe = '198,222,255';
      unten = 'Weißer Zwerg – nur noch so groß wie die Erde, glüht langsam aus';
    } else {
      // Supernova: erst der Blitz, dann die davonrasende Huelle.
      const blitz = Math.exp(-u * 8);
      if (blitz > 0.02) _wrGlanz(ctx, cx, cy, 60 + 190 * u, '255,246,214', Math.min(0.95, blitz));
      ctx.save(); ctx.globalCompositeOperation = 'lighter';
      for (let k = 0; k < 3; k++) {
        const rr = rHR + u * (150 + k * 40);
        ctx.strokeStyle = 'rgba(' + (k ? '255,176,96' : '255,236,196') + ',' + (0.5 * (1 - u)).toFixed(3) + ')';
        ctx.lineWidth = 6 - k * 1.5;
        ctx.beginPath(); ctx.arc(cx, cy, rr, 0, 6.283); ctx.stroke();
      }
      ctx.restore();
      if (ende.typ === 'neutron') {
        // Ein Neutronenstern rotiert bis zu hundertmal je Sekunde und schickt
        // dabei zwei Strahlenkeulen herum - deshalb drehen sich hier zwei Strahlen.
        const w = t * 3.4;
        ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.lineCap = 'round';
        ctx.strokeStyle = 'rgba(186,230,253,0.5)'; ctx.lineWidth = 2.4;
        for (const s of [1, -1]) {
          ctx.beginPath(); ctx.moveTo(cx, cy);
          ctx.lineTo(cx + Math.cos(w) * 54 * s, cy + Math.sin(w) * 54 * s); ctx.stroke();
        }
        ctx.restore();
        _wrGlanz(ctx, cx, cy, 20, '186,230,253', 0.75);
        ctx.fillStyle = '#eff6ff';
        ctx.beginPath(); ctx.arc(cx, cy, 2.6, 0, 6.283); ctx.fill();
        farbe = '186,230,253';
        unten = 'Neutronenstern – rund 20 km groß, dreht sich rasend schnell';
      } else {
        // Schwarzes Loch: eine Flaeche ganz ohne Licht, aussen herum der helle
        // Ring aus Licht, das um das Loch herumgelenkt wird. Kein Schimmer auf
        // der Flaeche selbst - sonst sieht es aus, als wuerde sie leuchten.
        _wrGlanz(ctx, cx, cy, 46, '255,186,110', 0.34);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(cx, cy, 13, 0, 6.283); ctx.fill();
        ctx.save(); ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = 'rgba(255,240,206,0.85)'; ctx.lineWidth = 2.2;
        ctx.beginPath(); ctx.arc(cx, cy, 18, 0, 6.283); ctx.stroke();
        ctx.restore();
        farbe = '255,186,110';
        unten = 'Schwarzes Loch – nicht einmal Licht kommt heraus';
      }
    }
  }

  // ── Zeitbalken: die ganze Lebenszeit auf einem Streifen ──────────────────
  // Der Balken zeigt 1,1 * T. Der weisse Strich sitzt bei T, dem Ende der
  // Hauptreihe; das kurze rote Stueck dahinter ist die Riesen- und Endphase.
  // Genau der weisse Strich ist die Zahl, die ins Heft kommt.
  const bx0 = 26, bx1 = W - 26, by = 268, bh = 9;
  const tick = bx0 + (bx1 - bx0) / 1.1;
  const alter = _stbAlter(M, ph, T);
  ctx.fillStyle = 'rgba(148,163,184,0.18)'; ctx.fillRect(bx0, by, bx1 - bx0, bh);
  ctx.fillStyle = 'rgba(248,113,113,0.22)'; ctx.fillRect(tick, by, bx1 - tick, bh);
  ctx.fillStyle = 'rgba(' + farbe + ',0.85)';
  ctx.fillRect(bx0, by, (bx1 - bx0) * Math.max(0, Math.min(1, alter / (1.1 * T))), bh);
  ctx.strokeStyle = 'rgba(255,255,255,0.7)'; ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.moveTo(tick, by - 4); ctx.lineTo(tick, by + bh + 4); ctx.stroke();
  ctx.strokeStyle = 'rgba(203,213,225,0.35)'; ctx.lineWidth = 1;
  ctx.strokeRect(bx0 + 0.5, by + 0.5, bx1 - bx0 - 1, bh - 1);

  // ── Genau vier Beschriftungen, mehr wuerde das Bild zustellen ────────────
  _wrText(ctx, cx, 26, ph.name, { font: '600 11.5px system-ui, sans-serif', farbe: '#e2e8f0' });
  _wrText(ctx, cx, 234, unten, { font: '10px system-ui, sans-serif', farbe: '#a5b4fc' });
  _wrText(ctx, bx0, 258, ph.i === 0 ? 'Sternentstehung' : 'Alter: ' + _stbZeit(alter),
          { align: 'left', font: '10px system-ui, sans-serif', farbe: '#cbd5e1' });
  _wrText(ctx, bx1, 258, 'Lebensdauer ' + _stbZeit(T),
          { align: 'right', font: '600 10px system-ui, sans-serif', farbe: '#fde68a' });
}

// ═══ STERNSPEKTRUM ═══════════════════════════════════════════
// ══════════════════════════════════════════════════════════════════════════
// 7.3.x  WORAUS BESTEHEN DIE STERNE?  –  Sternspektrum und Fraunhoferlinien
//
// Schliesst den Bogen zu Kapitel 2: dasselbe Prisma wie beim Regenbogen, nur
// faellt jetzt Sternlicht hinein. Im Farbband fehlen einzelne Streifen - die
// Gashuelle des Sterns hat genau diese Farben verschluckt. Weil jedes Element
// immer dieselben Farben verschluckt, ist das Streifenmuster ein Fingerabdruck.
// ══════════════════════════════════════════════════════════════════════════

let _spk = null;

const _SPK_L0 = 400, _SPK_L1 = 700;                    // sichtbarer Bereich in nm
const _SPK_BAND = { x: 172, y: 104, w: 284, h: 44 };   // Farbband auf dem Schirm
const _SPK_BILD = {};   // fertige Farbband-Bilder, je Quelle einmal gerechnet
const _SPK_MAX  = {};   // Maximum der Planckkurve je Temperatur

/* Die Elemente mit ihren ECHTEN Wellenlaengen in nm.
   rel = wie tief die einzelne Linie im Vergleich zu den anderen Linien
   desselben Elements ist. Die Hoehe des ganzen Satzes kommt aus der Quelle,
   die Verteilung innerhalb des Elements bleibt immer gleich. */
const _SPK_EL = [
  { k: 'H',  name: 'Wasserstoff', farbe: '#ff8fa3', rgb: '255,143,163',
    lin: [656.3, 486.1, 434.0, 410.2], rel: [1.00, 0.90, 0.78, 0.68] },   // Balmer α β γ δ
  { k: 'He', name: 'Helium',      farbe: '#7ee0c0', rgb: '126,224,192',
    lin: [587.6, 501.6, 447.1],        rel: [0.95, 0.70, 1.00] },         // D3, 501,6, 447,1
  { k: 'Na', name: 'Natrium',     farbe: '#ffc04d', rgb: '255,192,77',
    lin: [589.0, 589.6],               rel: [1.00, 0.80] },               // D2 und D1
  { k: 'Fe', name: 'Eisen',       farbe: '#a8c8ff', rgb: '168,200,255',
    lin: [527.0, 516.9, 495.8, 438.4], rel: [0.90, 1.00, 0.75, 0.85] }    // E2, b4, c, 438,4
];

/* Alle Linien in einer flachen Liste - so muss beim Zeichnen und beim Zaehlen
   nicht doppelt geschachtelt werden. */
const _SPK_LIN = _SPK_EL.reduce((a, e) => a.concat(
  e.lin.map((L, i) => ({ el: e.k, lam: L, rel: e.rel[i] }))), []);

/* Die vier Quellen der Heftseite.
   T = Oberflaechentemperatur in Kelvin (daraus wird der Farbverlauf des Bandes
   gerechnet), grad = dieselbe Temperatur in Grad Celsius zum Vorlesen.
   st = wie kraeftig die Linien des Elements sind (0 = gar nicht da).
   Die WELLENLAENGEN aendern sich nie - nur diese Staerken. Genau das ist die
   Aussage der Seite, deshalb steckt der Unterschied auch nur in dieser Zeile. */
const _SPK_Q = [
  { id: 'stern1', knopf: 'Stern 1 gelb', kurz: 'Stern 1', farbwort: 'gelb',
    name: 'Stern 1 – gelb, wie unsere Sonne', typ: 'gelber Stern (Klasse G)',
    T: 5800, grad: '5 500',
    koerper: ['#fffdf0', '#ffd257', '#f0902a'], glanz: '255,205,110',
    st: { H: 0.72, He: 0.05, Na: 0.52, Fe: 0.45 } },
  { id: 'stern2', knopf: 'Stern 2 blau-weiß', kurz: 'Stern 2', farbwort: 'blau-weiß',
    name: 'Stern 2 – blau-weiß und sehr heiß', typ: 'blau-weißer Stern (Klasse B)',
    T: 15000, grad: '15 000',
    koerper: ['#ffffff', '#d4e6ff', '#7fb0ff'], glanz: '150,190,255',
    st: { H: 0.92, He: 0.70, Na: 0.04, Fe: 0.06 } },
  { id: 'stern3', knopf: 'Stern 3 rot', kurz: 'Stern 3', farbwort: 'rot',
    name: 'Stern 3 – rot und kühl', typ: 'roter Stern (Klasse M)',
    T: 3200, grad: '2 900',
    koerper: ['#fff0d8', '#ff9a5a', '#c0331a'], glanz: '255,140,90',
    st: { H: 0.18, He: 0.00, Na: 0.92, Fe: 0.80 } },
  { id: 'lampe', knopf: '💡 Glühlampe', kurz: 'Glühlampe', farbwort: 'Gegenprobe',
    name: 'Glühlampe – die Gegenprobe', typ: 'glühender Draht, keine Gashülle davor',
    T: 2700, grad: '2 400',
    koerper: ['#fffbe8', '#ffd98a', '#e08a2a'], glanz: '255,214,140',
    st: { H: 0, He: 0, Na: 0, Fe: 0 } }
];
/* Farbbereiche des Bandes. Die Grenzen sind so gelegt, dass die Linien dort
   landen, wo sie im Heft benannt werden: 486 nm blaugruen, 502 nm gruen,
   588/589 nm gelb, 656 nm rot. d = Form fuer "im ... Bereich". */
const _SPK_BEREICH = [
  { bis: 430, n: 'violett',  d: 'violetten' },
  { bis: 480, n: 'blau',     d: 'blauen' },
  { bis: 498, n: 'blaugrün', d: 'blaugrünen' },
  { bis: 565, n: 'grün',     d: 'grünen' },
  { bis: 592, n: 'gelb',     d: 'gelben' },
  { bis: 625, n: 'orange',   d: 'orangen' },
  { bis: 999, n: 'rot',      d: 'roten' }
];
function _spkBereich(lam) {
  for (const b of _SPK_BEREICH) if (lam < b.bis) return b;
  return _SPK_BEREICH[_SPK_BEREICH.length - 1];
}
// ── Physik: Farbe und Helligkeit einer Wellenlaenge ────────────────────────

/* Spektralfarbe einer Wellenlaenge (Naeherung nach Bruton) - dieselbe
   Zuordnung wie beim Regenbogen in Kapitel 2. 400 nm violett bis 700 nm rot,
   an beiden Enden wird es dunkler, weil das Auge dort kaum noch etwas sieht. */
function _spkFarbe(lam) {
  let r = 0, g = 0, b = 0;
  if (lam < 440)      { r = -(lam - 440) / 60; b = 1; }
  else if (lam < 490) { g = (lam - 440) / 50;  b = 1; }
  else if (lam < 510) { g = 1; b = -(lam - 510) / 20; }
  else if (lam < 580) { r = (lam - 510) / 70;  g = 1; }
  else if (lam < 645) { r = 1; g = -(lam - 645) / 65; }
  else                { r = 1; }
  let f = 1;
  if (lam < 420)      f = 0.35 + 0.65 * (lam - 380) / 40;
  else if (lam > 680) f = 0.35 + 0.65 * (720 - lam) / 40;
  return [r * f, g * f, b * f];
}

/* Planck-Strahlung, nur der Verlauf ueber die Wellenlaenge. Die Vorfaktoren
   kuerzen sich weg, weil gleich auf das Maximum normiert wird.
   c2 = h*c/k = 1,438 77e7 nm*K, lam in nm, T in Kelvin. */
function _spkPlanck(lam, T) {
  return 1 / (Math.pow(lam, 5) * (Math.exp(1.43877e7 / (lam * T)) - 1));
}
function _spkMax(T) {
  if (_SPK_MAX[T]) return _SPK_MAX[T];
  let m = 0;
  for (let lam = _SPK_L0; lam <= _SPK_L1; lam += 2) m = Math.max(m, _spkPlanck(lam, T));
  return (_SPK_MAX[T] = m);
}

/* Farbe einer Wellenlaenge, so wie sie bei DIESER Temperatur aussieht:
   Der heisse Stern strahlt am blauen Ende viel mehr ab, der kuehle am roten.
   Der Exponent 0,42 staucht das Verhaeltnis. Ungestaucht waere beim
   Gluehlampenband das blaue Ende fast schwarz - und das saehe aus, als fehlten
   dort Farben. Genau das soll die Gegenprobe ja NICHT sagen. */
function _spkRGB(lam, T) {
  const f = _spkFarbe(lam), h = Math.pow(_spkPlanck(lam, T) / _spkMax(T), 0.42);
  return [Math.round(255 * Math.min(1, f[0] * h)),
          Math.round(255 * Math.min(1, f[1] * h)),
          Math.round(255 * Math.min(1, f[2] * h))];
}
function _spkCSS(lam, T) { const c = _spkRGB(lam, T); return 'rgb(' + c[0] + ',' + c[1] + ',' + c[2] + ')'; }

/* Ort einer Wellenlaenge im Farbband. Massstab ist linear in der
   Wellenlaenge - deshalb liegt jede Linie an ihrer wirklichen Stelle. */
function _spkX(lam) { return _SPK_BAND.x + (lam - _SPK_L0) / (_SPK_L1 - _SPK_L0) * _SPK_BAND.w; }
/* Das Farbband wird EINMAL je Quelle in ein Bild von 301 Pixeln gerechnet -
   ein Pixel je Nanometer - und danach nur noch breitgezogen. Ohne diesen
   Puffer waeren das 301 Exponentialfunktionen in jedem Einzelbild. */
function _spkBandBild(qi) {
  if (_SPK_BILD[qi]) return _SPK_BILD[qi];
  const q = _SPK_Q[qi], n = _SPK_L1 - _SPK_L0 + 1;
  const cv = document.createElement('canvas');
  cv.width = n; cv.height = 1;
  const c = cv.getContext('2d');
  const img = c.createImageData(n, 1);
  for (let i = 0; i < n; i++) {
    const rgb = _spkRGB(_SPK_L0 + i, q.T);
    img.data[i * 4] = rgb[0]; img.data[i * 4 + 1] = rgb[1];
    img.data[i * 4 + 2] = rgb[2]; img.data[i * 4 + 3] = 255;
  }
  c.putImageData(img, 0, 0);
  return (_SPK_BILD[qi] = cv);
}
// ── Zustand und Bedienung ─────────────────────────────────────────────────

function _spkInit() {
  // tiefe startet bei 0: die Linien blenden sich beim Oeffnen ein, als liefe
  // das Licht gerade erst durch das Prisma.
  _spk = {
    q: 0,
    tiefe: { H: 0, He: 0, Na: 0, Fe: 0 },
    streifen: false, slide: 0,
    lupe: 656.3, auto: true, richtung: -1,
    t: 0, tStatus: 0
  };
}
function _spkQuelle(i) {
  if (!_spk) return;
  _spk.q = i;
  document.querySelectorAll('[data-spk]').forEach(b =>
    b.classList.toggle('primary', b.dataset.spk === _SPK_Q[i].id));
  _spkStatus();
}

function _spkStreifen() {
  if (!_spk) return;
  _spk.streifen = !_spk.streifen;
  const b = document.getElementById('spkStreifenBtn');
  if (b) {
    b.classList.toggle('primary', _spk.streifen);
    b.textContent = _spk.streifen ? '📏 Vergleichsstreifen ausblenden'
                                  : '📏 Vergleichsstreifen einblenden';
  }
  _spkStatus();
}

/* Regler und Klick ins Bild setzen beide die Lupe - und schalten den Suchlauf
   ab, sonst wuerde die Lupe unter der Hand wieder weglaufen. */
function _spkLupe(v) {
  if (!_spk) return;
  _spk.auto = false;
  document.getElementById('spkAutoBtn')?.classList.remove('primary');
  _spk.lupe = Math.max(_SPK_L0, Math.min(_SPK_L1, +v));
  _spkStatus();
}
function _spkSuchlauf() {
  if (!_spk) return;
  _spk.auto = !_spk.auto;
  document.getElementById('spkAutoBtn')?.classList.toggle('primary', _spk.auto);
  _spkStatus();
}
function _spkKlick(ev) {
  if (!_spk) return;
  const cv = ev.currentTarget, r = cv.getBoundingClientRect();
  const x = (ev.clientX - r.left) * (cv.width / r.width);
  const lam = _SPK_L0 + (x - _SPK_BAND.x) / _SPK_BAND.w * (_SPK_L1 - _SPK_L0);
  if (lam < _SPK_L0 - 10 || lam > _SPK_L1 + 10) return;   // daneben getippt
  _spkLupe(lam);
  const s = document.getElementById('spkLupe');
  if (s) s.value = Math.round(_spk.lupe * 2) / 2;
}
// ── Auswertung ────────────────────────────────────────────────────────────

function _spkTiefe(L) { return _spk.tiefe[L.el] * L.rel; }

/* Welche Linie liegt unter der Lupe? Toleranz 2,2 nm - das ist ungefaehr die
   Breite, mit der die Linie im Band gezeichnet ist. */
function _spkTreffer() {
  let best = null, bs = 0, bt = 0;
  for (const L of _SPK_LIN) {
    const t = _spkTiefe(L), d = Math.abs(L.lam - _spk.lupe);
    if (d > 2.2 || t <= 0.10) continue;
    // tiefe Linien zaehlen mehr, nahe Linien auch: sonst meldet die Lupe die
    // kraeftige Nachbarlinie, obwohl der Zeiger genau auf einer anderen steht
    const s = t * (1 - d / 3.2);
    if (s > bs) { bs = s; best = L; bt = t; }
  }
  return best ? { L: best, t: bt } : null;
}
function _spkWortAdj(t) { return t >= 0.55 ? 'kräftiger' : t >= 0.28 ? 'deutlicher' : 'schwacher'; }
function _spkWort(t)    { return t >= 0.55 ? 'kräftig'   : t >= 0.28 ? 'deutlich'   : t >= 0.10 ? 'schwach' : 'nicht zu sehen'; }

/* Zaehlung fuer Schritt 1 des Hefts: wie viele dunkle Streifen sind zu sehen
   und in welchen Farbbereichen liegen sie? Linien, die naeher als 1,5 nm
   beieinander stehen, zaehlen als eine - die Natrium-Doppellinie sieht man im
   Band ja auch nur als einen Streifen, erst die Lupe trennt sie. */
function _spkZaehlung() {
  const sicht = _SPK_LIN.filter(L => _spkTiefe(L) >= 0.12).sort((a, b) => a.lam - b.lam);
  const zahl = {}; let n = 0, vor = -99;
  for (const L of sicht) {
    if (L.lam - vor < 1.5) continue;
    vor = L.lam; n++;
    const b = _spkBereich(L.lam).d;
    zahl[b] = (zahl[b] || 0) + 1;
  }
  const teile = _SPK_BEREICH.filter(b => zahl[b.d]).map(b => zahl[b.d] + ' im ' + b.d);
  return { n, text: teile.length ? teile.join(', ') + ' Bereich' : '' };
}
function _spkStatus() {
  const el = document.getElementById('spkStatus'); if (!el || !_spk) return;
  const q = _SPK_Q[_spk.q], lam = _spk.lupe, ber = _spkBereich(lam), tr = _spkTreffer();

  const wert = document.getElementById('spkLupeWert');
  if (wert) wert.textContent = _fpmNum(lam, 0) + ' nm';

  let s = '<b>' + q.name + '</b><br>' + q.typ + ' · Oberfläche etwa ' + q.grad + ' °C<br>';
  s += '<br>Lupe bei <b>' + _fpmNum(lam, 0) + ' nm</b> (' + ber.n + '): ';
  if (!tr) {
    s += 'das Farbband leuchtet hier, <b>kein dunkler Streifen</b>.';
  } else {
    const e = _SPK_EL.find(x => x.k === tr.L.el);
    s += '<b>' + _spkWortAdj(tr.t) + ' dunkler Streifen</b>';
    if (_spk.streifen) {
      s += ' → <b style="color:' + e.farbe + '">' + e.name + '</b>';
      if (tr.L.el === 'Na') s += ' (Doppellinie, dicht neben der Helium-Linie bei 588 nm)';
    } else {
      s += '. Blende den Vergleichsstreifen ein, um das Element zu bestimmen.';
    }
  }
  s += '<br><br>';

  if (q.id === 'lampe') {
    s += '<b>Gegenprobe:</b> Das Farbband ist <b>lückenlos</b> – kein einziger Streifen fehlt. ' +
         'Der glühende Draht hat keine Gashülle davor, die Farben verschlucken könnte.';
  } else if (_spk.streifen) {
    s += _SPK_EL.map(e => e.name + ': <b>' + _spkWort(_spk.tiefe[e.k]) + '</b>').join(' · ');
  } else {
    const z = _spkZaehlung();
    s += '<b>' + z.n + ' dunkle Streifen</b> gefunden' + (z.text ? ': ' + z.text : '') + '.';
  }
  el.innerHTML = s;
}
// ── Bewegung ──────────────────────────────────────────────────────────────

function _spkUpdate(dt) {
  if (!_spk) return;
  const d = Math.min(dt, 0.05);
  _spk.t += d;
  const q = _SPK_Q[_spk.q];

  /* Die Linienstaerken gleiten zu ihrem neuen Wert, statt zu springen. Beim
     Umschalten von Stern zu Stern sieht man dadurch genau das, worum es geht:
     Die Linien bleiben an DERSELBEN Stelle stehen und werden nur staerker
     oder schwaecher. Ein harter Wechsel saehe aus wie ein anderes Muster. */
  let bewegt = false;
  for (const k in _spk.tiefe) {
    const ziel = q.st[k], ist = _spk.tiefe[k];
    if (Math.abs(ziel - ist) > 0.002) { _spk.tiefe[k] = ist + (ziel - ist) * Math.min(1, d * 3.2); bewegt = true; }
    else _spk.tiefe[k] = ziel;
  }

  // Der Vergleichsstreifen schiebt sich von unten unter das Band - wie das
  // Papierlineal, das im Heft untergeschoben wird.
  const zs = _spk.streifen ? 1 : 0;
  if (Math.abs(_spk.slide - zs) > 0.003) _spk.slide += (zs - _spk.slide) * Math.min(1, d * 4.5);
  else _spk.slide = zs;

  // Suchlauf: solange niemand am Regler zieht, wandert die Lupe von selbst
  // ueber das Band. So steht das Bild nie still, auch ohne Knopfdruck.
  if (_spk.auto) {
    _spk.lupe += _spk.richtung * 20 * d;
    if (_spk.lupe >= _SPK_L1) { _spk.lupe = _SPK_L1; _spk.richtung = -1; }
    if (_spk.lupe <= _SPK_L0) { _spk.lupe = _SPK_L0; _spk.richtung = 1; }
    const r = document.getElementById('spkLupe');
    if (r) r.value = Math.round(_spk.lupe * 2) / 2;
  }

  // Der Statustext wird hoechstens fuenfmal je Sekunde neu gesetzt - bei jedem
  // Einzelbild waere es unlesbares Flackern und unnoetige DOM-Arbeit.
  _spk.tStatus -= d;
  if ((_spk.auto || bewegt) && _spk.tStatus <= 0) { _spk.tStatus = 0.2; _spkStatus(); }
}
// ── Bild ──────────────────────────────────────────────────────────────────

/* Lichtquelle links: entweder der Stern mit seiner Gashuelle oder die
   Gluehlampe ohne. Der Unterschied im Bild ist der Grund fuer den Unterschied
   im Farbband - deshalb ist die Huelle als eigener Ring gezeichnet. */
function _spkQuelleZeichnen(ctx, q, t) {
  const x = 48, y = 38, puls = 1 + 0.05 * Math.sin(t * 1.3);
  if (q.id === 'lampe') {
    _wrGlanz(ctx, x, y, 34 * puls, q.glanz, 0.6);
    ctx.fillStyle = '#6b7280';
    ctx.fillRect(x - 27, y - 6, 12, 12);                 // Sockel
    ctx.fillStyle = 'rgba(255,246,214,0.14)';
    ctx.beginPath(); ctx.arc(x, y, 14, 0, 6.283); ctx.fill();
    ctx.strokeStyle = 'rgba(255,240,200,0.5)'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.arc(x, y, 14, 0, 6.283); ctx.stroke();
    ctx.strokeStyle = '#fff3c4'; ctx.lineWidth = 1.6;    // Gluehwendel
    ctx.beginPath();
    for (let i = 0; i <= 8; i++) {
      const px = x - 8 + i * 2, py = y + (i % 2 ? -5 : 5);
      i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
    }
    ctx.stroke();
    _wrGlanz(ctx, x, y, 12, '255,240,190', 0.9);
  } else {
    _wrGlanz(ctx, x, y, 40 * puls, q.glanz, 0.7);
    _wrKoerper(ctx, x, y, 15, q.koerper, { lx: 0, ly: 0, rand: false });
    // Gashuelle: hier entstehen die dunklen Linien
    ctx.strokeStyle = 'rgba(' + q.glanz + ',' + (0.30 + 0.10 * Math.sin(t * 1.3)).toFixed(2) + ')';
    ctx.lineWidth = 4;
    ctx.beginPath(); ctx.arc(x, y, 19.5, 0, 6.283); ctx.stroke();
  }
}
/* Prisma und Strahlengang. Der weisse Strahl faellt links ein, wird im Glas
   geknickt und faechert beim Austritt auf: Violett wird am staerksten
   abgelenkt und trifft das Band links, Rot am wenigsten und trifft rechts. */
function _spkStrahlen(ctx, q, t) {
  const A = [130, 10], B = [100, 68], C = [160, 68];   // Prisma
  const ein = [64, 38], pE = [114.5, 40], pA = [147, 44];

  // Weisser Strahl bis ins Glas
  _wrSpur(ctx, [ein, pE], '255,252,240', 1.5);
  _wrSpur(ctx, [pE, pA], '255,252,240', 1.3);

  // Glaskoerper
  const gg = ctx.createLinearGradient(A[0], A[1], C[0], C[1]);
  gg.addColorStop(0, 'rgba(206,226,255,0.20)');
  gg.addColorStop(1, 'rgba(150,180,235,0.08)');
  ctx.fillStyle = gg;
  ctx.beginPath();
  ctx.moveTo(A[0], A[1]); ctx.lineTo(B[0], B[1]); ctx.lineTo(C[0], C[1]); ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(200,222,255,0.55)'; ctx.lineWidth = 1.2; ctx.stroke();

  // Faecher: 26 Strahlen, alle 12 nm einer. Ihre Farbe UND ihre Helligkeit
  // kommen aus der Temperatur der Quelle - der heisse Stern schickt am blauen
  // Ende mehr los, der kuehle am roten.
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.lineWidth = 1.7;
  for (let lam = _SPK_L0; lam <= _SPK_L1; lam += 12) {
    const c = _spkRGB(lam, q.T);
    ctx.strokeStyle = 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',0.42)';
    ctx.beginPath(); ctx.moveTo(pA[0], pA[1]); ctx.lineTo(_spkX(lam), _SPK_BAND.y); ctx.stroke();
  }
  ctx.restore();

  // Lichtpakete laufen mit: eines auf dem weissen Strahl, drei im Faecher.
  // Damit fliesst sichtbar staendig Licht, auch wenn niemand etwas drueckt.
  const p1 = (t * 0.6) % 1;
  _wrGlanz(ctx, ein[0] + (pA[0] - ein[0]) * p1, ein[1] + (pA[1] - ein[1]) * p1, 7, '255,250,225', 0.85);
  [430, 545, 640].forEach((lam, i) => {
    const p = ((t * 0.55 + i * 0.33) % 1);
    const c = _spkRGB(lam, q.T);
    _wrGlanz(ctx, pA[0] + (_spkX(lam) - pA[0]) * p, pA[1] + (_SPK_BAND.y - pA[1]) * p,
             6, c[0] + ',' + c[1] + ',' + c[2], 0.8);
  });
}
/* Das Farbband mit den dunklen Linien. Die Linien werden ueber das gepufferte
   Band gelegt, damit ihre Tiefe weich wachsen kann, ohne dass das Band jedes
   Mal neu gerechnet werden muss. */
function _spkBand(ctx) {
  const B = _SPK_BAND, bild = _spkBandBild(_spk.q);
  ctx.drawImage(bild, 0, 0, bild.width, 1, B.x, B.y, B.w, B.h);
  for (const L of _SPK_LIN) {
    const a = _spkTiefe(L);
    if (a < 0.02) continue;
    const x = _spkX(L.lam);
    // Kern plus zwei blasse Flanken: so bekommt die Linie einen weichen Rand,
    // ohne dass fuer jede ein eigener Verlauf erzeugt werden muss.
    ctx.fillStyle = 'rgba(6,8,18,' + (a * 0.92).toFixed(3) + ')';
    ctx.fillRect(x - 1.1, B.y, 2.2, B.h);
    ctx.fillStyle = 'rgba(6,8,18,' + (a * 0.32).toFixed(3) + ')';
    ctx.fillRect(x - 2.3, B.y, 1.2, B.h);
    ctx.fillRect(x + 1.1, B.y, 1.2, B.h);
  }
  ctx.strokeStyle = 'rgba(200,215,245,0.35)'; ctx.lineWidth = 1;
  ctx.strokeRect(B.x - 0.5, B.y - 0.5, B.w + 1, B.h + 1);
}
/* Wellenlaengen-Lineal unter dem Band. Erst dadurch ist nachpruefbar, dass
   jede Linie wirklich an ihrer Stelle sitzt - 656 nm liegt im Rot, 410 nm
   ganz aussen im Violett. */
function _spkSkala(ctx) {
  const B = _SPK_BAND, y = B.y + B.h;
  ctx.strokeStyle = 'rgba(160,180,215,0.45)'; ctx.lineWidth = 1;
  ctx.beginPath();
  for (let lam = _SPK_L0; lam <= _SPK_L1; lam += 25) {
    const x = _spkX(lam);
    ctx.moveTo(x, y + 2); ctx.lineTo(x, y + (lam % 100 === 0 ? 8 : 5));
  }
  ctx.stroke();
  for (let lam = _SPK_L0; lam <= _SPK_L1; lam += 100)
    _wrText(ctx, _spkX(lam), y + 19, lam + (lam === _SPK_L0 ? ' nm' : ''),
            { font: '9px system-ui, sans-serif', farbe: '#8fa2c6' });
}
/* Der Vergleichsstreifen: je Element eine Zeile mit seinen Linien, auf
   demselben Massstab wie das Band. Wer eine dunkle Linie im Band mit einer
   farbigen Linie in einer Zeile zur Deckung bringt, hat das Element gefunden.
   Die Zeile, die gerade unter der Lupe passt, wird hervorgehoben. */
function _spkStreifenZeichnen(ctx, tr) {
  const B = _SPK_BAND, s = _spk.slide, off = (1 - s) * 130;
  ctx.save();
  ctx.globalAlpha = Math.min(1, s * 1.4);
  _SPK_EL.forEach((e, i) => {
    const y = 176 + i * 26 + off, treffer = tr && tr.L.el === e.k && _spk.streifen;
    ctx.fillStyle = treffer ? 'rgba(28,36,64,0.92)' : 'rgba(10,14,28,0.85)';
    ctx.fillRect(B.x, y, B.w, 21);
    ctx.strokeStyle = treffer ? 'rgba(' + e.rgb + ',0.85)' : 'rgba(150,170,210,0.25)';
    ctx.lineWidth = 1;
    ctx.strokeRect(B.x + 0.5, y + 0.5, B.w - 1, 20);
    ctx.fillStyle = e.farbe;
    for (const L of e.lin) ctx.fillRect(_spkX(L) - 1.1, y + 2, 2.2, 17);
    _wrText(ctx, B.x - 8, y + 15, e.name,
            { align: 'right', font: (treffer ? '600 ' : '') + '10px system-ui, sans-serif', farbe: e.farbe });
    // Lotlinie vom Band zur passenden Zeile: die Zuordnung selbst, sichtbar
    if (treffer) {
      ctx.strokeStyle = 'rgba(' + e.rgb + ',0.7)'; ctx.setLineDash([3, 3]);
      ctx.beginPath();
      ctx.moveTo(_spkX(tr.L.lam), B.y + B.h + 2); ctx.lineTo(_spkX(tr.L.lam), y);
      ctx.stroke(); ctx.setLineDash([]);
    }
  });
  ctx.restore();
}
/* Lupe: ein 14 nm breiter Ausschnitt des Bandes, rund zwoelfmal vergroessert.
   Erst hier trennen sich die Natrium-Doppellinie (589,0 und 589,6 nm) und die
   Helium-Linie bei 587,6 nm, die im ganzen Band als ein Streifen erscheinen. */
function _spkLupeZeichnen(ctx, q) {
  const B = _SPK_BAND, lam = _spk.lupe, cx = _spkX(lam);
  const spanne = 7, pw = 142, ph = 38, py = 56;
  const px = Math.max(B.x - 6, Math.min(B.x + B.w - pw + 6, cx - pw / 2));
  const l0 = lam - spanne, l1 = lam + spanne;

  // Markierung im Band
  ctx.strokeStyle = 'rgba(255,255,255,0.85)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(cx, B.y - 3); ctx.lineTo(cx, B.y + B.h + 3); ctx.stroke();

  // Sichtstrahlen vom Bandausschnitt zum Lupenfenster
  ctx.strokeStyle = 'rgba(190,210,245,0.28)'; ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(_spkX(Math.max(_SPK_L0, l0)), B.y); ctx.lineTo(px, py + ph);
  ctx.moveTo(_spkX(Math.min(_SPK_L1, l1)), B.y); ctx.lineTo(px + pw, py + ph);
  ctx.stroke();

  // Fenster: Farbverlauf des Ausschnitts, drei Stuetzstellen reichen auf 14 nm
  const g = ctx.createLinearGradient(px, 0, px + pw, 0);
  g.addColorStop(0,   _spkCSS(Math.max(_SPK_L0, l0), q.T));
  g.addColorStop(0.5, _spkCSS(lam, q.T));
  g.addColorStop(1,   _spkCSS(Math.min(_SPK_L1, l1), q.T));
  ctx.fillStyle = g;
  ctx.fillRect(px, py, pw, ph);
  for (const L of _SPK_LIN) {
    const a = _spkTiefe(L);
    if (a < 0.05 || L.lam < l0 || L.lam > l1) continue;
    const x = px + (L.lam - l0) / (2 * spanne) * pw;
    ctx.fillStyle = 'rgba(6,8,18,' + (a * 0.92).toFixed(3) + ')';
    ctx.fillRect(x - 1.8, py, 3.6, ph);
    ctx.fillStyle = 'rgba(6,8,18,' + (a * 0.3).toFixed(3) + ')';
    ctx.fillRect(x - 3.4, py, 1.6, ph);
    ctx.fillRect(x + 1.8, py, 1.6, ph);
  }
  ctx.strokeStyle = 'rgba(220,232,255,0.75)'; ctx.lineWidth = 1.4;
  ctx.strokeRect(px - 0.5, py - 0.5, pw + 1, ph + 1);
  _wrText(ctx, px + pw / 2, py - 6, 'Lupe: ' + _fpmNum(lam, 0) + ' nm · ' + _spkBereich(lam).n,
          { font: '10px system-ui, sans-serif', farbe: '#e2e8ff' });
}
function _spkDraw(ctx, cv) {
  if (!_spk) return;
  const W = cv.width, t = _spk.t, q = _SPK_Q[_spk.q], tr = _spkTreffer();
  _wrHimmel(ctx, cv, t, { oben: '#080d20', unten: '#02030a', dichte: 0.7, seed: 19 });
  _spkQuelleZeichnen(ctx, q, t);
  _spkStrahlen(ctx, q, t);
  _spkBand(ctx);
  _spkSkala(ctx);
  if (_spk.slide > 0.01) _spkStreifenZeichnen(ctx, tr);
  _spkLupeZeichnen(ctx, q);
  _wrText(ctx, W - 10, 16, q.kurz + ' · ' + q.farbwort + ' · etwa ' + q.grad + ' °C',
          { align: 'right', font: '600 10.5px system-ui, sans-serif', farbe: '#dbeafe' });
}
// ── Oberflaeche ───────────────────────────────────────────────────────────

function _spkHTML() {
  const knoepfe = _SPK_Q.map((q, i) =>
    `<button class="sim-btn${i === 0 ? ' primary' : ''}" data-spk="${q.id}" onclick="_spkQuelle(${i})">${q.knopf}</button>`
  ).join('');
  return `<div class="sim-box sim-box-wide fpm-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🔭 Woraus bestehen die Sterne?</h3>
    <div class="fpm-note" style="margin-top:2px">Lass das Licht eines Sterns durch das Prisma fallen und suche im Farbband die dunklen Streifen. Blende dann den Vergleichsstreifen ein und ordne jede dunkle Linie dem Element zu, dessen Linie an derselben Stelle sitzt. Mit der Lupe (Regler oder Klick ins Band) siehst du jede Stelle vergrößert.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="spkAnim" width="470" height="286" class="phys-anim-cv" style="cursor:crosshair" onclick="_spkKlick(event)"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">${knoepfe}</div>
        <div class="sim-btn-row" style="margin-top:4px">
          <button class="sim-btn" id="spkStreifenBtn" onclick="_spkStreifen()">📏 Vergleichsstreifen einblenden</button>
          <button class="sim-btn primary" id="spkAutoBtn" onclick="_spkSuchlauf()">🔍 Suchlauf</button>
        </div>
        <div class="phys-ctrl" style="margin-top:6px">
          <span class="phys-ctrl-label">Lupe – Wellenlänge: <span id="spkLupeWert">656 nm</span></span>
          <input type="range" id="spkLupe" min="400" max="700" step="0.5" value="656"
                 oninput="_spkLupe(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
      </div>
      <div>
        <div class="fpm-label">Beobachtung</div>
        <div class="lmp-status on" id="spkStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Über der glühenden Oberfläche jedes Sterns liegt eine <b>Gashülle</b>. Ihre Atome <b>verschlucken genau die Farben, die sie selbst aussenden könnten</b> – jedes Element immer bei denselben Wellenlängen. Dieses Licht fehlt uns, deshalb sehen wir dort einen dunklen Streifen.</div>
        <div class="fpm-note" style="margin-top:8px">Das Muster ist ein <b>Fingerabdruck</b>: Bei allen drei Sternen sitzen die Wasserstofflinien an genau derselben Stelle, nur unterschiedlich kräftig. Wie kräftig eine Linie ist, verrät die <b>Temperatur</b>. Die Glühlampe hat gar keine Gashülle davor – ihr Band ist lückenlos.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Heiß und blau-weiß → fast nur <b>Wasserstoff</b> und <b>Helium</b>. &nbsp;|&nbsp; Kühl und rot → zusätzlich <b>Natrium</b> und <b>Eisen</b>. &nbsp;|&nbsp; Glühlampe → <b>keine Lücke</b>.
    </p>
  </div>`;
}

// ═══ MILCHSTRASSE ════════════════════════════════════════════
/* ══════════════════════════════════════════════════════════════════════
   DIE MILCHSTRASSE – WO STEHEN WIR?
   Zwei Fenster: links die ganze Galaxie (von oben bis zur Seitenansicht
   drehbar), rechts der Himmel, den man von der Sonne aus in der
   eingestellten Richtung sieht. Die Sternzahl im rechten Fenster wird
   NICHT geraten, sondern entlang der Sichtlinie aus dem Scheibenmodell
   aufsummiert - deshalb passen Bild und Zahl immer zusammen.
   ══════════════════════════════════════════════════════════════════════ */
let _mst = null;

/* Alle Laengen in Lichtjahren. Die Zahlen sind die heute gemessenen:
   Scheibe rund 100 000 Lj breit (also 50 000 Lj Radius), aber nur etwa
   1000 Lj dick (500 Lj nach oben, 500 nach unten) - hundertmal breiter
   als dick. Die Sonne steht 26 000 Lj vom Zentrum entfernt. */
const _MST_RAND   = 50000;   // Radius der Sternscheibe
const _MST_DICK   = 500;     // halbe Scheibendicke
const _MST_HR     = 9000;    // radiale Skalenlaenge: nach aussen wird es duenner
const _MST_HZ     = 350;     // Skalenhoehe senkrecht zur Scheibe
const _MST_SICHT  = 6000;    // Staub in der Scheibe verschluckt fernes Licht
const _MST_SKALA  = 0.25;    // rechnet die Saeulendichte in "Sterne im Blickfeld" um
const _MST_R0     = 26000;   // echter Abstand der Sonne vom Zentrum
const _MST_BULGE  = 6000;    // zentrale Verdickung
const _MST_BALKEN = 13500;   // halbe Laenge des Balkens
const _MST_UMLAUF = 225;     // Mio. Jahre fuer einen Umlauf der Sonne
const _MST_WSUN   = -0.90;   // Winkel der Sonne im Ruhesystem der Galaxie
const _MST_SKYW   = 420;     // Groesse des zweiten Fensters (wie im HTML)
const _MST_SKYH   = 220;
const _MST_MAXST  = 210;     // mehr Sterne zeichnet das zweite Fenster nie

/* Die drei Blickrichtungen der Hefttabelle. dr = Schritt in der Scheibe
   (zum Zentrum oder nach aussen), dz = Schritt senkrecht heraus. */
const _MST_RI = [
  { k: 'mitte',  n: 'längs durch die Scheibe zur Mitte', kurz: 'zur Mitte',   dr: -1, dz: 0, band: 10 },
  { k: 'aussen', n: 'längs durch die Scheibe nach außen', kurz: 'nach außen', dr:  1, dz: 0, band: 17 },
  { k: 'quer',   n: 'quer aus der Scheibe heraus',        kurz: 'quer heraus', dr: 0, dz: 1, band: 0  }
];
/* 26000 -> "26 000". toLocaleString setzt einen Punkt, und "26.000"
   liest ein Siebtklaessler als Komma-Zahl. */
function _mstZahl(v) {
  return String(Math.round(v)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
}
/* Sterndichte im Modell, bezogen auf die Dichte im Zentrum = 1.
   Nach aussen faellt sie exponentiell ab (Skalenlaenge 9000 Lj), nach oben
   und unten viel schneller (Skalenhoehe 350 Lj) - genau das macht die
   Scheibe duenn. */
function _mstDichte(r, z) {
  return Math.exp(-Math.abs(r) / _MST_HR - Math.abs(z) / _MST_HZ);
}
/* Zaehlt die Sterne laengs einer Sichtlinie: in Schritten von 200 Lj
   aufsummieren, wie viele Sterne dort stehen. Der Faktor exp(-s/6000)
   ist der Staub - fernes Licht in der Scheibe kommt nicht mehr an,
   deshalb sehen wir das Zentrum selbst nicht. Ohne diesen Faktor waere
   die Richtung "zur Mitte" 200-mal so hell wie "quer heraus"; gemessen
   sind es rund 40-mal. */
function _mstZaehl(idx, R0) {
  const d = _MST_RI[idx], ds = 200;
  let summe = 0;
  for (let s = ds / 2; s < 100000; s += ds) {
    const r = R0 + d.dr * s, z = d.dz * s;
    if (Math.abs(r) > _MST_RAND || Math.abs(z) > 6000) break;
    summe += _mstDichte(r, z) * Math.exp(-s / _MST_SICHT) * ds;
  }
  return summe * _MST_SKALA;
}
/* Sternwolke der Galaxie: einmal beim Start gebaut, danach nur noch
   gedreht. Gespeichert wird polar (r, w, z) im Ruhesystem der Galaxie -
   dann ist die Drehung ein einziger Winkel dazu, und die Neigung der
   Ansicht ist reine Projektion. */
function _mstBauSterne() {
  const rnd = _wrRnd(4711), st = [];
  const B = 0.2199;                       // tan(12,4 Grad): Steigungswinkel der Arme
  // 1) Zentrale Verdickung - dicker als die Scheibe, deshalb eigene Hoehe
  for (let i = 0; i < 34; i++) {
    st.push({ r: _MST_BULGE * Math.pow(rnd(), 0.7), w: rnd() * 6.283,
              z: (rnd() + rnd() - 1) * _MST_BULGE * 0.5, g: 0.4 + rnd() * 0.6 });
  }
  // 2) Balken: die Milchstrasse ist eine BALKENspiralgalaxie, der Balken
  //    ist rund 27 000 Lj lang und liegt schraeg zu unserer Blickrichtung
  for (let i = 0; i < 26; i++) {
    const u = (rnd() * 2 - 1) * _MST_BALKEN, q = (rnd() * 2 - 1) * 2400;
    const x = u * Math.cos(0.55) - q * Math.sin(0.55);
    const y = u * Math.sin(0.55) + q * Math.cos(0.55);
    st.push({ r: Math.hypot(x, y), w: Math.atan2(y, x),
              z: (rnd() + rnd() - 1) * 900, g: 0.35 + rnd() * 0.6 });
  }
  // 3) Vier Spiralarme: logarithmische Spirale, am Balkenende beginnend
  for (let i = 0; i < 152; i++) {
    const th = 0.15 + rnd() * 1.85 * Math.PI;
    let r = _MST_BALKEN * Math.exp(B * th) * (1 + (rnd() + rnd() - 1) * 0.13);
    if (r > _MST_RAND) continue;
    st.push({ r, w: (i % 4) * Math.PI / 2 + th + (rnd() - 0.5) * 0.22,
              z: (rnd() + rnd() + rnd() - 1.5) * _MST_HZ * 1.5, g: rnd() });
  }
  // 4) Sterne zwischen den Armen: radial exponentiell verteilt, wie die
  //    Rechnung im zweiten Fenster es annimmt
  for (let i = 0; i < 30; i++) {
    const r = Math.min(_MST_RAND, -_MST_HR * Math.log(1 - rnd() * 0.98));
    st.push({ r, w: rnd() * 6.283, z: (rnd() + rnd() + rnd() - 1.5) * _MST_HZ * 1.5,
              g: rnd() * 0.7 });
  }
  // 5) Orionarm: der kurze Nebenarm, in dem die Sonne steht. Ohne ihn
  //    saesse der Sonnenpunkt im Leeren zwischen zwei grossen Armen.
  for (let i = 0; i < 16; i++) {
    const u = (rnd() * 2 - 1) * 6000, q = (rnd() * 2 - 1) * 1200;
    const x = _MST_R0 * Math.cos(_MST_WSUN) + u * 0.86 - q * 0.5;
    const y = _MST_R0 * Math.sin(_MST_WSUN) + u * 0.5 + q * 0.86;
    st.push({ r: Math.hypot(x, y), w: Math.atan2(y, x),
              z: (rnd() + rnd() - 1) * _MST_HZ, g: 0.3 + rnd() * 0.5 });
  }
  return st;
}
/* Mittellinien der vier Arme fuer das leuchtende Band unter den Sternen. */
function _mstBauArme() {
  const B = 0.2199, arme = [];
  for (let a = 0; a < 4; a++) {
    const p = [];
    for (let k = 0; k <= 18; k++) {
      const th = 0.15 + (k / 18) * 1.85 * Math.PI;
      const r = _MST_BALKEN * Math.exp(B * th);
      if (r > _MST_RAND) break;
      p.push([r, a * Math.PI / 2 + th]);
    }
    arme.push(p);
  }
  return arme;
}
/* Sternhimmel des zweiten Fensters. n Sterne werden so verteilt, wie die
   Sichtlinie sie antrifft: laengs durch die Scheibe draengen sie sich in
   einem schmalen Band (senkrecht exponentiell, wie die Scheibe selbst),
   quer heraus liegen sie gleichmaessig verstreut. Ein Sechstel steht immer
   ringsum - das sind die nahen Sterne, die es in jeder Richtung gibt. */
function _mstBauHimmel(n, idx, R0) {
  const d = _MST_RI[idx];
  const rnd = _wrRnd(idx * 977 + Math.round(R0 / 1000) * 31 + 7);
  const mitte = _MST_SKYH * 0.52, hs = [];
  for (let i = 0; i < n; i++) {
    let y;
    if (!d.band || rnd() < 0.16) {
      y = rnd() * _MST_SKYH;
    } else {
      const a = -Math.log(1 - rnd() * 0.999) * d.band;
      y = mitte + (rnd() < 0.5 ? -a : a);
      if (y < 1 || y > _MST_SKYH - 1) y = rnd() * _MST_SKYH;
    }
    const g = Math.pow(rnd(), 2.6);
    const f = rnd();
    hs.push({ x: rnd() * _MST_SKYW, y, r: 0.5 + g * 1.7, a: 0.3 + g * 0.62,
              ph: rnd() * 6.283,
              f: f > 0.88 ? '188,208,255' : f < 0.12 ? '255,226,180' : '255,255,255' });
  }
  return hs;
}
function _mstInit() {
  _mst = {
    t: 0,
    ri: 0,                    // gewaehlte Blickrichtung (Index in _MST_RI)
    neig: 0,                  // 0 Grad = von oben, 90 Grad = von der Seite
    R0: _MST_R0,              // Abstand der Sonne vom Zentrum
    sterne: _mstBauSterne(),
    arme: _mstBauArme(),
    zahl: 0, quer: 0, probe: 1, himmel: []
  };
  _mstMess();
}
/* Nach jeder Aenderung neu rechnen: Sternzahl der eingestellten Richtung,
   Vergleichswert "quer heraus" und der dazu passende Himmel. Bis 210
   Sterne wird jeder einzelne gezeichnet - die drei Zeilen der Hefttabelle
   liegen genau in diesem Bereich, dort stimmt das Bild also Stern fuer
   Stern mit der Zahl ueberein. Darueber (Gegenprobe im Zentrum) wird nur
   noch jeder n-te gemalt, und das steht dann auch im Bild. */
function _mstMess() {
  if (!_mst) return;
  _mst.zahl = _mstZaehl(_mst.ri, _mst.R0);
  _mst.quer = _mstZaehl(2, _mst.R0);
  const n = Math.max(1, Math.round(_mst.zahl));
  _mst.probe = Math.max(1, Math.ceil(n / _MST_MAXST));
  _mst.himmel = _mstBauHimmel(Math.max(2, Math.round(n / _mst.probe)), _mst.ri, _mst.R0);
}
function _mstSetRichtung(i) {
  if (!_mst) return;
  _mst.ri = i;
  _mstMess(); _mstStatus();
  document.querySelectorAll('[data-mst]').forEach(b => {
    b.classList.toggle('primary', b.dataset.mst === 'ri:' + i);
  });
}
function _mstSetNeigung(v) {
  if (!_mst) return;
  _mst.neig = +v;
  const el = document.getElementById('mstNeigLbl');
  if (el) el.textContent = _mst.neig < 12 ? 'von oben (' + Math.round(_mst.neig) + '°)'
        : _mst.neig > 78 ? 'von der Seite (' + Math.round(_mst.neig) + '°)'
        : 'schräg (' + Math.round(_mst.neig) + '°)';
}
/* Der Sonnenpunkt wandert auf seinem Strahl zum Zentrum - genau die
   Bewegung, die das Heft als Gegenprobe verlangt. */
function _mstSetSonne(v) {
  if (!_mst) return;
  _mst.R0 = +v;
  const el = document.getElementById('mstR0Lbl');
  if (el) el.textContent = _mstZahl(_mst.R0) + ' Lichtjahre';
  _mstMess(); _mstStatus();
}
function _mstGegenprobe() { _mstSchieben(0); }
function _mstEcht()       { _mstSchieben(_MST_R0); }
/* Knopf und Regler muessen dasselbe sagen: erst den Schieber nachziehen,
   dann rechnen. Sonst steht "26 000" am Regler und die Sonne sitzt im Kern. */
function _mstSchieben(v) {
  const s = document.getElementById('mstR0');
  if (s) s.value = v;
  _mstSetSonne(v);
}
function _mstHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🌌 Die Milchstraße – wo stehen wir?</h3>
    <div class="fpm-note" style="margin-top:2px">Links die ganze Galaxie: mit dem Regler von oben bis zur Seitenansicht drehen und den Punkt der Sonne suchen. Rechts der Himmel, den man von der Sonne aus in der eingestellten Richtung sieht.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="mstAnim" width="420" height="340" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <span class="fpm-label" style="margin-right:4px">Blickrichtung</span>
          <button class="sim-btn primary" data-mst="ri:0" onclick="_mstSetRichtung(0)">zur Mitte</button>
          <button class="sim-btn"         data-mst="ri:1" onclick="_mstSetRichtung(1)">nach außen</button>
          <button class="sim-btn"         data-mst="ri:2" onclick="_mstSetRichtung(2)">quer heraus</button>
        </div>
        <div class="phys-ctrl" style="margin-top:6px">
          <span class="phys-ctrl-label">Ansicht drehen: <b id="mstNeigLbl">von oben (0°)</b></span>
          <input type="range" id="mstNeig" min="0" max="90" step="1" value="0"
                 oninput="_mstSetNeigung(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="phys-ctrl">
          <span class="phys-ctrl-label">Sonne vom Zentrum: <b id="mstR0Lbl">26 000 Lichtjahre</b></span>
          <input type="range" id="mstR0" min="0" max="45000" step="1000" value="26000"
                 oninput="_mstSetSonne(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="sim-btn-row" style="margin-top:4px">
          <button class="sim-btn" onclick="_mstGegenprobe()">Gegenprobe: Sonne in die Mitte</button>
          <button class="sim-btn" onclick="_mstEcht()">zurück auf 26 000 Lj</button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Blick von der Sonne aus</div>
        <canvas id="mstSky" width="${_MST_SKYW}" height="${_MST_SKYH}" class="phys-anim-cv"></canvas>
        <div class="lmp-status on" id="mstStatus" style="margin-top:8px"></div>
        <div class="fpm-note" style="margin-top:10px">Die Milchstraße ist eine <b>Balkenspiralgalaxie</b>: rund <b>100 000 Lichtjahre</b> breit, die Scheibe aber nur etwa <b>1000 Lichtjahre</b> dick – hundertmal breiter als dick. Unsere Sonne steht <b>26 000 Lichtjahre</b> vom Zentrum entfernt im <b>Orionarm</b>, also weder in der Mitte noch am Rand; für einen Umlauf braucht sie rund ${_MST_UMLAUF} Millionen Jahre. Längs durch die Scheibe stehen sehr viele Sterne hintereinander, quer heraus nur wenige – daher das milchige Band am Himmel.</div>
      </div>
    </div>
  </div>`;
}
function _mstStatus() {
  const el = document.getElementById('mstStatus');
  if (!el || !_mst) return;
  const d = _MST_RI[_mst.ri];
  const n = Math.max(1, Math.round(_mst.zahl));
  const q = Math.max(0.05, _mst.quer);
  const v = _mst.zahl / q;
  // Der Vergleichssatz nimmt immer "quer heraus" bei der eingestellten
  // Sonnenposition als Mass - genau die Gegenueberstellung der Hefttabelle.
  const vgl = _mst.ri === 2 ? 'Das ist der Vergleichswert für die anderen beiden Zeilen.'
            : 'Das sind <b>' + _mstZahl(Math.round(v)) + '-mal</b> so viele wie quer aus der Scheibe heraus.';
  let hin;
  if (_mst.R0 < 3000) {
    hin = '<b>Gegenprobe:</b> Von der Mitte aus wären beide Richtungen <b>längs</b> durch die Scheibe gleich dicht – ein Band ohne helle und schwache Seite. Genau das sehen wir am Himmel <b>nicht</b>: Zum Sternbild Schütze hin ist das Band deutlich heller.';
  } else if (_mst.ri === 0) {
    hin = 'Blick durch die dichteste Gegend der Scheibe – das hellste Stück des Bandes. Das Zentrum selbst bleibt hinter Staub verborgen.';
  } else if (_mst.ri === 1) {
    hin = 'Auch längs durch die Scheibe, aber nach außen wird sie dünner – das Band ist hier schwächer.';
  } else {
    hin = 'Senkrecht heraus ist die Scheibe schon nach wenigen hundert Lichtjahren zu Ende – kaum Sterne, freier Blick ins All.';
  }
  el.innerHTML =
    `<b>${d.n}</b><br>` +
    `Sonne ${_mstZahl(_mst.R0)} Lichtjahre vom Zentrum` +
    (Math.abs(_mst.R0 - _MST_R0) < 500 ? ' (echter Wert)' : '') + '<br>' +
    `Sterne im Blickfeld: <b>${_mstZahl(n)}</b><br>${vgl}<br>${hin}`;
}
function _mstUpdate(dt) {
  if (!_mst) return;
  _mst.t += Math.min(dt, 0.05);
}
/* ── Fenster 1: die ganze Galaxie ──────────────────────────────────────
   Der Massstab ist FEST (rund 0,00256 px je Lichtjahr) und aendert sich
   beim Drehen nicht. Nur so beweist die Seitenansicht etwas: die Scheibe
   bleibt 256 px breit und schrumpft auf gut 2 px Hoehe zusammen. */
function _mstDraw(ctx, cv) {
  if (!_mst) return;
  const W = cv.width, H = cv.height, t = _mst.t;
  const cx = W / 2, cy = H / 2 - 4;
  const s = 128 / _MST_RAND;
  const nb = _mst.neig * Math.PI / 180, ci = Math.cos(nb), si = Math.sin(nb);
  /* Die Scheibe dreht sich im Uhrzeigersinn (negativer Winkel). Das ist
     kein Geschmack: Spiralarme laufen HINTERHER (trailing), ihre Enden
     zeigen also entgegen der Drehrichtung. Andersherum gedreht liefen die
     Arme voran - so etwas gibt es am Himmel nicht. Eine volle Runde dauert
     hier gut hundert Sekunden, in Wirklichkeit 225 Millionen Jahre. */
  const ang = -t * 0.055;
  const wS = _MST_WSUN + ang;

  /* Projektion: von oben sieht man die Ebene (x,y), von der Seite nur noch
     die Hoehe z. Das Minus vor z legt "oben aus der Scheibe heraus" auch im
     Bild nach oben. */
  const px = x => cx + x * s;
  const py = (y, z) => cy + (y * ci - z * si) * s;

  _wrHimmel(ctx, cv, t, { oben: '#060a1e', unten: '#01020a', dichte: 0.55, seed: 29 });

  // ── milchiger Schein der Scheibe ────────────────────────────────────
  // Ein einziger Verlauf, in der Hoehe gestaucht: von oben ein Kreis, von
  // der Seite ein hauchduenner Streifen.
  const fD = Math.max(_MST_DICK / _MST_RAND, ci);
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.translate(cx, cy); ctx.scale(1, fD);
  const gD = ctx.createRadialGradient(0, 0, _MST_RAND * s * 0.04, 0, 0, _MST_RAND * s);
  gD.addColorStop(0, 'rgba(198,214,255,0.30)');
  gD.addColorStop(0.38, 'rgba(136,164,238,0.12)');
  gD.addColorStop(1, 'rgba(80,110,200,0)');
  ctx.fillStyle = gD;
  ctx.beginPath(); ctx.arc(0, 0, _MST_RAND * s, 0, 6.283); ctx.fill();
  ctx.restore();

  // ── Spiralarme als leuchtende Baender ───────────────────────────────
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  for (const arm of _mst.arme) {
    for (const [br, al] of [[13, 0.055], [5, 0.10]]) {
      ctx.strokeStyle = 'rgba(150,180,255,' + al + ')';
      ctx.lineWidth = br;
      ctx.beginPath();
      arm.forEach((p, i) => {
        const w = p[1] + ang, X = px(p[0] * Math.cos(w)), Y = py(p[0] * Math.sin(w), 0);
        i ? ctx.lineTo(X, Y) : ctx.moveTo(X, Y);
      });
      ctx.stroke();
    }
  }
  ctx.restore();

  // ── zentrale Verdickung: von der Seite bleibt sie hoch, die Scheibe nicht
  ctx.save();
  ctx.translate(cx, cy); ctx.scale(1, Math.max(0.46, ci));
  _wrGlanz(ctx, 0, 0, _MST_BULGE * s * 2.4, '255,226,168', 0.5);
  ctx.restore();

  // ── die Sterne ──────────────────────────────────────────────────────
  for (const st of _mst.sterne) {
    const w = st.w + ang;
    const X = px(st.r * Math.cos(w)), Y = py(st.r * Math.sin(w), st.z);
    const r = 0.55 + st.g * 1.25;
    ctx.fillStyle = 'rgba(' + (st.g > 0.72 ? '198,216,255' : '255,250,238') + ',' +
                    (0.34 + st.g * 0.52).toFixed(2) + ')';
    ctx.beginPath(); ctx.arc(X, Y, r, 0, 6.283); ctx.fill();
  }

  // ── Bahn der Sonne um das Zentrum ───────────────────────────────────
  const rS = _mst.R0 * s;
  ctx.save();
  ctx.setLineDash([4, 5]);
  ctx.strokeStyle = 'rgba(253,224,171,0.45)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.ellipse(cx, cy, Math.max(1, rS), Math.max(0.4, rS * ci), 0, 0, 6.283);
  ctx.stroke();
  ctx.restore();

  // ── Blickrichtung als Pfeil, der im zweiten Fenster gilt ────────────
  const sx = px(_mst.R0 * Math.cos(wS)), sy = py(_mst.R0 * Math.sin(wS), 0);
  const d = _MST_RI[_mst.ri];
  // Richtungsvektor in der Galaxie: laengs der Scheibe (zum Zentrum oder
  // nach aussen) oder senkrecht heraus.
  const len = d.dz ? 9000 : 13000;
  const ex = px(_mst.R0 * Math.cos(wS) + d.dr * len * Math.cos(wS));
  const ey = py(_mst.R0 * Math.sin(wS) + d.dr * len * Math.sin(wS), d.dz * len);
  const lp = Math.hypot(ex - sx, ey - sy);
  let lx = sx, ly = sy;
  if (lp > 9) {
    _wrSpur(ctx, [[sx, sy], [ex, ey]], '134,239,172', 1.5);
    const ux = (ex - sx) / lp, uy = (ey - sy) / lp;
    ctx.fillStyle = 'rgba(134,239,172,0.95)';
    ctx.beginPath();
    ctx.moveTo(ex, ey);
    ctx.lineTo(ex - ux * 8 - uy * 4, ey - uy * 8 + ux * 4);
    ctx.lineTo(ex - ux * 8 + uy * 4, ey - uy * 8 - ux * 4);
    ctx.closePath(); ctx.fill();
    lx = ex + ux * 6; ly = ey + uy * 6;
  } else {
    /* Von oben zeigt "quer heraus" genau auf uns zu - ein Pfeil waere nur
       ein Punkt. Deshalb das Zeichen fuer "aus dem Bild heraus": Kreis mit
       Punkt. Wer die Richtung sehen will, muss die Ansicht drehen. */
    ctx.strokeStyle = 'rgba(134,239,172,0.95)'; ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.arc(sx, sy - 14, 6, 0, 6.283); ctx.stroke();
    ctx.fillStyle = 'rgba(134,239,172,0.95)';
    ctx.beginPath(); ctx.arc(sx, sy - 14, 1.8, 0, 6.283); ctx.fill();
    lx = sx; ly = sy - 24;
  }

  // ── die Sonne ───────────────────────────────────────────────────────
  _wrGlanz(ctx, sx, sy, 15, '255,232,150', 0.9);
  _wrKoerper(ctx, sx, sy, 2.8, ['#fffdf0', '#ffe08a', '#ffb03a'], { rand: false });

  // ── Beschriftung: nie mehr als vier Texte gleichzeitig ──────────────
  _wrText(ctx, 10, 16, 'Ansicht: ' + (_mst.neig < 12 ? 'von oben' : _mst.neig > 78 ? 'von der Seite' : 'schräg') +
          ' (' + Math.round(_mst.neig) + '°)',
          { align: 'left', font: '10px system-ui, sans-serif', farbe: '#93a4c8' });

  const rechts = sx > cx;
  _wrText(ctx, sx + (rechts ? -9 : 9), sy + (sy < 26 ? 20 : -9),
          'Sonne · ' + _mstZahl(_mst.R0) + ' Lj vom Zentrum',
          { align: rechts ? 'right' : 'left', font: '600 10px system-ui, sans-serif', farbe: '#ffe9b0' });

  _wrText(ctx, Math.max(58, Math.min(W - 58, lx)), Math.max(30, Math.min(H - 26, ly)),
          'Blick ' + d.kurz, { font: '10px system-ui, sans-serif', farbe: '#bbf7d0' });

  // Massband: die Breite steht immer als Pfeil da, der Text darueber
  // wechselt - in der Seitenansicht ist die Dicke die Nachricht.
  const my = H - 20, mx0 = cx - _MST_RAND * s, mx1 = cx + _MST_RAND * s;
  ctx.strokeStyle = 'rgba(147,164,200,0.75)'; ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(mx0, my); ctx.lineTo(mx1, my);
  ctx.moveTo(mx0 + 6, my - 4); ctx.lineTo(mx0, my); ctx.lineTo(mx0 + 6, my + 4);
  ctx.moveTo(mx1 - 6, my - 4); ctx.lineTo(mx1, my); ctx.lineTo(mx1 - 6, my + 4);
  ctx.stroke();
  _wrText(ctx, cx, my - 6, _mst.neig < 50
          ? '100 000 Lichtjahre breit'
          : 'Scheibe nur ~1000 Lichtjahre dick – 100-mal breiter als dick',
          { font: '10px system-ui, sans-serif', farbe: '#93a4c8' });

  _mstHimmelDraw();
}
/* ── Fenster 2: der Himmel von der Sonne aus ───────────────────────────
   Gezeichnet wird genau die Sternzahl, die die Rechnung fuer diese
   Richtung ergibt - das Bild ist also kein Dekor, sondern das Messergebnis.
   Der Himmel schwenkt langsam durch, damit das Fenster nie stillsteht. */
function _mstHimmelDraw() {
  const cv = document.getElementById('mstSky');
  if (!cv || !_mst) return;
  const ctx = cv.getContext('2d');
  const W = cv.width, H = cv.height, t = _mst.t;
  const d = _MST_RI[_mst.ri], band = H * 0.52;

  _wrHimmel(ctx, cv, t, { oben: '#070b1c', unten: '#02030a', sterne: false });

  // ── milchiger Schein: viele ferne Sterne, die einzeln keiner mehr sieht
  const hell = Math.min(1, _mst.zahl / 210);
  if (d.band) {
    for (let i = 0; i <= 6; i++) {
      _wrGlanz(ctx, (i / 6) * W, band + 2 * Math.sin(t * 0.4 + i), 44 + 8 * Math.sin(t * 0.5 + i * 1.3),
               '158,180,240', 0.04 + hell * 0.085);
    }
    // Zur Mitte hin steht die zentrale Verdickung im Blickfeld
    if (_mst.ri === 0) _wrGlanz(ctx, W * 0.5, band, 74, '255,228,176', 0.05 + hell * 0.10);
  }

  // ── die gezaehlten Sterne, mit langsamem Schwenk und Funkeln ────────
  const drift = (t * 4) % W;
  for (const st of _mst.himmel) {
    const x = (st.x + drift) % W;
    const f = 0.55 + 0.45 * Math.sin(t * 1.9 + st.ph);
    ctx.fillStyle = 'rgba(' + st.f + ',' + (st.a * (0.62 + 0.38 * f)).toFixed(3) + ')';
    ctx.beginPath(); ctx.arc(x, st.y, st.r * (0.88 + 0.24 * f), 0, 6.283); ctx.fill();
  }

  // ── Staub in der Scheibe: der dunkle Riss mitten im Band ────────────
  if (d.band) {
    ctx.save();
    ctx.lineCap = 'round';
    ctx.strokeStyle = 'rgba(3,5,14,' + (_mst.ri === 0 ? 0.6 : 0.42) + ')';
    ctx.lineWidth = _mst.ri === 0 ? 9 : 6;
    ctx.beginPath();
    for (let i = 0; i <= 8; i++) {
      const x = i / 8 * W, y = band - 3 + 5 * Math.sin(i * 0.85 + 0.6);
      i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
    }
    ctx.stroke();
    ctx.restore();
  }

  _wrText(ctx, 10, 16, 'Blick ' + d.kurz, { align: 'left', font: '600 10.5px system-ui, sans-serif', farbe: '#bbf7d0' });
  _wrText(ctx, 10, H - 10, 'Sterne im Blickfeld: ' + _mstZahl(Math.max(1, Math.round(_mst.zahl))),
          { align: 'left', font: '600 11px system-ui, sans-serif', farbe: '#e2e8f0' });
  if (d.band && hell > 0.15)
    _wrText(ctx, W - 10, band - 26, 'milchiges Band', { align: 'right', font: '10px system-ui, sans-serif', farbe: '#c7d2fe' });
  if (_mst.probe > 1)
    _wrText(ctx, W - 10, 16, 'gezeichnet: jeder ' + _mst.probe + '. Stern',
            { align: 'right', font: '9.5px system-ui, sans-serif', farbe: '#93a4c8' });
}

function openPhysicsSim(simId) {
  closePhysicsSim();
  const modal = document.createElement('div');
  modal.id = 'physModal';
  modal.className = 'sim-overlay';
  document.body.appendChild(modal);

  const fn = _physSimDefs[simId];
  if (fn) { fn(modal); return; }
  // Unbekannte Kennung: Frueher stand hier "wird vorbereitet…" - das klang nach
  // Warten, obwohl nichts mehr kam, und in der Konsole stand kein Wort davon.
  console.warn('openPhysicsSim: unbekannte Kennung "' + simId + '" - '
             + 'sie steht nicht in _physSimDefs.');
  modal.innerHTML = `<div class="sim-box">
      <button class="sim-x" onclick="closePhysicsSim()">✕</button>
      <h3 class="sim-h3">Zu diesem Thema gibt es noch keine Simulation</h3>
      <p class="sim-hint">Du kannst das Fenster schließen und im Heft weiterarbeiten.</p>
    </div>`;
}

