// ═══════════════════════════════════════════════════════
// 10.3.13  RADIOAKTIVER ZERFALL UND HALBWERTSZEIT
// Realschule NRW - Klasse 10 - Inhaltsfeld "Kernenergie und Radioaktivitaet"
// Jeder Kern zerfaellt EINZELN und ZUFAELLIG. Wann ein bestimmter Kern an der
// Reihe ist, sagt niemand voraus; wie viele in einer Halbwertszeit uebrig
// bleiben, dagegen sehr genau. Genau dieser Gegensatz ist die Seite wert -
// deshalb wuerfelt die Simulation wirklich und legt die gemessenen Punkte
// neben die theoretische Kurve.
// ═══════════════════════════════════════════════════════
let _hwz = null;
const _HWZ_N0 = 200;                       // so viele Kerne liegen im Raster
const _HWZ_NUKLIDE = [
  { id: 'rn220', name: 'Radon-220',      t: 55.6,      e: 's',    kurz: '55,6 s',
    text: 'Im Schulversuch nachweisbar: Nach einer Minute ist rund die Hälfte weg.' },
  { id: 'i131',  name: 'Iod-131',        t: 8.02,      e: 'Tage', kurz: '8,02 Tage',
    text: 'In der Medizin: Nach zwei Monaten ist praktisch nichts mehr übrig.' },
  { id: 'c14',   name: 'Kohlenstoff-14', t: 5730,      e: 'Jahre', kurz: '5730 Jahre',
    text: 'Damit bestimmt man das Alter von Holz, Knochen und Leder.' },
  { id: 'cs137', name: 'Cäsium-137',     t: 30.17,     e: 'Jahre', kurz: '30,17 Jahre',
    text: 'Nach einem Reaktorunfall der Stoff, der am längsten Ärger macht.' },
  { id: 'pu239', name: 'Plutonium-239',  t: 24110,     e: 'Jahre', kurz: '24.110 Jahre',
    text: 'Deshalb muss ein Endlager Hunderttausende Jahre dichthalten.' },
];
function _hwzNuk() { return _HWZ_NUKLIDE.find(n => n.id === _hwz.nuk) || _HWZ_NUKLIDE[0]; }
function _hwzInit() {
  _hwz = { nuk: 'rn220', kerne: new Array(_HWZ_N0).fill(true), schritte: 0,
           verlauf: [{ h: 0, n: _HWZ_N0 }], t: 0, blink: 0, zuletzt: 0 };
}
function _hwzLebt() { return _hwz.kerne.reduce((a, b) => a + (b ? 1 : 0), 0); }
function _hwzTheorie(h) { return _HWZ_N0 * Math.pow(0.5, h); }

// ── Bedienung ──────────────────────────────────────────
function _hwzSetNuk(id) {
  if (!_hwz) return;
  _hwz.nuk = id;
  _hwzReset();
  _HWZ_NUKLIDE.forEach(n => document.getElementById('hwzN' + n.id)?.classList.toggle('primary', n.id === id));
}
function _hwzReset() {
  if (!_hwz) return;
  _hwz.kerne = new Array(_HWZ_N0).fill(true);
  _hwz.schritte = 0; _hwz.verlauf = [{ h: 0, n: _HWZ_N0 }]; _hwz.zuletzt = 0;
  _hwzStatus();
}
function _hwzSchritt() {
  // Eine Halbwertszeit weiter: JEDER noch lebende Kern zerfaellt mit der
  // Wahrscheinlichkeit 1/2 - unabhaengig von allen anderen und davon, wie lange
  // er schon da ist. Kerne altern nicht.
  if (!_hwz) return;
  const vorher = _hwzLebt();
  for (let i = 0; i < _hwz.kerne.length; i++) {
    if (_hwz.kerne[i] && Math.random() < 0.5) _hwz.kerne[i] = false;
  }
  _hwz.schritte += 1; _hwz.blink = 1;
  _hwz.zuletzt = vorher - _hwzLebt();
  _hwz.verlauf.push({ h: _hwz.schritte, n: _hwzLebt() });
  _hwzStatus();
}
function _hwzStatus() {
  const el = document.getElementById('hwzStatus'); if (!el || !_hwz) return;
  const n = _hwzNuk(), lebt = _hwzLebt(), h = _hwz.schritte;
  const soll = _hwzTheorie(h);
  const zeit = h * n.t;
  // Grosse Zahlen mit Tausenderpunkt: „24 110 Jahre" liest sich, „24,1 Tausend" nicht.
  const zeitTxt = zeit === 0 ? '0'
    : (zeit >= 1000 ? Math.round(zeit).toLocaleString('de-DE')
                    : _fpmNum(zeit, zeit < 100 ? 1 : 0));
  const hwZahl = h === 1 ? 'einer Halbwertszeit' : h + ' Halbwertszeiten';
  let t = `<b>${n.name}</b>, Halbwertszeit ${n.kurz}.<br>`;
  t += `Nach <b>${hwZahl}</b> – das sind ${zeitTxt} ${n.e} – `;
  t += `sind noch <b>${lebt}</b> von ${_HWZ_N0} Kernen übrig (${_fpmNum(100 * lebt / _HWZ_N0, 1)} %).<br>`;
  t += `Erwartet hätte man ${_fpmNum(soll, soll < 10 ? 1 : 0)}.`;
  if (h > 0) t += ` Im letzten Schritt sind <b>${_hwz.zuletzt}</b> Kerne zerfallen.`;
  el.innerHTML = t;
  el.className = 'lmp-status on';
}

// ── Animation ──────────────────────────────────────────
function _hwzUpdate(dt) { if (_hwz) { _hwz.t += dt; _hwz.blink = Math.max(0, _hwz.blink - dt * 1.6); } }
function _hwzDraw(ctx, cv) {
  if (!_hwz) return;
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H); ctx.fillStyle = '#0b1020'; ctx.fillRect(0, 0, W, H);

  // ── Kernraster oben: 200 Kerne, 20 je Zeile ──
  const sp = 20, zeilen = _HWZ_N0 / sp, rx = 16, ry = 22, dx = 15, dy = 13;
  ctx.font = '700 11px sans-serif'; ctx.textAlign = 'left'; ctx.fillStyle = '#e2e8f0';
  ctx.fillText(_HWZ_N0 + ' Kerne – jeder zerfällt für sich', rx, 14);
  for (let i = 0; i < _HWZ_N0; i++) {
    const x = rx + (i % sp) * dx, y = ry + Math.floor(i / sp) * dy;
    if (_hwz.kerne[i]) {
      // Die noch vorhandenen Kerne pulsieren leicht, jeder mit eigener Phase.
      // Das sagt genau das Richtige: Jeder von ihnen kann in jedem Augenblick
      // zerfallen, und welcher es trifft, weiss niemand vorher. An den Zahlen
      // aendert das nichts - gezaehlt wird weiterhin nur beim Knopfdruck.
      const pu = 0.72 + 0.28 * Math.sin(_hwz.t * 2.2 + i * 0.7);
      ctx.fillStyle = 'rgba(248,113,113,' + pu.toFixed(3) + ')';
      ctx.beginPath(); ctx.arc(x, y, 4.2, 0, 2 * Math.PI); ctx.fill();
    }
    else { ctx.strokeStyle = 'rgba(148,163,184,0.45)'; ctx.lineWidth = 1; ctx.beginPath(); ctx.arc(x, y, 3.4, 0, 2 * Math.PI); ctx.stroke(); }
  }
  const unten = ry + zeilen * dy + 6;
  ctx.fillStyle = '#94a3b8'; ctx.font = '10px sans-serif';
  ctx.fillText('● noch nicht zerfallen    ○ zerfallen', rx, unten + 4);

  // ── Zerfallskurve unten ──
  const oxL = 44, oxR = W - 14, oyT = unten + 20, oyB = H - 26;
  const hMax = 6;
  const px = h => oxL + (h / hMax) * (oxR - oxL);
  const py = n => oyB - (n / _HWZ_N0) * (oyB - oyT);
  ctx.strokeStyle = '#64748b'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(oxL, oyT); ctx.lineTo(oxL, oyB); ctx.lineTo(oxR, oyB); ctx.stroke();
  ctx.fillStyle = '#94a3b8'; ctx.font = '9px sans-serif'; ctx.textAlign = 'center';
  for (let h = 0; h <= hMax; h++) {
    const x = px(h);
    ctx.strokeStyle = 'rgba(100,116,139,0.22)'; ctx.beginPath(); ctx.moveTo(x, oyT); ctx.lineTo(x, oyB); ctx.stroke();
    ctx.fillText(String(h), x, oyB + 11);
  }
  ctx.textAlign = 'right';
  for (const n of [0, 50, 100, 150, 200]) {
    const y = py(n);
    ctx.strokeStyle = 'rgba(100,116,139,0.22)'; ctx.beginPath(); ctx.moveTo(oxL, y); ctx.lineTo(oxR, y); ctx.stroke();
    ctx.fillText(String(n), oxL - 4, y + 3);
  }
  ctx.fillStyle = '#cbd5e1'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText('Zeit in Halbwertszeiten', (oxL + oxR) / 2, H - 8);
  ctx.save(); ctx.translate(11, (oyT + oyB) / 2); ctx.rotate(-Math.PI / 2);
  ctx.fillText('Zahl der Kerne', 0, 0); ctx.restore();

  // theoretische Kurve: halbiert sich in jedem Schritt
  ctx.strokeStyle = 'rgba(74,222,128,0.6)'; ctx.lineWidth = 2; ctx.setLineDash([5, 4]);
  ctx.beginPath();
  for (let i = 0; i <= 120; i++) { const h = i / 120 * hMax; const x = px(h), y = py(_hwzTheorie(h)); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); }
  ctx.stroke(); ctx.setLineDash([]);
  ctx.fillStyle = '#4ade80'; ctx.font = '700 10px sans-serif'; ctx.textAlign = 'left';
  ctx.fillText('erwartet: jedes Mal die Hälfte', px(2.1), py(_hwzTheorie(2.1)) - 8);

  // gemessene Punkte
  ctx.fillStyle = '#38bdf8';
  _hwz.verlauf.forEach(v => { if (v.h <= hMax) { ctx.beginPath(); ctx.arc(px(v.h), py(v.n), 4, 0, 2 * Math.PI); ctx.fill(); } });
  ctx.strokeStyle = 'rgba(56,189,248,0.7)'; ctx.lineWidth = 1.6; ctx.beginPath();
  _hwz.verlauf.filter(v => v.h <= hMax).forEach((v, i) => { const x = px(v.h), y = py(v.n); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); });
  ctx.stroke();
  ctx.fillStyle = '#38bdf8'; ctx.font = '700 10px sans-serif';
  ctx.fillText('gemessen', px(0.15), py(_HWZ_N0) - 8);
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 10.3.13  (ns = 'halbwertszeit') - im 0123-Gate
// ═══════════════════════════════════════════════════════
function _hwzArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('halbwertszeit')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('halbwertszeit')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Warum kann man nie sagen, wann ein bestimmter Kern zerfällt – aber sehr genau, wie viele es in einer Halbwertszeit sind?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, dass nach einer Halbwertszeit … , weil …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Wähle ein Nuklid und drücke fünfmal „eine Halbwertszeit weiter“.</li>
          <li>Notiere nach jedem Schritt, wie viele Kerne noch übrig sind.</li>
          <li>Setze zurück und wiederhole den Durchgang – vergleiche die beiden Reihen.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Halbwertszeiten</td><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td></tr>
          <tr><td>1. Durchgang</td><td>${inp('a1','')}</td><td>${inp('a2','')}</td><td>${inp('a3','')}</td><td>${inp('a4','')}</td><td>${inp('a5','')}</td></tr>
          <tr><td>2. Durchgang</td><td>${inp('b1','')}</td><td>${inp('b2','')}</td><td>${inp('b3','')}</td><td>${inp('b4','')}</td><td>${inp('b5','')}</td></tr>
          <tr><td>erwartet</td><td>100</td><td>50</td><td>25</td><td>12,5</td><td>6,25</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Auswertung</div>
        ${ta('a6', 'Die beiden Durchgänge sind … . Trotzdem liegen beide nahe an der erwarteten Reihe, weil …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">6 · Merksatz</div>
        <div class="ab-t">Nach einer Halbwertszeit ist noch ${inp('m1', 'welcher Anteil?')} der Kerne übrig. Für einen einzelnen Kern lässt sich der Zeitpunkt ${inp('m2', 'wie gut?')} vorhersagen.</div></div>`;
  return _abWrap('halbwertszeit', 'Radioaktiver Zerfall und Halbwertszeit', body);
}

function _hwzHTML() {
  const knopf = n => `<button class="sim-btn${_hwz.nuk === n.id ? ' primary' : ''}" id="hwzN${n.id}" onclick="_hwzSetNuk('${n.id}')">${n.name}</button>`;
  return `<div class="sim-box sim-box-wide fpm-sim hwz-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">☢️ Warum kann man nie sagen, wann ein Kern zerfällt?</h3>
    <div class="fpm-note" style="margin-top:2px">Jeder der 200 Kerne zerfällt <b>für sich</b> und <b>zufällig</b>. Schau, wie viele nach jeder Halbwertszeit übrig sind – und wie nah das an der erwarteten Zahl liegt.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="hwzAnim" width="440" height="330" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" onclick="_hwzSchritt()">⏭ eine Halbwertszeit weiter</button>
          <button class="sim-btn" onclick="_hwzReset()">↺ Zurücksetzen</button>
        </div>
        <div class="sim-btn-row" style="margin-top:4px">
          <span class="fpm-label" style="align-self:center">Nuklid:</span>
          ${_HWZ_NUKLIDE.map(knopf).join('')}
        </div>
      </div>
      <div>
        <div class="fpm-label">Wie viele Kerne sind noch da?</div>
        <div class="lmp-status" id="hwzStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Die <b>Halbwertszeit T½</b> ist die Zeit, nach der im Mittel die <b>Hälfte</b> der Kerne zerfallen ist. Sie hängt allein vom Nuklid ab – nicht von Temperatur, Druck oder Alter der Probe. Ein einzelner Kern <b>altert nicht</b>: Ein Kern, der schon lange da ist, zerfällt im nächsten Moment mit derselben Wahrscheinlichkeit wie ein frischer.</div>
        <div class="fpm-note" style="margin-top:8px"><b>Modellgrenze:</b> 200 Kerne sind wenige. Deshalb weicht die gemessene Reihe sichtbar von der erwarteten ab. In einem Gramm Stoff stecken rund 10²¹ Kerne – dort ist die Abweichung nicht mehr messbar.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Für den <b>einzelnen</b> Kern gilt nur eine Wahrscheinlichkeit · für die <b>Menge</b> ein Gesetz: N(t) = N₀ · (½)^(t/T½)
    </p>
    ${_hwzArbeitsblattHTML()}
  </div>`;
}


// ═══════════════════════════════════════════════════════
// 10.3.14  ATOMBAU UND ISOTOPE
// Realschule NRW - Klasse 10 - Inhaltsfeld "Kernenergie und Radioaktivitaet"
// Zwei Fragen in einer Simulation: Woraus besteht ein Atom (Protonen bestimmen
// das Element)? Und warum gibt es vom selben Element verschiedene Sorten
// (Neutronen aendern nur die Masse)? Deshalb zwei getrennte Regler - wer am
// Protonenregler zieht, wechselt das Element; wer am Neutronenregler zieht,
// bleibt beim Element und wechselt nur das Isotop.
// Haeufigkeiten nach IUPAC (Isotopic Compositions of the Elements).
// ═══════════════════════════════════════════════════════
let _atb = null;
const _ATB_ZMAX = 20, _ATB_NMAX = 28;

// stabil: Neutronenzahl -> natuerlicher Anteil in Prozent
// instabil: Neutronenzahl -> Halbwertszeit als Text
const _ATB_ELEMENTE = [
  { z: 1,  sym: 'H',  name: 'Wasserstoff', stabil: { 0: 99.9885, 1: 0.0115 },
    instabil: { 2: '12,3 Jahre' }, notiz: 'Das einzige Atom, dessen Kern aus einem einzigen Teilchen bestehen kann.' },
  { z: 2,  sym: 'He', name: 'Helium',      stabil: { 1: 0.000134, 2: 99.999866 },
    instabil: {}, notiz: 'Der Heliumkern ist genau das, was als Alphastrahlung davonfliegt.' },
  { z: 3,  sym: 'Li', name: 'Lithium',     stabil: { 3: 7.59, 4: 92.41 }, instabil: {} },
  { z: 4,  sym: 'Be', name: 'Beryllium',   stabil: { 5: 100 },
    instabil: { 3: '53 Tage', 6: '1,4 Millionen Jahre' } },
  { z: 5,  sym: 'B',  name: 'Bor',         stabil: { 5: 19.9, 6: 80.1 },
    instabil: {}, notiz: 'Bor schluckt Neutronen – deshalb steckt es in den Steuerstäben eines Reaktors.' },
  { z: 6,  sym: 'C',  name: 'Kohlenstoff', stabil: { 6: 98.93, 7: 1.07 },
    instabil: { 8: '5730 Jahre' }, notiz: 'C-14 entsteht laufend in der Luft – damit bestimmt man Alter.' },
  { z: 7,  sym: 'N',  name: 'Stickstoff',  stabil: { 7: 99.636, 8: 0.364 }, instabil: {} },
  { z: 8,  sym: 'O',  name: 'Sauerstoff',  stabil: { 8: 99.757, 9: 0.038, 10: 0.205 }, instabil: {} },
  { z: 9,  sym: 'F',  name: 'Fluor',       stabil: { 10: 100 }, instabil: {} },
  { z: 10, sym: 'Ne', name: 'Neon',        stabil: { 10: 90.48, 11: 0.27, 12: 9.25 }, instabil: {} },
  { z: 11, sym: 'Na', name: 'Natrium',     stabil: { 12: 100 }, instabil: { 13: '15 Stunden' } },
  { z: 12, sym: 'Mg', name: 'Magnesium',   stabil: { 12: 78.99, 13: 10.00, 14: 11.01 }, instabil: {} },
  { z: 13, sym: 'Al', name: 'Aluminium',   stabil: { 14: 100 }, instabil: {} },
  { z: 14, sym: 'Si', name: 'Silicium',    stabil: { 14: 92.223, 15: 4.685, 16: 3.092 }, instabil: {} },
  { z: 15, sym: 'P',  name: 'Phosphor',    stabil: { 16: 100 }, instabil: { 17: '14,3 Tage' } },
  { z: 16, sym: 'S',  name: 'Schwefel',    stabil: { 16: 94.99, 17: 0.75, 18: 4.25, 20: 0.01 }, instabil: {} },
  { z: 17, sym: 'Cl', name: 'Chlor',       stabil: { 18: 75.76, 20: 24.24 },
    instabil: {}, notiz: 'Drei Viertel Cl-35, ein Viertel Cl-37 – deshalb steht im Periodensystem 35,45 u.' },
  { z: 18, sym: 'Ar', name: 'Argon',       stabil: { 18: 0.334, 20: 0.063, 22: 99.604 }, instabil: {} },
  { z: 19, sym: 'K',  name: 'Kalium',      stabil: { 20: 93.258, 22: 6.730 },
    instabil: { 21: '1,25 Milliarden Jahre' },
    notiz: 'K-40 steckt in jeder Banane und in dir selbst – jeder Mensch strahlt ein wenig.' },
  { z: 20, sym: 'Ca', name: 'Calcium',     stabil: { 20: 96.941, 22: 0.647, 23: 0.135, 24: 2.086, 26: 0.004, 28: 0.187 }, instabil: {} },
];

// Schnellwahl: die Isotope, um die es im Unterricht wirklich geht
const _ATB_BEISPIELE = [
  { z: 1,  n: 0,  t: 'Wasserstoff-1' },
  { z: 2,  n: 2,  t: 'Helium-4' },
  { z: 6,  n: 6,  t: 'Kohlenstoff-12' },
  { z: 6,  n: 8,  t: 'Kohlenstoff-14' },
  { z: 17, n: 18, t: 'Chlor-35' },
  { z: 17, n: 20, t: 'Chlor-37' },
  { z: 19, n: 21, t: 'Kalium-40' },
];

const _ATB_HOCH = { 0: '⁰', 1: '¹', 2: '²', 3: '³', 4: '⁴', 5: '⁵', 6: '⁶', 7: '⁷', 8: '⁸', 9: '⁹' };
const _ATB_TIEF = { 0: '₀', 1: '₁', 2: '₂', 3: '₃', 4: '₄', 5: '₅', 6: '₆', 7: '₇', 8: '₈', 9: '₉' };
function _atbHoch(n) { return String(n).split('').map(c => _ATB_HOCH[c]).join(''); }
function _atbTief(n) { return String(n).split('').map(c => _ATB_TIEF[c]).join(''); }

function _atbEl(z) { return _ATB_ELEMENTE[z - 1]; }

/* Schalenmodell fuer Z <= 20: 2, 8, 8, 2 - genau so, wie es die Realschule lehrt. */
function _atbSchalen(z) {
  const platz = [2, 8, 8, 2], s = [];
  let rest = z;
  for (const p of platz) { if (rest <= 0) break; s.push(Math.min(p, rest)); rest -= p; }
  return s;
}

/* Die Kernbausteine einmal setzen und dann liegen lassen - sonst zappelt das Bild. */
function _atbBaueKern() {
  const A = _atb.z + _atb.n, pos = [];
  const ringe = [[0, 1], [10, 6], [19, 12], [28, 18], [37, 24]];
  let k = 0;
  for (const [r, anz] of ringe) {
    for (let i = 0; i < anz && k < A; i++, k++) {
      const w = (i / anz) * Math.PI * 2 + (r ? r * 0.07 : 0);
      pos.push({ x: r * Math.cos(w), y: r * Math.sin(w) });
    }
    if (k >= A) break;
  }
  // Protonen und Neutronen gemischt verteilen, aber fest: gerade Plaetze zuerst
  const reihe = pos.map((p, i) => i).sort((a, b) => ((a * 7) % 13) - ((b * 7) % 13));
  _atb.kern = pos.map(p => ({ x: p.x, y: p.y, p: false }));
  for (let i = 0; i < _atb.z; i++) _atb.kern[reihe[i]].p = true;
}

function _atbInit() {
  _atb = { z: 6, n: 6, t: 0, kern: [] };
  _atbBaueKern();
}

function _atbSetZ(v) {
  _atb.z = Math.max(1, Math.min(_ATB_ZMAX, Math.round(+v)));
  _atbBaueKern(); _atbStatus();
}
function _atbSetN(v) {
  _atb.n = Math.max(0, Math.min(_ATB_NMAX, Math.round(+v)));
  _atbBaueKern(); _atbStatus();
}
function _atbBeispiel(i) {
  const b = _ATB_BEISPIELE[i];
  _atb.z = b.z; _atb.n = b.n;
  const rz = document.getElementById('atbZ'), rn = document.getElementById('atbN');
  if (rz) rz.value = b.z;
  if (rn) rn.value = b.n;
  _atbBaueKern(); _atbStatus();
}

function _atbStatus() {
  const el = document.getElementById('atbStatus');
  if (!el || !_atb) return;
  const e = _atbEl(_atb.z), A = _atb.z + _atb.n;
  const anteil = e.stabil[_atb.n], hwz = e.instabil[_atb.n];
  const schrift = _atbHoch(A) + _atbTief(_atb.z) + e.sym;

  let t = `<b>${schrift}</b> &nbsp; – &nbsp; <b>${e.name}-${A}</b><br>`;
  t += `Im Kern: <b>${_atb.z}</b> Protonen und <b>${_atb.n}</b> Neutronen, zusammen <b>${A}</b> Kernbausteine.<br>`;
  t += `In der Hülle: <b>${_atb.z}</b> Elektronen, verteilt auf ${_atbSchalen(_atb.z).join(' + ')}.<br>`;
  t += `Die Massenzahl ist die Summe: A = ${_atb.z} + ${_atb.n} = <b>${A}</b>.<br><br>`;

  if (anteil !== undefined) {
    const anzeige = anteil >= 1 ? _fpmNum(anteil, anteil >= 99 ? 3 : 2)
                  : (anteil >= 0.01 ? _fpmNum(anteil, 3) : _fpmNum(anteil, 6));
    t += `✅ <b>Stabil.</b> Von allen ${e.name}-Atomen der Erde sind <b>${anzeige} %</b> von dieser Sorte.`;
  } else if (hwz !== undefined) {
    t += `☢️ <b>Nicht stabil.</b> Dieser Kern zerfällt, seine Halbwertszeit beträgt <b>${hwz}</b>.`;
  } else {
    t += `✖ <b>Diesen Kern gibt es so nicht.</b> ${_atb.n} Neutronen passen nicht zu ${_atb.z} Protonen – ein solcher Kern zerfällt sofort wieder.`;
  }

  const gesch = Object.keys(e.stabil).map(n => `${e.name}-${+n + e.z}`);
  if (gesch.length > 1) t += `<br><br>Stabile Sorten dieses Elements: <b>${gesch.join(', ')}</b>. Alle heißen ${e.name}, weil alle <b>${e.z} Protonen</b> haben – sie unterscheiden sich nur in den Neutronen. Solche Sorten nennt man <b>Isotope</b>.`;
  else t += `<br><br>Von ${e.name} ist nur <b>eine</b> Sorte stabil: ${e.name}-${+Object.keys(e.stabil)[0] + e.z}.`;

  if (e.notiz) t += `<br><br><i>${e.notiz}</i>`;
  el.innerHTML = t;

  const wz = document.getElementById('atbWertZ'), wn = document.getElementById('atbWertN');
  if (wz) wz.textContent = _atb.z;
  if (wn) wn.textContent = _atb.n;
}

function _atbUpdate(dt) { if (_atb) _atb.t += dt; }

function _atbDraw(ctx, cv) {
  if (!_atb) return;
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, cv.width, cv.height);
  const cx = 158, cy = 166, e = _atbEl(_atb.z), A = _atb.z + _atb.n;

  // Elektronenschalen
  const schalen = _atbSchalen(_atb.z);
  const rad = [52, 82, 112, 142];
  ctx.lineWidth = 1;
  schalen.forEach((anz, si) => {
    const r = rad[si];
    ctx.strokeStyle = '#cbd5e1';
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
    const dreh = _atb.t * (0.5 - si * 0.09);
    for (let i = 0; i < anz; i++) {
      const w = dreh + (i / anz) * Math.PI * 2;
      const x = cx + r * Math.cos(w), y = cy + r * Math.sin(w);
      ctx.fillStyle = '#2563eb';
      ctx.beginPath(); ctx.arc(x, y, 4.2, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#fff'; ctx.font = 'bold 7px system-ui';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText('–', x, y - 0.5);
    }
  });

  // Kern
  for (const b of _atb.kern) {
    ctx.fillStyle = b.p ? '#dc2626' : '#64748b';
    ctx.beginPath(); ctx.arc(cx + b.x, cy + b.y, 5.2, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,.55)'; ctx.lineWidth = 0.8; ctx.stroke();
  }

  // Beschriftung
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 15px system-ui';
  ctx.fillText(_atbHoch(A) + _atbTief(_atb.z) + e.sym + '   ' + e.name + '-' + A, 12, 24);

  ctx.font = '11px system-ui';
  ctx.fillStyle = '#dc2626';
  ctx.beginPath(); ctx.arc(20, 300, 5.2, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#0f172a'; ctx.fillText(_atb.z + ' Protonen  (+)', 30, 304);
  ctx.fillStyle = '#64748b';
  ctx.beginPath(); ctx.arc(20, 317, 5.2, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#0f172a'; ctx.fillText(_atb.n + ' Neutronen  (ohne Ladung)', 30, 321);
  ctx.fillStyle = '#2563eb';
  ctx.beginPath(); ctx.arc(258, 300, 4.2, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#0f172a'; ctx.fillText(_atb.z + ' Elektronen  (–)', 268, 304);

  // Groessenvergleich - der Kern ist hier viel zu gross gezeichnet
  ctx.fillStyle = '#94a3b8'; ctx.font = '10px system-ui';
  ctx.fillText('Kern hier 10 000-mal zu groß gezeichnet', 268, 321);

  // Ladungsbilanz rechts oben
  ctx.textAlign = 'right'; ctx.font = 'bold 11px system-ui'; ctx.fillStyle = '#0f172a';
  ctx.fillText(_atb.z + ' mal (+)  und  ' + _atb.z + ' mal (–)  →  nach außen neutral', cv.width - 12, 24);
}

function _atbArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('atombau')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('atombau')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Was macht ein Atom zu genau diesem Element – und was darf sich ändern, ohne dass das Element wechselt?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, dass sich das Element ändert, wenn … , weil …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Stelle 6 Protonen und 6 Neutronen ein. Notiere Name und Massenzahl.</li>
          <li>Ziehe nur den <b>Neutronen</b>-Regler auf 7 und dann auf 8. Ändert sich der Name?</li>
          <li>Ziehe jetzt nur den <b>Protonen</b>-Regler auf 7. Was steht nun da?</li>
          <li>Wähle Chlor-35 und Chlor-37 und lies beide Anteile ab.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Protonen</td><td>6</td><td>6</td><td>6</td><td>7</td></tr>
          <tr><td>Neutronen</td><td>6</td><td>7</td><td>8</td><td>7</td></tr>
          <tr><td>Name</td><td>${inp('a1','')}</td><td>${inp('a2','')}</td><td>${inp('a3','')}</td><td>${inp('a4','')}</td></tr>
          <tr><td>Massenzahl A</td><td>${inp('b1','')}</td><td>${inp('b2','')}</td><td>${inp('b3','')}</td><td>${inp('b4','')}</td></tr>
          <tr><td>stabil?</td><td>${inp('c1','')}</td><td>${inp('c2','')}</td><td>${inp('c3','')}</td><td>${inp('c4','')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Auswertung</div>
        ${ta('a6', 'Das Element hängt allein von … ab. Die Neutronen ändern nur … . Chlor-35 kommt zu … % vor, Chlor-37 zu … % – deshalb steht im Periodensystem 35,45 u und nicht 35 oder 37.', 4)}</div>

      <div class="ab-sec"><div class="ab-h">6 · Merksatz</div>
        <div class="ab-t">Die <b>Protonenzahl</b> bestimmt das ${inp('m1', 'was?')}. Atome mit gleicher Protonenzahl, aber verschiedener Neutronenzahl heißen ${inp('m2', 'wie?')}.</div></div>`;
  return _abWrap('atombau', 'Atombau und Isotope', body);
}

function _atbHTML() {
  const knopf = (b, i) => `<button class="sim-btn" onclick="_atbBeispiel(${i})">${b.t}</button>`;
  return `<div class="sim-box sim-box-wide fpm-sim atb-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">⚛️ Woraus besteht ein Atom – und warum gibt es das gleiche Element in mehreren Sorten?</h3>
    <div class="fpm-note" style="margin-top:2px">Zwei Regler, zwei ganz verschiedene Wirkungen: Am <b>Protonen</b>-Regler wechselt das Element. Am <b>Neutronen</b>-Regler bleibt das Element – nur die Sorte ändert sich.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="atbAnim" width="440" height="330" class="phys-anim-cv"></canvas>
        <div style="margin-top:6px">
          <label class="fpm-label" for="atbZ">Protonen im Kern: <b id="atbWertZ">6</b></label>
          <input type="range" id="atbZ" min="1" max="${_ATB_ZMAX}" value="6" step="1" oninput="_atbSetZ(this.value)" style="width:100%">
          <label class="fpm-label" for="atbN">Neutronen im Kern: <b id="atbWertN">6</b></label>
          <input type="range" id="atbN" min="0" max="${_ATB_NMAX}" value="6" step="1" oninput="_atbSetN(this.value)" style="width:100%">
        </div>
        <div class="sim-btn-row" style="margin-top:4px">
          ${_ATB_BEISPIELE.map(knopf).join('')}
        </div>
      </div>
      <div>
        <div class="fpm-label">Was ist das für ein Atom?</div>
        <div class="lmp-status" id="atbStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Die Schreibweise <b>ᴬ<sub>Z</sub>X</b>: oben die <b>Massenzahl A</b> (alle Kernbausteine zusammen), unten die <b>Kernladungszahl Z</b> (nur die Protonen). Die Neutronenzahl steht nirgends – man rechnet sie aus: <b>N = A − Z</b>.</div>
        <div class="fpm-note" style="margin-top:8px"><b>Modellgrenze:</b> Zwei Dinge stimmen hier nicht mit der Wirklichkeit. Der Kern ist rund <b>10 000-mal zu groß</b> gezeichnet – wäre das Atom ein Fußballstadion, wäre der Kern eine Erbse im Anstoßkreis. Und Elektronen laufen nicht auf Kreisbahnen wie Planeten; sie halten sich nur mit gewisser Wahrscheinlichkeit in einem Bereich auf. Das Schalenbild ist ein <b>Merkbild</b>, kein Foto.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Protonen bestimmen das <b>Element</b> · Neutronen bestimmen das <b>Isotop</b> · A = Z + N
    </p>
    ${_atbArbeitsblattHTML()}
  </div>`;
}

// ═══════════════════════════════════════════════════════
// 10.3.15  KERNSPALTUNG
// Realschule NRW - Klasse 10 - Inhaltsfeld "Kernenergie und Radioaktivitaet"
// Nicht nur "der Kern zerplatzt". Die Seite lebt von zwei Bilanzen, die man
// nachrechnen kann: A und Z gehen nicht verloren, und die Bruchstuecke wiegen
// zusammen WENIGER als der Ausgangskern - dieser Massenunterschied ist die
// Energie. Deshalb zeigt die Statuszeile beide Summen ausgeschrieben.
// Zahlen: 1 u entspricht 931,5 MeV; 1 MeV = 1,602e-13 J.
// ═══════════════════════════════════════════════════════
let _ksp = null;
const _KSP_U = 931.5;                  // MeV je Atommasseneinheit
const _KSP_MEV_J = 1.602e-13;          // Joule je MeV
const _KSP_SKE = 29.3e6;               // Joule je kg Steinkohle (SKE)

/* Drei Spaltungen, die wirklich vorkommen. dm = Massenunterschied in u. */
const _KSP_WEGE = [
  { id: 'ba', a1: 141, z1: 56, s1: 'Ba', n1: 'Barium-141',
              a2: 92,  z2: 36, s2: 'Kr', n2: 'Krypton-92',  frei: 3, dm: 0.1860 },
  { id: 'xe', a1: 140, z1: 54, s1: 'Xe', n1: 'Xenon-140',
              a2: 94,  z2: 38, s2: 'Sr', n2: 'Strontium-94', frei: 2, dm: 0.1983 },
  { id: 'cs', a1: 137, z1: 55, s1: 'Cs', n1: 'Cäsium-137',
              a2: 96,  z2: 37, s2: 'Rb', n2: 'Rubidium-96', frei: 3, dm: 0.1854 },
];

const _KSP_HOCH = { 0:'⁰',1:'¹',2:'²',3:'³',4:'⁴',5:'⁵',6:'⁶',7:'⁷',8:'⁸',9:'⁹' };
const _KSP_TIEF = { 0:'₀',1:'₁',2:'₂',3:'₃',4:'₄',5:'₅',6:'₆',7:'₇',8:'₈',9:'₉' };
function _kspSchrift(a, z, sym) {
  const h = String(a).split('').map(c => _KSP_HOCH[c]).join('');
  const t = String(z).split('').map(c => _KSP_TIEF[c]).join('');
  return h + t + sym;
}

function _kspWeg() { return _KSP_WEGE.find(w => w.id === _ksp.weg) || _KSP_WEGE[0]; }

function _kspInit() {
  _ksp = { weg: 'ba', t: 0, laeuft: true, bruch: [], neutr: [], phGezeigt: -1 };
  _kspStart();
}

function _kspStart() {
  const w = _kspWeg();
  _ksp.t = 0; _ksp.laeuft = true; _ksp.phGezeigt = -1;
  // Bruchstuecke fliegen auseinander - das schwerere langsamer (Impulserhaltung)
  const vGes = 150, m1 = w.a1, m2 = w.a2;
  _ksp.bruch = [
    { x: 0, y: 0, vx: -vGes * m2 / (m1 + m2), vy: -14, a: w.a1, z: w.z1, sym: w.s1, r: 26 },
    { x: 0, y: 0, vx:  vGes * m1 / (m1 + m2), vy:  14, a: w.a2, z: w.z2, sym: w.s2, r: 22 },
  ];
  _ksp.neutr = [];
  for (let i = 0; i < w.frei; i++) {
    const winkel = -0.9 + i * (1.8 / Math.max(1, w.frei - 1)) + (w.frei === 1 ? 0.9 : 0);
    _ksp.neutr.push({ x: 0, y: 0, vx: 210 * Math.cos(winkel), vy: 210 * Math.sin(winkel) });
  }
  _kspStatus();
}

function _kspSetWeg(id) {
  _ksp.weg = id;
  for (const w of _KSP_WEGE) {
    const b = document.getElementById('kspW' + w.id);
    if (b) b.className = 'sim-btn' + (w.id === id ? ' primary' : '');
  }
  _kspStart();
}

function _kspPause() {
  _ksp.laeuft = !_ksp.laeuft;
  const b = document.getElementById('kspPause');
  if (b) b.textContent = _ksp.laeuft ? '⏸ Anhalten' : '▶ Weiter';
}

/* Phase 0 Neutron fliegt an · 1 Kern zittert (U-236) · 2 gespalten */
function _kspPhase() { return _ksp.t < 1.2 ? 0 : (_ksp.t < 2.3 ? 1 : 2); }

function _kspUpdate(dt) {
  if (!_ksp || !_ksp.laeuft) return;
  _ksp.t += dt;
  if (_kspPhase() === 2) {
    const s = _ksp.t - 2.3;
    for (const b of _ksp.bruch) { b.x = b.vx * s; b.y = b.vy * s; }
    for (const n of _ksp.neutr) { n.x = n.vx * s; n.y = n.vy * s; }
  }
  if (_ksp.t > 6.5) { _kspStart(); return; }
  if (_kspPhase() !== _ksp.phGezeigt) _kspStatus();
}

function _kspStatus() {
  const el = document.getElementById('kspStatus');
  if (!el || !_ksp) return;
  const w = _kspWeg(), ph = _kspPhase();
  _ksp.phGezeigt = ph;
  const links = _kspSchrift(1, 0, 'n') + ' + ' + _kspSchrift(235, 92, 'U');
  const rechts = _kspSchrift(w.a1, w.z1, w.s1) + ' + ' + _kspSchrift(w.a2, w.z2, w.s2) +
                 ' + ' + w.frei + ' ' + _kspSchrift(1, 0, 'n');
  const aL = 1 + 235, aR = w.a1 + w.a2 + w.frei;
  const zL = 0 + 92,  zR = w.z1 + w.z2;
  const mev = w.dm * _KSP_U;
  const joule = mev * _KSP_MEV_J;
  // 1 kg U-235: N = 1000 g / 235 g/mol * 6,022e23
  const kerne = (1000 / 235) * 6.022e23;
  const eKg = kerne * joule;
  const kohle = eKg / _KSP_SKE;

  const phaseTxt = ph === 0 ? 'Ein <b>langsames Neutron</b> fliegt auf den Urankern zu.'
                 : ph === 1 ? 'Der Kern hat es geschluckt: Aus ²³⁵U ist kurz <b>²³⁶U</b> geworden. Er zittert und wird länglich.'
                 : 'Der Kern ist <b>gespalten</b>. Die Bruchstücke stoßen sich ab und fliegen auseinander, dazu kommen freie Neutronen.';

  let t = `${phaseTxt}<br><br>`;
  t += `<b>${links} → ${rechts}</b><br><br>`;
  t += `Kernbausteine: links ${1} + ${235} = <b>${aL}</b>, rechts ${w.a1} + ${w.a2} + ${w.frei} = <b>${aR}</b>. Geht auf.<br>`;
  t += `Protonen: links ${0} + ${92} = <b>${zL}</b>, rechts ${w.z1} + ${w.z2} = <b>${zR}</b>. Geht auch auf.<br><br>`;
  t += `Und trotzdem fehlt etwas: Die Bruchstücke wiegen zusammen <b>${_fpmNum(w.dm, 4)} u</b> weniger als vorher. Genau dieser <b>Massenunterschied</b> wird zu Energie:<br>`;
  t += `E = ${_fpmNum(w.dm, 4)} u · 931,5 MeV/u = <b>${_fpmNum(mev, 1)} MeV</b> je Spaltung.<br><br>`;
  t += `Das sind ${_fpmNum(mev, 1)} MeV · 1,602 · 10⁻¹³ J/MeV = <b>${_fpmNum(joule * 1e11, 2)} · 10⁻¹¹ J</b> – winzig. Aber in <b>1 kg</b> Uran-235 stecken 2,56 · 10²⁴ Kerne. Alle zusammen ergeben <b>${_fpmNum(eKg / 1e12, 0)} Billionen Joule</b>.<br>`;
  t += `Dieselbe Energie liefern etwa <b>${_fpmNum(kohle / 1000, 0)} Tonnen Steinkohle</b> – ein ganzer Güterzug voll, gegen einen Uranwürfel von knapp 4 cm Kantenlänge.`;
  el.innerHTML = t;
}

function _kspDraw(ctx, cv) {
  if (!_ksp) return;
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, cv.width, cv.height);
  const cx = 220, cy = 165, ph = _kspPhase(), w = _kspWeg();

  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';

  if (ph < 2) {
    // Urankern, in Phase 1 laenglich gezogen
    const s = ph === 1 ? (_ksp.t - 1.2) / 1.1 : 0;
    const zit = ph === 1 ? Math.sin(_ksp.t * 26) * 3.5 * s : 0;
    const rx = 40 + 26 * s, ry = 40 - 11 * s;
    ctx.save(); ctx.translate(cx + zit, cy);
    ctx.fillStyle = ph === 1 ? '#f59e0b' : '#7c3aed';
    ctx.beginPath(); ctx.ellipse(0, 0, rx, ry, 0, 0, Math.PI * 2); ctx.fill();
    if (ph === 1 && s > 0.55) {   // Einschnuerung andeuten
      ctx.fillStyle = '#f8fafc';
      const t2 = (s - 0.55) / 0.45;
      ctx.beginPath(); ctx.ellipse(0, -ry, ry * 0.9 * t2, ry * 0.55 * t2, 0, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.ellipse(0,  ry, ry * 0.9 * t2, ry * 0.55 * t2, 0, 0, Math.PI * 2); ctx.fill();
    }
    ctx.restore();
    ctx.fillStyle = '#fff'; ctx.font = 'bold 14px system-ui';
    ctx.fillText(ph === 1 ? '²³⁶U' : '²³⁵U', cx + zit, cy);

    if (ph === 0) {   // anfliegendes Neutron
      const nx = cx - 40 - (1.2 - _ksp.t) * 150;
      ctx.fillStyle = '#64748b';
      ctx.beginPath(); ctx.arc(nx, cy, 9, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#fff'; ctx.font = 'bold 10px system-ui'; ctx.fillText('n', nx, cy);
      ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1.5; ctx.setLineDash([4, 4]);
      ctx.beginPath(); ctx.moveTo(nx + 12, cy); ctx.lineTo(cx - 42, cy); ctx.stroke();
      ctx.setLineDash([]);
    }
  } else {
    for (const b of _ksp.bruch) {
      ctx.fillStyle = '#0d9488';
      ctx.beginPath(); ctx.arc(cx + b.x, cy + b.y, b.r, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#fff'; ctx.font = 'bold 12px system-ui';
      ctx.fillText(_kspSchrift(b.a, b.z, b.sym), cx + b.x, cy + b.y);
    }
    for (const n of _ksp.neutr) {
      ctx.fillStyle = '#64748b';
      ctx.beginPath(); ctx.arc(cx + n.x, cy + n.y, 8, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#fff'; ctx.font = 'bold 9px system-ui'; ctx.fillText('n', cx + n.x, cy + n.y);
    }
  }

  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 13px system-ui';
  ctx.fillText(['1 · Ein Neutron fliegt an', '2 · Der Kern schluckt es und wird länglich',
                '3 · Er reißt auseinander'][ph], 12, 24);
  ctx.font = '11px system-ui'; ctx.fillStyle = '#475569';
  ctx.fillText(_kspSchrift(1, 0, 'n') + ' + ' + _kspSchrift(235, 92, 'U') + '  →  ' +
               _kspSchrift(w.a1, w.z1, w.s1) + ' + ' + _kspSchrift(w.a2, w.z2, w.s2) +
               ' + ' + w.frei + ' ' + _kspSchrift(1, 0, 'n'), 12, 44);
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 12px system-ui';
  ctx.fillText('frei werdende Energie: ' + _fpmNum(w.dm * _KSP_U, 1) + ' MeV je Spaltung', 12, 314);
}

function _kspArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('kernspaltung')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('kernspaltung')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Woher kommt die riesige Energie, wenn ein einziger Kern zerbricht – wo doch nichts verbrannt wird?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, dass die Energie aus … kommt, weil …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Sieh dir die drei Phasen an: anfliegendes Neutron, ²³⁶U, Spaltung.</li>
          <li>Wähle nacheinander alle drei Spaltwege und notiere die Gleichung.</li>
          <li>Prüfe bei jedem Weg: Stimmen die Summen oben (A) und unten (Z)?</li>
          <li>Lies den Massenunterschied und die Energie je Spaltung ab.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Spaltweg</td><td>Barium</td><td>Xenon</td><td>Cäsium</td></tr>
          <tr><td>Summe A rechts</td><td>${inp('a1','')}</td><td>${inp('a2','')}</td><td>${inp('a3','')}</td></tr>
          <tr><td>Summe Z rechts</td><td>${inp('b1','')}</td><td>${inp('b2','')}</td><td>${inp('b3','')}</td></tr>
          <tr><td>freie Neutronen</td><td>${inp('c1','')}</td><td>${inp('c2','')}</td><td>${inp('c3','')}</td></tr>
          <tr><td>Energie in MeV</td><td>${inp('d1','')}</td><td>${inp('d2','')}</td><td>${inp('d3','')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Auswertung</div>
        ${ta('a6', 'Die Summen A und Z sind vorher und nachher … . Trotzdem wird Energie frei, weil … . Bei allen drei Wegen entstehen … freie Neutronen – das ist wichtig, weil …', 4)}</div>

      <div class="ab-sec"><div class="ab-h">6 · Merksatz</div>
        <div class="ab-t">Bei der Kernspaltung wiegen die Bruchstücke zusammen ${inp('m1', 'mehr oder weniger?')} als der Ausgangskern. Der fehlende Teil wird zu ${inp('m2', 'was?')}.</div></div>`;
  return _abWrap('kernspaltung', 'Kernspaltung – woher die Energie kommt', body);
}

function _kspHTML() {
  const knopf = w => `<button class="sim-btn${_ksp.weg === w.id ? ' primary' : ''}" id="kspW${w.id}" onclick="_kspSetWeg('${w.id}')">${w.n1.split('-')[0]} + ${w.n2.split('-')[0]}</button>`;
  return `<div class="sim-box sim-box-wide fpm-sim ksp-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">⚛️ Wie holt man riesige Energie aus einem winzigen Kern?</h3>
    <div class="fpm-note" style="margin-top:2px">Ein <b>langsames</b> Neutron genügt. Der Urankern schluckt es, wird länglich und reißt auseinander. Achte auf die beiden Summen – und darauf, was <b>trotzdem</b> fehlt.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="kspAnim" width="440" height="330" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" onclick="_kspStart()">↺ Spaltung noch einmal</button>
          <button class="sim-btn" id="kspPause" onclick="_kspPause()">⏸ Anhalten</button>
        </div>
        <div class="sim-btn-row" style="margin-top:4px">
          <span class="fpm-label" style="align-self:center">Spaltweg:</span>
          ${_KSP_WEGE.map(knopf).join('')}
        </div>
      </div>
      <div>
        <div class="fpm-label">Was passiert – und was rechnet sich daraus?</div>
        <div class="lmp-status" id="kspStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Warum ein <b>langsames</b> Neutron? Ein schnelles fliegt am Kern vorbei, bevor er es festhalten kann. Deshalb steht in jedem Reaktor ein <b>Moderator</b> – meist Wasser –, der die Neutronen abbremst.</div>
        <div class="fpm-note" style="margin-top:8px"><b>Modellgrenze:</b> Uran-235 spaltet sich nicht immer gleich. Es gibt über <b>30 verschiedene</b> Paare von Bruchstücken; hier siehst du drei davon. Welches Paar entsteht, entscheidet der Zufall – die frei werdende Energie ist aber jedes Mal fast gleich groß. In Büchern steht oft <b>200 MeV</b>; die Massenbilanz hier ergibt rund <b>175 MeV</b>. Der Unterschied ist kein Fehler: Die Bruchstücke sind selbst radioaktiv und geben später noch einmal Energie ab. Zusammen kommt man auf die 200 MeV.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      A und Z bleiben erhalten · die <b>Masse</b> nicht · der fehlende Rest ist die Energie: E = Δm · c²
    </p>
    ${_kspArbeitsblattHTML()}
  </div>`;
}

// ═══════════════════════════════════════════════════════
// 10.3.16  KETTENREAKTION UND REAKTORSTEUERUNG
// Realschule NRW - Klasse 10 - Inhaltsfeld "Kernenergie und Radioaktivitaet"
// Der ganze Unterschied zwischen Kraftwerk und Katastrophe steckt in einer
// einzigen Zahl: k, dem Vermehrungsfaktor. k < 1 erstirbt, k = 1 laeuft
// gleichmaessig, k > 1 waechst lawinenartig. Deshalb ist k hier ein Regler
// (die Steuerstaebe) und keine feste Zahl - und die Simulation zaehlt wirklich
// Spaltung fuer Spaltung nach, statt eine Kurve zu zeichnen.
// ═══════════════════════════════════════════════════════
let _ket = null;
const _KET_MEV = 200;                     // MeV je Spaltung, mit Folgezerfaellen
const _KET_J = _KET_MEV * 1.602e-13;      // Joule je Spaltung
const _KET_MAX = 4000;                    // mehr Spaltungen zeichnet niemand mehr

function _ketInit() {
  _ket = {
    stab: 50,          // Steuerstaebe: 0 = ganz gezogen, 100 = ganz eingefahren
    gen: 0,            // Generation
    zahl: 500,         // Spaltungen in dieser Generation
    verlauf: [500],
    laeuft: false,
    t: 0,
    punkte: [],        // gezeichnete Spaltungen
  };
  _ketPunkte();
}

/* k haengt an der Stabstellung: ganz gezogen 1,60 - ganz eingefahren 0,40.
   Bei 50 % steht k genau auf 1,00 - das ist der Betriebspunkt. */
function _ketK() { return 1.6 - (_ket.stab / 100) * 1.2; }

function _ketPunkte() {
  const n = Math.min(_ket.zahl, 260);
  _ket.punkte = [];
  for (let i = 0; i < n; i++) {
    // gleichmaessig ueber die Flaeche, aber fest - sonst flimmert das Bild
    const a = (i * 2.399963) % (Math.PI * 2), r = 118 * Math.sqrt((i + 0.5) / n);
    _ket.punkte.push({ x: r * Math.cos(a), y: r * Math.sin(a) * 0.72 });
  }
}

function _ketSetStab(v) {
  _ket.stab = Math.max(0, Math.min(100, Math.round(+v)));
  const w = document.getElementById('ketWertStab');
  if (w) w.textContent = _ket.stab;
  _ketStatus();
}

function _ketSchritt() {
  const k = _ketK();
  // Wirklich abzaehlen, nicht multiplizieren: jede Spaltung setzt Neutronen frei,
  // jedes davon loest mit Wahrscheinlichkeit k/1 eine neue Spaltung aus.
  let neu = 0;
  const zaehl = Math.min(_ket.zahl, 20000);
  const p = k / 2;                       // 2 Neutronen je Spaltung, jedes trifft mit p
  for (let i = 0; i < zaehl; i++) {
    if (Math.random() < p) neu++;
    if (Math.random() < p) neu++;
  }
  if (_ket.zahl > 20000) neu = Math.round(_ket.zahl * k);
  _ket.zahl = Math.min(neu, _KET_MAX * 40);
  _ket.gen++;
  _ket.verlauf.push(_ket.zahl);
  if (_ket.verlauf.length > 26) _ket.verlauf.shift();
  _ketPunkte();
  _ketStatus();
}

function _ketReset() {
  _ket.gen = 0; _ket.zahl = 500; _ket.verlauf = [500]; _ket.t = 0;
  _ketPunkte(); _ketStatus();
}

function _ketLauf() {
  _ket.laeuft = !_ket.laeuft;
  const b = document.getElementById('ketLauf');
  if (b) b.textContent = _ket.laeuft ? '⏸ Anhalten' : '▶ Laufen lassen';
}

function _ketUpdate(dt) {
  if (!_ket) return;
  _ket.t += dt;
  if (_ket.laeuft) {
    _ket.warte = (_ket.warte || 0) + dt;
    if (_ket.warte > 0.75) { _ket.warte = 0; _ketSchritt(); }
  }
}

/* Die Zahl der Spaltungen schwankt um viele Zehnerpotenzen - eine feste
   Einheit wuerde entweder 0,00 oder eine sechsstellige Zahl anzeigen. */
function _ketJoule(e) {
  if (e <= 0) return '0 J';
  if (e < 1e-9)  return _fpmNum(e * 1e12, 1) + ' · 10⁻¹² J';
  if (e < 1e-6)  return _fpmNum(e * 1e9,  1) + ' · 10⁻⁹ J';
  if (e < 1e-3)  return _fpmNum(e * 1e6,  1) + ' · 10⁻⁶ J';
  return _fpmNum(e * 1e3, 1) + ' · 10⁻³ J';
}

function _ketStatus() {
  const el = document.getElementById('ketStatus');
  if (!el || !_ket) return;
  const k = _ketK();
  const z = _ket.zahl;
  const eJ = z * _KET_J;

  let lage, farbe;
  if (k < 0.98) { lage = 'unterkritisch'; farbe = '#2563eb'; }
  else if (k <= 1.02) { lage = 'kritisch – genau richtig'; farbe = '#16a34a'; }
  else { lage = 'überkritisch'; farbe = '#dc2626'; }

  let t = `Steuerstäbe <b>${_ket.stab} %</b> eingefahren &nbsp;→&nbsp; Vermehrungsfaktor <b>k = ${_fpmNum(k, 2)}</b><br>`;
  t += `<b style="color:${farbe}">${lage}</b><br><br>`;
  t += `Generation <b>${_ket.gen}</b>: <b>${z.toLocaleString('de-DE')}</b> Spaltungen`;
  if (_ket.gen > 0) {
    const vor = _ket.verlauf[_ket.verlauf.length - 2];
    if (vor > 0) t += ` (vorher ${vor.toLocaleString('de-DE')})`;
  }
  t += `.<br><br>`;

  if (k < 0.98) {
    t += `Aus 100 Spaltungen werden in der nächsten Generation nur <b>${Math.round(k * 100)}</b>. Jede Generation ist kleiner als die davor – die Kette <b>erstickt</b>. So fährt man einen Reaktor herunter.`;
  } else if (k <= 1.02) {
    t += `Aus 100 Spaltungen werden wieder rund <b>${Math.round(k * 100)}</b>. Jede Generation ist so groß wie die davor – die Kette <b>läuft gleichmäßig weiter</b>. Genau so arbeitet ein Kernkraftwerk: <b>k = 1</b>, Tag und Nacht.`;
  } else {
    t += `Aus 100 Spaltungen werden in der nächsten Generation <b>${Math.round(k * 100)}</b>. Jede Generation ist größer als die davor – die Kette <b>wächst lawinenartig</b>. Nach 10 solchen Generationen wären es schon rund ${Math.round(Math.pow(k, 10)).toLocaleString('de-DE')}-mal so viele.`;
  }
  t += `<br><br>Jede Spaltung liefert rund 200 MeV, also 3,2 · 10⁻¹¹ J. Diese ${z.toLocaleString('de-DE')} Spaltungen zusammen ergeben <b>${_ketJoule(eJ)}</b> – so wenig, dass man es nicht spürt. Ein Kraftwerk braucht deshalb rund <b>10¹⁹ Spaltungen in jeder Sekunde</b>, um auf 300 Megawatt zu kommen.`;
  el.innerHTML = t;
}

function _ketDraw(ctx, cv) {
  if (!_ket) return;
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, cv.width, cv.height);
  const k = _ketK();

  // Brennstab-Behaelter
  ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 2;
  ctx.strokeRect(18, 46, 404, 200);

  // Steuerstaebe von oben hineinfahren
  const tief = (_ket.stab / 100) * 196;
  ctx.fillStyle = '#334155';
  for (let i = 0; i < 6; i++) {
    const x = 48 + i * 66;
    ctx.fillRect(x, 46, 13, tief);
    ctx.fillStyle = '#1e293b'; ctx.fillRect(x - 3, 38, 19, 10);
    ctx.fillStyle = '#334155';
  }

  // Spaltungen als Punkte
  const cx = 220, cy = 146;
  const farbe = k < 0.98 ? '#2563eb' : (k <= 1.02 ? '#16a34a' : '#dc2626');
  for (const p of _ket.punkte) {
    const puls = 2.6 + Math.sin(_ket.t * 7 + p.x * 0.1) * 0.7;
    ctx.fillStyle = farbe;
    ctx.beginPath(); ctx.arc(cx + p.x, cy + p.y, puls, 0, Math.PI * 2); ctx.fill();
  }

  // Verlauf als Balken
  const bx = 18, by = 322, bh = 58, bw = 404;
  const gmax = Math.max(...(_ket.verlauf.length ? _ket.verlauf : [1]), 1);
  const n = _ket.verlauf.length, w = Math.min(15, bw / Math.max(n, 1) - 2);
  ctx.strokeStyle = '#e2e8f0'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(bx + bw, by); ctx.stroke();
  for (let i = 0; i < n; i++) {
    const h = Math.max(1.5, (_ket.verlauf[i] / gmax) * bh);
    ctx.fillStyle = i === n - 1 ? farbe : '#cbd5e1';
    ctx.fillRect(bx + i * (w + 2), by - h, w, h);
  }

  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 13px system-ui';
  ctx.fillText('Steuerstäbe ' + _ket.stab + ' % eingefahren   ·   k = ' + _fpmNum(k, 2), 18, 26);
  ctx.font = '11px system-ui'; ctx.fillStyle = '#475569';
  ctx.fillText('Generation ' + _ket.gen + ':  ' + _ket.zahl.toLocaleString('de-DE') + ' Spaltungen', 18, 266);
  ctx.fillText('Spaltungen je Generation', 18, 282);
  ctx.textAlign = 'right';
  ctx.fillText(_ket.punkte.length < _ket.zahl ? '(gezeichnet: 260 von ' + _ket.zahl.toLocaleString('de-DE') + ')' : '', 422, 266);
}

function _ketArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('kettenreaktion')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('kettenreaktion')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Wovon hängt es ab, ob eine Kettenreaktion erstirbt, gleichmäßig läuft oder außer Kontrolle gerät?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, dass die Kette weiterläuft, wenn … , weil …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Setze zurück – es beginnt mit 500 Spaltungen. Fahre die Steuerstäbe auf 80 % ein und drücke fünfmal „nächste Generation“.</li>
          <li>Setze zurück, stelle 50 % ein und wiederhole.</li>
          <li>Setze zurück, stelle 20 % ein und wiederhole.</li>
          <li>Notiere jedes Mal k und die Zahl der Spaltungen.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Steuerstäbe</td><td>80 %</td><td>50 %</td><td>20 %</td></tr>
          <tr><td>k</td><td>${inp('a1','')}</td><td>${inp('a2','')}</td><td>${inp('a3','')}</td></tr>
          <tr><td>nach 5 Generationen</td><td>${inp('b1','')}</td><td>${inp('b2','')}</td><td>${inp('b3','')}</td></tr>
          <tr><td>erstirbt / gleich / wächst</td><td>${inp('c1','')}</td><td>${inp('c2','')}</td><td>${inp('c3','')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Auswertung</div>
        ${ta('a6', 'Je weiter die Steuerstäbe eingefahren sind, desto … . Ein Kraftwerk arbeitet bei k = … , weil … . Bei k = 1,2 wären es nach 10 Generationen schon … mal so viele Spaltungen.', 4)}</div>

      <div class="ab-sec"><div class="ab-h">6 · Merksatz</div>
        <div class="ab-t">Die Steuerstäbe <b>schlucken Neutronen</b>. Fährt man sie tiefer ein, wird k ${inp('m1', 'größer oder kleiner?')}. Ein Kraftwerk läuft dauerhaft bei k = ${inp('m2', 'welcher Wert?')}.</div></div>`;
  return _abWrap('kettenreaktion', 'Kettenreaktion steuern', body);
}

function _ketHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim ket-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🎛️ Wie verhindert man, dass eine Kettenreaktion außer Kontrolle gerät?</h3>
    <div class="fpm-note" style="margin-top:2px">Jede Spaltung setzt zwei bis drei Neutronen frei. Die meisten fliegen davon oder werden geschluckt – nur ein Teil trifft einen neuen Kern. Wie groß dieser Teil ist, bestimmen die <b>Steuerstäbe</b>. Die Zahl dazu heißt <b>k</b>: Sie sagt, wie viele neue Spaltungen aus <b>einer</b> Spaltung folgen.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="ketAnim" width="440" height="330" class="phys-anim-cv"></canvas>
        <div style="margin-top:6px">
          <label class="fpm-label" for="ketStab">Steuerstäbe eingefahren: <b id="ketWertStab">50</b> %</label>
          <input type="range" id="ketStab" min="0" max="100" value="50" step="1" oninput="_ketSetStab(this.value)" style="width:100%">
        </div>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" onclick="_ketSchritt()">⏭ nächste Generation</button>
          <button class="sim-btn" id="ketLauf" onclick="_ketLauf()">▶ Laufen lassen</button>
          <button class="sim-btn" onclick="_ketReset()">↺ Zurücksetzen</button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Wie geht es weiter?</div>
        <div class="lmp-status" id="ketStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Vom Reaktor zur Steckdose sind es vier Schritte: Die Bruchstücke fliegen auseinander und <b>erhitzen</b> den Brennstab. Die Wärme macht aus Wasser <b>Dampf</b>. Der Dampf treibt eine <b>Turbine</b>. Die Turbine dreht den <b>Generator</b>. Nur der letzte Schritt macht Strom – alles davor ist ganz gewöhnliche Wärmekraftwerks-Technik. Ein Kernkraftwerk ist ein Dampfkraftwerk, dessen Feuer aus Kernspaltung besteht.</div>
        <div class="fpm-note" style="margin-top:8px"><b>Modellgrenze:</b> Hier zählen ein paar Tausend Spaltungen; in einem Reaktor sind es rund <b>10¹⁹ in jeder Sekunde</b>. Und k lässt sich in Wirklichkeit nicht einfach am Regler drehen – es hängt außerdem von Temperatur, Dampfblasen und dem Alter der Brennstäbe ab. Dass ein Reaktor überhaupt regelbar ist, liegt an einem Glücksfall: Ein kleiner Teil der Neutronen kommt erst <b>Sekunden später</b> aus den Bruchstücken. Ohne diese „verzögerten Neutronen“ ginge alles zu schnell zum Nachsteuern.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      k &lt; 1 erstirbt · <b>k = 1 Kraftwerk</b> · k &gt; 1 lawinenartig
    </p>
    ${_ketArbeitsblattHTML()}
  </div>`;
}

// ═══════════════════════════════════════════════════════
// 10.3.17  ZERFALLSREIHE UND NUKLIDKARTE
// Realschule NRW - Klasse 10 - Inhaltsfeld "Kernenergie und Radioaktivitaet"
// Zwei Fragen auf einmal: WARUM zerfaellt ein Kern (er liegt neben dem Tal der
// stabilen Kerne - zu viele Neutronen fuer seine Protonen) und WAS wird aus ihm
// (Alpha: A-4, Z-2 · Beta: A bleibt, Z+1). Deshalb laeuft der Kern hier
// wirklich Schritt fuer Schritt durch die Nuklidkarte, bis er bei Blei
// ankommt - und jeder Schritt schreibt seine Gleichung mit.
// Daten: Uran-238-Reihe, Halbwertszeiten nach der Karlsruher Nuklidkarte.
// ═══════════════════════════════════════════════════════
let _zrr = null;

const _ZRR_REIHE = [
  { a: 238, z: 92, s: 'U',  n: 'Uran-238',       art: 'α', hwz: '4,5 Milliarden Jahre' },
  { a: 234, z: 90, s: 'Th', n: 'Thorium-234',    art: 'β', hwz: '24,1 Tage' },
  { a: 234, z: 91, s: 'Pa', n: 'Protactinium-234', art: 'β', hwz: '1,2 Minuten' },
  { a: 234, z: 92, s: 'U',  n: 'Uran-234',       art: 'α', hwz: '245.500 Jahre' },
  { a: 230, z: 90, s: 'Th', n: 'Thorium-230',    art: 'α', hwz: '75.380 Jahre' },
  { a: 226, z: 88, s: 'Ra', n: 'Radium-226',     art: 'α', hwz: '1600 Jahre' },
  { a: 222, z: 86, s: 'Rn', n: 'Radon-222',      art: 'α', hwz: '3,8 Tage' },
  { a: 218, z: 84, s: 'Po', n: 'Polonium-218',   art: 'α', hwz: '3,1 Minuten' },
  { a: 214, z: 82, s: 'Pb', n: 'Blei-214',       art: 'β', hwz: '26,8 Minuten' },
  { a: 214, z: 83, s: 'Bi', n: 'Bismut-214',     art: 'β', hwz: '19,9 Minuten' },
  { a: 214, z: 84, s: 'Po', n: 'Polonium-214',   art: 'α', hwz: '0,00016 Sekunden' },
  { a: 210, z: 82, s: 'Pb', n: 'Blei-210',       art: 'β', hwz: '22,3 Jahre' },
  { a: 210, z: 83, s: 'Bi', n: 'Bismut-210',     art: 'β', hwz: '5,0 Tage' },
  { a: 210, z: 84, s: 'Po', n: 'Polonium-210',   art: 'α', hwz: '138,4 Tage' },
  { a: 206, z: 82, s: 'Pb', n: 'Blei-206',       art: null, hwz: null },
];

const _ZRR_NOTIZ = {
  'Radon-222': 'Radon ist ein <b>Gas</b>. Es steigt aus dem Boden in Keller und Wohnräume – von der natürlichen Strahlung, die ein Mensch abbekommt, kommt der größte Teil daher.',
  'Radium-226': 'Marie Curie hat es entdeckt. Ihre Notizbücher strahlen bis heute.',
  'Blei-206': 'Ein stabiler Kern. Er hat 82 Protonen – und genau bei 82 liegt eine besonders stabile Anordnung.',
  'Polonium-214': 'Eine Sechzehntel-Millisekunde. Diesen Kern sieht niemand – er ist weg, bevor man messen kann.',
};

const _ZRR_HOCH = {0:'⁰',1:'¹',2:'²',3:'³',4:'⁴',5:'⁵',6:'⁶',7:'⁷',8:'⁸',9:'⁹'};
const _ZRR_TIEF = {0:'₀',1:'₁',2:'₂',3:'₃',4:'₄',5:'₅',6:'₆',7:'₇',8:'₈',9:'₉','-':'₋'};
function _zrrSchrift(a, z, sym) {
  return String(a).split('').map(c => _ZRR_HOCH[c]).join('') +
         String(z).split('').map(c => _ZRR_TIEF[c]).join('') + sym;
}

function _zrrInit() { _zrr = { i: 0, t: 0, blitz: 0 }; }

function _zrrJetzt() { return _ZRR_REIHE[_zrr.i]; }

function _zrrSchritt() {
  if (_zrr.i < _ZRR_REIHE.length - 1) { _zrr.i++; _zrr.blitz = 1; _zrrStatus(); }
}
function _zrrZurueck() { if (_zrr.i > 0) { _zrr.i--; _zrrStatus(); } }
function _zrrReset() { _zrr.i = 0; _zrr.blitz = 0; _zrrStatus(); }
function _zrrEnde() { _zrr.i = _ZRR_REIHE.length - 1; _zrrStatus(); }

function _zrrUpdate(dt) {
  if (!_zrr) return;
  _zrr.t += dt;
  if (_zrr.blitz > 0) _zrr.blitz = Math.max(0, _zrr.blitz - dt * 1.6);
}

function _zrrStatus() {
  const el = document.getElementById('zrrStatus');
  if (!el || !_zrr) return;
  const k = _zrrJetzt(), N = k.a - k.z;
  let t = `Schritt <b>${_zrr.i}</b> von ${_ZRR_REIHE.length - 1} &nbsp;·&nbsp; jetzt: <b>${_zrrSchrift(k.a, k.z, k.s)}</b>, ${k.n}<br>`;
  t += `${k.z} Protonen, ${N} Neutronen &nbsp;·&nbsp; auf <b>ein</b> Proton kommen <b>${_fpmNum(N / k.z, 2)}</b> Neutronen.<br>`;
  t += k.art === null ? `<b>Stabil</b> – dieser Kern hat keine Halbwertszeit.<br><br>`
                      : `Halbwertszeit: <b>${k.hwz}</b><br><br>`;

  if (k.art === null) {
    t += `<b>Hier bleibt es.</b> Blei-206 ist stabil – das Verhältnis von Neutronen zu Protonen passt jetzt. Die ganze Reihe ist damit zu Ende.<br><br>`;
    const aStart = _ZRR_REIHE[0], alpha = _ZRR_REIHE.filter(x => x.art === 'α').length,
          beta = _ZRR_REIHE.filter(x => x.art === 'β').length;
    t += `Von ${aStart.n} bis hierher waren es <b>${alpha} Alphazerfälle</b> und <b>${beta} Betazerfälle</b>.<br>`;
    t += `Nachrechnen: 238 − ${alpha} · 4 = <b>${238 - alpha * 4}</b>. Und 92 − ${alpha} · 2 + ${beta} · 1 = <b>${92 - alpha * 2 + beta}</b>. Beides stimmt mit Blei-206 überein.`;
  } else {
    const nx = _ZRR_REIHE[_zrr.i + 1];
    if (k.art === 'α') {
      t += `Dieser Kern hat <b>zu viele Kernbausteine</b>. Er wirft ein ganzes Paket ab: zwei Protonen und zwei Neutronen zusammen – einen <b>Heliumkern</b>. Das ist <b>Alphastrahlung</b>.<br><br>`;
      t += `<b>${_zrrSchrift(k.a, k.z, k.s)} → ${_zrrSchrift(nx.a, nx.z, nx.s)} + ${_zrrSchrift(4, 2, 'He')}</b><br><br>`;
      t += `A: ${k.a} − 4 = <b>${nx.a}</b> &nbsp;·&nbsp; Z: ${k.z} − 2 = <b>${nx.z}</b>. Das Element wechselt – aus ${k.n.split('-')[0]} wird ${nx.n.split('-')[0]}.`;
    } else {
      t += `Dieser Kern hat <b>zu viele Neutronen</b>. Eines davon wandelt sich um: Aus dem Neutron wird ein Proton, und ein Elektron fliegt heraus. Das ist <b>Betastrahlung</b>.<br><br>`;
      t += `<b>${_zrrSchrift(k.a, k.z, k.s)} → ${_zrrSchrift(nx.a, nx.z, nx.s)} + ${_zrrSchrift(0, -1, 'e')}</b><br><br>`;
      t += `A: bleibt <b>${nx.a}</b> – es geht ja kein Baustein verloren, einer wird nur umgebaut. Z: ${k.z} + 1 = <b>${nx.z}</b>. Auch hier wechselt das Element.`;
    }
  }
  if (_ZRR_NOTIZ[k.n]) t += `<br><br><i>${_ZRR_NOTIZ[k.n]}</i>`;
  el.innerHTML = t;
}

function _zrrDraw(ctx, cv) {
  if (!_zrr) return;
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, cv.width, cv.height);

  // Nuklidkarte: N waagerecht, Z senkrecht
  const nMin = 123, nMax = 147, zMin = 81, zMax = 93;
  const oxL = 44, oxR = 424, oyB = 268, oyT = 44;
  const px = n => oxL + ((n - nMin) / (nMax - nMin)) * (oxR - oxL);
  const py = z => oyB - ((z - zMin) / (zMax - zMin)) * (oyB - oyT);

  // Raster
  ctx.strokeStyle = '#e8edf3'; ctx.lineWidth = 1;
  for (let n = nMin; n <= nMax; n += 2) { ctx.beginPath(); ctx.moveTo(px(n), oyT); ctx.lineTo(px(n), oyB); ctx.stroke(); }
  for (let z = zMin; z <= zMax; z += 1) { ctx.beginPath(); ctx.moveTo(oxL, py(z)); ctx.lineTo(oxR, py(z)); ctx.stroke(); }

  // Achsen
  ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.moveTo(oxL, oyT); ctx.lineTo(oxL, oyB); ctx.lineTo(oxR, oyB); ctx.stroke();
  ctx.fillStyle = '#475569'; ctx.font = '10px system-ui';
  ctx.textAlign = 'center'; ctx.textBaseline = 'top';
  for (let n = nMin + 1; n <= nMax; n += 4) ctx.fillText(String(n), px(n), oyB + 5);
  ctx.fillText('Neutronen  N  →', (oxL + oxR) / 2, oyB + 20);
  ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
  for (let z = zMin + 1; z <= zMax; z += 2) ctx.fillText(String(z), oxL - 6, py(z));
  ctx.save(); ctx.translate(14, (oyT + oyB) / 2); ctx.rotate(-Math.PI / 2);
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('Protonen  Z  →', 0, 0); ctx.restore();

  // Weg der Reihe
  ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 1.6;
  ctx.beginPath();
  _ZRR_REIHE.forEach((k, i) => {
    const x = px(k.a - k.z), y = py(k.z);
    i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
  });
  ctx.stroke();

  // Kerne
  _ZRR_REIHE.forEach((k, i) => {
    const x = px(k.a - k.z), y = py(k.z);
    const jetzt = i === _zrr.i, erledigt = i < _zrr.i;
    let f = '#e2e8f0';
    if (k.art === null) f = '#16a34a';
    else if (erledigt) f = '#94a3b8';
    if (jetzt) f = k.art === null ? '#16a34a' : (k.art === 'α' ? '#dc2626' : '#2563eb');
    ctx.fillStyle = f;
    const r = jetzt ? 11 + _zrr.blitz * 5 : 8;
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
    if (jetzt) { ctx.strokeStyle = '#0f172a'; ctx.lineWidth = 2; ctx.stroke(); }
    // Der Kern, an dem die Reihe gerade steht, bekommt einen pulsierenden Ring -
    // aber NUR, solange er instabil ist. Blei-206 (art === null) liegt still da.
    // Genau das ist die Aussage der Seite: Die Reihe endet, wenn ein Kern stabil ist.
    if (jetzt && k.art !== null) {
      const pu = 1 + 0.5 * (1 + Math.sin(_zrr.t * 3.4));
      ctx.strokeStyle = 'rgba(220,38,38,' + (0.42 - 0.12 * pu).toFixed(3) + ')';
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(x, y, r + 4 + pu * 5, 0, Math.PI * 2); ctx.stroke();
    }
  });

  // Beschriftung des aktuellen Kerns
  const k = _zrrJetzt();
  const x = px(k.a - k.z), y = py(k.z);
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 12px system-ui';
  ctx.textAlign = 'center'; ctx.textBaseline = 'bottom';
  ctx.fillText(_zrrSchrift(k.a, k.z, k.s), x, y - 15);

  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 13px system-ui';
  ctx.fillText('Uran-238 auf dem Weg zu Blei-206', 14, 24);

  // Legende
  ctx.font = '11px system-ui';
  const leg = [['#dc2626', 'α: schräg nach unten links  (A−4, Z−2)'],
               ['#2563eb', 'β: nach oben links  (A bleibt, Z+1)'],
               ['#16a34a', 'stabil: Blei-206']];
  leg.forEach(([f, txt], i) => {
    const ly = 300 + i * 0;
    ctx.fillStyle = f;
    ctx.beginPath(); ctx.arc(20 + i * 148, 300, 6, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#334155'; ctx.font = '9.5px system-ui';
    ctx.fillText(txt.split(':')[0] + ':', 29 + i * 148, 297);
    ctx.fillText(txt.split(': ')[1], 29 + i * 148, 308);
  });
}

function _zrrArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('zerfallsreihe')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('zerfallsreihe')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Warum zerfällt ein Kern überhaupt – und was ist danach aus ihm geworden?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, dass ein Kern zerfällt, wenn … . Danach ist er …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Starte bei Uran-238 und gehe Schritt für Schritt weiter bis Blei-206.</li>
          <li>Notiere für die ersten vier Schritte die Zerfallsart und die Gleichung.</li>
          <li>Achte in der Karte darauf, wohin sich der Punkt bewegt.</li>
          <li>Zähle am Ende alle α- und alle β-Zerfälle.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Schritt</td><td>1</td><td>2</td><td>3</td><td>4</td></tr>
          <tr><td>Kern vorher</td><td>${inp('a1','')}</td><td>${inp('a2','')}</td><td>${inp('a3','')}</td><td>${inp('a4','')}</td></tr>
          <tr><td>α oder β?</td><td>${inp('b1','')}</td><td>${inp('b2','')}</td><td>${inp('b3','')}</td><td>${inp('b4','')}</td></tr>
          <tr><td>Kern nachher</td><td>${inp('c1','')}</td><td>${inp('c2','')}</td><td>${inp('c3','')}</td><td>${inp('c4','')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Auswertung</div>
        ${ta('a6', 'Beim α-Zerfall ändert sich A um … und Z um … . Beim β-Zerfall bleibt … gleich und Z ändert sich um … . Insgesamt zählt die Reihe … α-Zerfälle und … β-Zerfälle. Rechnung: 238 − … · 4 = 206 und 92 − … · 2 + … = 82.', 5)}</div>

      <div class="ab-sec"><div class="ab-h">6 · Merksatz</div>
        <div class="ab-t">Ein Kern zerfällt, wenn das Verhältnis von ${inp('m1', 'was zu was?')} nicht passt. Er hört auf zu zerfallen, sobald er ${inp('m2', 'wo?')} angekommen ist.</div></div>`;
  return _abWrap('zerfallsreihe', 'Zerfallsreihe: von Uran zu Blei', body);
}

function _zrrHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim zrr-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🧭 Warum zerfallen manche Kerne – und was wird aus ihnen?</h3>
    <div class="fpm-note" style="margin-top:2px">Uran-238 kommt nicht in einem Sprung bei Blei an, sondern in <b>14 Schritten</b>. Verfolge jeden davon: Welche Strahlung fliegt weg, und wohin wandert der Kern in der Karte?</div>
    <div class="fpm-grid">
      <div>
        <canvas id="zrrAnim" width="440" height="330" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" onclick="_zrrSchritt()">⏭ nächster Zerfall</button>
          <button class="sim-btn" onclick="_zrrZurueck()">⏮ zurück</button>
          <button class="sim-btn" onclick="_zrrEnde()">⏭⏭ bis zum Ende</button>
          <button class="sim-btn" onclick="_zrrReset()">↺ von vorn</button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Was passiert bei diesem Schritt?</div>
        <div class="lmp-status" id="zrrStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Stabile Kerne liegen in der Karte auf einem schmalen Band, dem <b>Tal der Stabilität</b>. Bei leichten Kernen liegt es bei etwa gleich vielen Protonen und Neutronen; je schwerer der Kern, desto mehr Neutronen braucht er. Wer zu weit daneben liegt, zerfällt – so lange, bis er im Tal ankommt.</div>
        <div class="fpm-note" style="margin-top:8px"><b>Modellgrenze:</b> Der Weg ist hier eine feste Kette. In Wirklichkeit gibt es an einigen Stellen <b>Abzweigungen</b> – Bismut-214 zerfällt zu 99,98 % über β, ganz selten aber über α. Und die Zeiten sind Halbwertszeiten, keine Termine: Ein einzelner Kern kann jeden Schritt sofort oder erst nach dem Tausendfachen der Halbwertszeit machen.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      α: A − 4, Z − 2 · β: A bleibt, Z + 1 · Schluss ist bei einem stabilen Kern
    </p>
    ${_zrrArbeitsblattHTML()}
  </div>`;
}

// ═══════════════════════════════════════════════════════
// 10.3.18  STRAHLENSCHUTZ - ABSTAND, ABSCHIRMUNG, AUFENTHALTSDAUER
// Realschule NRW - Klasse 10 - Inhaltsfeld "Kernenergie und Radioaktivitaet"
// Die drei A sind keine Merkspruch-Floskel, sondern drei verschiedene
// Rechnungen: Abstand geht QUADRATISCH ein, Abschirmung halbiert je
// Halbwertsdicke, Aufenthaltsdauer geht einfach linear ein. Deshalb hat jede
// der drei einen eigenen Regler - und die Statuszeile schreibt die Rechnung
// in dieser Reihenfolge hin.
// Zahlen: Gamma-Dosisleistungskonstante Cs-137 = 0,0927 mSv*m²/(h*GBq);
// Halbwertsdicke Blei fuer 662 keV = 6,5 mm.
// ═══════════════════════════════════════════════════════
let _stz = null;
const _STZ_GAMMA = 0.0927;     // µSv·m² je h und MBq
const _STZ_AKT = 1000;         // MBq, also 1 GBq - eine Quelle aus der Technik
const _STZ_HVD = 6.5;          // Halbwertsdicke Blei in mm

/* Zum Einordnen - alles in µSv. Quellen: Bundesamt fuer Strahlenschutz. */
const _STZ_VERGLEICH = [
  { v: 40,   t: 'ein Flug Frankfurt–New York' },
  { v: 100,  t: 'eine Röntgenaufnahme der Lunge' },
  { v: 1000, t: 'der Grenzwert, den die Öffentlichkeit im Jahr zusätzlich bekommen darf' },
  { v: 2100, t: 'was jeder in Deutschland im Jahr aus der Natur abbekommt' },
  { v: 20000, t: 'der Grenzwert für Menschen, die beruflich damit arbeiten – pro Jahr' },
];

function _stzInit() { _stz = { r: 100, d: 0, min: 20, t: 0 }; }

function _stzLeistung() {
  const rM = _stz.r / 100;
  return _STZ_GAMMA * _STZ_AKT / (rM * rM) * Math.pow(0.5, _stz.d / _STZ_HVD);
}

function _stzSet(was, v) {
  v = Math.round(+v);
  if (was === 'r') { _stz.r = Math.max(20, Math.min(300, v)); const e = document.getElementById('stzWertR'); if (e) e.textContent = _stz.r; }
  if (was === 'd') { _stz.d = Math.max(0, Math.min(40, v));  const e = document.getElementById('stzWertD'); if (e) e.textContent = _stz.d; }
  if (was === 't') { _stz.min = Math.max(1, Math.min(60, v)); const e = document.getElementById('stzWertT'); if (e) e.textContent = _stz.min; }
  _stzStatus();
}

function _stzZeig(v) {   // µSv lesbar machen
  if (v >= 1000) return _fpmNum(v / 1000, 2) + ' mSv';
  if (v >= 10) return _fpmNum(v, 1) + ' µSv';
  return _fpmNum(v, 2) + ' µSv';
}

function _stzStatus() {
  const el = document.getElementById('stzStatus');
  if (!el || !_stz) return;
  const rM = _stz.r / 100;
  // Jeder Zwischenwert wird auf die Stellen gerundet, mit denen er auch DASTEHT,
  // und erst dann weiterverrechnet. Sonst geht die abgedruckte Kette nicht auf.
  const ohne = +(_STZ_GAMMA * _STZ_AKT / (rM * rM)).toFixed(1);
  const hvz = _stz.d / _STZ_HVD;
  const faktor = +Math.pow(0.5, hvz).toFixed(3);
  const leist = +(ohne * faktor).toFixed(2);
  const dosis = +(leist * _stz.min / 60).toFixed(2);

  let t = `<b>Quelle:</b> Cäsium-137, 1 GBq – eine Quelle, wie sie in der Technik wirklich verwendet wird.<br><br>`;

  t += `<b>1 · Abstand</b> &nbsp; ${_fpmNum(rM, 2)} m<br>`;
  t += `H' = 0,0927 · 1000 / ${_fpmNum(rM, 2)}² = <b>${_fpmNum(ohne, 1)} µSv/h</b><br>`;
  if (_stz.r !== 100) {
    const gegen = _STZ_GAMMA * _STZ_AKT;
    t += `<span style="color:#475569">Bei 1 m wären es ${_fpmNum(gegen, 1)} µSv/h. Doppelter Abstand heißt <b>ein Viertel</b>, nicht die Hälfte – der Abstand geht <b>quadratisch</b> ein.</span><br>`;
  }
  t += `<br>`;

  t += `<b>2 · Abschirmung</b> &nbsp; ${_stz.d} mm Blei<br>`;
  if (_stz.d === 0) {
    t += `Kein Blei – es bleibt bei <b>${_fpmNum(leist, 1)} µSv/h</b>.<br>`;
  } else {
    t += `${_stz.d} mm sind ${_fpmNum(hvz, 2)} Halbwertsdicken (eine Halbwertsdicke ist 6,5 mm Blei).<br>`;
    t += `Übrig bleibt der Anteil 0,5<sup>${_fpmNum(hvz, 2)}</sup> = <b>${_fpmNum(faktor, 3)}</b>.<br>`;
    t += `H' = ${_fpmNum(ohne, 1)} µSv/h · ${_fpmNum(faktor, 3)} = <b>${_fpmNum(leist, 2)} µSv/h</b><br>`;
  }
  t += `<br>`;

  t += `<b>3 · Aufenthaltsdauer</b> &nbsp; ${_stz.min} Minuten<br>`;
  t += `H = ${_fpmNum(leist, 2)} µSv/h · ${_stz.min}/60 h = <b style="font-size:1.08em">${_fpmNum(dosis, 2)} µSv</b>`;
  t += dosis >= 1000 ? ` &nbsp;– das sind <b>${_fpmNum(dosis / 1000, 2)} mSv</b>.<br>` : `<br>`;
  t += `<span style="color:#475569">Die Zeit geht <b>einfach</b> ein: doppelt so lange, doppelte Dosis.</span><br><br>`;

  // Einordnung
  let nah = _STZ_VERGLEICH[0];
  for (const v of _STZ_VERGLEICH) if (Math.abs(Math.log(v.v / dosis)) < Math.abs(Math.log(nah.v / dosis))) nah = v;
  const mal = dosis / nah.v;
  t += `<b>Zum Vergleich:</b> ${_stzZeig(nah.v)} ist ${nah.t}. Diese Dosis hier ist ` +
       (mal >= 1.15 ? `rund <b>${_fpmNum(mal, mal < 10 ? 1 : 0)}-mal so groß</b>.`
      : mal <= 0.87 ? `rund <b>${_fpmNum(1 / mal, 1 / mal < 10 ? 1 : 0)}-mal kleiner</b>.`
      : `<b>ungefähr genauso groß</b>.`);
  el.innerHTML = t;
}

function _stzUpdate(dt) { if (_stz) _stz.t += dt; }

function _stzDraw(ctx, cv) {
  if (!_stz) return;
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, cv.width, cv.height);
  const bodenY = 250, qx = 46, qy = 170;
  const px = cm => qx + (cm / 300) * 348;     // 300 cm auf 348 Pixel

  // Boden
  ctx.fillStyle = '#e2e8f0'; ctx.fillRect(0, bodenY, cv.width, cv.height - bodenY);
  ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(0, bodenY); ctx.lineTo(cv.width, bodenY); ctx.stroke();

  // Strahlen, die von der Quelle ausgehen - Dichte nimmt nach aussen ab
  const faktor = Math.pow(0.5, _stz.d / _STZ_HVD);
  for (let i = 0; i < 13; i++) {
    const w = -1.15 + i * (2.3 / 12);
    const laenge = 340;
    ctx.strokeStyle = 'rgba(220,38,38,' + (0.30 + 0.16 * Math.sin(_stz.t * 3 + i)) + ')';
    ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.moveTo(qx, qy);
    ctx.lineTo(qx + laenge * Math.cos(w), qy + laenge * Math.sin(w));
    ctx.stroke();
  }

  // Bleiwand
  if (_stz.d > 0) {
    const wx = px(_stz.r * 0.55), bw = 6 + _stz.d * 0.5;
    ctx.fillStyle = '#475569';
    ctx.fillRect(wx, qy - 74, bw, 148);
    ctx.fillStyle = '#0f172a'; ctx.font = 'bold 10px system-ui';
    ctx.textAlign = 'center'; ctx.textBaseline = 'bottom';
    ctx.fillText(_stz.d + ' mm Blei', wx + bw / 2, qy - 80);
    // hinter der Wand wird es blasser
    ctx.fillStyle = 'rgba(248,250,252,' + (1 - faktor) * 0.82 + ')';
    ctx.fillRect(wx + bw, 40, cv.width - wx - bw, bodenY - 40);
  }

  // Quelle
  ctx.fillStyle = '#dc2626';
  ctx.beginPath(); ctx.arc(qx, qy, 13, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fff'; ctx.font = 'bold 11px system-ui';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('☢', qx, qy);
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 10px system-ui';
  ctx.textBaseline = 'top';
  ctx.fillText('Cs-137', qx, qy + 18);
  ctx.fillText('1 GBq', qx, qy + 30);

  // Person
  const mx = px(_stz.r);
  ctx.strokeStyle = '#0f172a'; ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.arc(mx, qy - 34, 9, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(mx, qy - 25); ctx.lineTo(mx, qy + 12);
  ctx.moveTo(mx - 13, qy - 12); ctx.lineTo(mx + 13, qy - 12);
  ctx.moveTo(mx, qy + 12); ctx.lineTo(mx - 11, qy + 38);
  ctx.moveTo(mx, qy + 12); ctx.lineTo(mx + 11, qy + 38);
  ctx.stroke();

  // Abstandsmass
  ctx.strokeStyle = '#2563eb'; ctx.lineWidth = 1.4;
  ctx.setLineDash([4, 3]);
  ctx.beginPath(); ctx.moveTo(qx, bodenY + 20); ctx.lineTo(mx, bodenY + 20); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = '#2563eb'; ctx.font = 'bold 11px system-ui';
  ctx.textAlign = 'center'; ctx.textBaseline = 'top';
  ctx.fillText(_fpmNum(_stz.r / 100, 2) + ' m', (qx + mx) / 2, bodenY + 26);

  // Anzeige oben
  const leist = _stzLeistung(), dosis = leist * _stz.min / 60;
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 13px system-ui';
  ctx.fillText('Dosisleistung: ' + _fpmNum(leist, leist < 10 ? 2 : 1) + ' µSv/h', 14, 24);
  ctx.font = 'bold 12px system-ui';
  ctx.fillText('in ' + _stz.min + ' Minuten:  ' + _stzZeig(dosis), 14, 42);
}

function _stzArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('strahlenschutz')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('strahlenschutz')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Womit schützt man sich am wirksamsten: mit Abstand, mit Blei oder damit, schneller fertig zu sein?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, dass … am meisten bringt, weil …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Stelle 100 cm, 0 mm Blei, 20 Minuten ein. Notiere die Dosisleistung.</li>
          <li>Verdopple <b>nur</b> den Abstand auf 200 cm. Notiere erneut.</li>
          <li>Gehe zurück auf 100 cm und lege <b>nur</b> 6,5 mm Blei dazwischen – nimm 7 mm.</li>
          <li>Nimm das Blei weg und halbiere <b>nur</b> die Zeit auf 10 Minuten.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Änderung</td><td>Ausgangswert</td><td>Abstand verdoppelt</td><td>7 mm Blei</td><td>Zeit halbiert</td></tr>
          <tr><td>Dosisleistung in µSv/h</td><td>${inp('a1','')}</td><td>${inp('a2','')}</td><td>${inp('a3','')}</td><td>${inp('a4','')}</td></tr>
          <tr><td>Dosis in µSv</td><td>${inp('b1','')}</td><td>${inp('b2','')}</td><td>${inp('b3','')}</td><td>${inp('b4','')}</td></tr>
          <tr><td>auf welchen Teil?</td><td>1</td><td>${inp('c2','')}</td><td>${inp('c3','')}</td><td>${inp('c4','')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Auswertung</div>
        ${ta('a6', 'Doppelter Abstand bringt … , weil … . Eine Halbwertsdicke Blei bringt … . Halbe Zeit bringt … . Am meisten bringt deshalb … .', 4)}</div>

      <div class="ab-sec"><div class="ab-h">6 · Merksatz</div>
        <div class="ab-t">Die drei A des Strahlenschutzes heißen ${inp('m1', 'welche drei?')}. Der Abstand wirkt am stärksten, weil er ${inp('m2', 'wie?')} eingeht.</div></div>`;
  return _abWrap('strahlenschutz', 'Strahlenschutz: die drei A', body);
}

function _stzHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim stz-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🛡️ Wie schütze ich mich am wirksamsten vor Strahlung?</h3>
    <div class="fpm-note" style="margin-top:2px">Drei Möglichkeiten hat man: weiter <b>weg</b> gehen, etwas <b>dazwischen</b> stellen, oder <b>kürzer</b> bleiben. Alle drei helfen – aber nicht gleich viel. Ändere immer nur eine und sieh nach.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="stzAnim" width="440" height="330" class="phys-anim-cv"></canvas>
        <div style="margin-top:6px">
          <label class="fpm-label" for="stzR">Abstand: <b id="stzWertR">100</b> cm</label>
          <input type="range" id="stzR" min="20" max="300" value="100" step="5" oninput="_stzSet('r', this.value)" style="width:100%">
          <label class="fpm-label" for="stzD">Blei dazwischen: <b id="stzWertD">0</b> mm</label>
          <input type="range" id="stzD" min="0" max="40" value="0" step="1" oninput="_stzSet('d', this.value)" style="width:100%">
          <label class="fpm-label" for="stzT">Aufenthaltsdauer: <b id="stzWertT">20</b> Minuten</label>
          <input type="range" id="stzT" min="1" max="60" value="20" step="1" oninput="_stzSet('t', this.value)" style="width:100%">
        </div>
      </div>
      <div>
        <div class="fpm-label">Wie viel kommt an?</div>
        <div class="lmp-status" id="stzStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Warum ist gerade der <b>Abstand</b> so wirksam? Die Strahlung verteilt sich auf eine Kugelfläche, und die wächst mit dem <b>Quadrat</b> des Radius. Doppelter Abstand heißt vierfache Fläche – also ein Viertel auf jedem Stück davon.</div>
        <div class="fpm-note" style="margin-top:8px"><b>Modellgrenze:</b> Gerechnet wird hier nur mit der <b>Gammastrahlung</b> von Cäsium-137. Alpha- und Betastrahlung würden schon von der Luft und einem Blatt Papier aufgehalten – für sie stimmt keine dieser Zahlen. Außerdem gilt die Rechnung für eine <b>punktförmige</b> Quelle im Freien; im Raum wird Strahlung an Wänden gestreut, sodass hinter dem Blei etwas mehr ankommt als hier angezeigt.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      <b>A</b>bstand (geht quadratisch ein) · <b>A</b>bschirmung (halbiert je 6,5 mm Blei) · <b>A</b>ufenthaltsdauer (geht einfach ein)
    </p>
    ${_stzArbeitsblattHTML()}
  </div>`;
}

// ═══════════════════════════════════════════════════════
// 10.3.19  IONISATION - WAS DIESE STRAHLUNG BESONDERS MACHT
// Realschule NRW - Klasse 10 - Inhaltsfeld "Kernenergie und Radioaktivitaet"
// "Radioaktive Strahlung ist gefaehrlich" ist keine Erklaerung. Gefaehrlich ist
// sie, weil sie Elektronen aus Atomen herausschlaegt - und dabei zerreisst sie
// Molekuele, auch die im Erbgut. Der entscheidende Unterschied zwischen Alpha,
// Beta und Gamma ist nicht die Reichweite an sich, sondern wie DICHT sie auf
// ihrem Weg ionisieren. Deshalb rechnet die Simulation Ionenpaare je Millimeter
// aus - und daraus wird verstaendlich, warum Alpha aussen harmlos und innen
// das Gefaehrlichste von allen ist.
// Zahl dahinter: In Luft kostet ein Ionenpaar im Mittel 34 eV (W-Wert).
// ═══════════════════════════════════════════════════════
let _ion = null;
const _ION_W = 34;         // eV je Ionenpaar in Luft

const _ION_ARTEN = [
  { id: 'a', name: 'Alphastrahlung', kurz: 'α', farbe: '#dc2626',
    e: 5.0, reich: 35, was: 'ein Heliumkern – zwei Protonen und zwei Neutronen',
    stopp: 'ein Blatt Papier oder wenige Zentimeter Luft', wr: 20,
    innen: 'Wird ein alphastrahlender Stoff <b>eingeatmet oder gegessen</b>, gibt es kein Papier mehr dazwischen. Dann liegt die ganze Ionisierungsspur mitten im Gewebe – deshalb ist Alphastrahlung innen die gefährlichste von allen.' },
  { id: 'b', name: 'Betastrahlung', kurz: 'β', farbe: '#2563eb',
    e: 1.0, reich: 3000, was: 'ein Elektron aus dem Kern',
    stopp: 'einige Millimeter Aluminium', wr: 1,
    innen: 'Betastrahlung kommt durch die Haut, verteilt ihre Wirkung aber auf einen viel längeren Weg.' },
  { id: 'g', name: 'Gammastrahlung', kurz: 'γ', farbe: '#16a34a',
    e: 0.66, reich: null, hwdLuft: 70, was: 'kein Teilchen, sondern sehr energiereiches Licht',
    stopp: 'dicke Bleiwände – und selbst die nur zum Teil', wr: 1,
    innen: 'Gammastrahlung durchdringt den ganzen Körper, ionisiert dabei aber nur sehr vereinzelt.' },
];

function _ionArt() { return _ION_ARTEN.find(a => a.id === _ion.art) || _ION_ARTEN[0]; }

function _ionInit() {
  _ion = { art: 'a', t: 0, treffer: [] };
  _ionBahn();
}

/* Die Ionisierungsorte einmal festlegen, damit das Bild nicht flimmert. */
function _ionBahn() {
  const a = _ionArt();
  // so viele Treffer zeichnen, wie sich unterscheiden lassen - nicht 147.000
  const anz = a.id === 'a' ? 46 : (a.id === 'b' ? 12 : 3);
  _ion.treffer = [];
  for (let i = 0; i < anz; i++) {
    const s = a.id === 'a'
      ? Math.pow((i + 0.5) / anz, 0.62)     // gegen Ende dichter (Bragg-Verhalten)
      : (i + 0.5) / anz;
    _ion.treffer.push({ s: s, y: ((i * 37) % 19 - 9) / 9 });
  }
}

function _ionSetArt(id) {
  _ion.art = id; _ion.t = 0;
  for (const a of _ION_ARTEN) {
    const b = document.getElementById('ionB' + a.id);
    if (b) b.className = 'sim-btn' + (a.id === id ? ' primary' : '');
  }
  _ionBahn(); _ionStatus();
}

function _ionUpdate(dt) { if (_ion) { _ion.t += dt; if (_ion.t > 4) _ion.t = 0; } }

function _ionStatus() {
  const el = document.getElementById('ionStatus');
  if (!el || !_ion) return;
  const a = _ionArt();
  const eV = a.e * 1e6;
  const paare = eV / _ION_W;

  let t = `<b>${a.name} (${a.kurz})</b> – ${a.was}.<br><br>`;
  t += `Energie: <b>${_fpmNum(a.e, 2)} MeV</b>, das sind ${Math.round(eV).toLocaleString('de-DE')} eV.<br>`;
  t += `In Luft kostet es im Mittel <b>34 eV</b>, einem Atom ein Elektron zu entreißen.<br>`;
  t += `Also reicht die Energie für ${Math.round(eV).toLocaleString('de-DE')} eV / 34 eV = <b>${Math.round(paare).toLocaleString('de-DE')} Ionenpaare</b>.<br><br>`;

  const alpha = _ION_ARTEN[0];
  const jeMmA = (alpha.e * 1e6 / _ION_W) / alpha.reich;

  if (a.reich === null) {
    // Gammastrahlung hat KEINE Reichweite - sie wird geschwaecht, nicht gestoppt.
    // Eine Ionisierungsdichte "je Millimeter" waere hier eine erfundene Zahl.
    t += `Anders als bei α und β lässt sich hier <b>keine Reichweite</b> angeben. Gammastrahlung wird nicht nach einer bestimmten Strecke aufgehalten, sondern nur immer weiter <b>abgeschwächt</b> – ein Teil kommt durch jede Wand.<br>`;
    t += `In Luft ist erst nach rund <b>${a.hwdLuft} Metern</b> die Hälfte weg, in Blei schon nach 6,5 Millimetern.<br><br>`;
    t += `Ein einzelnes Gammateilchen fliegt meist <b>lange Strecken, ohne irgendetwas zu tun</b>, und gibt seine Energie dann auf einen Schlag ab. Über den Weg gerechnet ionisiert es damit <b>tausendfach dünner</b> als Alphastrahlung.<br><br>`;
  } else {
    const jeMm = paare / a.reich;
    const reichTxt = a.reich >= 1000 ? _fpmNum(a.reich / 1000, 1) + ' m' : _fpmNum(a.reich / 10, 1) + ' cm';
    t += `Diese verteilt sie auf ihre Reichweite in Luft: <b>${reichTxt}</b>.<br>`;
    t += `Das ergibt <b>${jeMm >= 100 ? Math.round(jeMm).toLocaleString('de-DE') : _fpmNum(jeMm, 1)} Ionenpaare je Millimeter</b>.<br><br>`;
    if (a.id === 'a') {
      t += `Das ist eine <b>sehr dichte</b> Spur: Auf einem einzigen Millimeter werden über viertausend Atome zerlegt. Genau deshalb ist Alphastrahlung nach ein paar Zentimetern Luft am Ende – sie gibt ihre Energie sofort ab.<br><br>`;
    } else {
      t += `Verglichen mit Alphastrahlung ist das <b>${Math.round(jeMmA / jeMm).toLocaleString('de-DE')}-mal dünner</b>. Die Strahlung kommt deshalb viel weiter – richtet auf jedem einzelnen Millimeter aber viel weniger an.<br><br>`;
    }
  }
  t += `Aufgehalten wird sie durch: <b>${a.stopp}</b>.<br><br>`;
  t += `Im Strahlenschutz rechnet man ${a.kurz} mit dem Wichtungsfaktor <b>${a.wr}</b>. `;
  t += a.wr === 20 ? `Dieselbe Energie richtet als Alphastrahlung <b>zwanzigmal</b> so viel Schaden an wie als Beta- oder Gammastrahlung – weil sie so dicht ionisiert.<br><br>`
                   : `<br><br>`;
  t += `<i>${a.innen}</i>`;
  el.innerHTML = t;
}

function _ionDraw(ctx, cv) {
  if (!_ion) return;
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, cv.width, cv.height);
  const a = _ionArt();
  const x0 = 40, x1 = 412, y = 158;

  // Atome als Hintergrundraster
  ctx.fillStyle = '#dde5ee';
  for (let i = 0; i < 15; i++) for (let j = 0; j < 5; j++) {
    ctx.beginPath(); ctx.arc(x0 + 6 + i * 26, y - 52 + j * 26, 7, 0, Math.PI * 2); ctx.fill();
  }

  // Weg der Strahlung
  ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 1;
  ctx.setLineDash([3, 4]);
  ctx.beginPath(); ctx.moveTo(x0, y); ctx.lineTo(x1, y); ctx.stroke();
  ctx.setLineDash([]);

  const fort = Math.min(1, _ion.t / 2.6);
  const spitze = x0 + fort * (x1 - x0);

  // Ionisierungen, die schon passiert sind
  for (const tr of _ion.treffer) {
    const tx = x0 + tr.s * (x1 - x0);
    if (tx > spitze) continue;
    const ty = y + tr.y * 22;
    ctx.strokeStyle = a.farbe; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(tx, y); ctx.lineTo(tx, ty); ctx.stroke();
    ctx.fillStyle = a.farbe;
    ctx.beginPath(); ctx.arc(tx, ty, 3.2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#f59e0b';
    ctx.beginPath(); ctx.arc(tx, y, 2.6, 0, Math.PI * 2); ctx.fill();
  }

  // das Teilchen selbst
  if (fort < 1) {
    ctx.fillStyle = a.farbe;
    ctx.beginPath(); ctx.arc(spitze, y, a.id === 'a' ? 9 : (a.id === 'b' ? 6 : 5), 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#fff'; ctx.font = 'bold 10px system-ui';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(a.kurz, spitze, y);
  } else {
    ctx.fillStyle = '#94a3b8'; ctx.font = '11px system-ui';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(a.id === 'a' ? 'hier ist die Alphastrahlung zu Ende'
               : (a.id === 'b' ? 'die Betastrahlung fliegt weiter'
                               : 'die Gammastrahlung fliegt weiter'), (x0 + x1) / 2, y + 50);
  }

  // Massstab
  ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.moveTo(x0, 244); ctx.lineTo(x1, 244);
  ctx.moveTo(x0, 239); ctx.lineTo(x0, 249); ctx.moveTo(x1, 239); ctx.lineTo(x1, 249); ctx.stroke();
  ctx.fillStyle = '#475569'; ctx.font = '11px system-ui';
  ctx.textAlign = 'center'; ctx.textBaseline = 'top';
  ctx.fillText(a.reich === null
    ? 'keine Reichweite – nach rund ' + a.hwdLuft + ' m Luft ist erst die Hälfte weg'
    : 'Reichweite: ' + (a.reich >= 1000 ? _fpmNum(a.reich / 1000, 1) + ' m Luft'
                                        : _fpmNum(a.reich / 10, 1) + ' cm Luft'), (x0 + x1) / 2, 250);

  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 13px system-ui';
  ctx.fillText(a.name + '   ' + _fpmNum(a.e, 2) + ' MeV', 14, 24);
  ctx.font = 'bold 12px system-ui'; ctx.fillStyle = a.farbe;
  if (a.reich === null) {
    ctx.fillText('ionisiert nur ganz vereinzelt', 14, 44);
  } else {
    const jeMm = (a.e * 1e6 / _ION_W) / a.reich;
    ctx.fillText((jeMm >= 100 ? Math.round(jeMm).toLocaleString('de-DE') : _fpmNum(jeMm, 1)) +
                 ' Ionenpaare je Millimeter', 14, 44);
  }
  ctx.fillStyle = '#64748b'; ctx.font = '10px system-ui';
  ctx.fillText('● Atom   ● herausgeschlagenes Elektron   ● zurückbleibendes Ion', 14, 300);
  ctx.fillText('(gezeichnet sind nur einige der Ionisierungen – in Wirklichkeit sind es viel mehr)', 14, 315);
}

function _ionArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('ionisation')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('ionisation')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Was genau macht radioaktive Strahlung mit dem Stoff, durch den sie hindurchgeht – und warum ist das gefährlich?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, dass die Strahlung im Körper … , weil …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Wähle Alphastrahlung und beobachte die Spur bis zum Ende.</li>
          <li>Wechsle zu Beta und Gamma. Achte auf Reichweite <b>und</b> auf die Dichte der Spur.</li>
          <li>Notiere jedes Mal Energie, Reichweite und Ionenpaare je Millimeter.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Strahlungsart</td><td>Alpha</td><td>Beta</td><td>Gamma</td></tr>
          <tr><td>Energie in MeV</td><td>${inp('a1','')}</td><td>${inp('a2','')}</td><td>${inp('a3','')}</td></tr>
          <tr><td>Reichweite in Luft</td><td>${inp('b1','')}</td><td>${inp('b2','')}</td><td>keine</td></tr>
          <tr><td>Ionenpaare je mm</td><td>${inp('c1','')}</td><td>${inp('c2','')}</td><td>sehr wenige</td></tr>
          <tr><td>Wichtungsfaktor</td><td>${inp('d1','')}</td><td>${inp('d2','')}</td><td>${inp('d3','')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Auswertung</div>
        ${ta('a6', 'Alphastrahlung kommt am wenigsten weit, ionisiert aber am … . Deshalb ist sie von außen … , eingeatmet dagegen … . Gammastrahlung ist genau umgekehrt, weil …', 4)}</div>

      <div class="ab-sec"><div class="ab-h">6 · Merksatz</div>
        <div class="ab-t">Radioaktive Strahlung heißt <b>ionisierend</b>, weil sie aus Atomen ${inp('m1', 'was?')} herausschlägt. Gefährlich ist nicht die Reichweite, sondern wie ${inp('m2', 'wie?')} sie das tut.</div></div>`;
  return _abWrap('ionisation', 'Ionisation – warum diese Strahlung wirkt', body);
}

function _ionHTML() {
  const knopf = a => `<button class="sim-btn${_ion.art === a.id ? ' primary' : ''}" id="ionB${a.id}" onclick="_ionSetArt('${a.id}')">${a.kurz} ${a.name.replace('strahlung', '')}</button>`;
  return `<div class="sim-box sim-box-wide fpm-sim ion-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">⚡ Was macht diese Strahlung so besonders?</h3>
    <div class="fpm-note" style="margin-top:2px">Sie <b>ionisiert</b>: Auf ihrem Weg schlägt sie Elektronen aus Atomen heraus. Wo das in einer Zelle passiert, zerreißen Moleküle. Entscheidend ist nicht, wie weit die Strahlung kommt – sondern wie <b>dicht</b> sie unterwegs zuschlägt.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="ionAnim" width="440" height="330" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          ${_ION_ARTEN.map(knopf).join('')}
        </div>
      </div>
      <div>
        <div class="fpm-label">Wie viel wird zerlegt?</div>
        <div class="lmp-status" id="ionStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Ein <b>Ionenpaar</b> ist beides zusammen: das herausgeschlagene Elektron und das Atom, das ohne dieses Elektron zurückbleibt. Genau darauf beruhen auch alle Messgeräte – ein Geigerzähler zählt nichts anderes als solche Ionenpaare.</div>
        <div class="fpm-note" style="margin-top:8px"><b>Modellgrenze:</b> Gezeichnet sind nur einige Dutzend Ionisierungen; in Wirklichkeit sind es bei Alphastrahlung <b>rund 147.000</b> auf 3,5 cm. Außerdem ionisiert ein Alphateilchen nicht gleichmäßig – kurz vor dem Stillstand wird die Spur am dichtesten. Und die 34 eV gelten für <b>Luft</b>; in Gewebe ist der Wert etwas anders.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      α: kurz, aber sehr dicht · β: weiter, dünner · γ: sehr weit, sehr dünn
    </p>
    ${_ionArbeitsblattHTML()}
  </div>`;
}

// ═══════════════════════════════════════════════════════
// 10.3.20  KERNFUSION - WOHER DIE SONNE IHRE ENERGIE NIMMT
// Realschule NRW - Klasse 10 - Inhaltsfeld "Kernenergie und Radioaktivitaet"
// Die Sonne verbrennt nichts. Sie baut aus vier Wasserstoffkernen einen
// Heliumkern - und der wiegt WENIGER als die vier zusammen. Dieselbe Bilanz
// wie bei der Spaltung, nur andersherum. Der Temperaturregler ist der Kern der
// Seite: Unter etwa 10 Millionen Grad prallen die Kerne voneinander ab, weil
// beide positiv geladen sind. Erst darueber kommen sie nah genug zusammen.
// ═══════════════════════════════════════════════════════
let _fus = null;
const _FUS_H = 1.00782503, _FUS_HE = 4.00260325;   // Atommassen in u
const _FUS_DM = 4 * _FUS_H - _FUS_HE;
const _FUS_MEV = _FUS_DM * 931.5;
const _FUS_SONNE = 3.846e26;                        // Leuchtkraft in Watt
const _FUS_ZUENDET = 10;                            // Millionen Kelvin

function _fusInit() {
  _fus = { temp: 15, t: 0, teilchen: [], zaehler: 0, blitz: 0 };
  for (let i = 0; i < 22; i++) _fus.teilchen.push({
    x: 40 + ((i * 97) % 340), y: 60 + ((i * 61) % 150),
    vx: ((i % 5) - 2) * 22, vy: ((i % 7) - 3) * 16, he: false, alter: 0,
  });
}

function _fusSetTemp(v) {
  _fus.temp = Math.max(1, Math.min(30, Math.round(+v)));
  const e = document.getElementById('fusWertT');
  if (e) e.textContent = _fus.temp;
  _fusStatus();
}
function _fusReset() {
  _fus.zaehler = 0;
  for (const p of _fus.teilchen) { p.he = false; p.alter = 0; }
  _fusStatus();
}

function _fusUpdate(dt) {
  if (!_fus) return;
  _fus.t += dt;
  if (_fus.blitz > 0) _fus.blitz = Math.max(0, _fus.blitz - dt * 2);
  // Tempo waechst mit der Temperatur - das ist der ganze Punkt
  const tempo = 0.35 + _fus.temp / 12;
  for (const p of _fus.teilchen) {
    p.x += p.vx * dt * tempo; p.y += p.vy * dt * tempo;
    if (p.x < 26 || p.x > 396) { p.vx *= -1; p.x = Math.max(26, Math.min(396, p.x)); }
    if (p.y < 46 || p.y > 226) { p.vy *= -1; p.y = Math.max(46, Math.min(226, p.y)); }
    if (p.he) { p.alter += dt; if (p.alter > 2.4) { p.he = false; p.alter = 0; } }
  }
  // Verschmelzen nur oberhalb der Zuendtemperatur
  if (_fus.temp >= _FUS_ZUENDET && Math.random() < (_fus.temp - _FUS_ZUENDET) * 0.09 * dt * 12) {
    const frei = _fus.teilchen.filter(p => !p.he);
    if (frei.length > 4) {
      const p = frei[Math.floor(Math.random() * frei.length)];
      p.he = true; p.alter = 0;
      _fus.zaehler++; _fus.blitz = 1;
      _fusStatus();
    }
  }
}

function _fusStatus() {
  const el = document.getElementById('fusStatus');
  if (!el || !_fus) return;
  const T = _fus.temp;
  let t = `Temperatur im Kern: <b>${T} Millionen °C</b><br><br>`;

  if (T < _FUS_ZUENDET) {
    t += `<b style="color:#dc2626">Es passiert nichts.</b> Alle Kerne sind <b>positiv</b> geladen und stoßen sich ab. Bei dieser Temperatur sind sie zu langsam – sie prallen voneinander ab, bevor sie nah genug zusammenkommen.<br><br>`;
    t += `Erst ab etwa <b>10 Millionen Grad</b> sind die Kerne so schnell, dass sie die Abstoßung überwinden. Im Inneren der Sonne herrschen <b>15 Millionen Grad</b>.<br><br>`;
  } else {
    t += `<b style="color:#16a34a">Es zündet.</b> Die Kerne sind schnell genug, um trotz ihrer Abstoßung zusammenzukommen. Bisher entstanden hier <b>${_fus.zaehler}</b> Heliumkerne.<br><br>`;
  }

  t += `<b>4 ¹₁H → ⁴₂He</b><br><br>`;
  // sechs Nachkommastellen - damit geht 4 · 1,007825 = 4,031300 wirklich auf
  t += `Vier Wasserstoffkerne wiegen 4 · ${_fpmNum(_FUS_H, 6)} u = <b>${_fpmNum(4 * _FUS_H, 6)} u</b>.<br>`;
  t += `Ein Heliumkern wiegt nur <b>${_fpmNum(_FUS_HE, 6)} u</b>.<br>`;
  t += `Es fehlen ${_fpmNum(4 * _FUS_H, 6)} u − ${_fpmNum(_FUS_HE, 6)} u = <b>${_fpmNum(_FUS_DM, 6)} u</b>.<br>`;
  t += `Daraus wird Energie: ${_fpmNum(_FUS_DM, 6)} u · 931,5 MeV/u = <b>${_fpmNum(_FUS_MEV, 2)} MeV</b>.<br><br>`;

  t += `<b>Auf einen Kernbaustein umgerechnet:</b><br>`;
  t += `Fusion: ${_fpmNum(_FUS_MEV, 2)} MeV / 4 = <b>${_fpmNum(_FUS_MEV / 4, 2)} MeV</b><br>`;
  t += `Spaltung: 200 MeV / 236 = <b>${_fpmNum(200 / 236, 2)} MeV</b><br>`;
  t += `Die Fusion liefert also je Baustein rund das <b>${_fpmNum((_FUS_MEV / 4) / (200 / 236), 1)}-fache</b> der Kernspaltung.<br><br>`;

  const je = _FUS_MEV * 1.602e-13;
  const n = _FUS_SONNE / je;
  t += `Die Sonne strahlt ${_fpmNum(_FUS_SONNE / 1e26, 2)} · 10²⁶ Watt ab. Dafür muss sie in <b>jeder Sekunde</b> rund <b>${_fpmNum(n / 1e37, 1)} · 10³⁷</b> Heliumkerne bauen – das sind etwa <b>${Math.round(n * 4 * 1.6726e-27 / 1e9)} Millionen Tonnen</b> Wasserstoff je Sekunde. Und sie tut das seit 4,6 Milliarden Jahren.`;
  el.innerHTML = t;
}

function _fusDraw(ctx, cv) {
  if (!_fus) return;
  const heiss = _fus.temp >= _FUS_ZUENDET;
  ctx.fillStyle = heiss ? '#1a1206' : '#0b1220';
  ctx.fillRect(0, 0, cv.width, cv.height);

  // Kessel
  ctx.strokeStyle = heiss ? '#78350f' : '#1e293b'; ctx.lineWidth = 2;
  ctx.strokeRect(20, 40, 382, 192);

  for (const p of _fus.teilchen) {
    if (p.he) {
      ctx.fillStyle = '#fbbf24';
      ctx.beginPath(); ctx.arc(p.x, p.y, 12, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#78350f'; ctx.font = 'bold 10px system-ui';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText('He', p.x, p.y);
      // Energieblitz
      ctx.strokeStyle = 'rgba(251,191,36,' + Math.max(0, 1 - p.alter) + ')';
      ctx.lineWidth = 1.6;
      for (let i = 0; i < 6; i++) {
        const w = i * Math.PI / 3 + p.alter * 2;
        ctx.beginPath();
        ctx.moveTo(p.x + 15 * Math.cos(w), p.y + 15 * Math.sin(w));
        ctx.lineTo(p.x + (20 + p.alter * 18) * Math.cos(w), p.y + (20 + p.alter * 18) * Math.sin(w));
        ctx.stroke();
      }
    } else {
      ctx.fillStyle = heiss ? '#f87171' : '#64748b';
      ctx.beginPath(); ctx.arc(p.x, p.y, 6.5, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#fff'; ctx.font = 'bold 8px system-ui';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText('+', p.x, p.y);
    }
  }

  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#e2e8f0'; ctx.font = 'bold 13px system-ui';
  ctx.fillText(_fus.temp + ' Millionen °C', 20, 28);
  ctx.font = 'bold 12px system-ui';
  ctx.fillStyle = heiss ? '#fbbf24' : '#94a3b8';
  ctx.fillText(heiss ? 'Kerne verschmelzen · bisher ' + _fus.zaehler + ' Heliumkerne'
                     : 'zu kalt – die Kerne prallen ab', 20, 254);

  // Temperaturbalken
  const bx = 20, by = 276, bw = 382, bh = 14;
  ctx.fillStyle = '#1e293b'; ctx.fillRect(bx, by, bw, bh);
  const grd = ctx.createLinearGradient(bx, 0, bx + bw, 0);
  grd.addColorStop(0, '#334155'); grd.addColorStop(1, '#f59e0b');
  ctx.fillStyle = grd; ctx.fillRect(bx, by, (_fus.temp / 30) * bw, bh);
  const zx = bx + (_FUS_ZUENDET / 30) * bw;
  ctx.strokeStyle = '#f8fafc'; ctx.lineWidth = 1.6;
  ctx.beginPath(); ctx.moveTo(zx, by - 5); ctx.lineTo(zx, by + bh + 5); ctx.stroke();
  ctx.fillStyle = '#cbd5e1'; ctx.font = '10px system-ui';
  ctx.textAlign = 'center'; ctx.textBaseline = 'top';
  ctx.fillText('ab hier zündet es (10 Mio. °C)', zx, by + bh + 7);
  ctx.textAlign = 'right';
  ctx.fillText('Sonnenkern: 15 Mio. °C', bx + bw, by - 16);
}

function _fusArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('kernfusion')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('kernfusion')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Die Sonne brennt seit 4,6 Milliarden Jahren. Kein Feuer hält so lange durch – woher kommt ihre Energie wirklich?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, dass die Sonne ihre Energie aus … gewinnt, weil …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Stelle 5 Millionen Grad ein und beobachte eine halbe Minute lang.</li>
          <li>Erhöhe schrittweise. Ab welcher Temperatur entsteht der erste Heliumkern?</li>
          <li>Stelle 15 Millionen Grad ein – so heiß ist es im Kern der Sonne.</li>
          <li>Lies die Massenbilanz und die Energie je Kernbaustein ab.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Temperatur in Mio. °C</td><td>5</td><td>10</td><td>15</td><td>25</td></tr>
          <tr><td>Heliumkerne in 30 s</td><td>${inp('a1','')}</td><td>${inp('a2','')}</td><td>${inp('a3','')}</td><td>${inp('a4','')}</td></tr>
          <tr><td>Masse 4 H in u</td><td colspan="2">${inp('b1','')}</td><td colspan="2">Masse He-4: ${inp('b2','')}</td></tr>
          <tr><td>fehlende Masse in u</td><td colspan="2">${inp('c1','')}</td><td colspan="2">Energie: ${inp('c2','')} MeV</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Auswertung</div>
        ${ta('a6', 'Unterhalb von … Millionen Grad passiert nichts, weil die Kerne … . Vier Wasserstoffkerne wiegen zusammen … als ein Heliumkern; die fehlende Masse wird zu … . Je Kernbaustein liefert die Fusion das …-fache der Spaltung.', 5)}</div>

      <div class="ab-sec"><div class="ab-h">6 · Merksatz</div>
        <div class="ab-t">Bei der <b>Fusion</b> werden leichte Kerne ${inp('m1', 'was gemacht?')}. Damit das gelingt, braucht man ${inp('m2', 'was?')}, weil sich die Kerne gegenseitig abstoßen.</div></div>`;
  return _abWrap('kernfusion', 'Kernfusion – das Feuer der Sonne', body);
}

function _fusHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim fus-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">☀️ Woher nimmt die Sonne ihre Energie?</h3>
    <div class="fpm-note" style="margin-top:2px">In der Sonne wird nichts verbrannt. Dort werden <b>Kerne zusammengebaut</b> – aber nur, wenn es heiß genug ist. Dreh die Temperatur langsam hoch und pass auf, ab wann es losgeht.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="fusAnim" width="440" height="330" class="phys-anim-cv"></canvas>
        <div style="margin-top:6px">
          <label class="fpm-label" for="fusT">Temperatur: <b id="fusWertT">15</b> Millionen °C</label>
          <input type="range" id="fusT" min="1" max="30" value="15" step="1" oninput="_fusSetTemp(this.value)" style="width:100%">
        </div>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn" onclick="_fusReset()">↺ Zähler zurücksetzen</button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Was passiert – und was rechnet sich daraus?</div>
        <div class="lmp-status" id="fusStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Warum ist es so schwer, das auf der Erde nachzubauen? In der Sonne hilft die <b>gewaltige Schwerkraft</b> – sie presst das Gas auf 200 Milliarden bar zusammen. Auf der Erde gibt es diesen Druck nicht; deshalb müssen Fusionsanlagen auf <b>über 100 Millionen Grad</b> heizen, zehnmal heißer als der Sonnenkern.</div>
        <div class="fpm-note" style="margin-top:8px"><b>Modellgrenze:</b> Hier springen vier Kerne auf einmal zu Helium zusammen. In Wirklichkeit läuft das in <b>mehreren Schritten</b> ab, und dabei entstehen außerdem Positronen und Neutrinos, die einen kleinen Teil der Energie mitnehmen. Außerdem: Bei 15 Millionen Grad müsste ein einzelnes Proton im Mittel <b>Milliarden von Jahren</b> warten, bis es an der Reihe ist – nur weil die Sonne so unvorstellbar viele Protonen enthält, leuchtet sie trotzdem gleichmäßig.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      4 Wasserstoffkerne → 1 Heliumkern · die fehlende Masse wird zu Energie · je Baustein rund achtmal mehr als bei der Spaltung
    </p>
    ${_fusArbeitsblattHTML()}
  </div>`;
}

// ═══════════════════════════════════════════════════════
// 10.3.21  INDUKTION - SPANNUNG OHNE BATTERIE
// Realschule NRW - Klasse 10 - Inhaltsfeld "Elektrische Energieversorgung"
// Der entscheidende Satz der ganzen Klasse 10 steht hier: Es zaehlt nicht, DASS
// ein Magnet da ist, sondern dass sich etwas AENDERT. Deshalb faehrt der Magnet
// hier nicht nur hin und her - er bleibt zwischendurch auch LIEGEN, mitten in
// der Spule, und das Messgeraet faellt auf null zurueck. Ohne diese Ruhephase
// laesst sich ge1 nicht beantworten.
// Gerechnet wird U = N · B · A · v / d mit A = 4 cm² und d = 2 cm (Pollaenge).
// ═══════════════════════════════════════════════════════
let _ind = null;
const _IND_A = 4e-4;      // Querschnitt der Spule in m²
const _IND_D = 0.02;      // Strecke, auf der sich das Feld aufbaut, in m
const _IND_MAGNETE = [
  { id: 'schwach', name: 'schwach', b: 0.02 },
  { id: 'mittel',  name: 'mittel',  b: 0.05 },
  { id: 'stark',   name: 'stark',   b: 0.10 },
];

function _indMag() { return _IND_MAGNETE.find(m => m.id === _ind.mag) || _IND_MAGNETE[1]; }

function _indInit() {
  _ind = { v: 50, n: 600, mag: 'mittel', t: 0, phase: 0, s: 0 };
}

/* Betrag der induzierten Spannung, solange der Magnet sich bewegt. */
function _indU() {
  return _ind.n * _indMag().b * _IND_A * (_ind.v / 100) / _IND_D;
}

/* Was das Messgeraet gerade anzeigt - mit Vorzeichen, und null im Stillstand. */
function _indJetzt() {
  return _ind.phase === 0 ? _indU() : (_ind.phase === 2 ? -_indU() : 0);
}

function _indSet(was, v) {
  if (was === 'v') { _ind.v = Math.max(5, Math.min(100, Math.round(+v))); const e = document.getElementById('indWertV'); if (e) e.textContent = _ind.v; }
  if (was === 'n') { _ind.n = Math.max(100, Math.min(1200, Math.round(+v))); const e = document.getElementById('indWertN'); if (e) e.textContent = _ind.n; }
  _indStatus();
}
function _indSetMag(id) {
  _ind.mag = id;
  for (const m of _IND_MAGNETE) {
    const b = document.getElementById('indM' + m.id);
    if (b) b.className = 'sim-btn' + (m.id === id ? ' primary' : '');
  }
  _indStatus();
}

function _indUpdate(dt) {
  if (!_ind) return;
  _ind.t += dt;
  const dauer = 1.0 / (_ind.v / 50);      // bei 50 cm/s dauert die Fahrt 1 Sekunde
  const alt = _ind.phase;
  _ind.s += dt;
  if (_ind.phase === 0 && _ind.s >= dauer) { _ind.phase = 1; _ind.s = 0; }
  else if (_ind.phase === 1 && _ind.s >= 1.1) { _ind.phase = 2; _ind.s = 0; }
  else if (_ind.phase === 2 && _ind.s >= dauer) { _ind.phase = 3; _ind.s = 0; }
  else if (_ind.phase === 3 && _ind.s >= 1.1) { _ind.phase = 0; _ind.s = 0; }
  if (_ind.phase !== alt) _indStatus();
}

function _indStatus() {
  const el = document.getElementById('indStatus');
  if (!el || !_ind) return;
  const m = _indMag(), U = _indU(), jetzt = _indJetzt();
  const vMs = _ind.v / 100;

  const phTxt = ['Der Magnet wird <b>hineingeschoben</b>.',
                 'Der Magnet <b>liegt still</b> – mitten in der Spule.',
                 'Der Magnet wird <b>herausgezogen</b>.',
                 'Der Magnet <b>liegt still</b> – außerhalb der Spule.'][_ind.phase];

  let t = `${phTxt}<br>`;
  t += `Messgerät: <b style="font-size:1.14em">${_fpmNum(jetzt, 3)} V</b><br><br>`;

  if (_ind.phase === 1 || _ind.phase === 3) {
    t += `<b style="color:#dc2626">Null Volt – obwohl der Magnet da ist.</b> Er liegt nur still. Ein Magnet allein erzeugt <b>keine</b> Spannung; es muss sich etwas <b>ändern</b>.<br><br>`;
  } else {
    t += `Beim Hineinschieben und beim Herausziehen zeigt das Gerät <b>entgegengesetzte Vorzeichen</b> – der Strom fließt jeweils andersherum.<br><br>`;
  }

  t += `<b>Wie groß ist die Spannung, solange er sich bewegt?</b><br>`;
  t += `U = N · B · A · v / d<br>`;
  t += `U = ${_ind.n} · ${_fpmNum(m.b, 2)} T · 0,0004 m² · ${_fpmNum(vMs, 2)} m/s / 0,02 m<br>`;
  t += `U = <b>${_fpmNum(U, 3)} V</b><br><br>`;
  t += `<b>${_ind.n}</b> Windungen &nbsp;·&nbsp; Magnet <b>${m.name}</b> (${_fpmNum(m.b, 2)} T) &nbsp;·&nbsp; Tempo <b>${_ind.v} cm/s</b><br><br>`;
  t += `Alle drei gehen <b>einfach</b> ein: doppelt so viele Windungen – doppelte Spannung. Doppeltes Tempo – doppelte Spannung. Doppelt so starker Magnet – doppelte Spannung.`;
  el.innerHTML = t;
}

function _indDraw(ctx, cv) {
  if (!_ind) return;
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, cv.width, cv.height);
  const spx = 168, spy = 128, spB = 116, spH = 68;

  // Spule
  ctx.strokeStyle = '#b45309'; ctx.lineWidth = 3;
  const win = 9;
  for (let i = 0; i < win; i++) {
    const x = spx + 6 + i * ((spB - 12) / (win - 1));
    ctx.beginPath(); ctx.ellipse(x, spy, 6, spH / 2, 0, 0, Math.PI * 2); ctx.stroke();
  }
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 11px system-ui';
  ctx.textAlign = 'center'; ctx.textBaseline = 'bottom';
  ctx.fillText(_ind.n + ' Windungen', spx + spB / 2, spy - spH / 2 - 8);

  // Magnet: Position aus Phase und Fortschritt
  const dauer = 1.0 / (_ind.v / 50);
  const p = _ind.phase === 0 ? _ind.s / dauer
          : _ind.phase === 1 ? 1
          : _ind.phase === 2 ? 1 - _ind.s / dauer : 0;
  const mx = 34 + p * 168;
  const mB = 62, mH = 26;
  ctx.fillStyle = '#dc2626'; ctx.fillRect(mx, spy - mH / 2, mB / 2, mH);
  ctx.fillStyle = '#1e40af'; ctx.fillRect(mx + mB / 2, spy - mH / 2, mB / 2, mH);
  ctx.fillStyle = '#fff'; ctx.font = 'bold 13px system-ui';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('N', mx + mB / 4, spy);
  ctx.fillText('S', mx + 3 * mB / 4, spy);

  // Bewegungspfeil
  if (_ind.phase === 0 || _ind.phase === 2) {
    const dir = _ind.phase === 0 ? 1 : -1;
    ctx.strokeStyle = '#0f172a'; ctx.lineWidth = 2;
    const ax = _ind.phase === 0 ? mx + mB + 10 : mx - 10;
    ctx.beginPath(); ctx.moveTo(ax, spy + 42); ctx.lineTo(ax + dir * 34, spy + 42); ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(ax + dir * 34, spy + 42);
    ctx.lineTo(ax + dir * 25, spy + 37); ctx.lineTo(ax + dir * 25, spy + 47);
    ctx.closePath(); ctx.fillStyle = '#0f172a'; ctx.fill();
  } else {
    ctx.fillStyle = '#dc2626'; ctx.font = 'bold 12px system-ui';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText('liegt still', mx + mB / 2, spy + 46);
  }

  // Messgeraet
  const gx = 352, gy = 128, gr = 52;
  ctx.fillStyle = '#fff'; ctx.strokeStyle = '#334155'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(gx, gy, gr, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 1;
  for (let i = -4; i <= 4; i++) {
    const w = -Math.PI / 2 + i * 0.19;
    ctx.beginPath();
    ctx.moveTo(gx + (gr - 10) * Math.cos(w), gy + (gr - 10) * Math.sin(w));
    ctx.lineTo(gx + (gr - 3) * Math.cos(w), gy + (gr - 3) * Math.sin(w));
    ctx.stroke();
  }
  const jetzt = _indJetzt();
  const voll = Math.max(_indU(), 0.001);
  const aus = Math.max(-1, Math.min(1, jetzt / voll));
  const zw = -Math.PI / 2 + aus * 0.78;
  ctx.strokeStyle = jetzt === 0 ? '#94a3b8' : '#dc2626'; ctx.lineWidth = 2.6;
  ctx.beginPath(); ctx.moveTo(gx, gy + 8);
  ctx.lineTo(gx + (gr - 12) * Math.cos(zw), gy + 8 + (gr - 12) * Math.sin(zw));
  ctx.stroke();
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 12px system-ui';
  ctx.textAlign = 'center'; ctx.textBaseline = 'top';
  ctx.fillText(_fpmNum(jetzt, 3) + ' V', gx, gy + 18);
  ctx.font = '10px system-ui'; ctx.fillStyle = '#64748b';
  ctx.fillText('Spannungsmesser', gx, gy + gr + 6);

  // Draehte
  ctx.strokeStyle = '#334155'; ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(spx + spB, spy - 20); ctx.lineTo(gx - gr - 6, spy - 20);
  ctx.moveTo(spx + spB, spy + 20); ctx.lineTo(gx - gr - 6, spy + 20);
  ctx.stroke();

  // Kopf und Fuss
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 13px system-ui';
  ctx.fillText(['Magnet wird hineingeschoben', 'Magnet liegt still – in der Spule',
                'Magnet wird herausgezogen', 'Magnet liegt still – außerhalb'][_ind.phase], 14, 24);
  ctx.font = '11px system-ui'; ctx.fillStyle = '#475569';
  ctx.fillText('keine Batterie im Aufbau – nur ein Magnet, eine Spule und ein Messgerät', 14, 44);
  ctx.font = 'bold 12px system-ui'; ctx.fillStyle = jetzt === 0 ? '#dc2626' : '#0f172a';
  ctx.fillText(jetzt === 0 ? 'Spannung: 0,000 V – der Magnet bewegt sich nicht'
                           : 'Spannung: ' + _fpmNum(jetzt, 3) + ' V', 14, 300);
  ctx.font = '11px system-ui'; ctx.fillStyle = '#475569';
  ctx.fillText('Tempo ' + _ind.v + ' cm/s   ·   ' + _ind.n + ' Windungen   ·   Magnet ' +
               _indMag().name + ' (' + _fpmNum(_indMag().b, 2) + ' T)', 14, 316);
}

function _indArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('induktion-rs')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('induktion-rs')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Kann ein Magnet Spannung erzeugen, ohne dass eine Batterie im Spiel ist – und wovon hängt ab, wie viel?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, dass das Messgerät ausschlägt, wenn … , weil …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Beobachte einen ganzen Durchgang. Achte besonders auf die beiden Ruhephasen.</li>
          <li>Verdopple <b>nur</b> das Tempo von 25 auf 50 cm/s.</li>
          <li>Verdopple <b>nur</b> die Windungszahl von 300 auf 600.</li>
          <li>Wechsle <b>nur</b> von „mittel“ auf „stark“.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Magnet liegt still</td><td colspan="3">Spannung: ${inp('a0','')}</td></tr>
          <tr><td>Änderung</td><td>Tempo verdoppelt</td><td>Windungen verdoppelt</td><td>Magnet stärker</td></tr>
          <tr><td>vorher in V</td><td>${inp('a1','')}</td><td>${inp('a2','')}</td><td>${inp('a3','')}</td></tr>
          <tr><td>nachher in V</td><td>${inp('b1','')}</td><td>${inp('b2','')}</td><td>${inp('b3','')}</td></tr>
          <tr><td>wie viel mal?</td><td>${inp('c1','')}</td><td>${inp('c2','')}</td><td>${inp('c3','')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Auswertung</div>
        ${ta('a6', 'Solange der Magnet still liegt, zeigt das Gerät … – obwohl der Magnet da ist. Das heißt: Nicht der Magnet erzeugt die Spannung, sondern … . Verdoppelt man Tempo, Windungszahl oder Magnetstärke, so … .', 4)}</div>

      <div class="ab-sec"><div class="ab-h">6 · Merksatz</div>
        <div class="ab-t">Eine Spannung entsteht nur, wenn sich das Magnetfeld in der Spule ${inp('m1', 'was tut?')}. Beim Hineinschieben und Herausziehen ist das Vorzeichen ${inp('m2', 'wie?')}.</div></div>`;
  return _abWrap('induktion-rs', 'Induktion – Spannung ohne Batterie', body);
}

function _indHTML() {
  const knopf = m => `<button class="sim-btn${_ind.mag === m.id ? ' primary' : ''}" id="indM${m.id}" onclick="_indSetMag('${m.id}')">${m.name}</button>`;
  return `<div class="sim-box sim-box-wide fpm-sim ind-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🧲 Kann ein bewegter Magnet Strom erzeugen – ohne Batterie?</h3>
    <div class="fpm-note" style="margin-top:2px">Im Aufbau steckt <b>keine</b> Stromquelle: nur ein Magnet, eine Spule, ein Messgerät. Der Magnet fährt hinein, <b>bleibt liegen</b>, fährt heraus, bleibt liegen. Sieh genau hin, wann das Gerät ausschlägt – und wann nicht.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="indAnim" width="440" height="330" class="phys-anim-cv"></canvas>
        <div style="margin-top:6px">
          <label class="fpm-label" for="indV">Tempo des Magneten: <b id="indWertV">50</b> cm/s</label>
          <input type="range" id="indV" min="5" max="100" value="50" step="5" oninput="_indSet('v', this.value)" style="width:100%">
          <label class="fpm-label" for="indN">Windungen der Spule: <b id="indWertN">600</b></label>
          <input type="range" id="indN" min="100" max="1200" value="600" step="100" oninput="_indSet('n', this.value)" style="width:100%">
        </div>
        <div class="sim-btn-row" style="margin-top:4px">
          <span class="fpm-label" style="align-self:center">Magnet:</span>
          ${_IND_MAGNETE.map(knopf).join('')}
        </div>
      </div>
      <div>
        <div class="fpm-label">Was zeigt das Messgerät?</div>
        <div class="lmp-status" id="indStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Woher kommt die Energie? Nicht aus dem Magneten – der wird nicht schwächer. Sie kommt aus der <b>Hand</b>, die schiebt. Wer den Magneten schneller bewegt, muss auch <b>kräftiger drücken</b>. Genau davon lebt jedes Kraftwerk: Eine Turbine dreht Magnete an Spulen vorbei, und die Energie dafür liefert Dampf, Wasser oder Wind.</div>
        <div class="fpm-note" style="margin-top:8px"><b>Modellgrenze:</b> Hier ist die Spannung während der ganzen Fahrt gleich groß. In Wirklichkeit steigt sie an, wenn der Pol in die Spule eintritt, und fällt wieder ab – der Zeiger würde <b>zucken</b>, nicht stehen. Auch die Formel U = N · B · A · v / d ist eine Vereinfachung: Sie tut so, als baue sich das Feld auf genau 2 cm gleichmäßig auf.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Nur die <b>Änderung</b> erzeugt Spannung · mehr Windungen, mehr Tempo, stärkerer Magnet – jedes für sich verdoppelt
    </p>
    ${_indArbeitsblattHTML()}
  </div>`;
}

// ═══════════════════════════════════════════════════════
// 10.3.22  OERSTED - STROM BEWEGT EINE KOMPASSNADEL
// Realschule NRW - Klasse 10 - Inhaltsfeld "Strom und Magnetismus"
// Der Versuch, mit dem 1820 alles anfing. Entscheidend ist, dass die Nadel
// nicht "irgendwie zuckt", sondern sich zwischen ZWEI Feldern einstellt: dem
// Erdfeld nach Norden und dem Feld des Drahtes quer dazu. Deshalb rechnet die
// Simulation den Ausschlag wirklich aus - tan(Ausschlag) = B_Draht / B_Erde -
// und deshalb steht bei 1 cm und 1 A genau 45 Grad da: Da sind beide Felder
// gleich stark.
// Zahlen: B = 20 µT · I / r  (I in Ampere, r in Zentimetern);
// waagerechter Anteil des Erdfelds in Deutschland rund 20 µT.
// ═══════════════════════════════════════════════════════
let _oer = null;
const _OER_ERDE = 20;      // µT, waagerechter Anteil des Erdmagnetfelds

function _oerInit() { _oer = { i: 3, r: 2, an: true, umgepolt: false, unten: false, t: 0, winkel: 0 }; }

/* Auf eine Nachkommastelle gerundet - genau so steht der Wert auch auf dem
   Bildschirm, und genau mit diesem Wert wird weitergerechnet. */
function _oerBDraht() { return _oer.an ? +(20 * _oer.i / _oer.r).toFixed(1) : 0; }

/* Ausschlag aus dem Verhaeltnis der beiden Felder - nicht geraten. */
function _oerAusschlag() {
  const a = Math.atan(_oerBDraht() / _OER_ERDE) * 180 / Math.PI;
  const vz = (_oer.umgepolt ? -1 : 1) * (_oer.unten ? -1 : 1);
  return a * vz;
}

function _oerSet(was, v) {
  if (was === 'i') { _oer.i = Math.max(0, Math.min(5, +(+v).toFixed(1))); const e = document.getElementById('oerWertI'); if (e) e.textContent = _fpmNum(_oer.i, 1); }
  if (was === 'r') { _oer.r = Math.max(1, Math.min(5, +(+v).toFixed(1))); const e = document.getElementById('oerWertR'); if (e) e.textContent = _fpmNum(_oer.r, 1); }
  _oerStatus();
}
function _oerSchalter() {
  _oer.an = !_oer.an;
  const b = document.getElementById('oerAn');
  if (b) { b.textContent = _oer.an ? '⏻ Strom ausschalten' : '⏻ Strom einschalten'; b.className = 'sim-btn' + (_oer.an ? ' primary' : ''); }
  _oerStatus();
}
function _oerUmpolen() { _oer.umgepolt = !_oer.umgepolt; _oerStatus(); }
function _oerSeite() {
  _oer.unten = !_oer.unten;
  const b = document.getElementById('oerSeite');
  if (b) b.textContent = _oer.unten ? '↑ Nadel über den Draht' : '↓ Nadel unter den Draht';
  _oerStatus();
}

function _oerUpdate(dt) {
  if (!_oer) return;
  _oer.t += dt;
  // Nadel schwingt sich ein, statt zu springen
  const ziel = _oerAusschlag();
  _oer.winkel += (ziel - _oer.winkel) * Math.min(1, dt * 7);
}

function _oerStatus() {
  const el = document.getElementById('oerStatus');
  if (!el || !_oer) return;
  const B = _oerBDraht(), a = _oerAusschlag();

  let t = '';
  if (!_oer.an) {
    t += `<b>Strom aus.</b> Die Nadel zeigt nach <b>Norden</b> – wie jeder Kompass. Nur das Erdfeld wirkt auf sie, und das sind rund <b>${_OER_ERDE} µT</b>.<br><br>`;
    t += `Der Draht liegt genau so da wie vorher. Trotzdem passiert nichts: Ein Draht <b>ohne</b> Strom ist kein Magnet.<br><br>`;
  } else {
    t += `<b>Strom an: ${_fpmNum(_oer.i, 1)} A</b>, Abstand ${_fpmNum(_oer.r, 1)} cm.<br><br>`;
    t += `Feld des Drahtes: B = 20 µT · ${_fpmNum(_oer.i, 1)} / ${_fpmNum(_oer.r, 1)} = <b>${_fpmNum(B, 1)} µT</b><br>`;
    t += `Erdfeld (waagerecht): <b>${_OER_ERDE} µT</b><br><br>`;
    t += `Die Nadel stellt sich zwischen beide Felder. Wie weit sie sich dreht, sagt das Verhältnis:<br>`;
    t += `${_fpmNum(B, 1)} µT / ${_OER_ERDE} µT = <b>${_fpmNum(B / _OER_ERDE, 2)}</b> &nbsp;→&nbsp; Ausschlag <b>${_fpmNum(Math.abs(a), 1)}°</b> nach ${a >= 0 ? 'Osten' : 'Westen'}.<br><br>`;
    if (Math.abs(B - _OER_ERDE) < 0.6) {
      t += `<b>Hier sind beide Felder genau gleich stark.</b> Deshalb steht die Nadel exakt in der Mitte zwischen Norden und ${a >= 0 ? 'Osten' : 'Westen'}: 45°.<br><br>`;
    }
    t += `Der Strom fließt nach <b>${_oer.umgepolt ? 'Süden' : 'Norden'}</b>, die Nadel liegt <b>${_oer.unten ? 'unter' : 'über'}</b> dem Draht.<br><br>`;
  }
  t += `<b>Zwei Proben, die alles zeigen:</b> Polt man den Strom um, schlägt die Nadel zur <b>anderen Seite</b> aus. Legt man den Kompass unter statt über den Draht – <b>ebenfalls andersherum</b>. Das Feld des Drahtes läuft also <b>im Kreis um ihn herum</b>.`;
  el.innerHTML = t;
}

function _oerDraw(ctx, cv) {
  if (!_oer) return;
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, cv.width, cv.height);
  const cx = 200, cy = 152, kr = 74;

  // Draht: laeuft von unten nach oben (Nord-Sued), ueber oder unter dem Kompass
  const dx = cx;
  if (_oer.unten) {   // Draht ist dann UNTER dem Kompass -> zuerst zeichnen
    ctx.strokeStyle = '#b45309'; ctx.lineWidth = 5;
    ctx.beginPath(); ctx.moveTo(dx, 26); ctx.lineTo(dx, 278); ctx.stroke();
  }

  // Kompassdose
  ctx.fillStyle = '#fff'; ctx.strokeStyle = '#334155'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(cx, cy, kr, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  ctx.fillStyle = '#94a3b8'; ctx.font = 'bold 11px system-ui';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('N', cx, cy - kr + 12);
  ctx.fillText('S', cx, cy + kr - 12);
  ctx.fillText('W', cx - kr + 12, cy);
  ctx.fillText('O', cx + kr - 12, cy);
  ctx.strokeStyle = '#e2e8f0'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(cx, cy - kr + 22); ctx.lineTo(cx, cy + kr - 22);
  ctx.moveTo(cx - kr + 22, cy); ctx.lineTo(cx + kr - 22, cy); ctx.stroke();

  if (!_oer.unten) {  // Draht UEBER dem Kompass
    ctx.strokeStyle = '#b45309'; ctx.lineWidth = 5;
    ctx.beginPath(); ctx.moveTo(dx, 26); ctx.lineTo(dx, 278); ctx.stroke();
  }

  // Stromrichtung
  if (_oer.an && _oer.i > 0) {
    const auf = !_oer.umgepolt;
    for (let i = 0; i < 5; i++) {
      const y = 46 + ((i * 52 + (auf ? -1 : 1) * _oer.t * 60) % 220 + 220) % 220;
      ctx.fillStyle = '#f59e0b';
      ctx.beginPath();
      ctx.moveTo(dx, y + (auf ? -8 : 8));
      ctx.lineTo(dx - 6, y + (auf ? 4 : -4));
      ctx.lineTo(dx + 6, y + (auf ? 4 : -4));
      ctx.closePath(); ctx.fill();
    }
  }

  // Nadel
  const w = (_oer.winkel - 90) * Math.PI / 180;
  const nl = kr - 20;
  ctx.save(); ctx.translate(cx, cy);
  ctx.strokeStyle = '#dc2626'; ctx.lineWidth = 5; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(nl * Math.cos(w), nl * Math.sin(w)); ctx.stroke();
  ctx.strokeStyle = '#334155';
  ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-nl * Math.cos(w), -nl * Math.sin(w)); ctx.stroke();
  ctx.fillStyle = '#0f172a';
  ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
  ctx.lineCap = 'butt';

  // Kopf und Anzeige
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 13px system-ui';
  ctx.fillText(_oer.an ? 'Strom an: ' + _fpmNum(_oer.i, 1) + ' A' : 'Strom aus', 14, 24);
  ctx.font = '11px system-ui'; ctx.fillStyle = '#475569';
  ctx.fillText('Draht ' + (_oer.unten ? 'unter' : 'über') + ' der Nadel · Strom nach ' +
               (_oer.umgepolt ? 'Süden' : 'Norden') + ' · Abstand ' + _fpmNum(_oer.r, 1) + ' cm', 14, 42);

  const B = _oerBDraht(), a = _oerAusschlag();
  ctx.font = 'bold 12px system-ui'; ctx.fillStyle = _oer.an ? '#dc2626' : '#64748b';
  ctx.fillText(_oer.an ? 'Feld des Drahtes: ' + _fpmNum(B, 1) + ' µT   ·   Ausschlag ' +
                         _fpmNum(Math.abs(a), 1) + '° nach ' + (a >= 0 ? 'Osten' : 'Westen')
                       : 'Die Nadel zeigt nach Norden', 14, 302);
  ctx.font = '11px system-ui'; ctx.fillStyle = '#475569';
  ctx.fillText('Erdfeld waagerecht: ' + _OER_ERDE + ' µT', 14, 318);
}

function _oerArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('oersted')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('oersted')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Kann elektrischer Strom eine Kompassnadel bewegen – obwohl an einem Draht doch gar kein Magnet ist?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, dass die Nadel … , weil …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Strom aus: Wohin zeigt die Nadel? Notiere.</li>
          <li>Strom an mit 1 A, Abstand 1 cm. Lies den Ausschlag ab.</li>
          <li>Erhöhe auf 3 A und auf 5 A – jeweils bei 1 cm.</li>
          <li>Gehe zurück auf 3 A und vergrößere den Abstand auf 3 cm.</li>
          <li>Polnung umkehren, dann die Nadel unter den Draht legen.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Strom / Abstand</td><td>aus</td><td>1 A / 1 cm</td><td>3 A / 1 cm</td><td>3 A / 3 cm</td></tr>
          <tr><td>Feld des Drahtes in µT</td><td>${inp('a1','')}</td><td>${inp('a2','')}</td><td>${inp('a3','')}</td><td>${inp('a4','')}</td></tr>
          <tr><td>Ausschlag in Grad</td><td>${inp('b1','')}</td><td>${inp('b2','')}</td><td>${inp('b3','')}</td><td>${inp('b4','')}</td></tr>
          <tr><td>umgepolt: wohin?</td><td colspan="2">${inp('c1','')}</td><td colspan="2">Nadel unten: ${inp('c2','')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Auswertung</div>
        ${ta('a6', 'Ohne Strom zeigt die Nadel nach … . Mit Strom dreht sie sich, weil … . Je größer die Stromstärke, desto … . Je größer der Abstand, desto … . Beim Umpolen schlägt sie nach … aus – daraus folgt, dass das Feld des Drahtes …', 5)}</div>

      <div class="ab-sec"><div class="ab-h">6 · Merksatz</div>
        <div class="ab-t">Ein stromdurchflossener Draht ist von einem ${inp('m1', 'was?')} umgeben. Es verläuft ${inp('m2', 'wie?')} um den Draht herum.</div></div>`;
  return _abWrap('oersted', 'Der Versuch von Ørsted', body);
}

function _oerHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim oer-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🧭 Kann elektrischer Strom eine Kompassnadel bewegen?</h3>
    <div class="fpm-note" style="margin-top:2px">Genau diesen Versuch machte Hans Christian Ørsted im Jahr 1820 – zufällig, während einer Vorlesung. Was er sah, war der Anfang von allem: Elektrizität und Magnetismus haben miteinander zu tun.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="oerAnim" width="440" height="330" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" id="oerAn" onclick="_oerSchalter()">⏻ Strom ausschalten</button>
          <button class="sim-btn" onclick="_oerUmpolen()">⇄ umpolen</button>
          <button class="sim-btn" id="oerSeite" onclick="_oerSeite()">↓ Nadel unter den Draht</button>
        </div>
        <div style="margin-top:6px">
          <label class="fpm-label" for="oerI">Stromstärke: <b id="oerWertI">3,0</b> A</label>
          <input type="range" id="oerI" min="0" max="5" value="3" step="0.5" oninput="_oerSet('i', this.value)" style="width:100%">
          <label class="fpm-label" for="oerR">Abstand Draht – Nadel: <b id="oerWertR">2,0</b> cm</label>
          <input type="range" id="oerR" min="1" max="5" value="2" step="0.5" oninput="_oerSet('r', this.value)" style="width:100%">
        </div>
      </div>
      <div>
        <div class="fpm-label">Was macht die Nadel – und warum genau so viel?</div>
        <div class="lmp-status" id="oerStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Die Nadel dreht sich <b>nie ganz</b> quer zum Draht. Sie stellt sich zwischen die beiden Felder, die auf sie wirken: das Erdfeld nach Norden und das Feld des Drahtes quer dazu. Sind beide gleich stark, steht sie genau in der Mitte – bei <b>45°</b>.</div>
        <div class="fpm-note" style="margin-top:8px"><b>Modellgrenze:</b> Gerechnet wird mit einem <b>unendlich langen, geraden</b> Draht; ein kurzes Stück Kabel erzeugt weniger. Der Wert 20 µT für das Erdfeld gilt für Deutschland – am Äquator ist der waagerechte Anteil fast doppelt so groß, an den Polen fast null. Und in einem echten Klassenzimmer stören Eisenträger, Lautsprecher und Handys die Nadel zusätzlich.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      B = 20 µT · I / r &nbsp;·&nbsp; tan(Ausschlag) = B<sub>Draht</sub> / B<sub>Erde</sub> &nbsp;·&nbsp; das Feld läuft <b>im Kreis</b> um den Draht
    </p>
    ${_oerArbeitsblattHTML()}
  </div>`;
}

// ═══════════════════════════════════════════════════════
// 10.3.23  KRAFT AUF EINEN STROMDURCHFLOSSENEN LEITER
// Realschule NRW - Klasse 10 - Inhaltsfeld "Strom und Magnetismus"
// Das Motorprinzip. Zwei Fragen stecken darin, und beide brauchen eine eigene
// Bedienung: WIE GROSS ist die Kraft (F = B · I · L, drei Regler) und WOHIN
// zeigt sie (zwei Umpolknoepfe). Der lehrreichste Griff ist, BEIDES umzupolen -
// dann bleibt die Kraftrichtung, und man versteht, dass es aufs Zusammenspiel
// ankommt und nicht auf eine der beiden Ursachen allein.
// ═══════════════════════════════════════════════════════
let _lkr = null;
const _LKR_L = 0.10;          // wirksame Leiterlaenge in Metern
const _LKR_KLAMMER = 0.01;    // Gewichtskraft einer Bueroklammer, gerundet auf 0,01 N

function _lkrInit() { _lkr = { b: 0.20, i: 5, stromUm: false, magnetUm: false, t: 0, y: 0 }; }

/* Auf die Stellen runden, mit denen die Groessen auch dastehen. */
function _lkrF() { return +(_lkr.b * _lkr.i * _LKR_L).toFixed(3); }
function _lkrRichtung() {   // +1 nach oben, -1 nach unten
  return (_lkr.stromUm ? -1 : 1) * (_lkr.magnetUm ? -1 : 1);
}

function _lkrSet(was, v) {
  if (was === 'b') { _lkr.b = +(+v).toFixed(2); const e = document.getElementById('lkrWertB'); if (e) e.textContent = _fpmNum(_lkr.b, 2); }
  if (was === 'i') { _lkr.i = +(+v).toFixed(1); const e = document.getElementById('lkrWertI'); if (e) e.textContent = _fpmNum(_lkr.i, 1); }
  _lkrStatus();
}
function _lkrStromUm() { _lkr.stromUm = !_lkr.stromUm; _lkr.y = 0; _lkrStatus(); }
function _lkrMagnetUm() { _lkr.magnetUm = !_lkr.magnetUm; _lkr.y = 0; _lkrStatus(); }
function _lkrReset() { _lkr.stromUm = false; _lkr.magnetUm = false; _lkr.y = 0; _lkrStatus(); }

function _lkrUpdate(dt) {
  if (!_lkr) return;
  _lkr.t += dt;
  const ziel = _lkr.i === 0 ? 0 : _lkrRichtung() * Math.min(46, _lkrF() * 190);
  _lkr.y += (ziel - _lkr.y) * Math.min(1, dt * 4);
}

function _lkrStatus() {
  const el = document.getElementById('lkrStatus');
  if (!el || !_lkr) return;
  const F = _lkrF(), r = _lkrRichtung();
  const nord = _lkr.magnetUm ? 'rechts' : 'links';
  const stromRi = _lkr.stromUm ? 'nach hinten' : 'nach vorn';

  let t = '';
  if (_lkr.i === 0) {
    t += `<b style="color:#dc2626">Kein Strom – keine Kraft.</b> Der Stab hängt zwischen den Polen, und nichts passiert. Ein Magnetfeld allein schiebt einen Draht nicht.<br><br>`;
  } else {
    t += `Der Stab wird <b style="font-size:1.1em">nach ${r > 0 ? 'oben' : 'unten'}</b> gedrückt.<br><br>`;
  }
  t += `<b>Wie groß ist die Kraft?</b><br>`;
  t += `F = B · I · L<br>`;
  t += `F = ${_fpmNum(_lkr.b, 2)} T · ${_fpmNum(_lkr.i, 1)} A · ${_fpmNum(_LKR_L, 2)} m = <b>${_fpmNum(F, 3)} N</b><br>`;
  if (F > 0) {
    const kl = F / _LKR_KLAMMER;
    t += `Das sind ${_fpmNum(F, 3)} N / 0,01 N = <b>${_fpmNum(kl, kl < 10 ? 1 : 0)} Büroklammern</b> – so schwer wäre etwas, das der Stab gerade anheben könnte. (Eine Büroklammer wiegt rund 1 g, ihre Gewichtskraft ist etwa 0,01 N.)<br>`;
  }
  t += `<br><b>Wohin zeigt sie?</b><br>`;
  t += `Nordpol ${nord} &nbsp;·&nbsp; Strom fließt ${stromRi} &nbsp;→&nbsp; Kraft nach <b>${r > 0 ? 'oben' : 'unten'}</b>.<br><br>`;
  t += `<b>Drei-Finger-Regel der rechten Hand:</b> Der <b>Daumen</b> zeigt in die technische Stromrichtung, der <b>Zeigefinger</b> vom Nord- zum Südpol, dann zeigt der <b>Mittelfinger</b> dorthin, wohin der Stab gedrückt wird.<br><br>`;
  const beide = _lkr.stromUm && _lkr.magnetUm;
  const eins = _lkr.stromUm !== _lkr.magnetUm;
  if (beide) t += `<i>Du hast <b>beides</b> umgepolt – und die Kraft zeigt wieder in die ursprüngliche Richtung. Zweimal umgekehrt hebt sich auf.</i>`;
  else if (eins) t += `<i>Du hast <b>eines von beiden</b> umgepolt – die Kraft zeigt jetzt andersherum.</i>`;
  else t += `<i>Probiere: Polt man <b>eines</b> von beiden um, dreht sich die Kraft. Polt man <b>beide</b> um, bleibt sie.</i>`;
  el.innerHTML = t;
}

function _lkrDraw(ctx, cv) {
  if (!_lkr) return;
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, cv.width, cv.height);
  const cx = 220, cy = 150;
  const nordLinks = !_lkr.magnetUm;

  // Polschuhe
  const pw = 54, ph = 150;
  ctx.fillStyle = nordLinks ? '#dc2626' : '#1e40af';
  ctx.fillRect(52, cy - ph / 2, pw, ph);
  ctx.fillStyle = nordLinks ? '#1e40af' : '#dc2626';
  ctx.fillRect(cv.width - 52 - pw, cy - ph / 2, pw, ph);
  ctx.fillStyle = '#fff'; ctx.font = 'bold 22px system-ui';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText(nordLinks ? 'N' : 'S', 52 + pw / 2, cy);
  ctx.fillText(nordLinks ? 'S' : 'N', cv.width - 52 - pw / 2, cy);

  // Feldlinien von N nach S
  ctx.strokeStyle = 'rgba(100,116,139,.45)'; ctx.lineWidth = 1.4;
  for (let i = -2; i <= 2; i++) {
    const y = cy + i * 30;
    ctx.beginPath(); ctx.moveTo(52 + pw, y); ctx.lineTo(cv.width - 52 - pw, y); ctx.stroke();
    const mx = (52 + pw + cv.width - 52 - pw) / 2, d = nordLinks ? 1 : -1;
    ctx.fillStyle = 'rgba(100,116,139,.6)';
    ctx.beginPath();
    ctx.moveTo(mx + d * 7, y); ctx.lineTo(mx - d * 4, y - 4.5); ctx.lineTo(mx - d * 4, y + 4.5);
    ctx.closePath(); ctx.fill();
  }

  // Aufhaengung und Stab
  const sy = cy + _lkr.y;
  ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(150, 34); ctx.lineTo(150, sy); ctx.moveTo(290, 34); ctx.lineTo(290, sy); ctx.stroke();
  ctx.fillStyle = '#b45309';
  ctx.fillRect(150, sy - 5, 140, 10);
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 10px system-ui';
  ctx.textBaseline = 'middle'; ctx.textAlign = 'center';
  ctx.fillText('L = 10 cm', 220, sy + 18);

  // Stromrichtung im Stab: nach vorn = Punkt, nach hinten = Kreuz
  const vorn = !_lkr.stromUm;
  if (_lkr.i > 0) {
    for (const x of [176, 220, 264]) {
      ctx.strokeStyle = '#f59e0b'; ctx.lineWidth = 2;
      if (vorn) { ctx.fillStyle = '#f59e0b'; ctx.beginPath(); ctx.arc(x, sy, 3.2, 0, Math.PI * 2); ctx.fill(); }
      else {
        ctx.beginPath();
        ctx.moveTo(x - 3.4, sy - 3.4); ctx.lineTo(x + 3.4, sy + 3.4);
        ctx.moveTo(x + 3.4, sy - 3.4); ctx.lineTo(x - 3.4, sy + 3.4); ctx.stroke();
      }
    }
  }

  // Kraftpfeil
  const F = _lkrF(), r = _lkrRichtung();
  if (_lkr.i > 0 && F > 0) {
    const len = Math.min(66, 22 + F * 130);
    ctx.strokeStyle = '#16a34a'; ctx.lineWidth = 3.4;
    ctx.beginPath(); ctx.moveTo(220, sy); ctx.lineTo(220, sy - r * len); ctx.stroke();
    ctx.fillStyle = '#16a34a';
    ctx.beginPath();
    ctx.moveTo(220, sy - r * (len + 11));
    ctx.lineTo(220 - 7, sy - r * (len - 3));
    ctx.lineTo(220 + 7, sy - r * (len - 3));
    ctx.closePath(); ctx.fill();
    ctx.font = 'bold 12px system-ui'; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    ctx.fillText('F = ' + _fpmNum(F, 3) + ' N', 232, sy - r * (len - 4));
  }

  // Kopf und Fuss
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 13px system-ui';
  ctx.fillText('B = ' + _fpmNum(_lkr.b, 2) + ' T   ·   I = ' + _fpmNum(_lkr.i, 1) + ' A   ·   L = 10 cm', 14, 24);
  ctx.font = '11px system-ui'; ctx.fillStyle = '#475569';
  ctx.fillText('Nordpol ' + (nordLinks ? 'links' : 'rechts') + '   ·   Strom ' +
               (vorn ? 'nach vorn (aus dem Bild heraus) ⊙' : 'nach hinten (ins Bild hinein) ⊗'), 14, 42);
  ctx.font = 'bold 12px system-ui'; ctx.fillStyle = _lkr.i > 0 ? '#16a34a' : '#dc2626';
  ctx.fillText(_lkr.i > 0
    ? 'F = ' + _fpmNum(_lkr.b, 2) + ' · ' + _fpmNum(_lkr.i, 1) + ' · 0,10 = ' + _fpmNum(F, 3) + ' N  nach ' + (r > 0 ? 'oben' : 'unten')
    : 'Kein Strom – keine Kraft', 14, 300);
  ctx.font = '10px system-ui'; ctx.fillStyle = '#64748b';
  ctx.fillText('⊙ Strom kommt auf dich zu    ⊗ Strom fließt von dir weg', 14, 316);
}

function _lkrArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('leiterkraft')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('leiterkraft')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Warum bewegt sich ein Draht, sobald Strom durch ihn fließt und er zwischen den Polen eines Magneten hängt?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, dass der Stab sich bewegt, weil … . Die Kraft wird größer, wenn …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Stelle I = 0 A ein. Was passiert? Notiere.</li>
          <li>Stelle B = 0,20 T und I = 5,0 A ein. Notiere Kraft und Richtung.</li>
          <li>Verdopple <b>nur</b> die Stromstärke auf 10,0 A.</li>
          <li>Gehe zurück auf 5,0 A und verdopple <b>nur</b> B auf 0,40 T.</li>
          <li>Polt den Strom um. Danach zusätzlich den Magneten.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Einstellung</td><td>I = 0 A</td><td>0,20 T / 5,0 A</td><td>0,20 T / 10,0 A</td><td>0,40 T / 5,0 A</td></tr>
          <tr><td>Kraft F in N</td><td>${inp('a1','')}</td><td>${inp('a2','')}</td><td>${inp('a3','')}</td><td>${inp('a4','')}</td></tr>
          <tr><td>Richtung</td><td>${inp('b1','')}</td><td>${inp('b2','')}</td><td>${inp('b3','')}</td><td>${inp('b4','')}</td></tr>
          <tr><td>nur Strom umgepolt</td><td colspan="2">${inp('c1','')}</td><td colspan="2">beides umgepolt: ${inp('c2','')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Auswertung</div>
        ${ta('a6', 'Ohne Strom passiert … . Verdoppelt man I, so … ; verdoppelt man B, so … . Beides geht also … in die Kraft ein. Polt man eines von beiden um, … ; polt man beide um, … , weil …', 5)}</div>

      <div class="ab-sec"><div class="ab-h">6 · Merksatz</div>
        <div class="ab-t">Auf einen stromdurchflossenen Leiter im Magnetfeld wirkt die Kraft ${inp('m1', 'welche Formel?')}. Ihre Richtung findet man mit der ${inp('m2', 'welche Regel?')}.</div></div>`;
  return _abWrap('leiterkraft', 'Kraft auf einen stromdurchflossenen Leiter', body);
}

function _lkrHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim lkr-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">⚙️ Warum bewegt sich ein Draht im Magnetfeld?</h3>
    <div class="fpm-note" style="margin-top:2px">Ein Kupferstab hängt lose zwischen den Polen eines Hufeisenmagneten. Solange kein Strom fließt, passiert nichts. Schalte den Strom ein – und pass auf, <b>wohin</b> er gedrückt wird.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="lkrAnim" width="440" height="330" class="phys-anim-cv"></canvas>
        <div style="margin-top:6px">
          <label class="fpm-label" for="lkrI">Stromstärke I: <b id="lkrWertI">5,0</b> A</label>
          <input type="range" id="lkrI" min="0" max="10" value="5" step="0.5" oninput="_lkrSet('i', this.value)" style="width:100%">
          <label class="fpm-label" for="lkrB">Magnetfeld B: <b id="lkrWertB">0,20</b> T</label>
          <input type="range" id="lkrB" min="0.05" max="0.5" value="0.2" step="0.05" oninput="_lkrSet('b', this.value)" style="width:100%">
        </div>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn" onclick="_lkrStromUm()">⇄ Strom umpolen</button>
          <button class="sim-btn" onclick="_lkrMagnetUm()">⇄ Magnet umdrehen</button>
          <button class="sim-btn" onclick="_lkrReset()">↺ zurücksetzen</button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Wie groß ist die Kraft – und wohin zeigt sie?</div>
        <div class="lmp-status" id="lkrStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Diese Kraft heißt oft <b>Lorentzkraft</b>. Sie ist nicht dasselbe wie das Anziehen zweier Magnete: Hier zieht nichts, hier wird <b>quer geschoben</b> – senkrecht zum Strom und senkrecht zum Feld zugleich. Genau das ist der Trick, aus dem jeder Elektromotor gebaut ist.</div>
        <div class="fpm-note" style="margin-top:8px"><b>Modellgrenze:</b> Die Formel F = B · I · L gilt nur, wenn der Draht <b>senkrecht</b> zum Feld liegt. Steht er schräg, wird die Kraft kleiner; liegt er längs des Feldes, ist sie null. Außerdem ist das Feld hier überall gleich stark gezeichnet – bei einem echten Hufeisenmagneten ist es an den Rändern schwächer.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      F = B · I · L &nbsp;·&nbsp; ein Umpolen dreht die Kraft, zwei Umpolungen heben sich auf
    </p>
    ${_lkrArbeitsblattHTML()}
  </div>`;
}

// ═══════════════════════════════════════════════════════
// 10.3.24  ELEKTROMOTOR - AUS KRAFT WIRD DREHUNG
// Realschule NRW - Klasse 10 - Inhaltsfeld "Strom und Magnetismus"
// Drei Themen in einer Simulation, und der Kommutator ist der Angelpunkt.
// Ohne ihn dreht sich die Spule eine halbe Umdrehung, kippt zurueck und
// pendelt sich fest - GENAU das muss man sehen, sonst bleibt "der Polwender
// dreht den Strom um" ein auswendig gelernter Satz. Deshalb laesst er sich
// hier abschalten, und die Simulation rechnet die Drehung wirklich aus,
// statt eine Drehung abzuspielen.
// M = N · B · I · A · sin θ,  A = 20 cm².
// ═══════════════════════════════════════════════════════
let _emo = null;
const _EMO_A = 0.002;         // Flaeche der Spule in m² (20 cm²)

function _emoInit() {
  _emo = { n: 20, b: 0.20, i: 2, komm: true, laeuft: true,
           theta: 0.35, omega: 0, t: 0, drehungen: 0, steht: false };
}

/* Groesstes Drehmoment - so steht es auch in der Anzeige. */
function _emoMmax() { return +(_emo.n * _emo.b * _emo.i * _EMO_A).toFixed(4); }

/* Drehmoment in der aktuellen Stellung. Mit Kommutator wird der Strom bei
   jeder halben Umdrehung umgepolt, deshalb bleibt das Vorzeichen gleich. */
function _emoM() {
  const s = Math.sin(_emo.theta);
  return _emoMmax() * (_emo.komm ? Math.abs(s) : s);
}

function _emoSet(was, v) {
  if (was === 'n') { _emo.n = Math.round(+v); const e = document.getElementById('emoWertN'); if (e) e.textContent = _emo.n; }
  if (was === 'b') { _emo.b = +(+v).toFixed(2); const e = document.getElementById('emoWertB'); if (e) e.textContent = _fpmNum(_emo.b, 2); }
  if (was === 'i') { _emo.i = +(+v).toFixed(1); const e = document.getElementById('emoWertI'); if (e) e.textContent = _fpmNum(_emo.i, 1); }
  _emo.steht = false; _emoStatus();
}
function _emoKomm() {
  _emo.komm = !_emo.komm;
  const b = document.getElementById('emoKomm');
  if (b) { b.textContent = _emo.komm ? '🔁 Kommutator ist AN' : '⛔ Kommutator ist AUS';
           b.className = 'sim-btn' + (_emo.komm ? ' primary' : ''); }
  _emo.steht = false; _emoStatus();
}
function _emoReset() {
  _emo.theta = 0.35; _emo.omega = 0; _emo.drehungen = 0; _emo.steht = false; _emoStatus();
}

function _emoUpdate(dt) {
  if (!_emo || !_emo.laeuft) return;
  _emo.t += dt;
  const J = 0.0012;                       // Traegheit der Spule
  const reib = 0.0016;                    // Lagerreibung und Luftwiderstand
  const alt = _emo.theta;
  _emo.omega += ((_emoM() - reib * _emo.omega) / J) * dt;
  _emo.theta += _emo.omega * dt;
  // volle Umdrehungen zaehlen
  if (Math.floor(_emo.theta / (Math.PI * 2)) !== Math.floor(alt / (Math.PI * 2))) {
    _emo.drehungen++; _emoStatus();
  }
  // Ohne Kommutator pendelt sie sich fest - das ist die Kernbeobachtung
  // frueher als "festgefahren" melden - die Physik bleibt gleich, nur der
  // Hinweis kommt nicht erst nach zwanzig Sekunden Zusehen
  const stehtJetzt = !_emo.komm && Math.abs(_emo.omega) < 0.6 &&
                     Math.abs(Math.sin(_emo.theta)) < 0.18 && _emo.t > 2;
  if (stehtJetzt !== _emo.steht) { _emo.steht = stehtJetzt; _emoStatus(); }
}

function _emoStatus() {
  const el = document.getElementById('emoStatus');
  if (!el || !_emo) return;
  const Mmax = _emoMmax();
  const uMin = Math.abs(_emo.omega) * 60 / (Math.PI * 2);

  let t = `<b>Drehmoment – wie kräftig dreht der Motor?</b><br>`;
  t += `M = N · B · I · A<br>`;
  t += `M = ${_emo.n} · ${_fpmNum(_emo.b, 2)} T · ${_fpmNum(_emo.i, 1)} A · 0,002 m² = <b>${_fpmNum(Mmax, 4)} N·m</b><br>`;
  t += `Das sind <b>${_fpmNum(Mmax * 1000, 1)} Millinewtonmeter</b>.<br><br>`;

  if (_emo.i === 0) {
    t += `<b style="color:#dc2626">Kein Strom – der Motor steht.</b><br><br>`;
  } else if (!_emo.komm) {
    t += `<b style="color:#dc2626">Kommutator ist ausgeschaltet.</b><br>`;
    t += _emo.steht
      ? `Die Spule hat sich <b>festgefahren</b>. Sie ist genau so weit gedreht, dass ihre Fläche quer zum Feld steht – dort ist das Drehmoment null, und weiter dreht nichts. Genau hier scheitert jeder Motor ohne Polwender.<br><br>`
      : `Sieh zu, was passiert: Die Spule dreht sich an, kommt über die Senkrechte hinaus – und dann drückt die Kraft sie <b>zurück</b>. Sie pendelt und bleibt stehen.<br><br>`;
  } else {
    t += `<b style="color:#16a34a">Kommutator ist eingeschaltet.</b> Bei jeder halben Umdrehung polt er den Strom in der Spule um. Dadurch drückt die Kraft <b>immer in dieselbe Drehrichtung</b> – der Motor läuft durch.<br>`;
    t += `Bisher <b>${_emo.drehungen}</b> volle Umdrehungen, gerade rund <b>${_fpmNum(uMin, 0)} Umdrehungen je Minute</b>.<br><br>`;
  }

  t += `<b>Was macht ihn kräftiger?</b> Alle vier Größen gehen <b>einfach</b> ein: doppelt so viele Windungen, doppelte Stromstärke, doppelt starker Magnet oder doppelte Spulenfläche – jedes für sich verdoppelt das Drehmoment.<br><br>`;
  t += `<span style="color:#475569">Zurzeit: <b>${_emo.n}</b> Windungen · <b>${_fpmNum(_emo.b, 2)} T</b> · <b>${_fpmNum(_emo.i, 1)} A</b> · 20 cm²</span>`;
  el.innerHTML = t;
}

function _emoDraw(ctx, cv) {
  if (!_emo) return;
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, cv.width, cv.height);
  const cx = 220, cy = 148, R = 74;

  // Polschuhe
  ctx.fillStyle = '#dc2626'; ctx.fillRect(30, cy - 78, 44, 156);
  ctx.fillStyle = '#1e40af'; ctx.fillRect(cv.width - 74, cy - 78, 44, 156);
  ctx.fillStyle = '#fff'; ctx.font = 'bold 20px system-ui';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('N', 52, cy); ctx.fillText('S', cv.width - 52, cy);

  ctx.strokeStyle = 'rgba(100,116,139,.32)'; ctx.lineWidth = 1.2;
  for (let i = -2; i <= 2; i++) {
    const y = cy + i * 32;
    ctx.beginPath(); ctx.moveTo(74, y); ctx.lineTo(cv.width - 74, y); ctx.stroke();
  }

  // Spule von der Seite: eine Strecke, die sich dreht
  const th = _emo.theta;
  const ax = Math.cos(th) * R, ay = Math.sin(th) * R * 0.42;
  ctx.strokeStyle = '#b45309'; ctx.lineWidth = 5; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(cx - ax, cy - ay); ctx.lineTo(cx + ax, cy + ay); ctx.stroke();
  ctx.lineCap = 'butt';

  // die beiden Leiterseiten mit ihrer Kraft
  const s = Math.sin(th);
  const vorz = _emo.komm ? (s >= 0 ? 1 : -1) : 1;   // der Kommutator polt um
  for (const seite of [1, -1]) {
    const px = cx + seite * ax, py = cy + seite * ay;
    ctx.fillStyle = '#0f172a';
    ctx.beginPath(); ctx.arc(px, py, 8, 0, Math.PI * 2); ctx.fill();
    // Stromrichtung: eine Seite hinein, die andere heraus
    const raus = (seite * vorz) > 0;
    ctx.strokeStyle = '#f59e0b'; ctx.lineWidth = 2;
    if (raus) { ctx.fillStyle = '#f59e0b'; ctx.beginPath(); ctx.arc(px, py, 3, 0, Math.PI * 2); ctx.fill(); }
    else {
      ctx.beginPath();
      ctx.moveTo(px - 3.4, py - 3.4); ctx.lineTo(px + 3.4, py + 3.4);
      ctx.moveTo(px + 3.4, py - 3.4); ctx.lineTo(px - 3.4, py + 3.4); ctx.stroke();
    }
    // Kraftpfeil senkrecht nach oben oder unten
    if (_emo.i > 0) {
      const dir = raus ? -1 : 1;
      const L = 26;
      ctx.strokeStyle = '#16a34a'; ctx.lineWidth = 2.6;
      ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, py + dir * L); ctx.stroke();
      ctx.fillStyle = '#16a34a';
      ctx.beginPath();
      ctx.moveTo(px, py + dir * (L + 8));
      ctx.lineTo(px - 5, py + dir * (L - 2));
      ctx.lineTo(px + 5, py + dir * (L - 2));
      ctx.closePath(); ctx.fill();
    }
  }

  // Achse und Kommutator
  ctx.fillStyle = '#334155';
  ctx.beginPath(); ctx.arc(cx, cy, 6, 0, Math.PI * 2); ctx.fill();
  const kx = cx, ky = cy + 96;
  ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(cx, cy + 6); ctx.lineTo(kx, ky - 16); ctx.stroke();
  ctx.fillStyle = _emo.komm ? '#16a34a' : '#cbd5e1';
  ctx.beginPath(); ctx.arc(kx, ky, 16, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = '#f8fafc'; ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(kx - 16 * Math.cos(th), ky - 16 * Math.sin(th));
  ctx.lineTo(kx + 16 * Math.cos(th), ky + 16 * Math.sin(th));
  ctx.stroke();
  ctx.fillStyle = _emo.komm ? '#16a34a' : '#94a3b8';
  ctx.font = 'bold 10px system-ui'; ctx.textAlign = 'center'; ctx.textBaseline = 'top';
  ctx.fillText(_emo.komm ? 'Kommutator AN' : 'Kommutator AUS', kx, ky + 20);

  // Kopf und Fuss
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#0f172a'; ctx.font = 'bold 13px system-ui';
  ctx.fillText('M = ' + _fpmNum(_emoMmax() * 1000, 1) + ' mN·m   ·   ' + _emo.n + ' Windungen   ·   ' +
               _fpmNum(_emo.i, 1) + ' A   ·   ' + _fpmNum(_emo.b, 2) + ' T', 14, 24);
  const uMin = Math.abs(_emo.omega) * 60 / (Math.PI * 2);
  ctx.font = 'bold 12px system-ui';
  ctx.fillStyle = _emo.steht ? '#dc2626' : (_emo.komm ? '#16a34a' : '#b45309');
  ctx.fillText(_emo.i === 0 ? 'Kein Strom – der Motor steht'
             : _emo.steht ? 'festgefahren – ohne Kommutator geht es nicht weiter'
             : _fpmNum(uMin, 0) + ' Umdrehungen je Minute   ·   ' + _emo.drehungen + ' volle Umdrehungen', 14, 300);
  ctx.font = '10px system-ui'; ctx.fillStyle = '#64748b';
  ctx.fillText('⊙ Strom kommt heraus    ⊗ Strom fließt hinein    ↑↓ Kraft auf die Leiterseite', 14, 316);
}

function _emoArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('elektromotor')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('elektromotor')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Wie wird aus einer Kraft eine Drehung, die nicht nach einer halben Umdrehung wieder aufhört?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, dass die Spule sich weiterdreht, weil … . Ohne Kommutator würde sie …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Sieh dem laufenden Motor eine halbe Minute zu. Wo sitzen die Kräfte?</li>
          <li>Schalte den <b>Kommutator aus</b> und setze zurück. Was macht die Spule jetzt?</li>
          <li>Schalte ihn wieder ein. Verdopple <b>nur</b> die Windungszahl von 20 auf 40.</li>
          <li>Gehe zurück auf 20 und verdopple <b>nur</b> die Stromstärke.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Einstellung</td><td>20 Wdg. / 2 A</td><td>40 Wdg. / 2 A</td><td>20 Wdg. / 4 A</td></tr>
          <tr><td>Drehmoment in mN·m</td><td>${inp('a1','')}</td><td>${inp('a2','')}</td><td>${inp('a3','')}</td></tr>
          <tr><td>Umdrehungen je Minute</td><td>${inp('b1','')}</td><td>${inp('b2','')}</td><td>${inp('b3','')}</td></tr>
          <tr><td>ohne Kommutator</td><td colspan="3">${inp('c1','was macht die Spule?')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Auswertung</div>
        ${ta('a6', 'Auf die beiden Seiten der Spule wirken Kräfte in … Richtung, dadurch entsteht eine … . Ohne Kommutator bleibt die Spule stehen, sobald … . Der Kommutator sorgt dafür, dass … . Verdoppelt man Windungszahl oder Stromstärke, so …', 5)}</div>

      <div class="ab-sec"><div class="ab-h">6 · Merksatz</div>
        <div class="ab-t">Der <b>Kommutator</b> polt bei jeder ${inp('m1', 'wie oft?')} Umdrehung den Strom in der Spule um. Das Drehmoment berechnet man als ${inp('m2', 'welche Formel?')}.</div></div>`;
  return _abWrap('elektromotor', 'Der Elektromotor und sein Kommutator', body);
}

function _emoHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim emo-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">⚙️ Wie wird aus der Kraft eine Drehbewegung?</h3>
    <div class="fpm-note" style="margin-top:2px">Auf die beiden Seiten der Spule wirken Kräfte in <b>entgegengesetzte</b> Richtungen – die eine nach oben, die andere nach unten. Das dreht. Aber warum hört es nach einer halben Umdrehung nicht auf? Schalte den <b>Kommutator</b> aus und sieh selbst.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="emoAnim" width="440" height="330" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" id="emoKomm" onclick="_emoKomm()">🔁 Kommutator ist AN</button>
          <button class="sim-btn" onclick="_emoReset()">↺ zurücksetzen</button>
        </div>
        <div style="margin-top:6px">
          <label class="fpm-label" for="emoN">Windungen der Spule: <b id="emoWertN">20</b></label>
          <input type="range" id="emoN" min="5" max="60" value="20" step="5" oninput="_emoSet('n', this.value)" style="width:100%">
          <label class="fpm-label" for="emoI">Stromstärke I: <b id="emoWertI">2,0</b> A</label>
          <input type="range" id="emoI" min="0" max="6" value="2" step="0.5" oninput="_emoSet('i', this.value)" style="width:100%">
          <label class="fpm-label" for="emoB">Magnetfeld B: <b id="emoWertB">0,20</b> T</label>
          <input type="range" id="emoB" min="0.05" max="0.5" value="0.2" step="0.05" oninput="_emoSet('b', this.value)" style="width:100%">
        </div>
      </div>
      <div>
        <div class="fpm-label">Wie kräftig dreht er – und warum hört er nicht auf?</div>
        <div class="lmp-status" id="emoStatus" style="margin-top:6px"></div>
        <div class="fpm-note" style="margin-top:10px">Der <b>Kommutator</b> (auch Polwender oder Stromwender genannt) ist ein geteilter Ring, der sich mit der Spule mitdreht. Zwei feste Kohlebürsten schleifen darauf. Bei jeder halben Umdrehung wechseln die Hälften – und damit fließt der Strom in der Spule andersherum, während die Kräfte weiter in dieselbe Drehrichtung drücken.</div>
        <div class="fpm-note" style="margin-top:8px"><b>Modellgrenze:</b> Ein echter Motor hat nicht eine, sondern <b>mehrere Spulen</b> versetzt auf dem Anker – sonst bliebe er in der Totlage hängen, wenn man ihn dort anhält. Außerdem entsteht in der drehenden Spule selbst eine Spannung, die dem Strom entgegenwirkt; deshalb dreht ein echter Motor nicht immer schneller, sondern erreicht eine Enddrehzahl. Hier begrenzt nur die Reibung.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      M = N · B · I · A &nbsp;·&nbsp; ohne Kommutator bleibt die Spule nach einer halben Umdrehung stehen
    </p>
    ${_emoArbeitsblattHTML()}
  </div>`;
}

// ═══════════════════════════════════════════════════════
// ZEICHEN-HILFSFUNKTIONEN
// ═══════════════════════════════════════════════════════

function _drawRoad(ctx, cv) {
  ctx.fillStyle = '#f1f5f9'; ctx.fillRect(0, 0, cv.width, cv.height);
  ctx.fillStyle = '#e2e8f0'; ctx.fillRect(0, cv.height - 55, cv.width, 55);
  ctx.strokeStyle = '#fff'; ctx.lineWidth = 3; ctx.setLineDash([30, 20]);
  ctx.beginPath(); ctx.moveTo(0, cv.height - 27); ctx.lineTo(cv.width, cv.height - 27); ctx.stroke();
  ctx.setLineDash([]);
}

function _drawCar(ctx, x, y, color) {
  ctx.fillStyle = color;
  ctx.beginPath(); if (ctx.roundRect) ctx.roundRect(x, y, 70, 30, 6); else ctx.rect(x, y, 70, 30);
  ctx.fill();
  ctx.fillStyle = '#93c5fd';
  ctx.beginPath(); if (ctx.roundRect) ctx.roundRect(x + 10, y - 16, 42, 18, 4); else ctx.rect(x + 10, y - 16, 42, 18);
  ctx.fill();
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.arc(x + 14, y + 30, 9, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(x + 54, y + 30, 9, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fbbf24';
  ctx.beginPath(); ctx.arc(x + 14, y + 30, 4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(x + 54, y + 30, 4, 0, Math.PI * 2); ctx.fill();
}

function _infoBox(ctx, cv, lines) {
  const x = cv.width - 8, y = 8, lh = 16;
  ctx.fillStyle = 'rgba(255,255,255,0.88)';
  ctx.beginPath();
  if (ctx.roundRect) ctx.roundRect(x - 130, y, 128, lines.length * lh + 6, 6);
  else ctx.rect(x - 130, y, 128, lines.length * lh + 6);
  ctx.fill();
  ctx.fillStyle = '#1f2937'; ctx.font = '700 11px sans-serif'; ctx.textAlign = 'right';
  lines.forEach((l, i) => ctx.fillText(l, x - 4, y + 12 + i * lh));
  ctx.textAlign = 'left';
}

