function _reiArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('reihe')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('reihe')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Was passiert, wenn mehrere Lampen hintereinander (in Reihe) geschaltet sind – und wenn eine ausfällt?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute: Wenn ich eine Lampe herausdrehe, dann … Mit mehr Lampen leuchten sie …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Stelle nacheinander <b>1, 2 und 3</b> Lampen in Reihe ein. Beobachte die Helligkeit.</li>
          <li>Dreh bei 2 oder 3 Lampen eine <b>heraus</b>. Was machen die anderen?</li>
          <li>Trage deine Beobachtungen ein.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>1 Lampe – Helligkeit</td><td>${inp('t1', 'hell/mittel/schwach')}</td></tr>
          <tr><td>2 Lampen – Helligkeit je Lampe</td><td>${inp('t2', '')}</td></tr>
          <tr><td>3 Lampen – Helligkeit je Lampe</td><td>${inp('t3', '')}</td></tr>
          <tr><td>Eine Lampe herausgedreht → die anderen</td><td>${inp('t4', 'leuchten/aus')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne einen Stromkreis mit zwei Lampen in Reihe.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Wie ändert sich die Helligkeit, wenn mehr Lampen in Reihe sind? ${inp('a1', '')}</li>
          <li>Was passiert mit allen Lampen, wenn eine ausfällt? ${inp('a2', '')}</li>
          <li>Wie viele Stromwege gibt es in der Reihenschaltung? ${inp('a3', '')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">In der Reihenschaltung liegen die Lampen ${inp('m1', 'nebeneinander/hintereinander')} in einem Stromweg.<br>
        Fällt eine Lampe aus, gehen ${inp('m2', 'alle/keine')} aus.<br>
        Je mehr Lampen in Reihe, desto ${inp('m3', 'heller/schwächer')} leuchtet jede.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Bei alten Lichterketten war der ganze Strang dunkel, wenn ein einziges Lämpchen kaputt war. Erkläre das mit der Reihenschaltung.</div>
        ${ta('tr1', 'Bei der alten Lichterkette …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="reiMini">${_reiMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_reiSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_reiSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_reiSelf(3)">😃 sicher</button>
          <span id="reiSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="reiSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> 1 Lampe hell; 2 Lampen schwächer; 3 Lampen noch schwächer. Eine Lampe heraus → alle aus (nur ein Stromweg).</div>
        <div class="ab-t"><b>Fachlich richtig.</b> In Reihe fließt überall derselbe Strom; die Spannung teilt sich auf die Lampen auf → jede leuchtet schwächer. Jede Unterbrechung öffnet den einzigen Kreis → alles aus.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Die erste Lampe bekommt mehr Strom als die zweite." (2) „Wenn eine ausfällt, leuchten die anderen weiter" (Parallel-Denken). (3) „Mehr Lampen = heller".</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Stromweg mit dem Finger nachfahren (nur ein Weg); Vergleich mit späterer Parallelschaltung ankündigen.</div>
        <div class="ab-t"><b>Musterlösung.</b> 6.1 „wird schwächer" · 6.2 „alle gehen aus" · 6.3 „nur einer". Merksatz: hintereinander · alle · schwächer. Transfer: Alle Lämpchen in Reihe → ein kaputtes unterbricht den einzigen Kreis → alle dunkel. Minidiagnose: 1→„alle aus" · 2→„schwächer" · 3→„ein Weg".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('reihe')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('reihe', 'Was geschieht bei einer Reihenschaltung?', body);
}

const _REI_MINI = [
  { q: '1. In einer Reihenschaltung fällt eine Lampe aus. Was machen die anderen?',
    opts: ['Sie leuchten weiter', 'Sie gehen alle aus', 'Sie leuchten heller'], correct: 1,
    fb: ['In Reihe gibt es nur einen Weg – der ist dann unterbrochen.',
         'Richtig! Eine Unterbrechung → alle Lampen aus.',
         'Heller werden sie sicher nicht.'] },
  { q: '2. Was passiert mit der Helligkeit, wenn mehr Lampen in Reihe sind?',
    opts: ['Jede leuchtet heller', 'Jede leuchtet schwächer', 'Bleibt gleich'], correct: 1,
    fb: ['Andersherum – sie teilen sich die Spannung.',
         'Richtig! Mehr Lampen in Reihe → jede leuchtet schwächer.',
         'Die Helligkeit ändert sich sehr wohl.'] },
  { q: '3. Wie viele Stromwege gibt es in einer Reihenschaltung?',
    opts: ['Nur einen', 'Zwei getrennte', 'Für jede Lampe einen'], correct: 0,
    fb: ['Richtig! Es gibt nur einen einzigen Stromweg.',
         'Getrennte Wege hat die Parallelschaltung.',
         'Das wäre eine Parallelschaltung.'] }
];
function _reiMiniHTML() {
  return _REI_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_reiAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="reiFb${qi}"></div></div>`).join('');
}
function _reiAns(qi, oi) {
  const m = _REI_MINI[qi], el = document.getElementById('reiFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _reiSelf(n) {
  const out = document.getElementById('reiSelfOut'), val = document.getElementById('reiSelfVal');
  if (val) { val.value = String(n); _abSave('reihe'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 5.2.5  WAS GESCHIEHT BEI EINER PARALLELSCHALTUNG?
// Realschule NRW – Klasse 5 · Inhaltsfeld "Strom und Magnetismus"
// Handlungsorientiert: zwei Lampen auf getrennten Stromwegen, jede
// mit eigenem Schalter. Jede Lampe lässt sich unabhängig ein- und
// ausschalten; jede leuchtet mit voller Helligkeit.
// Nur ungefährliche Kleinspannung.
// ═══════════════════════════════════════════════════════

let _par = null;
function _parInit() { _par = { sw1: true, sw2: true, t: 0 }; }

function _parHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim par-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">💡⇊💡 Deins aus, meins an: Wovon hängt es ab, ob du ein Lämpchen allein ausschalten kannst?</h3>
    <div class="fpm-note" style="margin-top:2px">Über den Pritschen hängen Bens und Jonas’ Lämpchen an derselben Flachbatterie, jedes mit eigenem Schalter. Probiere alle vier Schalterstellungen aus und beobachte, welches Lämpchen leuchtet. (Nur ungefährliche Batterie-Kleinspannung.)</div>
    <div class="fpm-grid">
      <div>
        <canvas id="parAnim" width="440" height="240" class="phys-anim-cv"></canvas>
      </div>
      <div>
        <div class="fpm-label">Probiere aus</div>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" id="parS1" onclick="_parToggle('sw1')">🔘 Bens Schalter (Lampe 1): <span id="parS1T">an</span></button>
        </div>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" id="parS2" onclick="_parToggle('sw2')">🔘 Jonas’ Schalter (Lampe 2): <span id="parS2T">an</span></button>
        </div>
        <div class="lmp-status" id="parStatus"></div>
        <div class="fpm-note" style="margin-top:10px">Prüfe alle vier Stellungen der beiden Schalter und notiere jedes Mal, welches Lämpchen leuchtet.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      In der <b>Parallelschaltung</b> gibt es <b>mehrere</b> Stromwege. &nbsp;|&nbsp; Geht eine Lampe aus, leuchtet die andere weiter.
    </p>
    ${_parArbeitsblattHTML()}
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _parToggle(k) {
  _par[k] = !_par[k];
  const s1 = document.getElementById('parS1T'); if (s1) s1.textContent = _par.sw1 ? 'an' : 'aus';
  const s2 = document.getElementById('parS2T'); if (s2) s2.textContent = _par.sw2 ? 'an' : 'aus';
  document.getElementById('parS1')?.classList.toggle('primary', _par.sw1);
  document.getElementById('parS2')?.classList.toggle('primary', _par.sw2);
  _parStatus();
}
function _parStatus() {
  const el = document.getElementById('parStatus'); if (!el) return;
  const n = (_par.sw1 ? 1 : 0) + (_par.sw2 ? 1 : 0);
  if (n === 2) { el.textContent = '✓ Beide Lampen leuchten – jede voll hell.'; el.className = 'lmp-status on'; }
  else if (n === 1) { el.textContent = '✓ Eine Lampe aus – die andere leuchtet weiter (getrennte Wege).'; el.className = 'lmp-status on'; }
  else { el.textContent = '✗ Beide Schalter offen → beide Lampen aus.'; el.className = 'lmp-status off'; }
}

// ── Animation ──────────────────────────────────────────
function _parUpdate(dt) { if (_par) _par.t += dt; }
function _parLampe(ctx, x, y, r, on) {
  if (on) { ctx.fillStyle = 'rgba(250,204,21,0.35)'; ctx.beginPath(); ctx.arc(x, y, r + 10, 0, 2 * Math.PI); ctx.fill(); }
  ctx.fillStyle = on ? '#fde047' : '#e2e8f0'; ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(x, y, r, 0, 2 * Math.PI); ctx.fill(); ctx.stroke();
  ctx.strokeStyle = on ? '#b45309' : '#94a3b8'; ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.moveTo(x - 6, y - 6); ctx.lineTo(x + 6, y + 6); ctx.moveTo(x + 6, y - 6); ctx.lineTo(x - 6, y + 6); ctx.stroke();
}
function _parSwitch(ctx, x, y, on) {
  // Schalter im SENKRECHTEN Zweig. Erst den Draht wegnehmen: ein offener Schalter
  // muss den Zweig sichtbar unterbrechen, sonst sieht der Kreis auch offen
  // geschlossen aus.
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(x - 17, y - 17, 34, 34);
  ctx.fillStyle = '#334155'; ctx.beginPath(); ctx.arc(x, y - 12, 3, 0, 2 * Math.PI); ctx.arc(x, y + 12, 3, 0, 2 * Math.PI); ctx.fill();
  ctx.strokeStyle = on ? '#16a34a' : '#dc2626'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(x, y + 12); if (on) ctx.lineTo(x, y - 12); else ctx.lineTo(x + 13, y - 6); ctx.stroke();
}
function _parDraw(ctx, cv) {
  if (!_par) return;
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H); ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, W, H);
  // Uebliche Schulbuch-Orientierung: waagerechte Sammelschienen oben und unten,
  // senkrechte Zweige dazwischen - links die Batterie, rechts die beiden Lampen
  // nebeneinander. Alle drei Zweige haengen an denselben zwei Schienen, deshalb
  // hat jede Lampe ihre eigene geschlossene Masche mit der Batterie.
  const L = 58, x1 = 250, x2 = 372, yT = 46, yB = 196;
  const cyB = (yT + yB) / 2, ySw = 92, yLp = 148;
  ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(L, yT); ctx.lineTo(x2, yT); ctx.moveTo(L, yB); ctx.lineTo(x2, yB); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(L, yT); ctx.lineTo(L, yB); ctx.stroke();
  [x1, x2].forEach(x => { ctx.beginPath(); ctx.moveTo(x, yT); ctx.lineTo(x, yB); ctx.stroke(); });

  // Stromweg je eingeschalteter Lampe als geschlossener Ring: Batteriezweig,
  // obere Schiene, Lampenzweig, untere Schiene zurueck.
  const _parFluss = x => {
    ctx.strokeStyle = '#22c55e'; ctx.lineWidth = 3;
    ctx.setLineDash([9, 9]); ctx.lineDashOffset = -(_par.t * 70) % 18;
    ctx.beginPath();
    ctx.moveTo(L, yT); ctx.lineTo(L, yB);
    ctx.moveTo(L, yT); ctx.lineTo(x, yT);
    ctx.moveTo(L, yB); ctx.lineTo(x, yB);
    ctx.moveTo(x, yT); ctx.lineTo(x, yB);
    ctx.stroke(); ctx.setLineDash([]); ctx.lineDashOffset = 0;
  };
  if (_par.sw1) _parFluss(x1);
  if (_par.sw2) _parFluss(x2);

  // Batterie im linken Zweig, mit Luecke im Draht
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(L - 20, cyB - 21, 40, 42);
  ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(L - 16, cyB - 8); ctx.lineTo(L + 16, cyB - 8); ctx.stroke();
  ctx.lineWidth = 6; ctx.beginPath(); ctx.moveTo(L - 9, cyB + 8); ctx.lineTo(L + 9, cyB + 8); ctx.stroke();
  ctx.fillStyle = '#334155'; ctx.font = '700 13px sans-serif'; ctx.textAlign = 'left';
  ctx.fillText('+', L + 22, cyB - 3); ctx.fillText('\u2212', L + 22, cyB + 20);
  ctx.fillStyle = '#64748b'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Batterie', L, yB + 18);

  [[x1, _par.sw1, 'Lampe 1'], [x2, _par.sw2, 'Lampe 2']].forEach(([x, on, lbl]) => {
    _parSwitch(ctx, x, ySw, on);
    _parLampe(ctx, x, yLp, 14, on);
    ctx.fillStyle = '#64748b'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center'; ctx.fillText(lbl, x, yT - 10);
  });

  // Elektronen: vom Minus-Pol (untere Platte) nach unten, ueber die untere
  // Schiene in den Zweig, oben herum und zurueck zum Plus-Pol.
  const _parWeg = x => [[L, cyB + 8], [L, yB], [x, yB], [x, yT], [L, yT], [L, cyB - 8]];
  if (_par.sw1) _elektronen(ctx, _parWeg(x1), _par.t);
  if (_par.sw2) _elektronen(ctx, _parWeg(x2), _par.t);
  if (_par.sw1 || _par.sw2) _elLegende(ctx, L + 96, H - 8);
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 5.2.5  (ns = 'parallel') – im 0123-Gate
// ═══════════════════════════════════════════════════════
function _parArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('parallel')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('parallel')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Was passiert bei zwei Lampen auf getrennten Stromwegen (parallel), wenn ich nur eine ausschalte?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute: Wenn ich Lampe 1 ausschalte, dann macht Lampe 2 …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Schalte beide Lampen ein. Wie hell leuchten sie?</li>
          <li>Schalte nur <b>Lampe 1</b> aus. Was macht Lampe 2?</li>
          <li>Probiere alle Kombinationen aus und trage sie ein.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Schalter 1</td><td>Schalter 2</td><td>Lampe 1</td><td>Lampe 2</td></tr>
          <tr><td>an</td><td>an</td><td>${inp('t1a', '')}</td><td>${inp('t1b', '')}</td></tr>
          <tr><td>aus</td><td>an</td><td>${inp('t2a', '')}</td><td>${inp('t2b', '')}</td></tr>
          <tr><td>an</td><td>aus</td><td>${inp('t3a', '')}</td><td>${inp('t3b', '')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne zwei Lampen parallel (auf zwei getrennten Wegen) mit der Batterie.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Sind die Lampen voneinander abhängig? ${inp('a1', 'ja/nein')}</li>
          <li>Wie hell leuchtet jede Lampe im Vergleich zur Reihenschaltung? ${inp('a2', '')}</li>
          <li>Wie viele Stromwege gibt es? ${inp('a3', '')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">In der Parallelschaltung hat jede Lampe einen ${inp('m1', 'eigenen/gemeinsamen')} Stromweg.<br>
        Schaltet man eine Lampe aus, leuchtet die andere ${inp('m2', 'weiter/auch aus')}.<br>
        Jede Lampe leuchtet mit ${inp('m3', 'voller/halber')} Helligkeit.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Zu Hause kannst du das Licht in der Küche anlassen und im Wohnzimmer ausschalten. Welche Schaltung wird deshalb im Haushalt benutzt? Begründe.</div>
        ${ta('tr1', 'Im Haushalt benutzt man die … , weil …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="parMini">${_parMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_parSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_parSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_parSelf(3)">😃 sicher</button>
          <span id="parSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="parSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> an/an → beide leuchten; aus/an → nur Lampe 2; an/aus → nur Lampe 1. Jede Lampe leuchtet unabhängig und mit voller Helligkeit.</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Parallel = mehrere getrennte Stromwege; an jeder Lampe liegt die volle Spannung → volle Helligkeit; Ausfall/Abschalten eines Zweigs betrifft die anderen nicht.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Wenn eine aus ist, gehen beide aus" (Reihen-Denken). (2) „Parallel leuchten die Lampen schwächer." (3) „Es gibt nur einen Schalter für alles."</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Beide getrennten Wege mit dem Finger nachfahren; direkter Vergleich zur Reihenschaltung (5.2.4).</div>
        <div class="ab-t"><b>Musterlösung.</b> Tabelle: an/an; aus→L1 aus,L2 an; an→L1 an,L2 aus. 6.1 „nein" · 6.2 „voll/heller" · 6.3 „mehrere". Merksatz: eigenen · weiter · voller. Transfer: Parallelschaltung, weil jedes Gerät unabhängig geschaltet werden kann. Minidiagnose: 1→„leuchtet weiter" · 2→„volle Helligkeit" · 3→„Parallelschaltung".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('parallel')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('parallel', 'Was geschieht bei einer Parallelschaltung?', body);
}

const _PAR_MINI = [
  { q: '1. Zwei Lampen sind parallel geschaltet. Du schaltest Lampe 1 aus. Was macht Lampe 2?',
    opts: ['Sie geht auch aus', 'Sie leuchtet weiter', 'Sie leuchtet schwächer'], correct: 1,
    fb: ['Nein – die Wege sind getrennt.',
         'Richtig! Lampe 2 hat einen eigenen Weg und leuchtet weiter.',
         'Sie bleibt gleich hell.'] },
  { q: '2. Wie hell leuchtet jede Lampe in der Parallelschaltung?',
    opts: ['Halb so hell', 'Mit voller Helligkeit', 'Gar nicht'], correct: 1,
    fb: ['Das wäre die Reihenschaltung.',
         'Richtig! An jeder Lampe liegt die volle Spannung → volle Helligkeit.',
         'Sie leuchten sehr wohl.'] },
  { q: '3. Welche Schaltung benutzt man im Haushalt, damit jedes Licht einzeln geht?',
    opts: ['Reihenschaltung', 'Parallelschaltung', 'Gar keine'], correct: 1,
    fb: ['In Reihe würde ein Ausfall alles lahmlegen.',
         'Richtig! Im Haushalt sind die Geräte parallel geschaltet.',
         'Doch, man braucht die Parallelschaltung.'] }
];
function _parMiniHTML() {
  return _PAR_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_parAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="parFb${qi}"></div></div>`).join('');
}
function _parAns(qi, oi) {
  const m = _PAR_MINI[qi], el = document.getElementById('parFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _parSelf(n) {
  const out = document.getElementById('parSelfOut'), val = document.getElementById('parSelfVal');
  if (val) { val.value = String(n); _abSave('parallel'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 5.2.6  WELCHE WIRKUNGEN KANN ELEKTRISCHER STROM HABEN?
// Realschule NRW – Klasse 5 · Inhaltsfeld "Strom und Magnetismus"
// Handlungsorientiert: verschiedene Verbraucher an denselben
// Stromkreis anschließen und die Wirkung beobachten – Licht-,
// Wärme-, magnetische und Bewegungswirkung. Energieumwandlung.
// Stromstärke verändern → Wirkung stärker. Nur Kleinspannung.
// ═══════════════════════════════════════════════════════

const _WIR_DEV = [
  { k: 'lampe', name: 'Glühlampe', ic: '💡', wirk: ['licht', 'waerme'], um: 'elektrische Energie → Licht + Wärme' },
  { k: 'heiz',  name: 'Heizdraht', ic: '🔥', wirk: ['waerme'],          um: 'elektrische Energie → Wärme' },
  { k: 'spule', name: 'Spule (Elektromagnet)', ic: '🧲', wirk: ['magnet'], um: 'elektrische Energie → magnetische Wirkung' },
  { k: 'motor', name: 'Elektromotor', ic: '⚙️', wirk: ['bewegung', 'waerme'], um: 'elektrische Energie → Bewegung (+ etwas Wärme)' }
];
const _WIR_ALL = [
  { k: 'licht', n: 'Lichtwirkung', ic: '☀️' },
  { k: 'waerme', n: 'Wärmewirkung', ic: '🔥' },
  { k: 'magnet', n: 'magnetische Wirkung', ic: '🧲' },
  { k: 'bewegung', n: 'Bewegungswirkung', ic: '🌀' }
];
let _wir = null;
function _wirInit() { _wir = { dev: 'lampe', I: 3, rot: 0, t: 0 }; }
function _wirCur() { return _WIR_DEV.find(d => d.k === _wir.dev); }

function _wirHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim wir-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">⚡ Welche Wirkungen kann elektrischer Strom haben?</h3>
    <div class="fpm-note" style="margin-top:2px">Schließe verschiedene Geräte an denselben Stromkreis an. Was bewirkt der Strom jeweils? Verändere die Stromstärke. (Nur Batterie-Kleinspannung.)</div>
    <div class="fpm-grid">
      <div>
        <canvas id="wirAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="phys-ctrl" style="margin-top:8px">
          <span class="phys-ctrl-label">Stromstärke I: <b id="wirILbl">3 A</b></span>
          <input type="range" id="wirI" min="1" max="5" step="1" value="3"
            oninput="_wirSetI(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
      </div>
      <div>
        <div class="fpm-label">Gerät anschließen</div>
        <div class="msf-chips" id="wirChips">${_wirChipsHTML()}</div>
        <div class="fpm-label" style="margin-top:10px">Beobachtete Wirkung(en)</div>
        <div id="wirWirk">${_wirWirkHTML()}</div>
        <div class="wir-um" id="wirUm"></div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Strom kann <b>Licht</b>, <b>Wärme</b>, <b>Magnetismus</b> und <b>Bewegung</b> erzeugen. &nbsp;|&nbsp; Dabei wird elektrische Energie umgewandelt.
    </p>
    ${_wirArbeitsblattHTML()}
  </div>`;
}
function _wirChipsHTML() {
  return _WIR_DEV.map(d => `<button class="msf-chip${d.k === _wir.dev ? ' cur' : ''}" onclick="_wirSetDev('${d.k}')">${d.ic} ${d.name}</button>`).join('');
}
function _wirWirkHTML() {
  const cur = _wirCur();
  return _WIR_ALL.map(w => {
    const on = cur.wirk.indexOf(w.k) >= 0;
    return `<div class="wir-row ${on ? 'on' : 'off'}">${on ? '✓' : '—'} ${w.ic} ${w.n}</div>`;
  }).join('');
}

// ── Bedienung ──────────────────────────────────────────
function _wirSetI(v) { _wir.I = +v; const e = document.getElementById('wirILbl'); if (e) e.textContent = _fpmNum(+v, 0) + ' A'; }
function _wirSetDev(k) {
  _wir.dev = k;
  const chips = document.getElementById('wirChips'); if (chips) chips.innerHTML = _wirChipsHTML();
  const w = document.getElementById('wirWirk'); if (w) w.innerHTML = _wirWirkHTML();
  const um = document.getElementById('wirUm'); if (um) um.innerHTML = '🔄 <b>Energieumwandlung:</b> ' + _wirCur().um;
}

// ── Animation ──────────────────────────────────────────
function _wirUpdate(dt) { if (_wir) { _wir.t += dt; if (_wir.dev === 'motor') _wir.rot += _wir.I * dt * 1.4; } }
function _wirDraw(ctx, cv) {
  if (!_wir) return;
  const W = cv.width, H = cv.height, I = _wir.I, k = _wir.dev;
  ctx.clearRect(0, 0, W, H); ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, W, H);
  const cx = W / 2 + 30, cy = H / 2;
  // Batterie links + Zuleitungen
  ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(40, cy - 12); ctx.lineTo(40, cy + 12); ctx.stroke();
  ctx.lineWidth = 6; ctx.beginPath(); ctx.moveTo(52, cy - 7); ctx.lineTo(52, cy + 7); ctx.stroke();
  ctx.fillStyle = '#64748b'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Batterie', 46, cy + 28);
  ctx.strokeStyle = '#22c55e'; ctx.lineWidth = 3; ctx.setLineDash([8, 8]); ctx.lineDashOffset = -(_wir.t * (40 + I * 20)) % 16;
  ctx.beginPath(); ctx.moveTo(52, cy); ctx.lineTo(cx - 40, cy); ctx.stroke();
  ctx.setLineDash([]); ctx.lineDashOffset = 0;
  ctx.fillStyle = '#16a34a'; ctx.font = '11px sans-serif'; ctx.textAlign = 'left'; ctx.fillText('I = ' + _fpmNum(I, 0) + ' A', 70, cy - 10);

  if (k === 'lampe') {
    const g = I / 5;
    ctx.fillStyle = 'rgba(250,204,21,' + (0.1 + 0.35 * g) + ')'; ctx.beginPath(); ctx.arc(cx, cy, 26 + 24 * g, 0, 2 * Math.PI); ctx.fill();
    ctx.fillStyle = '#fde047'; ctx.strokeStyle = '#b45309'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(cx, cy, 24, 0, 2 * Math.PI); ctx.fill(); ctx.stroke();
    ctx.strokeStyle = '#b45309'; ctx.beginPath(); ctx.moveTo(cx - 8, cy + 6); ctx.lineTo(cx, cy - 6); ctx.lineTo(cx + 8, cy + 6); ctx.stroke();
    ctx.fillStyle = '#334155'; ctx.font = '700 12px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Licht + Wärme', cx, cy + 56);
  } else if (k === 'heiz') {
    const hot = I / 5;
    ctx.strokeStyle = `rgb(${200 + Math.round(55 * hot)},${Math.round(120 - 90 * hot)},40)`; ctx.lineWidth = 5; ctx.lineCap = 'round';
    ctx.beginPath(); for (let i = 0; i <= 8; i++) { const x = cx - 40 + i * 10; const y = cy + (i % 2 ? 10 : -10); i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y); } ctx.stroke();
    for (let i = 0; i < 3; i++) { const wy = cy - 22 - ((_wir.t * 30 + i * 18) % 40); ctx.strokeStyle = 'rgba(239,68,68,' + (0.5 * hot) + ')'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(cx - 12 + i * 12, wy); ctx.quadraticCurveTo(cx - 6 + i * 12, wy - 6, cx - 12 + i * 12, wy - 12); ctx.stroke(); }
    ctx.fillStyle = '#334155'; ctx.font = '700 12px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Wärme (Draht glüht)', cx, cy + 46);
  } else if (k === 'spule') {
    ctx.fillStyle = '#94a3b8'; ctx.fillRect(cx - 6, cy - 30, 12, 60);
    ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 2 + I * 0.4;
    for (let i = 0; i < 5; i++) { ctx.beginPath(); ctx.ellipse(cx, cy - 22 + i * 11, 12, 4, 0, 0, 2 * Math.PI); ctx.stroke(); }
    // Kompassnadel darunter, Ausschlag ~ I
    const ny = cy + 46, ang = -Math.PI / 2 + (I / 5) * 0.9;
    ctx.strokeStyle = '#cbd5e1'; ctx.beginPath(); ctx.arc(cx, ny, 16, 0, 2 * Math.PI); ctx.stroke();
    ctx.strokeStyle = '#dc2626'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(cx, ny); ctx.lineTo(cx + Math.cos(ang) * 13, ny + Math.sin(ang) * 13); ctx.stroke();
    ctx.fillStyle = '#334155'; ctx.font = '700 12px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Magnet lenkt Nadel ab', cx, ny + 34);
  } else if (k === 'motor') {
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(cx, cy, 26, 0, 2 * Math.PI); ctx.stroke();
    ctx.save(); ctx.translate(cx, cy); ctx.rotate(_wir.rot);
    ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 5; ctx.beginPath(); ctx.moveTo(-22, 0); ctx.lineTo(22, 0); ctx.stroke();
    ctx.fillStyle = '#7c3aed'; ctx.beginPath(); ctx.arc(0, 0, 5, 0, 2 * Math.PI); ctx.fill();
    ctx.restore();
    ctx.fillStyle = '#334155'; ctx.font = '700 12px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Bewegung (dreht sich)', cx, cy + 50);
  }
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 5.2.6  (ns = 'wirkung') – im 0123-Gate
// ═══════════════════════════════════════════════════════
function _wirArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('wirkung')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('wirkung')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Was kann elektrischer Strom alles bewirken?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, elektrischer Strom kann … erzeugen.', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Schließe nacheinander <b>jedes Gerät</b> an (Lampe, Heizdraht, Spule, Motor).</li>
          <li>Beobachte, welche Wirkung entsteht. Verändere die Stromstärke.</li>
          <li>Trage die Wirkung in die Tabelle ein.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Glühlampe</td><td>${inp('t_lampe', 'welche Wirkung?')}</td></tr>
          <tr><td>Heizdraht</td><td>${inp('t_heiz', '')}</td></tr>
          <tr><td>Spule (Elektromagnet)</td><td>${inp('t_spule', '')}</td></tr>
          <tr><td>Elektromotor</td><td>${inp('t_motor', '')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne ein Gerät und male Symbole für seine Wirkung dazu (z. B. Strahlen für Licht, Wellen für Wärme).</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Nenne die vier Wirkungen des Stroms. ${inp('a1', '1. … 2. … 3. … 4. …')}</li>
          <li>Was passiert mit der Wirkung, wenn die Stromstärke größer wird? ${inp('a2', '')}</li>
          <li>Wozu wird die elektrische Energie im Motor umgewandelt? ${inp('a3', 'zu …')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Elektrischer Strom kann eine ${inp('m1', 'Wirkung 1')}-, ${inp('m2', 'Wirkung 2')}-, magnetische und Bewegungs-Wirkung haben.<br>
        Dabei wird ${inp('m3', 'welche Energie?')} Energie in andere Energieformen umgewandelt.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Ordne zu, welche Wirkung diese Geräte nutzen: Föhn, Türklingel, Taschenlampe, Ventilator.</div>
        ${ta('tr1', 'Föhn: … , Türklingel: … , Taschenlampe: … , Ventilator: …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="wirMini">${_wirMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_wirSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_wirSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_wirSelf(3)">😃 sicher</button>
          <span id="wirSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="wirSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> Lampe → Licht (und Wärme); Heizdraht → Wärme; Spule → magnetische Wirkung (Nadel schlägt aus); Motor → Bewegung. Größere Stromstärke → stärkere Wirkung.</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Wirkungen des Stroms: Licht-, Wärme-, magnetische und Bewegungswirkung. In jedem Verbraucher wird elektrische Energie in andere Energieformen umgewandelt (z. B. elektrisch → Licht + Wärme).</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Strom erzeugt nur Licht." (2) „Wärme ist kein Effekt des Stroms." (3) „Energie geht verloren" statt umgewandelt.</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Reale Geräte zuordnen (Föhn, Klingel, Lampe, Ventilator); Energieumwandlung sprachlich mit „→" fassen; nur Kleinspannung.</div>
        <div class="ab-t"><b>Musterlösung.</b> 6.1 Licht, Wärme, Magnetismus, Bewegung · 6.2 „stärker" · 6.3 „Bewegung". Merksatz: Licht · Wärme · elektrische. Transfer: Föhn = Wärme + Bewegung, Türklingel = Magnet, Taschenlampe = Licht, Ventilator = Bewegung. Minidiagnose: 1→Wärme · 2→magnetische Wirkung · 3→„Licht und Wärme".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('wirkung')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('wirkung', 'Welche Wirkungen kann elektrischer Strom haben?', body);
}

const _WIR_MINI = [
  { q: '1. Welche Wirkung nutzt ein Heizdraht (z. B. im Toaster)?',
    opts: ['Lichtwirkung', 'Wärmewirkung', 'Bewegungswirkung'], correct: 1,
    fb: ['Ein wenig glüht er, aber der Zweck ist die Wärme.',
         'Richtig! Der Heizdraht nutzt die Wärmewirkung.',
         'Er bewegt sich nicht.'] },
  { q: '2. Eine Spule mit Strom lenkt eine Kompassnadel ab. Welche Wirkung ist das?',
    opts: ['Lichtwirkung', 'magnetische Wirkung', 'Wärmewirkung'], correct: 1,
    fb: ['Licht entsteht dabei nicht.',
         'Richtig! Das ist die magnetische Wirkung des Stroms.',
         'Wärme ist hier nicht der Punkt.'] },
  { q: '3. Wozu wird die elektrische Energie in einer Glühlampe umgewandelt?',
    opts: ['Nur zu Bewegung', 'Zu Licht und Wärme', 'Zu Magnetismus'], correct: 1,
    fb: ['Die Lampe bewegt sich nicht.',
         'Richtig! Elektrische Energie → Licht und Wärme.',
         'Eine Lampe ist kein Magnet.'] }
];
function _wirMiniHTML() {
  return _WIR_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_wirAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="wirFb${qi}"></div></div>`).join('');
}
function _wirAns(qi, oi) {
  const m = _WIR_MINI[qi], el = document.getElementById('wirFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _wirSelf(n) {
  const out = document.getElementById('wirSelfOut'), val = document.getElementById('wirSelfVal');
  if (val) { val.value = String(n); _abSave('wirkung'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 5.3.1  WIE KÖNNEN WIR EINEN GEGENSTAND SEHEN?
// Realschule NRW – Klasse 5 · Inhaltsfeld "Licht und Schall"
// Handlungsorientiert: Sender–Gegenstand–Empfänger-Modell. Lampe,
// Gegenstand, Auge. Wir sehen einen Gegenstand nur, wenn Licht von
// ihm ins Auge gelangt. Leuchtende Körper senden eigenes Licht,
// beleuchtete werfen fremdes Licht zurück (z. B. der Mond).
// ═══════════════════════════════════════════════════════

const _SEH_OBJ = [
  { k: 'lampe', name: 'Taschenlampe', ic: '🔦', leucht: true },
  { k: 'kerze', name: 'Kerze',        ic: '🕯️', leucht: true },
  { k: 'sonne', name: 'Sonne',        ic: '☀️', leucht: true },
  { k: 'buch',  name: 'Tüte Gummibärchen', ic: '🍬', leucht: false },
  { k: 'apfel', name: 'Katzenauge',   ic: '🔴', leucht: false },
  { k: 'mond',  name: 'Mond',         ic: '🌙', leucht: false }
];
let _seh = null;
function _sehInit() { _seh = { lampOn: true, obj: 'buch', t: 0 }; }
function _sehCur() { return _SEH_OBJ.find(o => o.k === _seh.obj); }
function _sehSieht() { const o = _sehCur(); return o.leucht || _seh.lampOn; }

function _sehHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim seh-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">👁️ Wie können wir einen Gegenstand sehen?</h3>
    <div class="fpm-note" style="margin-top:2px">In der Bude ist es stockdunkel. Emmas Tuete liegt neben dem Schlafsack. Schalte das Licht an und aus und waehle verschiedene Gegenstaende. Wann siehst du etwas, wann nicht?</div>
    <div class="fpm-grid">
      <div>
        <canvas id="sehAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" id="sehL" onclick="_sehToggle()">💡 Zimmerlicht: <span id="sehLT">an</span></button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Gegenstand wählen</div>
        <div class="msf-chips" id="sehChips">${_sehChipsHTML()}</div>
        <div class="lmp-status" id="sehStatus"></div>
        <div class="fpm-note" style="margin-top:10px">Probiere jeden Gegenstand zweimal: einmal mit Licht, einmal ohne Licht. Trage in die Tabelle im Forscherheft ein, ob du ihn siehst (ja / nein).</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Wir sehen einen Gegenstand nur, wenn <b>Licht von ihm ins Auge</b> gelangt. &nbsp;|&nbsp; Der Mond leuchtet nicht selbst – er wirft Sonnenlicht zurück.
    </p>
    ${_sehArbeitsblattHTML()}
  </div>`;
}
function _sehChipsHTML() {
  return _SEH_OBJ.map(o => `<button class="msf-chip${o.k === _seh.obj ? ' cur' : ''}" onclick="_sehSetObj('${o.k}')">${o.ic} ${o.name}</button>`).join('');
}

// ── Bedienung ──────────────────────────────────────────
function _sehToggle() {
  _seh.lampOn = !_seh.lampOn;
  const t = document.getElementById('sehLT'); if (t) t.textContent = _seh.lampOn ? 'an' : 'aus';
  document.getElementById('sehL')?.classList.toggle('primary', _seh.lampOn);
  _sehStatus();
}
function _sehSetObj(k) {
  _seh.obj = k;
  const chips = document.getElementById('sehChips'); if (chips) chips.innerHTML = _sehChipsHTML();
  _sehStatus();
}
function _sehStatus() {
  const el = document.getElementById('sehStatus'); if (!el) return;
  const o = _sehCur();
  if (o.leucht) { el.textContent = '✓ ' + o.name + ' – du siehst etwas.'; el.className = 'lmp-status on'; }
  else if (_seh.lampOn) { el.textContent = '✓ Licht an – du siehst: ' + o.name + '.'; el.className = 'lmp-status on'; }
  else { el.textContent = '✗ Licht aus – du siehst nichts.'; el.className = 'lmp-status off'; }
}

// ── Animation ──────────────────────────────────────────
function _sehUpdate(dt) { if (_seh) _seh.t += dt; }
function _sehRay(ctx, x1, y1, x2, y2, col) {
  ctx.strokeStyle = col; ctx.lineWidth = 2; ctx.setLineDash([7, 5]); ctx.lineDashOffset = -(_seh.t * 40) % 12;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke(); ctx.setLineDash([]); ctx.lineDashOffset = 0;
  // Pfeilspitze
  const a = Math.atan2(y2 - y1, x2 - x1); ctx.fillStyle = col;
  ctx.beginPath(); ctx.moveTo(x2, y2); ctx.lineTo(x2 - Math.cos(a - 0.4) * 8, y2 - Math.sin(a - 0.4) * 8); ctx.lineTo(x2 - Math.cos(a + 0.4) * 8, y2 - Math.sin(a + 0.4) * 8); ctx.closePath(); ctx.fill();
}
function _sehDraw(ctx, cv) {
  if (!_seh) return;
  const W = cv.width, H = cv.height, o = _sehCur(), sieht = _sehSieht();
  ctx.fillStyle = sieht ? '#eff6ff' : '#0f172a'; ctx.fillRect(0, 0, W, H);
  const lampX = 60, lampY = 50, objX = W / 2, objY = H / 2 + 10, eyeX = W - 55, eyeY = H / 2 + 10;
  // Lampe (Zimmerlicht)
  ctx.fillStyle = _seh.lampOn ? '#facc15' : '#475569';
  ctx.beginPath(); ctx.arc(lampX, lampY, 12, 0, 2 * Math.PI); ctx.fill();
  if (_seh.lampOn) { ctx.strokeStyle = '#fde047'; ctx.lineWidth = 1.4; for (let k = 0; k < 8; k++) { const an = k * Math.PI / 4; ctx.beginPath(); ctx.moveTo(lampX + Math.cos(an) * 14, lampY + Math.sin(an) * 14); ctx.lineTo(lampX + Math.cos(an) * 19, lampY + Math.sin(an) * 19); ctx.stroke(); } }
  ctx.fillStyle = _seh.lampOn ? '#92400e' : '#94a3b8'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Zimmerlicht', lampX, lampY + 30);
  // Gegenstand
  ctx.font = '34px sans-serif'; ctx.textAlign = 'center';
  if (sieht) ctx.fillText(o.ic, objX, objY + 12);
  else { ctx.globalAlpha = 0.18; ctx.fillText(o.ic, objX, objY + 12); ctx.globalAlpha = 1; }
  ctx.fillStyle = sieht ? '#334155' : '#64748b'; ctx.font = '700 12px sans-serif'; ctx.fillText(o.name, objX, objY - 26);
  // Auge
  ctx.fillStyle = '#fff'; ctx.strokeStyle = sieht ? '#334155' : '#64748b'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.ellipse(eyeX, eyeY, 18, 11, 0, 0, 2 * Math.PI); ctx.fill(); ctx.stroke();
  ctx.fillStyle = sieht ? '#1e40af' : '#64748b'; ctx.beginPath(); ctx.arc(eyeX, eyeY, 6, 0, 2 * Math.PI); ctx.fill();
  ctx.fillStyle = '#0f172a'; ctx.beginPath(); ctx.arc(eyeX, eyeY, 3, 0, 2 * Math.PI); ctx.fill();
  ctx.fillStyle = sieht ? '#334155' : '#94a3b8'; ctx.font = '10px sans-serif'; ctx.fillText('Auge', eyeX, eyeY + 26);
  // Lichtstrahlen
  if (o.leucht) {
    _sehRay(ctx, objX + 16, objY, eyeX - 20, eyeY, '#f59e0b');   // Gegenstand → Auge
  } else if (_seh.lampOn) {
    _sehRay(ctx, lampX + 12, lampY + 6, objX - 14, objY - 6, '#f59e0b');   // Lampe → Gegenstand
    _sehRay(ctx, objX + 16, objY, eyeX - 20, eyeY, '#f59e0b');             // Gegenstand → Auge
  } else {
    ctx.fillStyle = '#e2e8f0'; ctx.font = '700 13px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('🌑 zu dunkel – du siehst nichts', W / 2, 30);
  }
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 5.3.1  (ns = 'sehen') – im 0123-Gate
// ═══════════════════════════════════════════════════════
function _sehArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('sehen')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('sehen')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Warum können wir einen Gegenstand sehen – und warum im Dunkeln nicht?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, wir sehen einen Gegenstand, wenn …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Wähle einen <b>beleuchteten</b> Gegenstand (Buch, Apfel, Mond) und schalte das Licht aus. Was passiert?</li>
          <li>Wähle einen <b>leuchtenden</b> Gegenstand (Lampe, Kerze, Sonne). Siehst du ihn auch im Dunkeln?</li>
          <li>Achte auf die Lichtstrahlen: Woher kommen sie, wohin gehen sie?</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Gegenstand</td><td>leuchtet selbst?</td><td>im Dunkeln sichtbar?</td></tr>
          <tr><td>Lampe / Kerze / Sonne</td><td>${inp('t1a', 'ja/nein')}</td><td>${inp('t1b', 'ja/nein')}</td></tr>
          <tr><td>Buch / Apfel / Mond</td><td>${inp('t2a', 'ja/nein')}</td><td>${inp('t2b', 'ja/nein')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne Lampe, Gegenstand und Auge. Zeichne mit Pfeilen ein, wie das Licht ins Auge gelangt.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Was muss ins Auge gelangen, damit wir etwas sehen? ${inp('a1', '…')}</li>
          <li>Leuchtet der Mond selbst? Wenn nein – woher kommt sein Licht? ${inp('a2', '')}</li>
          <li>Warum sieht man in einem völlig dunklen Raum gar nichts? ${inp('a3', '')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Wir sehen einen Gegenstand nur, wenn ${inp('m1', 'was?')} von ihm in unser ${inp('m2', 'wohin?')} gelangt.<br>
        <b>Leuchtende</b> Körper senden eigenes Licht; <b>beleuchtete</b> Körper werfen ${inp('m3', 'welches Licht?')} Licht zurück.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Ein Katzenauge (Reflektor) am Fahrrad leuchtet nachts hell auf, wenn ein Auto kommt. Erkläre, warum – obwohl der Reflektor selbst kein Licht macht.</div>
        ${ta('tr1', 'Der Reflektor …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="sehMini">${_sehMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_sehSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_sehSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_sehSelf(3)">😃 sicher</button>
          <span id="sehSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="sehSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> Leuchtende Körper (Lampe, Kerze, Sonne) sieht man auch im Dunkeln. Beleuchtete Körper (Buch, Apfel, Mond) verschwinden, sobald das Licht aus ist.</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Sehen = Sender–Gegenstand–Empfänger: Licht geht von einer Quelle zum Gegenstand, wird zurückgeworfen und gelangt ins Auge. Nur so entsteht ein Seheindruck. Der Mond ist ein beleuchteter Körper.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Das Auge sendet Sehstrahlen aus." (2) „Man sieht Gegenstände auch ohne Licht." (3) „Der Mond leuchtet selbst."</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Pfeilrichtung Quelle→Gegenstand→Auge betonen; leuchtende vs. beleuchtete Körper sortieren lassen; völlige Dunkelheit als Gegenprobe.</div>
        <div class="ab-t"><b>Musterlösung.</b> Tabelle: leuchtend ja/ja; beleuchtet nein/nein. 6.1 „Licht" · 6.2 „nein, vom Sonnenlicht" · 6.3 „kein Licht gelangt ins Auge". Merksatz: Licht · Auge · fremdes. Transfer: Der Reflektor wirft das Autoscheinwerferlicht zurück ins Auge des Fahrers. Minidiagnose: 1→„Licht ins Auge" · 2→„nein, reflektiert" · 3→„es fehlt Licht".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('sehen')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('sehen', 'Wie können wir einen Gegenstand sehen?', body);
}

const _SEH_MINI = [
  { q: '1. Was muss passieren, damit du einen Gegenstand siehst?',
    opts: ['Dein Auge sendet Strahlen aus', 'Licht vom Gegenstand gelangt in dein Auge', 'Du musst ihn anfassen'], correct: 1,
    fb: ['Das Auge sendet kein Licht aus – es empfängt nur.',
         'Richtig! Sehen heißt: Licht vom Gegenstand kommt ins Auge.',
         'Anfassen ist nicht nötig – Licht genügt.'] },
  { q: '2. Leuchtet der Mond selbst?',
    opts: ['Ja', 'Nein, er wirft Sonnenlicht zurück', 'Nur bei Vollmond'], correct: 1,
    fb: ['Der Mond ist keine eigene Lichtquelle.',
         'Richtig! Der Mond ist ein beleuchteter Körper – er reflektiert Sonnenlicht.',
         'Auch bei Vollmond reflektiert er nur.'] },
  { q: '3. Warum siehst du in einem völlig dunklen Raum gar nichts?',
    opts: ['Weil die Augen schlafen', 'Weil kein Licht ins Auge gelangt', 'Weil alles schwarz gestrichen ist'], correct: 1,
    fb: ['An den Augen liegt es nicht.',
         'Richtig! Ohne Licht kann nichts ins Auge gelangen.',
         'Auch weiße Wände sieht man ohne Licht nicht.'] }
];
function _sehMiniHTML() {
  return _SEH_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_sehAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="sehFb${qi}"></div></div>`).join('');
}
function _sehAns(qi, oi) {
  const m = _SEH_MINI[qi], el = document.getElementById('sehFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _sehSelf(n) {
  const out = document.getElementById('sehSelfOut'), val = document.getElementById('sehSelfVal');
  if (val) { val.value = String(n); _abSave('sehen'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 5.3.2  WIE BREITET SICH LICHT AUS?
// Realschule NRW – Klasse 5 · Inhaltsfeld "Licht und Schall"
// Handlungsorientiert: Lampe, zwei Blenden mit Loch, Schirm. Das
// Licht kommt nur durch, wenn die beiden Löcher mit der Lampe auf
// einer GERADEN Linie liegen. So entdecken die Lernenden die
// geradlinige Lichtausbreitung (Lichtstrahl als Modell).
// ═══════════════════════════════════════════════════════

let _lau = null;
// Geometrie: Lampe x0, Blende1 x1, Blende2 x2, Schirm xS
const _LAU_X0 = 50, _LAU_X1 = 170, _LAU_X2 = 290, _LAU_XS = 402;
const _LAU_RATIO = (_LAU_X2 - _LAU_X0) / (_LAU_X1 - _LAU_X0);   // = 2

function _lauInit() { _lau = { h1: 18, h2: 0, t: 0 }; }
function _lauNeed2() { return _LAU_RATIO * _lau.h1; }            // Soll-Lage Loch 2
function _lauDurch() { return Math.abs(_lau.h2 - _lauNeed2()) < 11; }

function _lauHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim lau-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">📏 Noahs Taschenlampe: Laeuft das Licht geradeaus oder um die Ecke?</h3>
    <div class="fpm-note" style="margin-top:2px">Noah leuchtet mit der Taschenlampe zum Katzenauge am Baum. Ben haelt zwei Pappstreifen mit je einem Loch dazwischen. Verschiebe die Loecher, bis das Licht am Baum ankommt. Achte darauf, wie die Loecher dann zueinander liegen.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="lauAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="lmp-status" id="lauStatus" style="margin-top:6px"></div>
      </div>
      <div>
        <div class="fpm-label">Löcher verschieben</div>
        <div class="phys-ctrl" style="margin-top:6px">
          <span class="phys-ctrl-label">Loch der 1. Blende: <b id="lauH1Lbl">+18</b></span>
          <input type="range" id="lauH1" min="-50" max="50" step="2" value="18"
            oninput="_lauSetH(1,this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="phys-ctrl" style="margin-top:8px">
          <span class="phys-ctrl-label">Loch der 2. Blende: <b id="lauH2Lbl">0</b></span>
          <input type="range" id="lauH2" min="-50" max="50" step="2" value="0"
            oninput="_lauSetH(2,this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="fpm-note" style="margin-top:10px">Probiere mehrere Stellungen aus. Notiere im Forscherheft, bei welcher Stellung der Loecher das Licht ankommt und bei welcher nicht.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Licht breitet sich <b>geradlinig</b> aus. &nbsp;|&nbsp; Wir zeichnen den Weg des Lichts als geraden <b>Lichtstrahl</b>.
    </p>
    ${_lauArbeitsblattHTML()}
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _lauSetH(n, v) {
  _lau['h' + n] = +v;
  const el = document.getElementById('lauH' + n + 'Lbl'); if (el) el.textContent = (+v > 0 ? '+' : '') + _fpmNum(+v, 0);
  _lauStatus();
}
function _lauStatus() {
  const el = document.getElementById('lauStatus'); if (!el) return;
  if (_lauDurch()) { el.textContent = '✓ Das Licht kommt durch! Lampe und beide Löcher liegen auf einer geraden Linie.'; el.className = 'lmp-status on'; }
  else { el.textContent = '✗ Das Licht wird an einer Blende gestoppt – die Löcher liegen noch nicht auf einer Linie.'; el.className = 'lmp-status off'; }
}

// ── Animation ──────────────────────────────────────────
function _lauUpdate(dt) { if (_lau) _lau.t += dt; }
function _lauBlende(ctx, x, cy, holeY, H) {
  ctx.fillStyle = '#475569';
  ctx.fillRect(x - 5, 20, 10, (cy + holeY - 11) - 20);
  ctx.fillRect(x - 5, cy + holeY + 11, 10, (H - 20) - (cy + holeY + 11));
  ctx.fillStyle = '#cbd5e1'; ctx.fillRect(x - 5, cy + holeY - 11, 10, 22);   // Loch
}
function _lauDraw(ctx, cv) {
  if (!_lau) return;
  const W = cv.width, H = cv.height, cy = H / 2, durch = _lauDurch();
  ctx.clearRect(0, 0, W, H); ctx.fillStyle = '#0f172a'; ctx.fillRect(0, 0, W, H);
  // Lampe
  ctx.fillStyle = '#facc15'; ctx.beginPath(); ctx.arc(_LAU_X0, cy, 12, 0, 2 * Math.PI); ctx.fill();
  ctx.fillStyle = '#fde047'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Taschenlampe', _LAU_X0, cy + 28);
  // Blenden
  _lauBlende(ctx, _LAU_X1, cy, _lau.h1, H);
  _lauBlende(ctx, _LAU_X2, cy, _lau.h2, H);
  ctx.fillStyle = '#94a3b8'; ctx.font = '9px sans-serif'; ctx.fillText('Blende 1', _LAU_X1, H - 8); ctx.fillText('Blende 2', _LAU_X2, H - 8);
  // Schirm
  ctx.fillStyle = '#e2e8f0'; ctx.fillRect(_LAU_XS, 24, 8, H - 48);
  ctx.fillStyle = '#94a3b8'; ctx.fillText('Schirm', _LAU_XS + 4, H - 8);
  // Lichtstrahl
  const y1 = cy + _lau.h1;
  if (durch) {
    const yS = cy + _lau.h1 * (_LAU_XS - _LAU_X0) / (_LAU_X1 - _LAU_X0);
    ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 2.5; ctx.setLineDash([8, 6]); ctx.lineDashOffset = -(_lau.t * 60) % 14;
    ctx.beginPath(); ctx.moveTo(_LAU_X0 + 10, cy); ctx.lineTo(_LAU_XS, yS); ctx.stroke(); ctx.setLineDash([]); ctx.lineDashOffset = 0;
    // Lichtfleck
    ctx.fillStyle = 'rgba(250,204,21,0.5)'; ctx.beginPath(); ctx.arc(_LAU_XS + 4, yS, 9, 0, 2 * Math.PI); ctx.fill();
    ctx.fillStyle = '#fde047'; ctx.beginPath(); ctx.arc(_LAU_XS + 4, yS, 4, 0, 2 * Math.PI); ctx.fill();
  } else {
    // bis zur 2. Blende, dort gestoppt
    ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 2.5; ctx.setLineDash([8, 6]); ctx.lineDashOffset = -(_lau.t * 60) % 14;
    ctx.beginPath(); ctx.moveTo(_LAU_X0 + 10, cy); ctx.lineTo(_LAU_X2, cy + _lau.h1 * (_LAU_X2 - _LAU_X0) / (_LAU_X1 - _LAU_X0)); ctx.stroke(); ctx.setLineDash([]); ctx.lineDashOffset = 0;
    ctx.fillStyle = '#ef4444'; ctx.font = '700 11px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('✗ gestoppt', _LAU_X2, 18);
  }
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 5.3.2  (ns = 'ausbreitung') – im 0123-Gate
// ═══════════════════════════════════════════════════════
function _lauArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('ausbreitung')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('ausbreitung')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Auf welchem Weg breitet sich Licht aus – gerade oder um die Ecke?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, das Licht kommt durch beide Löcher, wenn …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Verschiebe das Loch der 1. Blende. Kommt das Licht durch?</li>
          <li>Verschiebe nun das Loch der 2. Blende, bis das Licht auf dem Schirm ankommt.</li>
          <li>Achte darauf, wie Lampe und beide Löcher zueinander liegen, wenn das Licht durchkommt.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtung</div>
        <ol class="ab-ol">
          <li>Kommt das Licht durch, wenn die Löcher versetzt sind? ${inp('b1', 'ja/nein')}</li>
          <li>Wie müssen Lampe und Löcher liegen, damit das Licht durchkommt? ${inp('b2', 'auf einer …')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne Lampe, beide Löcher und den Schirm. Zeichne den Lichtstrahl als gerade Linie ein.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Auf welchem Weg breitet sich Licht aus? ${inp('a1', '…')}</li>
          <li>Wie nennt man den geraden Weg des Lichts im Modell? ${inp('a2', 'Licht…')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Licht breitet sich ${inp('m1', 'wie?')} aus.<br>
        Den geraden Weg des Lichts stellt man im Modell als ${inp('m2', 'Licht…?')} dar.<br>
        Das Licht kommt nur durch, wenn die Löcher auf ${inp('m3', 'wie vielen Linien?')} Linie liegen.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Warum kannst du um eine Hausecke herum nicht sehen, was dahinter passiert – obwohl es dort hell ist?</div>
        ${ta('tr1', 'Ich kann nicht um die Ecke sehen, weil das Licht …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="lauMini">${_lauMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_lauSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_lauSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_lauSelf(3)">😃 sicher</button>
          <span id="lauSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="lauSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> Nur wenn Lampe und beide Löcher auf einer Geraden liegen, erscheint ein Lichtfleck auf dem Schirm. Sind die Löcher versetzt, wird das Licht an einer Blende gestoppt. (Da Blende 2 doppelt so weit weg ist, muss ihr Loch doppelt so weit aus der Mitte liegen.)</div>
        <div class="ab-t"><b>Fachlich richtig.</b> In einem klaren, gleichmäßigen Stoff (Luft, Vakuum) breitet sich Licht geradlinig aus. Der gerade Weg wird als Lichtstrahl modelliert. Das erklärt auch Schatten und die Lochkamera.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Licht biegt um Ecken." (2) „Licht sucht sich den kürzesten Weg durch die Löcher (auch wenn krumm)." (3) „Licht ist überall, deshalb kommt es immer durch."</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Gerade Linie mit dem Lineal anlegen; drei-Karten-Realversuch nachstellen; Lichtstrahl als Pfeil zeichnen.</div>
        <div class="ab-t"><b>Musterlösung.</b> 4.1 „nein" · 4.2 „auf einer geraden Linie". 6.1 „geradlinig" · 6.2 „Lichtstrahl". Merksatz: geradlinig · Lichtstrahl · einer. Transfer: Licht geht nur geradeaus und nicht um die Ecke. Minidiagnose: 1→„geradlinig" · 2→„auf einer Linie" · 3→„weil Licht nicht um die Ecke geht".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('ausbreitung')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('ausbreitung', 'Wie breitet sich Licht aus?', body);
}

const _LAU_MINI = [
  { q: '1. Auf welchem Weg breitet sich Licht aus?',
    opts: ['In Kurven', 'Geradlinig', 'Im Zickzack'], correct: 1,
    fb: ['Licht macht keine Kurven.',
         'Richtig! Licht breitet sich geradlinig aus.',
         'Es läuft schnurgerade, nicht im Zickzack.'] },
  { q: '2. Warum kommt das Licht nur durch, wenn die Löcher richtig stehen?',
    opts: ['Weil sie auf einer geraden Linie liegen müssen', 'Weil sie gleich groß sein müssen', 'Weil sie bunt sein müssen'], correct: 0,
    fb: ['Richtig! Nur auf einer geraden Linie kommt das Licht durch.',
         'Die Größe ist nicht entscheidend.',
         'Die Farbe spielt keine Rolle.'] },
  { q: '3. Warum kannst du nicht um eine Ecke sehen?',
    opts: ['Weil Ecken dunkel sind', 'Weil Licht nicht um die Ecke geht', 'Weil die Augen zu schwach sind'], correct: 1,
    fb: ['An der Dunkelheit liegt es nicht.',
         'Richtig! Licht geht geradeaus und nicht um die Ecke.',
         'Mit der Sehstärke hat es nichts zu tun.'] }
];
function _lauMiniHTML() {
  return _LAU_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_lauAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="lauFb${qi}"></div></div>`).join('');
}
function _lauAns(qi, oi) {
  const m = _LAU_MINI[qi], el = document.getElementById('lauFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _lauSelf(n) {
  const out = document.getElementById('lauSelfOut'), val = document.getElementById('lauSelfVal');
  if (val) { val.value = String(n); _abSave('ausbreitung'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 5.3.3  WIE ENTSTEHT EIN SCHATTEN?
// Realschule NRW – Klasse 5 · Inhaltsfeld "Licht und Schall"
// Handlungsorientiert: Punktlichtquelle, undurchsichtiger Gegenstand,
// Schirm. Bewege die Lampe (nach oben/unten) und entferne den
// Gegenstand. Entdecke: Der Schatten entsteht, weil Licht geradlinig
// ist und der Körper es blockiert – er liegt der Lampe GEGENÜBER.
// ═══════════════════════════════════════════════════════

let _sct = null;
function _sctInit() { _sct = { lampY: -20, objOn: true, t: 0 }; }

function _sctHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim sct-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🌑 Wovon haengt es ab, wo der Schatten an der Wand liegt?</h3>
    <div class="fpm-note" style="margin-top:2px">Jonas' Taschenlampe, der Pappwolf an der Waescheklammer und die Bretterwand der Bude. Verschiebe die Lampe und nimm den Pappwolf einmal weg. Beobachte, wo der Wolf an der Wand auftaucht.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="sctAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" id="sctObj" onclick="_sctToggle()">🧱 Gegenstand: <span id="sctObjT">da</span></button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Lampe bewegen</div>
        <div class="phys-ctrl" style="margin-top:6px">
          <span class="phys-ctrl-label">Lampe (Höhe): <b id="sctLLbl">oben</b></span>
          <input type="range" id="sctL" min="-60" max="60" step="4" value="-20"
            oninput="_sctSetL(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="lmp-status" id="sctStatus"></div>
        <div class="fpm-note" style="margin-top:10px">Stelle die Lampe nacheinander nach oben, in die Mitte und nach unten. Trage jedes Mal ein, wohin der Schatten an der Bretterwand wandert.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Ein Schatten entsteht, weil Licht <b>geradlinig</b> ist und ein undurchsichtiger Körper es <b>blockiert</b>. &nbsp;|&nbsp; Der Schatten hat den <b>Umriss</b> des Körpers.
    </p>
    ${_sctArbeitsblattHTML()}
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _sctSetL(v) {
  _sct.lampY = +v;
  const el = document.getElementById('sctLLbl'); if (el) el.textContent = +v < -12 ? 'oben' : (+v > 12 ? 'unten' : 'Mitte');
  _sctStatus();
}
function _sctToggle() {
  _sct.objOn = !_sct.objOn;
  const t = document.getElementById('sctObjT'); if (t) t.textContent = _sct.objOn ? 'da' : 'entfernt';
  document.getElementById('sctObj')?.classList.toggle('primary', _sct.objOn);
  _sctStatus();
}
function _sctStatus() {
  const el = document.getElementById('sctStatus'); if (!el) return;
  if (!_sct.objOn) { el.textContent = '✗ Kein Gegenstand → nichts blockiert das Licht → kein Schatten.'; el.className = 'lmp-status off'; }
  else { el.textContent = '✓ Der Gegenstand blockiert das Licht → dahinter entsteht ein Schatten (auf der lichtabgewandten Seite).'; el.className = 'lmp-status on'; }
}

// ── Animation ──────────────────────────────────────────
function _sctUpdate(dt) { if (_sct) _sct.t += dt; }
function _sctDraw(ctx, cv) {
  if (!_sct) return;
  const W = cv.width, H = cv.height, cy = H / 2;
  ctx.clearRect(0, 0, W, H); ctx.fillStyle = '#fef9c3'; ctx.fillRect(0, 0, W, H);   // hell (beleuchtet)
  const x0 = 55, yL = cy + _sct.lampY, xO = W / 2 - 6, hO = 34, xS = W - 46;
  const yTopO = cy - hO, yBotO = cy + hO;
  // Schirm
  ctx.fillStyle = '#e2e8f0'; ctx.fillRect(xS, 20, 8, H - 40);
  ctx.fillStyle = '#94a3b8'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Bretterwand', xS + 4, H - 8);

  if (_sct.objOn) {
    // Schattenstrahlen: Lampe über Ober-/Unterkante
    const yTopS = yL + (yTopO - yL) * (xS - x0) / (xO - x0);
    const yBotS = yL + (yBotO - yL) * (xS - x0) / (xO - x0);
    // Schattenraum (Kegel hinter dem Gegenstand)
    ctx.fillStyle = 'rgba(30,41,59,0.72)';
    ctx.beginPath(); ctx.moveTo(xO, yTopO); ctx.lineTo(xS, yTopS); ctx.lineTo(xS, yBotS); ctx.lineTo(xO, yBotO); ctx.closePath(); ctx.fill();
    // Grenzstrahlen
    ctx.strokeStyle = '#f59e0b'; ctx.lineWidth = 1.6; ctx.setLineDash([6, 4]); ctx.lineDashOffset = -(_sct.t * 40) % 10;
    ctx.beginPath(); ctx.moveTo(x0, yL); ctx.lineTo(xS, yTopS); ctx.moveTo(x0, yL); ctx.lineTo(xS, yBotS); ctx.stroke();
    ctx.setLineDash([]); ctx.lineDashOffset = 0;
    // Schattenbild auf dem Schirm
    ctx.fillStyle = '#1e293b'; ctx.fillRect(xS, Math.min(yTopS, yBotS), 8, Math.abs(yBotS - yTopS));
    ctx.fillStyle = '#334155'; ctx.font = '700 11px sans-serif'; ctx.textAlign = 'left';
    ctx.fillText('Schatten', xS + 12, (yTopS + yBotS) / 2);
    // Gegenstand
    ctx.fillStyle = '#7c3aed'; ctx.fillRect(xO - 6, yTopO, 12, yBotO - yTopO);
    ctx.fillStyle = '#334155'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Gegenstand', xO, yTopO - 8);
  } else {
    ctx.strokeStyle = '#f59e0b'; ctx.lineWidth = 1.4; ctx.setLineDash([6, 4]); ctx.lineDashOffset = -(_sct.t * 40) % 10;
    for (let k = -2; k <= 2; k++) { ctx.beginPath(); ctx.moveTo(x0, yL); ctx.lineTo(xS, cy + k * 26); ctx.stroke(); }
    ctx.setLineDash([]); ctx.lineDashOffset = 0;
  }
  // Lampe (Punktlichtquelle)
  ctx.fillStyle = '#f59e0b'; ctx.beginPath(); ctx.arc(x0, yL, 10, 0, 2 * Math.PI); ctx.fill();
  ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 1.4; for (let k = 0; k < 8; k++) { const an = k * Math.PI / 4; ctx.beginPath(); ctx.moveTo(x0 + Math.cos(an) * 12, yL + Math.sin(an) * 12); ctx.lineTo(x0 + Math.cos(an) * 16, yL + Math.sin(an) * 16); ctx.stroke(); }
  ctx.fillStyle = '#92400e'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Lampe', x0, yL - 18);
}

